window.__D("text/zohar-chadash/c002",{"p":[[9514011949,"<p>וְעִם כָּל זֶה לֹא נִתְיַישֵׁב בְּלִבּוֹ, וְהֶעֱלָה עוֹלוֹת, שֶׁנֶּאֱמַר (שם ח) וַיַּעַל עוֹלוֹת בַּמִּזְבֵּחַ. הוּא הַמִּזְבֵּחַ שֶׁהִקְרִיב עָלָיו אָדָם הָרִאשׁוֹן. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, הֲרֵי לְךָ מַה שֶּׁשָּׁאַלְתָּ, לֹא אוֹסִיף לְקַלֵּל עוֹד אֶת הָאֲדָמָה בַּעֲבוּר הָאָדָם, אָז נִתְיַישֵׁב בְּלִבּוֹ וּלְפִיכָךְ נִקְרָא אִישׁ הָאֲדָמָה, שֶׁנָּתַן נַפְשׁוֹ וְלִבּוֹ עָלֶיהָ לְהוֹצִיאָהּ מִן הַקְּלָלָה. וְאִית דְּאָמְרֵי שֶׁנִּתְעַסֵּק בְּעִסְקֵי הָאֲדָמָה.</p>"],[9514011950,"<p>(שם ט) וַיִּטַע כָּרֶם. גֶּפֶן גְּרוּשָׁה מָצָא, שֶׁנִּתְגָּרְשָׁה מִגַּן עֵדֶן וּבְיוֹמוֹ נְטָעָהּ וְנִשְׂתַּגְשְֹׁגָה, שֶׁנֶּאֱמַר (ישעיהו י״ז:י״א) בְּיוֹם נִטְעֵךְ תְּשַׂגְשֵׂגִי. רַבִּי אוֹמֵר, גֶּפֶן הָיְתָה, שֶׁנִּתְגָּרְשָׁה מִגַּן עֵדֶן, וַעֲנָבֶיהָ עִמָּהּ, וְסָחַט אוֹתָם, וְשָׁתָה מִן הַיַּיִן, וְנִתְגָּל.</p>"],[9514011951,"<p>רַבִּי בּוֹן פָּתַח, (ויקרא י׳:ח׳-ט׳) וַיְדַבֵּר ה' אֶל אַהֲרֹן לֵאמֹר יַיִן וְשֵׁכָר אַל תֵּשְׁתְּ אַתָּה וּבָנֶיךָ אִתָּךְ בְּבֹאֲכֶם אֶל אֹהֶל מוֹעֵד וְלֹא תָמוּתוּ חֻקַּת עוֹלָם לְדֹרֹתֵיכֶם. דְּאָמַר רִבִּי אָבוֹן, אֵין בְּכָל הָעוֹלָם דָּבָר שֶׁמִּתְגָּאֶה לִבּוֹ שֶׁל אָדָם, אֶלָּא בְּיַיִן. וְזֶה הָיָה עָנְשָׁם שֶׁל נָדָב וַאֲבִיהוּא, שֶׁאָכְלוּ וְשָׁתוּ וְגָבָהּ לִבָּם, וְזֶהוּ אֵשׁ זָרָה אֲשֶׁר לֹא צִוָּה אוֹתָם.</p>"],[9514011952,"<p>וְקוֹהֶם זֶה הָיָה נִגְזַר עֲלֵיהֶם, וּבָאָה מִדַּת הַדִּין לִשְׁלוֹחַ יָד בָּהֶם, שֶׁנֶּאֱמַר (שמות כ״ד:י״א) וְאֶל אֲצִילֵי בְּנֵי יִשְׂרָאֵל לֹא שָׁלַח יָדוֹ. אַף עַל פִּי שֶׁנִּגְזַר דִּינָם לִשְׁלֹחַ יָד בָּהֶם. וְלָמָּה הָיָה עָנְשָׁם, מִשּׁוּם וַיֶּחֱזוּ אֶת הָאֱלֹהִים וַיֹּאכְלוּ וַיִּשְׁתּוּ. נִכְנְסוּ, כְּשֶׁאָכְלוּ וְשָׁתוּ, וְנִגְזַר עָנְשָׁם בְּאוֹתָהּ שָׁעָה.</p>"],[9514011953,"<p>וּלְאַחַר כֵּן רָאוּ שֶׁלֹּא שָׁלַח יָד בָּהֶם בַּפַּעַם רִאשׁוֹנָה, עָשׂוּ ג\"כ בַּשְּׁנִיָה, וּמִבֵּין שְׁנֵי הַכְּרוּבִים יָצָא לַהַב וְנִשְׂרְפוּ. כִּי לְכָךְ הָיוּ הַכְּרוּבִים מְכֻוָּונִים, כְּנֶגֶד אוֹתָם הַכְּרוּבִים אֲשֶׁר בַּגַּן עֵדֶן.</p>"],[9514011954,"<p>וּלְאַחַר שֶׁמֵּתוּ, צִוָּה לְאַהֲרֹן וְלַכֹּהֲנִים הַבָּאִים אַחֲרָיו, לְהִמָּנַע עַצְמָם מִן הַיַּיִן, בְּבוֹאָם אֶל אֹהֶל מוֹעֵד, כְּדֵי שֶׁלֹּא יִכָּנְסוּ וְיִמָּצֵא לִבָּם בְּגֵאוּת וּבְגַּסּוּת הָרוּחַ.</p>"],[9514011955,"<p>אָמַר רַבִּי, תְּרֵי עִנְיָינֵי אִינוּן דְּלֹא מִתְיַישְּׁבֵי כַּחֲדָא, יֵינָא וּפוּלְחַן שְׁמַיָא. דְּתָנִינָן תַּמָּן, שָׁתוּי אַל יִתְפַּלֵּל. וְכֵן שִׁכּוֹר, אַל יִתְפַּלֵּל. וְאִם הִתְפַּלֵּל, תְּפִלָּתוֹ תּוֹעֵבָה.</p>"],[9514011956,"<p>וְאָמַר רַבִּי יוֹסֵי, שִׁכּוֹר הַמִּתְפַּלֵּל כְּאִלּוּ עוֹבֵד עֲבוֹדָה זָרָה. וּמְנָא לָן, מֵחַנָּה. דִּכְתִיב (שמואל א א׳:ט״ז) וַיַּחְשְׁבֶהָ עֵלִי לְשִׁכּוֹרָה. וְהֵשִׁיבָה וְאָמְרָה אַל תִּתֵּן אֶת אֲמָתְךָ לִפְנֵי בַּת בְּלִיַּעַל. וְאָמַר רִבִּי יוֹסֵי, כְּתִיב הָכָא בַּת בְּלִיַּעַל, וּכְתִיב הָתָם, (דברים י״ג:י״ד) יָצְאוּ אֲנָשִׁים בְּנֵי בְּלִיַּעַל, מַה לְּהַלָּן עֲבוֹדָה זָרָה, אַף כָּאן עֲבוֹדָה זָרָה.</p>"],[9514011957,"<p>אָמַר רִבִּי יִצְחָק, לֵית לָךְ גּוּבְרִין דְּאִתְקְרוֹן קַדִּישִׁין, בַּר אִינוּן פְּרִישֵׁי חַמְרָא. דִּכְתִיב כָּל יְמֵי הֲזִירוֹ לַה' קָדוֹשׁ יִהְיֶה.</p>"],[9514011958,"<p>וְאָמַר רִבִּי יִצְחָק, לֵית לָךְ חֲמַר דְּאִתְקְרֵי חֲמַר טוֹב, כְּחַמְרָא דְּאַרְעָא דְיִשְׂרָאֵל. וְיַתִּיר עַל כָּלְהוֹן, חַמְרָא דִּגְלִילָא עִילָּאָה, דְּלָא יָכֵיל אֵינַשׁ לְמִשְׁתֵּי פַּלְגּוּת לוֹגָא מִינֵּיהּ.</p>"],[9514011959,"<p>רַבִּי אֶלְעָזָר בַּר ר' שִׁמְעוֹן, אֲזַל לְמֶחֱמֵי לְר' יוֹסֵי בּ\"ר שִׁמְעוֹן בֶּן לָקוֹנְיָא חָמוֹי. יַהֲבֵי לֵיהּ לְמֵיכַל עֶגְלָא תְּלִיתָאָה רְכִיכָא, פְּתַח לֵיהּ חַד כּוּבָא דְחַמְרָא. חָמוֹי מָזִיג, וְהוּא שָׁתֵי, מָזִיג וְהוּא שָׁתֵי. אָמַר לֵיהּ אִיפְשָׁר דְּשָׁמַעְתְּ מֵאָבִיךָ, כַּמָּה הוּא שִׁיעוּרוֹ שֶׁל כּוֹס. אָמַר לֵיהּ כְּמוֹת שֶׁהוּא, אַחַת בְּחַמִּין וְאַחַת בְּצוֹנֵן, אֲבָל לֹא שִׁיעֲרוּ רַבָּנָן בְּכוֹסְךָ דְּהִיא זְעִירָא. וּבְחַמְרָךְ דְּהוּא טָבָא. וּבְמֵעוֹהִי דְּהוּא רְחָבָה.</p>"],[9514011960,"<p>וְאָמַר רִבִּי יְהוּדָה, מְבוּלְבָּל בְּדַעְתּוֹ הָיָה נֹחַ כְּשֶׁיָּצָא מִן הַתֵּיבָה, בְּדִירָתוֹ עִם הַחַיּוֹת וְהָרְמָשִׂים וְהַשְּׁרָצִים, וּמִפְּנֵי שֶׁשָּׁתָה מְעַט יַיִן, נִשְׁכָּר וְנִתְגָּל.</p>"],[9514011961,"<p>וְאָמַר רִבִּי יְהוּדָה בָּא כְּנַעַן וְסֵרְסוֹ, הֵקִיץ מִיֵּינוֹ, וּמָצָא עַצְמוֹ מְסוֹרָס. דִּכְתִיב (בראשית ט׳:כ״ד) וַיִּיקֶץ נֹחַ מִיֵּינוֹ, וַיֵּדַע אֵת אֲשֶׁר עָשָׂה לוֹ בְּנוֹ הַקָּטָן. אֲשֶׁר רָאָה לֹא נֶאֱמַר, אֶלָּא אֲשֶׁר עָשָׂה לוֹ, שֶׁסֵּרְסוֹ. וּלְפִיכָךְ קִלְּלוֹ, שֶׁנֶּאֱמַר (שם) וַיֹּאמֶר אָרוּר כְּנָעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו.</p>"],[9514011962,"<p>רַבִּי פָּתַח, (שם ח) וַיָּרַח ה' אֶת רֵיחַ הַנִּיחֹחַ וַיֹּאמֶר לֹא אֹסִף לְקַלֵּל עוֹד אֶת הָאֲדָמָה בַּעֲבוּר הָאָדָם. כְּשֶׁיָּצָא נֹחַ מִן הַתֵּיבָה, פָּתַח עֵינָיו, וְרָאָה אֶת כָּל הָעוֹלָם כֻּלּוֹ חָרֵב, הִתְחִיל בּוֹכֶה עַל הָעוֹלָם. אָמַר, רִבּוֹנוֹ שֶׁל עוֹלָם, אִם בִּשְׁבִיל חַטֹאת הָאָדָם, אוֹ בִּשְׁבִיל הַשּׁוֹטִים תְּאַבֵּד עוֹלָמְךָ, לָמָּה בְּרָאתָם, אוֹ הַאי, אוֹ הַאי. אִית לָךְ לְמֶעְבַּד אוֹ דְּלָא תִּבְרֵי אֵינַשׁ, אוֹ דְּלָא תֵּיבַד עָלְמָא. הֶעֱלָה עוֹלוֹת, וְקָם וְהִתְפַּלֵּל לְפָנָיו, וְאוֹתוֹ הָרֵיחַ עָלָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְעָרַב לוֹ.</p>"],[9514011963,"<p>אָמַר רִבִּי, ג' רֵיחוֹת עָלוּ לְפָנָיו, רֵיחַ עוֹלָתוֹ, וְרֵיחַ תְּפִלָּתוֹ, וְרֵיחַ מַעֲשָׂיו. וְלֹא הָיָה רֵיחַ בָּעוֹלָם דְּנִיחָא קַמֵּיהּ, כְּאוֹתוֹ הָרֵיחַ. וּלְפִיכָךְ צִוָּה וְאָמַר, (במדבר כ״ח:ב׳) רֵיחַ נִיחֹחִי תִּשְׁמְרוּ לְהַקְרִיב לִי בְּמוֹעֲדוֹ. כְּלוֹמַר רֵיחַ שֶׁהִקְרִיב נֹחַ לְפָנַי, תִּשְׁמְרוּ לְהַקְרִיב לִי, רֵיחַ עוֹלָה וּתְפִלָּה, וְכִשְׁרוֹן מַעֲשִׂים.</p>"],[9514011964,"<p>רַבִּי אַיְבוּ אָמַר, נֹחַ חָכָם הָיָה, וְהָיָה מֵבִין לְחִישַׁת וְצִפְצוּף כָּל הַנִּבְרָאִים וּרְמִיזָתָם, וּכְשֶׁהָיָה בַּתֵּיבָה, אָמַר יוֹדֵעַ אֲנִי שֶׁאֵין פִּקֵּחַ בָּעוֹפוֹת כְּמוֹ הָעוֹרֵב, לְמֵידַע מִנֵּיהּ סִימָנָא בְּעָלְמָא, מִיָּד וַיְשַׁלַּח אֶת הָעוֹרֵב.</p>"],[9514011965,"<p>אָמַר רִבִּי חִיָּיא, וְהָאֵיךְ עָבִיד הָכֵי, וְהָאָמַר רַבִּי בּוֹ, אָסוּר לְאִסְתַּכָּלָא בְּאִלֵּין מְנַחֲשֵׁי בְּעוֹפֵי דִשְׁמַיָא, וַהֲרֵי הוּא בִּכְלַל לֹא תְנַחֲשׁוּ וְלֹא תְעוֹנֵנוּ, אֲפִילּוּ כָּל נִיחוּשׁ בְּעָלְמָא.</p>"],[9514011966,"<p>אֶלָּא אָמַר רִבִּי חִיָּיא, לָמָּה שָׁלַח אֶת הָעוֹרֵב. דְּאָמַר רִבִּי חִיָּיא, מִצְטַעֵר הֲוָה נֹחַ טְפֵי עַל אוֹבָדָא דְעָלְמָא. אָמַר רִבּוֹנוֹ שֶׁל עוֹלָם, יָדַעְתִּי כִּי אַתָּה רַחוּם, וְאַתָּה לֹא רִחַמְתָּ עַל עוֹלָמְךָ, וְנֶהְפַּךְ רַחֲמָנוּתְךָ לְאַכְזָרוּת, אַתָּה לֹא רִחַמְתָּ עַל בָּנֶיךָ, יֵצֵא זֶה שֶׁאֵינוֹ מְרַחֵם עַל בָּנָיו, וְנֶהְפַּךְ לָהֶם לְאַכְזָרִי, וּלְפִיכָךְ שָׁלַח אֶת הָעוֹרֵב, רֶמֶז הוּא דְּקָא רָמַז.</p>"],[9514011967,"<p>אָמַר רִבִּי יוֹסֵי, וְכִי לֹא כְתִיב בֵּיהּ אִישׁ צַדִּיק תָּמִים הָיָה, וְהָאֵיךְ הִטִיחַ דְּבָרִים כְּלַפֵּי מַעְלָה. אָמַר רִבִּי חִיָּיא, מֵרוֹב צַעֲרוֹ הוּא דְאָמַר, דְּהָא תְּנַן, מִנַּיִן שֶׁאֵין דָּנִין אֶת הָאָדָם לְפִי צַעֲרוֹ, שֶׁנֶּאֱמַר (איוב ל״ד:ל״ה) אִיּוֹב לֹא בְדַעַת יְדַבֵּר וּדְבָרָיו לֹא בְּהַשְׂכֵּל. אַף עַל פִּי שֶׁהִטִיחַ דְּבָרִים כְּלַפֵּי מַעְלָה, אֵין דִּינוֹ כְּמֵזִיד, אֶלָּא כְּאָדָם בְּלֹא דַּעַת, לְפִי צַעֲרוֹ.</p>"],[9514011968,"<p>וְלֹא רָצָה הָעוֹרֵב לַהֲלוֹךְ בִּשְׁלִיחוּתוֹ, מִפְּנֵי שֶׁמְתוּקָן הוּא לִשְׁלִיחוּת אַחֶרֶת, לְפַרְנֵס אֵלִיָּהוּ, שֶׁנֶּאֱמַר (מלכים א י״ז:ו׳) וְהָעוֹרְבִים מְבִיאִים לוֹ לֶחֶם וּבָשָׂר, וְלֹא רָצָה לַעֲשׂוֹת שְׁלִיחוּתוֹ, עַד יְבשֶׁת הַמַּיִם מֵעַל הָאָרֶץ, שֶׁהָיָה עַל יְדֵי שְׁבוּעַת אֵלִיָּהוּ. כֵּיוָן שֶׁרָאָה נֹחַ שֶׁלֹּא עָשָׂה כְּהוֹגֶן, שָׁלַח אֶת הַיּוֹנָה.</p>"],[9514011969,"<p>וְאָמַר רַבִּי בּוֹן, תְּרֵי עִנְיָינֵי רָמַז בָּהּ, חָדָא, דִּכְתִיב (הושע ז׳:י״א) כְּיוֹנָה פּוֹתָה אֵין לֵב, כְּלוֹמַר מֵרֹב צַעֲרִי, אֵין לִבִּי עִמִּי וְנִפְתֶּה. אַחֲרִינָא, אָמַר נֹחַ, אֵין בְּכָל הָעוֹפוֹת דְּיִסְבּוֹל מִיתָתָה בְּלֹא סַרְבָנוּת, כַּיּוֹנָה. וּלְפִיכָךְ נִמְשְׁלוּ יִשְׂרָאֵל כְּיוֹנָה. אָמַר נֹחַ, כָּךְ יָאוֹת לָנָא לְמִסְבַּל כֹּלָּא, בְּלָא סַרְבָנוּתָא, וּלְפִיכָךְ וַיְשַׁלַּח אֶת הַיּוֹנָה.</p>"],[9514011970,"<p>תָּנוּ רַבָּנָן, מָה הֵשִׁיב הַקָּדוֹשׁ בָּרוּךְ הוּא לְנֹחַ, כְּשֶׁיָּצָא מִן הַתֵּיבָה וְרָאָה כָּל הָעוֹלָם חָרֵב, וְהִתְחִיל לִבְכּוֹת עָלָיו, וְאָמַר, רִבּוֹנוֹ שֶׁל עוֹלָם, נִקְרֵאתָ רַחוּם, הָיָה לְךָ לְרַחֵם עַל בְּרִיּוֹתֶיךָ.</p>"],[9514011971,"<p>הֵשִׁיבוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, רַעְיָא שַׁטְיָא, כְּעָן אֲמַרְתְּ דָּא, וְלָא בְּזִמְנָא דַּאֲמָרִית לָךְ בְּלִישְׁנָא רְכִיכָא, דִּכְתִיב (שם ו) עֲשֵׂה לְךָ תֵּבַת עֲצֵי גֹפֶר כו', וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל כו', לְשַׁחֵת כָּל בָּשָׂר כו', וַיֹּאמֶר ה' לְנֹחַ כו', כִּי אֹתְךָ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה, כּוּלֵּי הַאי אִתְעַכָּבִית עִמָּךְ, וַאֲמָרִית לָךְ, בְּדִיל דְּתִבְעֵי רַחֲמִין עַל עָלְמָא. וּמִכְּדֵין דְּשָׁמַעְתְּ דְּתִשְׁתֵּיזִיב אַתְּ בְּתֵיבוּתָא, לָא עָאל בְּלִבָּךְ בִּישׁוּתָא דְּעָלְמָא, וַעֲבַדְתְּ תֵּיבוּתָא וְאִשְׁתְּזֵבְתָּא. וּכְעָן דְּאִתְאֲבֵיד עָלְמָא, פָּתְחֵית פּוּמָךְ לְמַלָּלָא קֳדָמַי בַּעְיָין וְתַחֲנוּנִין.</p>"],[9514011972,"<p>כֵיוָן דְּחָזָא נֹחַ כָּךְ, הִקְרִיב עֲלָוָון וְקָרְבָּנִין, דִּכְתִיב (שם ח) וַיִּקַּח מִכָּל הַבְּהֵמָה הַטְהוֹרָה וּמִכָּל הָעוֹף הַטָהוֹר וַיַּעַל עוֹלוֹת בַּמִּזְבֵּחַ.</p>"],[9514011973,"<p>אָמַר רִבִּי יוֹחָנָן, בֹּא וּרְאֵה מַה בֵּין הַצַּדִּיקִים שֶׁהָיוּ לְיִשְׂרָאֵל אַחַר כַּךְ, וּבֵין נֹחַ. נֹחַ לֹא הֵגִין עַל דּוֹרוֹ, וְלֹא הִתְפַּלֵּל עָלָיו כְּאַבְרָהָם. דְּכֵיוָן דְּאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם, זַעֲקַת סְדוֹם וַעֲמוֹרָה כִּי רָבָּה, מִיָּד וַיִּגַּשׁ אַבְרָהָם וַיֹּאמַר. וְהִרְבָּה דְבָרִים כְּנֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא, עַד שֶׁשָּׁאַל שֶׁאִם יִמְּצָא שָׁם עֲשָׂרָה צַדִּיקִים, שֶׁיְכַפֵּר לְכָל הַדּוֹר בִּשְׁבִילָם, וְחָשַׁב אַבְרָהָם שֶׁהָיוּ י' בָּעִיר, עִם לוֹט וְאִשְׁתּוֹ וּבָנָיו וּבְנוֹתָיו, וַחֲתָנָיו, וְלָכֵן לֹא הִתְפַּלֵּל יוֹתֵר.</p>"],[9514011974,"<p>בָּא משֶׁה וְהֵגִין עַל כָּל הַדּוֹר, כֵּיוָן שֶׁאָמַר הַקָדוֹשׁ בָּרוּךְ הוּא לְמשֶׁה, יִשְׂרָאֵל חָטְאוּ, סָרוּ מַהֵר מִן הַדֶּרֶךְ. מַה כְּתִיב בֵּיהּ, (שמות ל״ב:ח׳) וַיְחַל משֶׁה. מַהוּ וַיְחַל. מְלַמֵּד שֶׁהִתְפַּלֵּל עַד שֶׁאֲחָזַתּוּ חַלְחָלָה. רַבָּנָן אָמְרֵי, לֹא הִנִּיחַ משֶׁה לְהַקָדוֹשׁ בָּרוּךְ הוּא, עַד שֶׁנָּתַן נַפְשׁוֹ עֲלֵיהֶם מִן הָעוֹלָם הַזֶּה וּמִן הָעוֹלָם הַבָּא. דִּכְתִיב, (שם) וְעַתָּה אִם תִּשָּׂא חַטָאתָם וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךָ אֲשֶׁר כָּתַבְתָּ.</p>"],[9514011975,"<p>אָמַר רִבִּי יוֹסֵי מֵהָכָא, (תהילים ק״ו:כ״ג) וַיֹּאמֶר לְהַשְּׁמִידָם לוּלֵי משֶׁה בְחִירוֹ עָמַד בַּפֶּרֶץ לְפָנָיו. וְכֵן כָּל הַצַּדִּיקִים הֵגִינוּ עַל דּוֹרָם, וְלֹא הִנִּיחוּ מִדַּת הַדִּין לִשְׁלוֹט בָּהֶם.</p>"],[9514011976,"<p>וְנֹחַ הִתְעַכֵּב עִמּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָמַר לֵיהּ רִבּוּי דְבָרִים, שֶׁמָּא יְבַקֵּשׁ עֲלֵיהֶם רַחֲמִים, וְלֹא הִשְׁגִּיחַ, וְלֹא בִּיקֵּשׁ עֲלֵיהֶם רַחֲמִים, וְעָשָׂה הַתֵּיבָה וְנֶאֱבַד כָּל הָעוֹלָם.</p>"],[9514011977,"<p>רַבִּי אֱלִיעֶזְר וְרַבִּי יְהוֹשֻׁעַ הֲווֹ יָתְבֵי בִּפְלָכֵי טְבֶרְיָא, אָמַר רִבִּי יְהוֹשֻׁעַ, רַבִּי, מַה רָאָה נֹחַ שֶׁלֹּא בִּקֵּשׁ רַחֲמִים עַל דּוֹרוֹ. אָמַר לוֹ, אֲפִילּוּ הוּא לֹא חָשַׁב בְּלִבּוֹ שֶׁיִּמָּלֵט. מָשָׁל, לְמוֹצֵא אֶשְׁכּוֹל עֲנָבִים שֶׁאֵינָם מְבוּשָׁלִים, בֵּין הַבּוֹסְרִים, דְּאִלּוּ הֲוָה בֵּין עֲנָבִים מְבוּשָׁלִים, לָא הֲווֹ כְּלוּם.</p>"],[9514011978,"<p>מַשְׁמַע, דִּכְתִיב (בראשית ז׳:א׳) כִּי אוֹתְךָ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה. הֲוָה לֵיהּ לְמֵימַר צַדִּיק לְפָנַי, מַהוּ בַּדּוֹר הַזֶּה. כְּלוֹמַר, לְפִי הַדּוֹר. וּלְפִיכָךְ לֹא בִּקֵּשׁ רַחֲמִים, אָמַר בְּלִבּוֹ וּלְוַאי שֶׁאֲבַקֵּשׁ רַחֲמִים עָלַי וְאִמָּלֵט, וְכָל שֶׁכֵּן שֶׁאֶתְפַּלֵּל עַל אֲחֵרִים.</p>"],[9514011979,"<p>לְבָתַר אָמַר רִבִּי אֱלִיעֶזְר, עַל כָּל דָּא, הֲוָה לֵיהּ לְמִתְבַּע רַחֲמִין עַל עָלְמָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּנִיחָא לֵיהּ, מַאן דַּאֲמַר טָבָא עַל בְּנוֹהִי.</p>"],[9514011980,"<p>מְנָא לָן, מִגִּדְעוֹן בַּר יוֹאָשׁ, דְּלָא הֲוָה זַכַּאי, וְלָא בַּר זַכַּאי, וּמִשּׁוּם דַּאֲמַר טִיבוּתָא עַל יִשְׂרָאֵל, מַה כְּתִיב בֵּיהּ. (שופטים ו׳:י״ד) וַיֹּאמֶר לוֹ ה' לֵךְ בְּכֹחֲךָ זֶה וְהוֹשַׁעְתָּ אֶת יִשְׂרָאֵל מִיַּד מִדְיָן. מַהוּ בְּכֹחֲךָ זֶה. טִיבוּתָא דָא דַּאֲמַרְתְּ עַל בָּנַי, יְהֵא לָךְ חֵילָא סַגִּיאָה, לְשֵׁיזָבוּתְהוֹן מִן יְדָא דְמִדְיָן.</p>"],[9514011981,"<p>וְעוֹד אָמַר רִבִּי אֶלְעָזָר, אַף עַל פִּי דִּיהֱוֵי צַדִּיקָא רַבָּה מִכָּל עָלְמָא, וְיֵימַר בִּישָׁא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, אִי דֵלָטוֹרִין עַל יִשְׂרָאֵל, עוֹנְשֵׁיהּ סַגְיָא מִן כָּלְהוֹן. וְלָא אַשְׁכַּחְנָא צַדִּיקָא טָבָא כְּאֵלִיָּהוּ בְּכָל דָּרָא, וּמִשּׁוּם דַּאֲמַר דֵּלָטוֹרִין עַל יִשְׂרָאֵל, דִּכְתִיב (מלכים א י״ט:י׳) כִּי עָזְבוּ בְרִיתְךָ בְּנֵי יִשְׂרָאֵל אֶת מִזְבְּחוֹתֶיךָ הָרָסוּ וְאֶת נְבִיאֶיךָ הָרְגוּ בֶחָרֶב, בֵּיהּ שַׁעֲתָא אַבְאֵישׁ סַגְיָא קַמֵּיהּ.</p>"],[9514011982,"<p>תָּא חֲזֵי מַה כְּתִיב בֵּיהּ. (שם) וַיַּבֵּט וְהִנֵּה מְרַאֲשֹׁתָיו עֻגַת רְצָפִים. מַהוּ רְצָפִים. אָמַר הַקָדוֹשׁ בָּרוּךְ הוּא, כְּדֵין יָאוֹת לְמֵיכַל, מַאן דַּאֲמַר דֵּלָטוֹרִין עַל בָּנַי.</p>"],[9514011983,"<p>אָמַר רִבִּי אֱלִיעֶזְר, מַאי דִכְתִיב, (שם) וַיֵּלֶךְ בְּכֹחַ הָאֲכִילָה הַהִיא אַרְבָּעִים יוֹם וְאַרְבָּעִים לַיְלָה עַד הַר הָאֱלֹהִים (חרבה). וְכִי בְּכֹחַ אֲכִילַת עוּגַּת רְצָפִים אָזַל כּוּלֵי הַאי.</p>"],[9514011984,"<p>אֶלָּא אָמַר רִבִּי אֱלִיעֶזְר, הִשְׁלִיךְ הַקָּדוֹשׁ בָּרוּךְ הוּא דּוּרְמִיטָה עַל אֵלִיָּהוּ, וְהֶרְאָהוּ עִנְיָנָא דְמשֶׁה, דִּיתִיב קַמֵּיהּ אַרְבְּעִין יְמָמִין וְאַרְבָּעִין לֵילָוָן, וּמִכְּדֵין דְּהֲוָה תַּמָּן, עָבְדוּ יִשְׂרָאֵל יַת עֶגְלָא. וּבְגִין דְּהֲוָה אַרְבְּעִין יְמָמִין וְאַרְבָּעִין לֵילָוָן דְּלֶחֶם לָא אָכַל, וּמַיָא לָא שָׁתֵי, לָא אַעֲדֵי מִתַּמָּן עַד דְּמָחַל לְהוֹן קוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9514011985,"<p>אָמַר לֵיהּ לְאֵלִיָּהוּ, כָּךְ הֲוָה לָךְ לְמֶעְבַּד, וְעוֹד הֲוָה לָךְ לְמֶחֱזֵי, דְּאִינוּן בָּנַי בְּנֵי רְחִימָאי, דְּקַבִּילוּ אוֹרַיְיתִי בְּטוּרָא דְחוֹרֵב, וְדָא הוּא דִּכְתִיב, וַיֵּלֶךְ בְּכֹחַ הָאֲכִילָה הַהִיא אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה. דְּחָזָא עִנְיָינָא דְמשֶׁה, דְּאִישְׁתְּהֵי קַמֵּיהּ אַרְבְּעִין יְמָמִין וְאַרְבָּעִין לֵילָוָן. וְעִנְיָינָא דְיִשְׂרָאֵל, דְּקַבִּילוּ אוֹרַיְיתָא בְּטוּרָא דְחוֹרֵב. וְדָא הוּא דִכְתִיב, (שם) עַד הַר הָאֱלֹהִים חֹרֵב.</p>"],[9514011986,"<p>אָמַר רִבִּי יִצְחָק, לֹא זָז אֵלִיָּהוּ מִשָּׁם, עַד שֶׁנִּשְׁבַּע לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, לְהוֹרוֹת זְכוּתָן שֶׁל יִשְׂרָאֵל תָּמִיד. וְכָל מִי שֶׁעוֹשֶׂה זְכוּת, הוּא מַקְדִּים וְאוֹמֵר לִפְנֵי הַקָדוֹשׁ בָּרוּךְ הוּא, כָּךְ וְכָךְ עָשָׂה עַכְשָׁיו פְּלוֹנִי. וְאֵינוֹ זָז מִשָּׁם, עַד שֶׁיִּכְתְּבוּ זְכוּתוֹ דְּהַהוּא גַבְרָא. דִּכְתִיב, (מלאכי ג׳:ט״ז) וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו.</p>"],[9514011987,"<p>אָמַר רִבִּי יְהוּדָה בֶּן פַּזִי, מֶה הָיָה עוֹנְשׁוֹ שֶׁל נֹחַ, שֶׁיָּצָא חִגֵּר בְּרַגְלָיו מִן הַתֵּיבָה, וְשָׁכַב וְנִתְבַּזֶּה, וְהִתְלוֹצֵץ עָלָיו בְּנוֹ, וְעָשָׂה לוֹ מַה שֶּׁעָשָׂה.</p>"],[9514011988,"<p>אָמַר רִבִּי אֶלְעָזָר, בֹּא וּרְאֵה כַּמָּה יֵשׁ לְאָדָם לָלֶכֶת בְּדֶרֶךְ יְשָׁרָה. בֹּא וּרְאֵה מִפְּנֵי שֶׁנָּטַל יַעֲקֹב הַבְּרָכוֹת מֵעֵשָׂו בְּרַמָּאוּת. תֵּדַע לָךְ, שֶׁלֹּא נִיתַּן רְשׁוּת לְשׁוּם אוּמָּה בָּעוֹלָם לְהִשְׁתַּעְבֵּד בְּיִשְׂרָאֵל, זוּלָתִי אוּמָּה שֶׁל עֵשָׂו.</p>"],[9514011989,"<p>אָמַר רִבִּי יוֹחָנָן בֶּן נוּרִי, נָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת שֵׁם בֶּן נֹחַ, וְהִפְרִישׁוֹ לְכֹהֵן עֶלְיוֹן, וּלְשָׁרְתוֹ. וְהִשְׁרָה שְׁכִינָתוֹ עִמּוֹ, וְקָרָא שְׁמוֹ מַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם. וְהָיָה יֶפֶת אָחִיו לוֹמֵד תּוֹרָה מִמֶּנּוּ בְּמִדְרָשׁוֹ, עַד שֶׁבָּא אַבְרָהָם, וְלָמַד תּוֹרָה בְּמִדְרָשׁוֹ שֶׁל שֵׁם. וְנִתְעַסֵּק הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאַבְרָהָם, וְנִשְׁתַּכְּחוּ כָּל הָאֲחֵרִים. בָּא אַבְרָהָם וְהִתְפַּלֵּל לִפְנֵי הַקָדוֹשׁ בָּרוּךְ הוּא, שֶׁיַּשְׁרֶה שְׁכִינָתוֹ תָּמִיד בְּבֵיתוֹ שֶׁל שֵׁם, וְהוֹדָה לוֹ, שֶׁנֶּאֱמַר (תהילים ק״י:ד׳) אַתָּה כֹהֵן לְעוֹלָם עַל דִּבְרָתִי מַלְכִּי צֶדֶק.</p>"],[9514011990,"<p>אָמַר רִבִּי יוֹחָנָן, וַהֲלֹא יֶפֶת הוּא הַגָּדוֹל, לָמָּה שֵׁם נָטַל הַכְּהוּנָּה. בִּשְׁבִיל שֶׁהָיָה תָּמִיד עוֹסֵק בַּתּוֹרָה, וּפֵירַשׁ מִדַּרְכֵי הָעוֹלָם. וּמֵאַיִן הָיָה לוֹ תּוֹרָה. אֶלָּא אָדָם הָרִאשׁוֹן יָדַע הַתּוֹרָה, וְהִנִּיחָהּ בְּקַבָּלָה לְשֵׁת בְּנוֹ, וְאַחַר כַּךְ בָּאָה לְיַד חֲנוֹךְ, עַד שֶׁבָּא לְשֵׁם וְהָיָה מִתְעַסֵק תָּמִיד בָּהּ.</p>"],[9514011991,"<p>אָמַר לוֹ ר' יוֹסֵי, אִם הַתּוֹרָה הָיְתָה בְּמִדְרָשׁוֹ שֶׁל שֵׁם, לָמָּה הוּצְרַךְ הַקָּדוֹשׁ בָּרוּךְ הוּא לְצַוּוֹת לִבְנֵי נֹחַ אוֹתָן שֶׁבַע מִצְוֹת שֶׁנִּצְטַוּוּ, שֶׁהֲרֵי בַּתּוֹרָה נִכְתְּבוּ קוֹדֶם לָכֵן, אֶלָּא אָמַר רִבִּי יִצְחָק, בְּשָׁעָה שֶׁהַמַּבּוּל בָּא לָעוֹלָם, וְנִכְנְסוּ לַתֵּיבָה, מֵרוֹב צַעֲרָם נִשְׁתַּכְּחָה מִשֵּׁם, עַד שֶׁבָּא הַקָדוֹשׁ בָּרוּךְ הוּא וְחִידֵּשׁ לָהֶם אוֹתָם שֶׁבַע מִצְוֹת.</p>"],[9514011992,"<p>אָמַר רִבִּי יוֹסֵי, חַס וְשָׁלוֹם לֹא נִשְׁתַּכְּחָה הַתּוֹרָה מִמֶּנּוּ, אֶלָּא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אִם אוֹמַר לָהֶם שֶׁיִּשְׁמְרוּ כָּל תּוֹרָתִי, יִפְרְקוּ כָּל הָעוֹל מֵהֶם, כַּאֲחֵרִים שֶׁאָמְרוּ (איוב כא) וְדַעַת דְּרָכֶיךָ לֹא חָפָצְנוּ. אֶלָּא אֶתֵּן לָהֶם דְּבָרִים מוּעָטִים, וְיִשְׁמְרוּ אוֹתָם.</p>"],[9514011993,"<p>עַד שֶׁיָּבוֹא מִי שֶׁיִּשְׁמוֹר כּוּלָּהּ, וְהוּא אַבְרָהָם, שֶׁנֶּאֱמַר (בראשית כ״ו:ה׳) עֵקֶב אֲשֶׁר שָׁמַע אַבְרָהָם בְּקֹלִי וַיִּשְׁמֹר מִשְׁמַרְתִּי מִצְוֹתַי חֻקּוֹתַי וְתוֹרֹתָי. דְּכֵיוָן שֶׁלָּמַד מִשֵּׁם הַתּוֹרָה, קִבֵּל עַל עַצְמוֹ שֶׁיִּשְׁמוֹר הַתּוֹרָה כּוּלָּהּ, וּלְפִיכָךְ בֵּירַר לָהֶם הַקָדוֹשׁ בָּרוּךְ הוּא שֶׁבַע מִצְוֹת מִן הַתּוֹרָה כְּדֵי שֶׁיִּשְׁמְרוּ אוֹתָם.</p>"],[9514011994,"<p>רַבִּי פָּתַח בִּכְנֶסֶת יִשְׂרָאֵל כְּנֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא, וַיְשַׁלַּח אֶת הָעוֹרֵב, דְּאָמַר רִבִּי פִּנְחָס, כְּתִיב, (שמואל ב טו) וַיֹּאמֶר דָּוִד כו', קוּמוּ וְנִבְרְחָה כִּי לֹא תִהְיֶה לָנוּ פְּלֵיטָה מִפְּנֵי אַבְשָׁלוֹם. וְאַף עַל פִּי שֶׁבָּרַח, מַאי כְּתִיב בֵּיהּ, (תהלים ג) מִזְמוֹר לְדָוִד בְּבָרְחוֹ מִפְּנֵי אַבְשָׁלוֹם בְּנוֹ. וְאַף עַל פִּי שֶׁהָיָה בּוֹרֵחַ וְנִגְרַשׁ מִמַּלְכוּתוֹ, לֹא מָנַע עַצְמוֹ מִלּוֹמַר שִׁירָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלָשׁוּב וּלְהִתְחַנֵּן לְפָנָיו. וַיְשַׁלַּח אֶת הָעוֹרֵב, זֶהוּ דָוִד, שֶׁהָיָה קוֹרֵא עִמָּהֶן תָּמִיד כְּעוֹרֵב.</p>"],[9514011995,"<p>דָּבָר אַחֵר, הָעוֹרֵב שֶׁבָּא מִיְהוּדָה, שֶׁנִּקְרָא עוֹרֵב, שֶׁנֶּאֱמַר, (בראשית מג) אָנֹכִי אֶעֶרְבֶנּוּ. הָעֹרֵב כְּתִיב, בְּלֹא וָא\"ו. אָמַר רִבִּי פִּנְחָס, לָמָּה נִקְרָא שְׁמוֹ עוֹרֵב, שֶׁהָיָה הוֹלֵךְ בֶּהָרִים כְּעוֹרֵב. וְהַיְינוּ דְּאָמַר לְשָׁאוּל, (שמואל א כו) כַּאֲשֶׁר יִרְדֹּף הַקֹּרֵא בֶּהָרִים. אָמַר לוֹ, שַׂמְתַּנִּי לִהְיוֹת כְּקוֹרֵא בֶּהָרִים, כְּתִיב הָכָא קוֹרֵא, וּכְתִיב הָתָם, (תהלים קמז) לִבְנֵי עוֹרֵב אֲשֶׁר יִקְרָאוּ.</p>"],[9514011996,"<p>וְאָמַר רִבִּי פִּנְחָס, בֹּא וּרְאֵה מַה בֵּין מַלְכֵי יְהוּדָה לְמַלְכֵי יִשְׂרָאֵל. שָׁלַח הַקָּדוֹשׁ בָּרוּךְ הוּא לְדָוִד, וְגַרְשֵׁהוּ מִמַּלְכוּתוֹ, וּמִיָּד שָׁב בִּתְשׁוּבָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאַל תִּתְמַהּ עַל זֶה, וַאֲפִילּוּ מְנַשֶּׁה מֶלֶךְ יְהוּדָה, שֶׁהָיָה רָשָׁע, מִיָּד שָׁב בִּתְשׁוּבָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלָקַח אוּמָּנוּת אֲבוֹתָיו, וְשָׁב לְמַלְכוּתוֹ.</p>"],[9514011997,"<p>וְזֶהוּ שֶׁבָּא הַכָּתוּב לְהוֹרוֹת, וַיְשַׁלַּח אֶת הָעוֹרֵב, זֶה דָּוִד, שֶׁהָיָה קוֹרֵא תָּמִיד כְּעוֹרֵב, וְשִׁלְּחָהוּ הַקָּדוֹשׁ בָּרוּךְ הוּא מִמַּלְכוּתוֹ, וְהוֹצִיאוֹ מִבֵּיתוֹ, וּמַה כְּתִיב בֵּיהּ. וַיֵּצֵא יָצוֹא וָשׁוֹ\"ב. דִּכְתִיב, (שמואל ב טו) וְדָוִד עֹלֶה בְּמַעֲלֵה הַזֵּיתִים עֹלֶה וּבוֹכֶה וְרֹאשׁ לוֹ חָפוּי. הָיָה יוֹצֵא וְשָׁב בִּתְשׁוּבָה, וּמִתְוַדֶּה עַל חַטֹאתָיו, וּמְבַקֵּשׁ רַחֲמִים עֲלֵיהֶם, וְיָדַע כִּי חַטֹאתָיו עָשׂוּ לוֹ שֶׁנִּשְׁלַח מִמַּלְכוּתוֹ וְנִגְרַשׁ.</p>"],[9514011998,"<p>וּבְכָל דָּבָר וְדָבָר דְּחֶטְאָה גָרֵים בְּמַלְכוּתוֹ, אוֹ בְּיִשְׂרָאֵל, הָיָה תּוֹלֶה הַדָּבָר בּוֹ, וַהֲוָה יָדַע דְּהוּא הָיָה גָּרֵים. עַד יְבשֶׁת הַמַּיִם, שֶׁהֵשִׁיבוּהוּ לֹא עָלֶיךָ הַדָּבָר, אֶלָּא אֶל שָׁאוּל וְאֶל בֵּית הַדָּמִים.</p>"],[9514011999,"<p>תָּא חֲזֵי, דִּכְתִיב (שם כא) וַיְהִי רָעָב בִּימֵי דָוִד שָׁלשׁ שָׁנִים שָׁנָה אַחֲרֵי שָׁנָה וַיְבַקֵּשׁ דָּוִד אֶת פְּנֵי ה', דְּסָבַר דְּהוּא הֲוָה גָּרֵים, אָמַר לֵיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא עָלֶיךָ זוֹ אֶלָּא עַל שָׁאוּל. עַד יְבשֶׁת הַמַּיִם, הָיָה תּוֹלֶה הַכֹּל בְּעַצְמוֹ, וּמִיָּד הָיָה שָׁב בִּתְשׁוּבָה. וְאָז לֹא הוּצְרַךְ לַחֲזוֹר בִּתְשׁוּבָה, שֶׁהַדָּבָר לֹא בָּא בִּשְׁבִילוֹ. הֲדָא הוּא דִכְתִיב, (בראשית ח׳:ז׳) וַיֵּצֵא יָצוֹא וָשׁוֹב עַד יְבשֶׁת הַמַּיִם, דַּאֲזַי לֹא הָיָה הַדָּבָר תָּלוּי בּוֹ.</p>"],[9514012000,"<p>אָמַר רִבִּי פִּנְחָס, רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְנַסּוֹת אֶת יִשְׂרָאֵל, וּשְׁלָחָם לְבָבֶל. שֶׁנֶּאֱמַר, (שם) וַיְשַׁלַּח אֶת הַיּוֹנָה מֵאִתּוֹ, זוֹ כְּנֶסֶת יִשְׂרָאֵל. רְאֵה מַה כְּתִיב בָּהּ, וְלֹא מָצְאָה הַיּוֹנָה מָנוֹחַ לְכַף רַגְלָהּ. שֶׁהִכְבִּיד עוּלָהּ מֶלֶךְ בָּבֶל, בְּרָעָב וּבְצָמָא וּבַהֲרִיגַת צַדִּיקִים הַרְבֵּה. וּמִשּׁוּם כּוֹבֶד עוּלָהּ, וַתָּשָׁב אֵלָיו אֶל הַתֵּיבָה, וְחָזְרָה בִּתְשׁוּבָה וְקִבְּלָהּ.</p>"],[9514012001,"<p>חָטְאָה כְּנֶסֶת יִשְׂרָאֵל כְּמִתְּחִלָּה, וַיּוֹסֶף לְהַגְלוֹתָם, שֶׁנֶּאֱמַר (שם) וַיּוֹסֶף שַׁלַּח אֶת הַיּוֹנָה מֵאִתּוֹ, בְּגָלוּת אַחֶרֶת שֶׁל יָוָן. דְּאָמַר רִבִּי יְהוּדָה, גָלוּת יָוָן אַחְשִׁיךְ פְּנֵיהוֹן דְּיִשְׂרָאֵל כְּשׁוּלֵי קְדֵרָה.</p>"],[9514012002,"<p>וּמֵרוֹב צַעֲרָם וְדוֹחֲקָם מַה כְּתִיב בֵּיהּ. וַתָּבֹא אֵלָיו הַיּוֹנָה לְעֵת עֶרֶב. מַה לְּעֵת עֶרֶב, דְּלָא הֲוָה נְהִירָא לְהוֹן שַׁעֲתָא דְּרַוְוחָא, כְּמָה דַּהֲוַת עֲבִידָא בְּקַדְמִיתָא, וְאִתְקַטְלֵי צַדִּיקַיָא, וְאִתְחַשַׁךְ יְמָמָא, וְאַעֲרֵיב לָהֶן שִׁמְשָׁא וְלָא יָכְלִין לְמֵיקַם מִן קֳדָם דּוֹחֳקָא סַגִּיאָה דַּהֲוֵי עֲלֵיהוֹן, שֶׁנֶּאֱמַר (ירמיהו ד׳:י״ג) אוֹי לָנוּ כִּי פָנָה הַיּוֹם כִּי יִנָּטוּ צִלְּלֵי עֶרֶב. כִּי פָנָה הַיּוֹם, אֵלוּ הֵן צַדִּיקַיָיא הַמְאִירִים כַּשֶׁמֶשׁ. כִּי יִנָטוּ צִלְּלֵי עֶרֶב, שֶׁנִּשְׁאֲרוּ כְּעוֹלְלוֹת בָּצִיר וְזֶהוּ לְעֵת עֶרֶב וְלֹא בִּזְמַן דִּנְהִירִין לְהוֹן צַדִּיקַיָא כְּשִׁמְשָׁא.</p>"],[9514012003,"<p>(בראשית ח) וְהִנֵּה עָלֶה זַיִת טָרָף בְּפִיהָ. לוּלֵי שֶׁהֵעִיר הַקָּדוֹשׁ בָּרוּךְ הוּא רוּחַ הַכֹּהֲנִים, שֶׁהָיוּ מַדְלִיקִין נֵרוֹת בְּשֶׁמֶן זַיִת, אֲזַי אָבְדָה פְּלֵיטַת יְהוּדָה מִן הָעוֹלָם. וּבְכָל פַּעַם וּפַעַם שָׁבָה בִּתְשׁוּבָה וְנִתְקַבְּלָה. אָמַר רִבִּי פִּנְחָס, חוּץ מִן גָּלוּתָא רְבִיעָאָה, דַּעֲדַיִין לֹא שָׁבָה, וְהַכֹּל תָּלוּי בִּתְשׁוּבָה.</p>"],[9514012004,"<p>וְאָמַר רִבִּי פִּנְחָס, אֵין לְךָ בְּכָל פַּעַם וּפַעַם, שֶׁלֹּא הִתְעַכֵּב הַקָּדוֹשׁ בָּרוּךְ הוּא גְּזַר דִּינָא שֶׁל כְּנֶסֶת יִשְׂרָאֵל, שֶׁבַע שְׁמִיטִין, וְשֶׁבַע יוֹבְלוֹת, שֶׁמָּא תַּחְזוֹר בִּתְשׁוּבָה. הֲדָא הוּא דִכְתִיב, (בראשית ח׳:י״ב) וַיִּיָחֶל עוֹד שִׁבְעַת יָמִים אֲחֵרִים, בַּר מִן קֳדָמָאי.</p>"],[9514012005,"<p>וַיְשַׁלַּח אֶת הַיּוֹנָה, בְּגָלוּת אֱדוֹם. וְלֹא יָסְפָה שׁוּב אֵלָיו עוֹד, דְּעַד הַיּוֹם לֹא חָזְרָה בִּתְשׁוּבָה, וְלֹא הֵעִירָה רוּחָהּ. דְּאָמַר רִבִּי פִּנְחָס, אִלְמָלֵי חָזְרָה בִּתְשׁוּבָה לֹא נִשְׁתַּיְירָה בַּגָּלוּת יוֹמָא חַד. רַבִּי אֱלִיעֶזֶר אוֹמֵר, כָּל הַגָּלֻיּוֹת שֶׁגָּלְתָה כְּנֶסֶת יִשְׂרָאֵל, נָתַן לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא זְמַן וְקֵץ, וְנִתְעוֹרְרָה תָּמִיד בִּתְשׁוּבָה, וְגָלוּת הָאַחֲרוֹן אֵין לוֹ קֵץ וּזְמָן, אֶלָּא הַכֹּל תָּלוּי בִּתְשׁוּבָה. שֶׁנֶּאֱמַר, (דברים ל׳:ב׳) וְשַׁבְתָּ עַד ה' אֱלֹהֶיךָ וְשָׁמַעְתָּ בְקוֹלוֹ. וּכְתִיב, (שם) אִם יִהְיֶה נִדַחֲךָ בִּקְצֵה הַשָּׁמַיִם מִשָּׁם יְקַבֶּצְךָ ה' אֱלֹהֶיךָ וּמִשָּׁם יִקָּחֶךָ.</p>"],[9514012006,"<p>אָמַר לֵיהּ רַבִּי עֲקִיבָא, אִם כֵּן, הֵיאַךְ יְהֵא דָא לְהִתְעוֹרְרָא כּוֹלְהוֹן כַּחֲדָא בִּתְשׁוּבָה, מַאן דַּהֲוֵי בְּסָיְיפֵי שְׁמַיָא, וּמַאן דְּהוּא בְּסָיְיפֵי אַרְעָא, הֵיךְ יִתְחַבְּרוּן כַּחֲדָא לְמֶעְבַּד תְּשׁוּבָה.</p>"],[9514012007,"<p>אָמַר לוֹ רַבִּי אֱלִיעֶזְר, חַיֶּיךָ, דְּאִי יַחְזְרוּן בִּתְשׁוּבָה רֵישֵׁי כְּנִישְׁתָּא, אוֹ חָדָא כְּנִישְׁתָּא, בִּזְכוּתָם יִתְכְּנֵשׁ כָּל גָּלוּתָא, דְּקוּדְשָׁא בְּרִיךְ הוּא אִיסְתְּכֵי תְּדִירָא, אֵימָתַי יַחְזְרוּן, וְיַעֲבֵד לְהוֹן טָבָא, דִּכְתִיב (ישעיהו ל׳:י״ח) וְלָכֵן יְחַכֶּה ה' לַחֲנַנְכֶם. מְחַכֶּה תָּמִיד אֵימָתַי יַעֲשׂוּ תְּשׁוּבָה.</p>"],[9514012008,"<p>אָמַר רִבִּי יוֹסֵי, אִיתָא הָא, כְּהָא דְאָמַר רִבִּי פִּנְחָס, דִּכְתִיב וְלֹא יָסְפָה שׁוּב אֵלָיו עוֹד. לֹא נֶאֱמַר וְלֹא יָסַף שׁוּב אֵלֶיהָ, אֶלָּא הִיא לֹא יָסְפָה שׁוּב אֵלָיו, מִכְּלַל דְּהוּא מְזוּמָן וּמְחַכֶּה אֵימָתַי תָּשׁוּב.</p>"],[9514012009,"<p>רַבִּי יְהוּדָה אֲמַר, תָּא חֲזֵי, הַאי דִּכְתִיב בְּיַעֲקֹב (בראשית ל״ב:כ״ה) וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ וַיְאָבֶק אִישׁ עִמּוֹ עַד עֲלוֹת הַשַּׁחַר. בֵּיהּ זִימְנָא אִתְיַהֲבָא רְשׁוּתָא לְכָל חֵילֵי דִשְׁמַיָא, לְאִינוּן רַבְרְבִין דְּאִתְמַנוּן עַל מַלְכְּוָותָא, וְאִתְפְּרָשׁוּ אִלֵּין לְשַׁלְּטָאָה עַל אִלֵּין, וְאִתְיַהֲבַת רְשׁוּתָא וְשׁוּלְטָנָא לְרַבְרְבָא דֶאֱדוֹם, לְשַׁלְטָאָה עַל אוּמַּיָיא.</p>"],[9514012010,"<p>בֵּיהּ שַׁעֲתָא מַה כְּתִיב. וַיִּוָּתֶר יַעֲקֹב לְבַדּוֹ, דְּעַד כְּעָן לָא הֲווֹ לֵיהּ בִּנְיָמִין וְלָא אַפּוֹטְרוֹפּוֹסָא בִּשְׁמַיָא.</p>"],[9514012011,"<p>וַיְאָבֶק אִישׁ עִמּוֹ, דֵּין הוּא סמאל, רַבָּא דֶאֱדוֹם. וּבְעָא דְּיִתְיְיהֵב יַעֲקֹב תְּחוֹת שִׁעְבּוּדָא דֶּאֱדוֹם, וּמִשּׁוּם זְכוּתָא רַבְרְבָא דְּהֲוָה בְּיַעֲקֹב, לָא אִתְיְיהֵיב בִּידֵיהּ.</p>"],[9514012012,"<p>אָמַר רִבִּי יְהוּדָה, בֵּיהּ שַׁעֲתָא אִתְכְּנָשׁוּ כָּל חֵילָא דִשְׁמַיָא, וּבְעוֹ לְמִיטְעַן עִם סמאל, בְּגִינֵיהּ דְּיַעֲקֹב. אֲמַר קוּדְשָׁא בְּרִיךְ הוּא, לָא אִיצְטְרִיךְ יַעֲקֹב לְשׁוּם חַד מִנְּכוֹן, הָא זְכוּתֵיהּ דְּיִטְעוֹן עִמֵּיהּ. מִיָּד וַיֵּאָבֶק אִישׁ עִמּוֹ, טָעִין עִמֵּיהּ.</p>"],[9514012013,"<p>אָמַר רִבִּי יוּדָא, תָּא חֲזֵי, מַה כְּתִיב בֵּיהּ. (שם) וַיַּרְא כִּי לֹא יָכוֹל לוֹ, דְּהֲוָה סַגִּיאָה זְכוּתֵיהּ, וְלָא יָכֵיל בְּטַעֲנָתֵיהּ לְאִשְׁתַּעְבְּדָא יַעֲקֹב תְּחוֹת יְדָא דֶאֱדוֹם. מִיָּד וַיִּגַּע בְּכַף יְרֵכוֹ. אִלֵּין אִינוּן בְּנוֹהִי נָפְקֵי יְרֵכֵיהּ.</p>"],[9514012014,"<p>בֵּיהּ שַׁעֲתָא אִתְחְלַשׁ יַעֲקֹב, וְלָא יָכֵיל לְמִטְעַן עִמֵּיהּ, דִּכְתִיב וַתֵּקַע כַּף יֶרֶךְ יַעֲקֹב בְּהֵאָבְקוֹ עִמּוֹ, בְּאַטְעָנוּתֵיהּ עִמֵּיהּ. וְאִתְיַהֲבָא רְשׁוּתָא לִסמאל, בְּנוֹהִי דְּיַעֲקֹב תְּחוֹת יְדָא דֶאֱדוֹם, כָּל זִימְנָא דְּיַעַבְרוּן עַל אוֹרַיְיתָא.</p>"],[9514012015,"<p>רַבִּי הֲוָה יָתֵיב יוֹמָא חַד, וַהֲוָה מִסְתַּכֵּל בְּהָא מִילְּתָא, דִּכְתִיב (דברים ד׳:ל׳) בַּצַּר לְךָ וּמְצָאוּךָ כֹּל הַדְּבָרִים הָאֵלֶּה בְּאַחֲרִית הַיָּמִים וְשַׁבְתָּ עַד ה' אֱלֹהֶיךָ וְשָׁמַעְתָּ בְּקֹלוֹ. אֲמַר, מַה דַּאֲמַר משֶׁה דִּיהֱוֵי בְּסוֹף יוֹמַיָא, כָּל אִינוּן עָקְתִין הָא אֲתָא, וּתְשׁוּבָה עַד כְּעָן לָא אִתְעֲבִידָא.</p>"],[9514012016,"<p>עַד דְּהֲוָה יָתֵיב, אָתָא אֵלִיָּהוּ זָכוּר לָטוֹב, אָמַר לֵיהּ, רַבִּי בְּמַאי אִתְעַסַּקְתְּ. אָמַר לֵיהּ בְּהַאי דְּאָמְרָה תּוֹרָה, דְּכַד יֵיתוּן עָקְתִין לְיִשְׂרָאֵל בְּסוֹף יוֹמַיָא, דְּיַעַבְדוּן תְּשׁוּבָה לְאַלְתָּר, דִּכְתִיב בְּאַחֲרִית הַיָּמִים וְשַׁבְתָּ, וְעַד כְּעָן לָא תָבוּ בִּתְיוּבְתָּא.</p>"],[9514012017,"<p>אָמַר לֵיהּ חַיֶּיךָ רַבִּי, בְּהַאי מִילְּתָא אִתְעַסַּק קוּדְשָׁא בְּרִיךְ הוּא יוֹמָא דֵין, וַאֲתָא מִיכָאֵל אַפֹּטְרוֹפְּסָא רַבָּה דִילְהוֹן, וּבָעֵי דְּאֵימָתַי יִפְקוֹן בְּנוֹהִי רְחִימוֹהִי מִתְּחוֹת גָּלוּתָא דֶּאֱדוֹם. וַאֲמַר, אַתְּ כְּתַבְתְּ בְּאוֹרַיְיתָךְ, דְּכַד יִסְבְּלוּן אִינוּן עוֹנְשַׁיָיא עַל מַה דַּעֲבָדוּ, מַאי כְּתִיב. (שם) כִּי אֵל רַחוּם ה' אֱלֹהֶיךָ.</p>"],[9514012018,"<p>אָמַר לֵיהּ, יֵיתֵי סמאל אַפּוֹטְרוֹפְּסָא דֶּאֱדוֹם וְיַטְעִין עִמֵּיהּ קַמָּאי. אֲתָא סמאל. וְטָעִין מִיכָאֵל מִלְּתָא דָא, כִּדְבְקַדְמֵייתָא. אֲמַר סמאל, מָארֵי דְעָלְמָא, אַתְּ הוּא דַאֲמַרְתְּ דִּתְהֱוֵי כְּנִישְׁתָּא דְיִשְׂרָאֵל תְּחוֹת שׁוּלְטָנָא דֶאֱדוֹם, עַד דְּיֶהֱוָן זַכָּאִין קַמָּךְ, וְהָא כָּלְהוֹן חַיָּיבִין עַד יוֹמָא דֵין.</p>"],[9514012019,"<p>בֵּיהּ שַׁעֲתָא אַנְזִיפֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, עַל דַּאֲמַר דֵּלָטוֹרָא עַל בְּנוֹהִי, וְעָרַק תְּלַת אַלְפֵי מִילִין. וַאֲמַר לְמִיכָאֵל, מִיכָאֵל הֲוָה לָךְ לְמֶהֱוֵי שְׁפִיל לְרֵישֵׁיהּ דִּקְרָא, דִּכְתִיב וְשַׁבְתָּ עַד ה' אֱלֹהֶיךָ וְשָׁמַעְתָּ בְקוֹלוֹ, וְאַחַר כַּךְ כְּתִיב כִּי אֵל רַחוּם ה' אֱלֹהֶיךָ.</p>"],[9514012020,"<p>אֲמַר מִיכָאֵל, מָארֵי דְעָלְמָא, הֲוָה לָךְ לְרַחֲמָא עֲלַיְיהוּ, אַתְּ רַחוּם, וְכָךְ אִתְקְרִיאַת. אָמַר לֵיהּ אוֹמָאָה אוֹמֵיתִי בְּיוֹמָא דְאִתְגַּזְרָא דִינָא קֳדָמָאי, עַד דִּי יְתוּבוּן. וְאִי כְּנִישְׁתָּא דְיִשְׂרָאֵל, אַפְתְּחַת תְּשׁוּבָה כְּעֵינָא דְּמַחֲטָא, אֲנָא אֶפְתַּח לָהּ תַּרְעִין רַבְרְבִין.</p>"],[9514012021,"<p>תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא מָגֵן לְצַדִּיקַיָא, דְּלָא יִשְׁלְטוּן בְּהוֹן בְּנֵי אֱנָשָׁא, וְקוּדְשָׁא בְּרִיךְ הוּא אָגִין עַל אַבְרָהָם, דְּלָא יִשְׁלְטוּן בֵּיהּ וּבְאִנְתְּתֵיהּ.</p>"],[9514012022,"<p>תָּא חֲזֵי, שְׁכִינְתָּא לָא אִתְעַדֵּי מֵעִם שָׂרָה. בְּהַהוּא לֵילְיָא, אָתָא פַּרְעֹה לְמִיקְרַב בַּהֲדָהּ. אֲתָא מַלְאָכָא, וְאַלְקֵי לֵיהּ. כָּל אֵימַת דְּהֲוָה שָׂרָה אָמְרָה אַלְקֵי, הֲוָה מַלְקֵי.</p>"],[9514012023,"<p>וְאַבְרָהָם הוּא אַתְקֵיף בְּמָארֵיהּ, דְּהָא שָׂרָה לָא יְהוֹן יָכְלֵי לְשַׁלְטָאָה עֲלָהּ. הֲדָא הוּא דִכְתִיב, (משלי כ״ח:א׳) וְצַדִּיקִים כִּכְפִיר יִבְטָח. וְהָכָא נִסְיוֹנָא הִיא, דְּלָא הִרְהֵר אַבְרָהָם אֲבַתְרֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9514012024,"<p>אָמַר רַבִּי, תָּא חֲזֵי דְבְּגִין כָּךְ, לָא פַקֵּיד לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְנַחֲתָא לְמִצְרַיִם, אֶלָּא הוּא מִגַּרְמֵיהּ נָחַת, בְּגִין דְּלָא יְהֵא פִּתְחוֹן פֶּה לִבְנֵי עָלְמָא, דַּאֲמַר לֵיהּ כָּךְ, וּלְבָתַר אִצְטָעֵר עַל אִנְתְּתֵיהּ. עַד כָּאן.</p>"],[9514012025,"<p><Noneb> מִדְרָשׁ הַנֶּעֱלָם </b></p>"],[9514012026,"<p>לֶךָ לְךָ. רַבִּי יְהוּדָה פָּתַח, (שיר השירים ב׳:י״ב) הַנִּצָּנִים נִרְאוּ בָאָרֶץ עֵת הַזָּמִיר הִגִּיעַ וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ. אָמַר רִבִּי יְהוּדָה, בֹּא וּרְאֵה, כַּמָּה יֵשׁ לוֹ לָאָדָם לְהַכְשִׁיר מַעֲשָׂיו לִפְנֵי בּוֹרְאוֹ, וּלְהִתְעַסֵּק בְּתוֹרָתוֹ יוֹמָם וָלָיְלָה. שֶׁמַּעֲלַת הַתּוֹרָה לְמַעְלָה מִן כָּל הַמַּעֲלוֹת.</p>"],[9514012027,"<p>הְאָמַר רִבִּי יְהוּדָה, תְּרֵין טָבִין רַבְרְבִין אִית בְּאוֹרַיְיתָא, חַיִּים, וְעוֹתְרָא. דִּכְתִיב, (משלי ג׳:ט״ז) אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ עשֶׁר וְכָבוֹד. אָמַר רַב פָּפָּא, אִלֵּין תְּלָתָא הֲווֹ. אָמַר לֵיהּ רַבִּי יְהוּדָה, כָּבוֹד בִּכְלַל הָעוֹשֶׁר הוּא. דְּמַאן דְּאִית לֵיהּ עוֹתְרָא, אִית לֵיהּ יְקָרָא, וּבַמֶּה יִזְכֶּה הָאָדָם לַכֹּל, בִּשְׁבִיל הַתּוֹרָה.</p>"],[9514012028,"<p>אָמַר רִבִּי יְהוּדָה, תָּא חֲזֵי, אֵין בְּכָל לַיְלָה וָלַיְלָה, שֶׁאֵינוֹ אוֹחֵז מטטרו\"ן שַׂר הַפָּנִים, כָּל נִשְׁמָתָן שֶׁל תַּלְמִידֵי חֲכָמִים, הָעוֹסְקִים בַּתּוֹרָה לִשְׁמָהּ, וּמַרְאֶה אוֹתָן לִפְנֵי הַקָדוֹשׁ בָּרוּךְ הוּא, וּמַמְתִּינִים מַלְאֲכֵי הַשָּׁרֵת וְדוֹמְמִים מִלּוֹמַר שִׁירָה, עַד שֶׁיִּתְכַּנְפוּ נַפְשׁוֹת הַצַּדִּיקִים עִמָּהֶם, וִיזַמְּרוּ בְּיַחַד לְאֵל עֶלְיוֹן.</p>"],[9514012029,"<p>שֶׁנֶּאֱמַר הַנִּצָּנִים נִרְאוּ בָאָרֶץ, אֵלּוּ הָעוֹסְקִים בַּתּוֹרָה לִשְׁמָהּ. עֵת הַזָּמִיר הִגִּיעַ, אָז הוּא עֵת לְזַמֵּר לְבוֹרְאָם בְּיַחַד. וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ, זֶה מטטרון, הַבָּא לֶאֱסוֹף נִשְׁמָתָן שֶׁל צַדִּיקִים, לְזַמֵּר לְיוֹצְרָם בְּכָל לַיְלָה וָלַיְלָה, שֶׁנֶּאֱמַר (תהילים קמ״ט:ה׳) יַעְלְזוּ חֲסִידִים בְּכָבוֹד יְרַנְּנוּ עַל מִשְׁכְּבוֹתָם. מַהוּ בְּכָבוֹד. אָמַר רִבִּי יְהוּדָה זֶה מטטרו\"ן.</p>"],[9514012030,"<p>אָמַר רִבִּי יַעֲקֹב בַּר אִידֵי, כָּל נִשְׁמוֹתָן שֶׁל צַדִּיקִים, נִגְזְרוּ מִתַּחַת כִּסֵּא הַכָּבוֹד, לִנְהֹג אֶת הַגּוּף, כְּאָב הַמַּנְהִיג אֶת הַבֵּן. כִּי בִּלְתִּי הַנְּשָׁמָה, לֹא יוּכַל הַגּוּף לְהִתְנַהֵג, וְלֹא לָדַעַת וְלַעֲשׂוֹת רְצוֹן בּוֹרְאוֹ. דְּהָא אָמַר רִבִּי אַבָּהוּ, הַנְּשָׁמָה הִיא מוֹרָה וּמְלַמְּדָה לָאָדָם, וּמֵחַנַכְתּוֹ בְּכָל דֶּרֶךְ יָשָׁר.</p>"],[9514012031,"<p>וּבְשָׁעָה שֶׁשּׁוֹלֵחַ הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָהּ מִמְּקוֹם הַקּוֹדֶשׁ, מְבָרֵךְ אוֹתָהּ בְּשֶׁבַע בְּרָכוֹת, הֲדָא הוּא דִכְתִיב (בראשית י״ב:א׳) וַיֹּאמֶר ה' אֶל אַבְרָם, זוֹ הִיא הַנְּשָׁמָה, שֶׁהִיא א\"ב, לְלַמֵּד אֶת הַגּוּף, וְרָ\"ם עָלָיו, שֶׁמִּמָּקוֹם רָם וְנִשָּׂא בָּאָה. וּמָה אוֹמֵר לָהּ, לֶךְ לְךָ מֵאַרְצְךָ וּמִמּוֹלַדְתְּךָ, מִדִּירָתְךָ, וּמִמְּקוֹמְךָ, וּמֵהַנָּאָתְךָ. וּמִבֵּית אָבִיךָ, אָמַר רִבִּי יַעֲקֹב זוֹ הִיא אַסְפַּקְלַרְיָא הַמְאִירָה. אֶל הָאָרֶץ אֲשֶׁר אַרְאֶךָּ, כְּלוֹמַר לְגוּף פְּלוֹנִי, לְגוּף קָדוֹשׁ. לְגוּף יָשָׁר.</p>"],[9514012032,"<p>וְעִם כָּל דָּא, וַאֲבָרְכָה מְבָרֲכֶיךָ, אוֹתָם הַנּוֹהֲגִים עִמְּךָ מִדּוֹת טוֹבוֹת, מִדּוֹת יְשָׁרוֹת. אוֹתָם הַמְבָרְכִים אוֹתִי בִּשְׁבִילְךָ, וְאוֹמְרִים כָּל זְמַן שֶׁהַנְּשָׁמָה בְּקִרְבִּי מוֹדֶה אֲנִי לְפָנֶיךָ ה' אֱלֹהַי. וּמְקַלֶּלְךָ אָאֹר, אוֹתָם הַמְקַלְּלִים אוֹתְךָ, וּמְקַלְקְלִים מַעֲשֵׂיהֶם וּדְרָכֵיהֶם.</p>"],[9514012033,"<p>(שם) וַיֵּלֶךְ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו ה'. כֵּיוָן שֶׁנִּתְבָּרְכָה בְּשֶׁבַע בְּרָכוֹת הַלָּלוּ, מַה כְּתִיב, וַיֵּלֶךְ אַבְרָם, זוֹ הִיא הַנְּשָׁמָה, שֶׁהִיא אָב לַגּוּף. וְרָם מִמְּקוֹם הָרָמִים. כַּאֲשֶׁר דִּבֶּר אֵלָיו ה', לְהִכָּנֵס בְּאוֹתוֹ הַגּוּף שֶׁנִּצְטַוָּה לְהַנְהִיגוֹ וּלְלַמְּדוֹ.</p>"],[9514012034,"<p>אָמַר רַבִּי יַעֲקֹב, רְאֵה מַה כְּתִיב בֵּיהּ, כֵּיוָן שֶׁבָּאָה לִיכָּנֵס בַּגּוּף, וַיֵּלֶךְ אִתּוֹ לוֹט, זֶהוּ יֵצֶר הָרָע, הַמְזוּמָן לִיכָּנֵס עִם הַנְּשָׁמָה בְּיַחַד כֵּיוָן שֶׁנּוֹלַד אָדָם, וּמִנַּיִן שֶׁנִּקְרָא יֵצֶר הָרָע כָּךְ, שֶׁנֶּאֱמַר (בראשית ח) כִּי יֵצֶר לֵב הָאָדָם רַע מִנְּעֻרָיו, וְזֶהוּ לוֹט שֶׁנִּתְאָרֵר בָּעוֹלָם.</p>"],[9514012035,"<p>וְאָזְלָא הָא כִּי הָא דְּאָמַר רִבִּי יִצְחָק, הַנָּחָשׁ שֶׁהֵשִּׁיא לְחַוָּה, הוּא יֵצֶר הָרָע. וְרָאִינוּ שֶׁנִּתְקַלֵּל, שֶׁנֶּאֱמַר (שם ג) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה, וּלְפִיכָךְ נִקְרָא לוֹט. שֶׁבְּשָׁעָה שֶׁהַנְּשָׁמָה בָּא לִיכָּנֵס בַּגּוּף, מִיָּד וַיֵּלֶךְ אִתּוֹ לוֹט, שֶׁהוּא מְזוּמָן לִיכָּנֵס עִמּוֹ, וּלְהַשְּׂטִין לָאָדָם, וְלִהְיוֹת מְקַטְרֵג לְהַנְּשָׁמָה.</p>"],[9514012036,"<p>אָמַר רִבִּי יַעֲקֹב בַּר ר' אִידֵי, מִנַּיִן מַה שֶּׁאָמַרְנוּ שֶׁהוּא מָשָׁל עַל הַנְּשָׁמָה. מִמַּה דִּכְתִיב אַחַר כַּךְ, (שם יב) וַיִּקַּח אַבְרָם אֶת שָׂרַי אִשְׁתּוֹ, זֶהוּ הַגּוּף. וְאֶת לוֹט בֶּן אָחִיו, זֶהוּ יֵצֶר הָרָע, שֶׁהוּא בֶּן אָחִיו, מְשׁוּתָּף וְנִדְבַּק עִם הַגּוּף. וְאֶת כָּל רְכוּשָׁם אֲשֶׁר רָכָשׁוּ, אֵלּוּ מַעֲשֵׂיהֶם. וַיֵּצְאוּ לָלֶכֶת אַרְצָה כְּנַעַן, כּוּלָּם מְדוּבָּקִים לָלֶכֶת בְּהַבְלֵי הָעוֹלָם, הוֹלְכִים אַחֲרֵי בִּצְעָם וְהִרְהוּרִים.</p>"],[9514012037,"<p>וַיַּעֲבֹר אַבְרָם בָּאָרֶץ עַד מְקוֹם שְׁכֶם עַד אֵלוֹן מוֹרֶה, בְּכָל מָקוֹם שֶׁזֶּה מִתְאַוֶּה, הַנְּשָׁמָה עִמּוֹ. וְהַכְּנַעֲנִי אָז בָּאָרֶץ, זוֹ הַתַּאֲוָה, שֶׁהִיא דְּבֵקָה בַּגּוּף.</p>"],[9514012038,"<p>כֵיוָן שֶׁפּוֹקֵד הַקָּדוֹשׁ בָּרוּךְ הוּא מַעֲשֵׂיהֶם, וּמוֹצִיא הַנְּשָׁמָה מִן הַגּוּף, הַנְּשָׁמָה רוֹצָה לַעֲלוֹת לְמַעְלָה, רְאֵה מַה כְּתִיב בָּהּ. (שם יג) וַיֵּלֶךְ לְמַסָּעָיו מִנֶּגֶב וְעַד בֵּית אֵל, וּרְצוֹנָהּ לַחֲזוֹר אֶל הַמָּקוֹם אֲשֶׁר הָיָה שָׁם אָהֳלֹה בַּתְּחִלָּה. אָמַר רִבִּי יַעֲקֹב, אָהֳלָהּ כְּתִיב בְּה\"א, וַאֲזַי הִיא עוֹמֶדֶת בֵּין בֵּית אֵל וּבֵין הָעַי, בֵּין לַעֲלוֹת לְמַעְלָה וּבֵין לֵירֵד לְמַטָה.</p>"],[9514012039,"<p>זָכְתָה עוֹלָה אֶל מְקוֹם הַמִּזְבֵּחַ, (שם) אֲשֶׁר עָשָׂה שָׁם בָּרִאשׁוֹנָה, מָקוֹם אֲשֶׁר מִיכָאֵל הַשַּׂר הַגָּדוֹל מַקְרִיב נִשְׁמָתָן שֶׁל צַדִּיקִים. וַיִּקְרָא שָׁם אַבְרָם בְּשֵׁם ה', הַנְּשָׁמָה נוֹתֶנֶת שֶׁבַח וְהוֹדָאָה בִּירוּשָׁלַיִם שֶׁל מַעְלָה, שֶׁזָּכְתָה לְאוֹתָהּ הַמַּעֲלָה. וְאִם לֹא זָכְתָה, מַה כְּתִיב. (שם יב) וַיִּסַּע אַבְרָם הָלּוֹךְ וְנָסוֹעַ הַנֶּגְבָּה, דּוֹחִין אוֹתָהּ וְהוֹלֶכֶת עַד שֶׁסּוֹבֶבֶת כָּל הָעוֹלָם עַד שֶׁתְּקַבֵּל עוֹנְשָׁהּ.</p>"],[9514012040,"<p>אָמַר רִבִּי יְהוּדָה, הַצַּדִּיקִים מָה הֵם עוֹשִׂים אִם בָּא לִיטָהֵר, אֲפִלּוּ יֵצֶר הָרָע הַבָּא לְקַטְרְגוֹ, נִשְׁמָתוֹ מְסַיַּיעַת אוֹתוֹ, שֶׁנֶּאֱמַר (שם יג) וַיֹּאמֶר אַבְרָם אֶל לוֹט, הַנְּשָׁמָה אוֹמֶרֶת לַיֵּצֶר הָרָע, אַל נָא תְהִי מְרִיבָה בֵּינִי וּבֵינֶךָ.</p>"],[9514012041,"<p>מָה עוֹשֶׂה הַצַּדִּיק הַזֶּה. הוֹלֵךְ לְבֵית הַמִּדְרָשׁ, קוֹרֵא וְשׁוֹנֶה, וּמְקַטְרֵג לַיֵצֶר הָרָע, וְאוֹמֵר לוֹ הֲלֹא כָל הָאָרֶץ לְפָנֶיךָ, הִפָּרֶד נָא מֵעָלָי. סַגִּיאִין אִית בְּעָלְמָא, דְּאַתְּ יָכֵיל לוֹן, מִן קֳדָם דְּאַבְאִישׁוּ עוֹבָדֵיהוֹן. אִם הַשְּׂמֹאל וְאֵימִינָה, אִם אַתָּה רוֹצֶה לְהַשְּׂמְאִיל אוֹתִי, אֲנִי אַיְמִין, אֵלֵךְ לְצַד יְמִין, שֶׁלֹּא אַטֶה אַשּׁוּרִי יָמִין וּשְׂמֹאל. וְאִם הַיָּמִין וְאַשְׂמְאִילָה, אַף עַל פִּי שֶׁאֶרְאֶה שֶׁהִיא טוֹבָה עֲצָתְךָ, אֶעֱשֶׂה הֵפֶךְ רְצוֹנְךָ וְתַאֲוָתְךָ.</p>"],[9514012042,"<p>וְאָמַר רַבִּי בּוֹ, יֵצֶר הָרָע מַהוּ עוֹשֶׂה בְּאוֹתָהּ שָׁעָה, שֶׁהוּא רוֹאֶה שֶׁלֹּא נֶעֶשְׂתָה עֲצָתוֹ, מַה כְּתִיב בֵּיהּ, (שם) וַיִּבְחַר לוֹ לוֹט אֶת כָּל כִּכַּר הַיַּרְדֵּן, לְאוֹתָם הָרְשָׁעִים שֶׁלֹּא יְקַטְרְגוּ עִמּוֹ, וּבִשְׁבִיל זֶה הַדֶּרֶךְ וַיִּפָּרְדוּ אִישׁ מֵעַל אָחִיו. וְאָז הַנְּשָׁמָה מַה כְּתִיב בָּהּ. וְאַבְרָם כָּבֵד מְאֹד, בְּכָל מַעֲשִׂים טוֹבִים וִישָׁרִים בַּתּוֹרָה וּמִצְוֹת.</p>"],[9514012043,"<p>(בראשית יד) וַיִּשְׁמַע אַבְרָם כִּי נִשְׁבָּה אָחִיו, ר' תַּנְחוּם פָּתַח, קַמְתִּי אֲנִי לִפְתֹּחַ לְדוֹדִי כו' (שיר השירים ה) וְדוֹדִי חָמַק עָבָר נַפְשִׁי יָצְאָה בְדַבְּרוֹ. אָמַר רִבִּי תַּנְחוּם, בֹּא וּרְאֵה כַּמָּה יֵשׁ לוֹ לָאָדָם לִיטָהֵר מֵעֲוֹנוֹתָיו, בְּעוֹד דַּרְכֵי הַתְּשׁוּבָה פְּתוּחִין לְפָנָיו, בְּטֶרֶם יִסָּתֵם הַדֶּרֶךְ. שֶׁנֶּאֱמַר (ישעיה נה) דִּרְשׁוּ ה' בְּהִמָּצְאוֹ וְגו'. יֵשׁ עִתִּים שֶׁהוּא קָרוֹב, וְיֵשׁ עִתִּים שֶׁהוּא רָחוֹק.</p>"],[9514012044,"<p>וּמִי אָמַר רִבִּי תַּנְחוּם הָכֵי, וְהָא כְתִיב (תהילים קמ״ה:י״ח) קָרוֹב ה' לְכָל קֹרְאָיו לְכֹל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת. אָמַר, הַאי קְרָא מְסַיֵּיעַ לֵיהּ. מַשְׁמַע דִּכְתִיב לְכֹל אֲשֶׁר יִקְרָאוּהוּ בֶאֱמֶת, וְעִם כָּל זֶה מַאי כְּתִיב, רְצוֹן יְרֵאָיו יַעֲשֶׂה.</p>"],[9514012045,"<p>מָשָׁל לְמֶלֶךְ, דְּהֲוָה יָתֵיב, וְאָתָא בַּר נָשׁ וְצָוַח קַמֵּיהּ, אָצֵית מַלְכָּא כָּל מַה דַּאֲמַר, וְלָא אָתֵיב לֵיהּ, הוּא צָוַח וּמַלְכָּא אָצֵית וְשָׁתֵיק. אָזַל הַהוּא גַבְרָא.</p>"],[9514012046,"<p>אָמְרוּ מְשַׁמְּשׁוֹהִי קַמֵּי מַלְכָּא, מָרָנָא, לָמָּה לָא אֲתֵיבַת לְהַאי מִסְּכֵּינָא מִדָּעַם, אֲמַר לְהוֹ, שְׁמָעִית כָּל מַה דַּאֲמַר, וְאָצֵית לֵיהּ, אֲבָל הוּא חַיָּיבָא קַמָּאי, וְלֵיתוֹהִי כְּדַאי לְמֶעְבַּד רְעוּתֵיהּ, דְּהָא אֲמָרוּ לֵיהּ וּלְחַבְרוֹהִי זִמְנִין סַגִּיאִין מִן שְׁמִי, דְּלָא יֶהֱווֹן בִּישִׁין, וְיֵיתוּן קַמָּאי וְאַעֲבֵיד עִמְּהוֹן טָבָא, וְלָא אַשְׁגָּחוּ בִּי, כְּעַן לֵית אֲנָא מַשְׁגַּח בְּהוֹן.</p>"],[9514012047,"<p>כָךָ הוּא הַקָּדוֹשׁ בָּרוּךְ הוּא, קָרוֹב ה' לְכָל קֹרְאָיו לְכֹל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת, וְשׁוֹמֵעַ לָהֶם. אֲבָל לְמִי שֶׁהוּא עוֹשֶׂה רְצוֹנוֹ, לְהַאי כְּתִיב, (שם) רְצוֹן יְרֵאָיו יַעֲשֶׂה וְאֶת שַׁוְעָתָם יִשְׁמַע וְיוֹשִׁיעֵם.</p>"],[9514012048,"<p>אָמַר רִבִּי חֶלְבוֹ אָמַר רַב הוּנָא, מִמִּי אַתָּה לָמֵד, מִמּשֶׁה רַבֵּינוּ עָלָיו הֲשָׁלוֹם. דִּכְתִיב (שמות ל״ג:ט״ז) וּבַמֶּה יִוָּדַע אֵפוֹא כִּי מָצָאתִי חֵן בְּעֵינֶיךָ אֲנִי וְעַמֶּךָ. אָמַר משֶׁה, רִבּוֹנוֹ שֶׁל עוֹלָם לֵית אֲנַן צְרִיכִין לְמַלְאָךְ, וְלֹא לְשָׂרָף, וְלֹא לְשַׂר, מַאי שִׁינּוּיָא יְהֵא לָנָא מִן הָאוּמּוֹת, לָהֶם שַׂר, וְלָנוּ שַׂר, אֲבָל וְנִפְלִינוּ אֲנִי וְעַמְּךָ וְגו', וּבַמֶּה יִוָּדַע אֵפוֹא כִּי מָצָאתִי חֵן בְּעֵינֶיךָ הֲלֹא בְּלֶכְתְּךָ עִמָּנוּ, אַתָּה וְלֹא שַׂר.</p>"],[9514012049,"<p>אָמַר רִבִּי יְהוּדָה, מַאי הֲוָה דַעְתֵּיהּ דְּמשֶׁה דְּלָא קַבֵּיל לֵיהּ לְמַלְאָכָא. אֶלָּא, אֲמַר משֶׁה יְדַעְנָא בְּהוֹן בְּיִשְׂרָאֵל, דְּאִינוּן חַיָּיבַיָא וּקְשֵׁי קְדַל, אִלְמָלֵי יִתְמַסְּרוּן לְמַלְאָכָא, וְכָל שֶׁכֵּן לְמִי שֶׁהוּא מִדַּת הַדִּין, לֹא יִשְׁתַּיֵּיר מִשּׂנְאֵיהוֹן דְּיִשְׂרָאֵל שָׂרִיד וּפָלִיט.</p>"],[9514012050,"<p>דְּאָמַר רִבִּי יְהוּדָה, בְּכָל מָקוֹם ה' מִדַּת רַחֲמִים. אָמַר משֶׁה, רִבּוֹנוֹ שֶׁל עוֹלָם, אַתָּה אָמַרְתָּ שֶׁמָּצָאתִי חֵן בְּעֵינֶיךָ. (שם לד) וְעַתָּה אִם נָא מָצָאתִי חֵן בְּעֵינֶיךָ יֵלֶךְ נָא אֲדֹנָי בְּקִרְבֵּנוּ דְּהוּא מִדַּת רַחֲמִים.</p>"],[9514012051,"<p>אָמַר לֵיהּ לָמָּה. אָמַר לֵיהּ כִּי עַם קְשֵׁה עֹרֶף הוּא וְסָלַחְתָּ. יִשְׂרָאֵל סַרְבָנִין טַרְחָנִין הֵם, כֵּיוָן שֶׁחוֹטְאִים יֵשׁ בְּיַד הַמַּלְאָךְ לַעֲשׂוֹת דִּין, וְלֹא לַעֲשׂוֹת סְלִיחָה וּמְחִילָה. אֲבָל אַתָּה רַחוּם וְחַנּוּן, הַיְכוֹלֶת וְהַכֹּחַ בְךָ, וְרַחֲמֶיךָ רַבִּים, וְסָלַחְתָּ לַעֲוֹנֵנוּ וּלְחַטָאתֵנוּ וּנְחַלְתָּנוּ. מַה שֶּׁאֵין רְשׁוּת לְשׁוּם מַלְאָךְ לַעֲשׂוֹת כֵּן.</p>"],[9514012052,"<p>אָמַר רִבִּי שִׁמְעוֹן, רַחְמָנוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵצֶל כְּנֶסֶת יִשְׂרָאֵל, הֲדָא הוּא דִכְתִיב, (שיר השירים ה) פִּתְחִי לִי, פֶּתַח שֶׁל תְּשׁוּבָה, לְמַעַן תִּזְכִּי לְכָל טוּב שֶׁבָּעוֹלָם. שֶׁרֹאשִׁי נִמְלָא טָל, זֶהוּ רֹאשׁ הָעוֹלָם. קְוֻצּוֹתַי רְסִיסֵי לָיְלָה, זֶהוּ קְצֵה הָעוֹלָם. כְּלוֹמַר, רֹאשׁ הָעוֹלָם וְקָצֵהוּ, מִלֵּאתִי כָּל טוּב בִּשְׁבִילֵךְ, וְלֹא פָּתַחְתְּ לִי בְּאוֹתוֹ זְמַן. וּלְאַחַר כֵּן כְּשֶׁהֵצִיק לָהּ מַה כְּתִיב, (שם) קַמְתִּי אֲנִי לִפְתֹּחַ לְדוֹדִי וְדוֹדִי חָמַק עָבָר נַפְשִׁי יָצְאָה בְדַבְּרוֹ.</p>"],[9514012053,"<p>דָּבָר אַחֵר, קַמְתִּי אֲנִי לִפְתֹּחַ לְדוֹדִי, זוֹ הִיא הַנְּשָׁמָה אֵצֶל הַגּוּף, בְּעוֹד שֶׁהַנְּשָׁמָה בַּגּוּף, אֵינָם רוֹצִים לְהָעִיר דַּרְכֵי הַתְּשׁוּבָה. אָמַר רִבִּי פִּנְחָס, בְּשָׁעָה שֶׁהַנְּשָׁמָה רוֹצָה לָצֵאת מִן הַגּוּף, מִתְחָרֶטֶת לָמָּה לֹא שָׁבָה בִּתְשׁוּבָה עַד שֶׁיָּצְאָה מִן הַגּוּף, וְנִשְׁאָר הַגּוּף כִּכְלִי אֵין חֵפֶץ בּוֹ.</p>"],[9514012054,"<p>וְאָמַר רִבִּי פִּנְחָס, כָּל שִׁבְעַת הַיָּמִים נַפְשׁוֹ מִתְאַבֶּלֶת עָלָיו וְאוֹמֶרֶת, קַמְתִּי אֲנִי לִפְתֹּחַ לְדוֹדִי. תֵּדַע לָךְ, בְּעוֹד שֶׁהַנְּשָׁמָה בַּגּוּף, וְהַגּוּף עוֹמֵד בְּכֹחַ, הִיא, תְּשׁוּבָה מַעַלְיָיתָא, וְלָא בְּשַׁעֲתָא דְּלָא יָכֵיל.</p>"],[9514012055,"<p>כדְּאָמַר רִבִּי פִּנְחָס, מָשָׁל לְמִדַּת הַדִּין, לְאָדָם הָעוֹמֵד עַל שׁוּלְחָנוֹ, וְהָיָה רָעֵב וְתָאֵב לֶאֱכוֹל, וּבְעוֹד שֶׁהָיָה אוֹכֵל, עָמַד עָנִי עַל הַפֶּתַח, שָׁאַל מִמֶּנּוּ לְהַאֲכִילוֹ, וְלֹא הֶחֱזִיר לוֹ פָּנִים, הָלַךְ אוֹתוֹ הֶעָנִי בְּפַחֵי נֶפֶשׁ.</p>"],[9514012056,"<p>לְאַחַר שָׁעָה, הִגִּישׁוּ עוֹד לְפָנָיו לֶאֱכוֹל, הָיָה בִּטְנוֹ מָלֵא מִכֹּל, כֵּיוָן שֶׁרָאָה שֶׁאֵינוֹ יָכוֹל לֶאֱכוֹל עוֹד, אָמַר תְּנוּ לוֹ לָזֶה הֶעָנִי. הָיָה חָכָם אֶחָד עוֹמֵד עָלָיו, אָמַר לֵיהּ, שׁוֹטֶה, אִלּוּ יְכֵילַת לֶאֱכוֹל לֹא נָתַתָּ לוֹ, עַתָּה שֶׁאֵין בְּךָ כֹּחַ לֶאֱכוֹל יוֹתֵר אַתָּה נוֹתְנוֹ לֶעָנִי.</p>"],[9514012057,"<p>כָךָ הוּא הָאָדָם בָּעוֹלָם הַזֶּה, הוֹלֵךְ בַּהֲבָלָיו רָעֵב לֶאֱכוֹל וּלְהַרְוִיחַ מָמוֹן, בָּא הֶעָנִי שֶׁהוּא הַיֵּצֶר הַטוֹב, וְשָׁאַל מִמֶּנּוּ בְּבַקָּשָׁה שֶׁיַּחֲזוֹר בִּתְשׁוּבָה וְלַעֲסוֹק בַּתּוֹרָה, וְאֵינוֹ רוֹצֶה, מִפְּנֵי שֶׁהוּא רָעֵב יוֹתֵר לְהַרְוִיחַ מָמוֹן.</p>"],[9514012058,"<p>לְאַחַר זְמַן תּוֹפְסִין אוֹתוֹ בַּקּוֹלָר, כְּשֶׁרוֹאֶה שֶׁאֵינוֹ יָכוֹל לְהַרְוִיחַ יוֹתֵר, אוֹמֵר אֶחֱזוֹר בִּתְשׁוּבָה. שֶׁמָּא יִתְּנוּ לוֹ שָׁעָה לְכָךְ, אוֹ שֶׁמָּא לֹא יִתְּנוּ לוֹ. אָמַר לֵיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, שׁוֹטֶה עַכְשָׁיו שֶׁאֵינְךָ יָכוֹל עוֹד לְהַרְוִיחַ יוֹתֵר אַתְּ אוֹמֵר אֶחְזוֹר בִּתְשׁוּבָה, דְּאִלּוּ הָיִיתָ יָכוֹל לְהַרְוִיחַ עוֹד לֹא הָיִיתָ חוֹזֵר בִּתְשׁוּבָה, בְּעוֹדוֹ כָּךְ יָצָאת נִשְׁמָתוֹ.</p>"],[9514012059,"<p>וְאָמַר רִבִּי זְרִיקָא, רַב דְּמִן חַבְרַיָיא אֱלִישָׁע בֶּן אֲבוּיָה הֲוָה, וְלָא יַהֲבוּ לֵיהּ רְשׁוּתָא לְמֶהֱדַר בִּתְשׁוּבָה, דְּנָפְקָא הַהוּא קָלָא, וַאֲמַר בְּשַׁעֲתָא דְּהֲוָה מֵת, כָּל אוֹרְחִין וּשְׁבִילִין מִלְּעֵילָא וּמִלְּרַע יִסְתַּתְּמוּן מֵהַהוּא גַבְרָא, דְּלָא יֵיתֵי לְעָלְמָא דְאָתֵי. ארִבִּי יְהוֹשֻׁעַ בֶּן לֵוִי, לָמָּה לָן כּוּלֵּי הַאי, ר (קהלת יב) וּזְכֹר אֶת בּוֹרְאֶךָ כו' עַד אֲשֶׁר לֹא יָבוֹאוּ יְמֵי הָרָעָה.</p>"],[9514012060,"<p>ג (בראשית יד) וַיִּשְׁמַע אַבְרָם כִּי נִשְׁבָּה אָחִיו. רַבִּי אַבָּא פָּתַח, כְּנֶגֶד יֵצֶר הָרָע כִּדְאִיתָא לְעֵיל. הָא תָּנִינָן, כֵּיוָן שֶׁנִּפְרַד יֵצֶר הָרָע מִן הַגּוּף שֶׁל צַדִּיק לְאֵיזֶה מָקוֹם הוֹלֵךְ, לִמְקוֹם הָרְשָׁעִים, שֶׁלֹּא יְקַטְרְגוּ עִמּוֹ.</p>"],[9514012061,"<p>מַאי מַשְׁמַע. דִּכְתִיב (בראשית יג) וְלוֹט יָשַׁב בְּעָרֵי הַכִּכָּר וַיֶּאֱהַל עַד סְדֹם וְאַנְשֵׁי סְדֹם רָעִים וְחַטָאִים וְגו', לִמְקוֹם רְשָׁעִים וְחַטָאִים, שָׁם שָׂם אָהֳלֹה לָשֶׁבֶת. יֵצֶר הָרָע שָׁם מַהוּ עוֹשֶׂה, חוֹטֵא עִמָּם, וּמַחְטִיא, עַד שֶׁנִּשְׁבָּה בַּעֲוֹנוֹתָיו וְנִלְכַּד.</p>"],[9514012062,"<p>וְנִשְׁמַת הַצַּדִּיק מָה (הוא) עוֹשָׂה. וַיִּשְׁמַע אַבְרָם זוֹ הִיא הַנְּשָׁמָה, כִּי נִשְׁבָּה אָחִיו, זֶה יֵצֶר הָרָע. וַיָּרֶק אֶת חֲנִיכָיו יְלִידֵי בֵיתוֹ, אֵלּוּ הֵם הַצַּדִיקִים הַמְחוּנָּכִים בְּמִצְווֹת, וּבְדֶרֶךְ הַטוֹב, כִּדְקָאָמַר רַבִּי אַבָּהוּ, כֵּיוָן שֶׁרוֹאֶה הַצַּדִּיק דְּהָרָשָׁע נֶעֱזָב וְנִלְכַּד בַּעֲוֹנוֹתָיו, הוֹלֵךְ לֶאֱחוֹז בּוֹ, אוּלַי יַחְזִירֵהוּ בִּתְשׁוּבָה, וּמְקַרְבוֹ וּמְלַמְּדוֹ. הֲדָא הוּא דִכְתִיב, וַיִּרְדֹף עַד דָּן, עַד עִיקַּר דִּינוֹ רוֹדֵף לְהַצִּילוֹ מִדִּינָהּ שֶׁל גֵּיהִנֹּם.</p>"],[9514012063,"<p>וְכֵן הוּא דֶּרֶךְ הַצַּדִּיקִים, לִרְדּוֹף אַחֲרֵי הָרְשָׁעִים כְּדֵי לְהַחֲזִירָם לַמּוּטָב. מַה כְּתִיב בְּהוּ. (שם יד) וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה וְגו'. וְזֶהוּ נִשְׁמַת הַצַּדִּיקִים, שֶׁמְיַסְּרִים וּמְבַקְּשִׁים לָהֶם, כְּדֵי שֶׁלֹּא יֵלְכוּ בְּדֶרֶךְ רִשְׁעָתָם. הוּא וַעֲבָדָיו וַיַּכֵּם, הַנְּשָׁמָה וְהַצַּדִּיקִים רוֹדְפִים אַחֲרֵיהֶם, וּמוֹכִיחִין לָהֶם, וּמְיַיסְּרִים לָהֶם.</p>"],[9514012064,"<p>וַיִּרְדְּפֵם עַד חוֹבָה, מוֹדִיעִים לָהֶם רָעָתָם, וְרוֹדְפִים אַחֲרֵיהֶם, עַד שֶׁמְגַלִּים לָהֶם רָעָתָם וְרִשְׁעָתָם, לְמַעַן יֵבוֹשׁוּ מִמַּעֲשֵׂיהֶם. וְזֶהוּ וַיִּרְדְּפֵם עַד חוֹבָה. הַנְּשָׁמָה עוֹשָׂה כָּךְ, וּמוֹדִיעָה לָהֶם דַּרְכָּם הָרָעָה, וְזֶהוּ עַד חוֹבָה. וְהָאֵיךְ הֵם הוֹלְכִים, לִשְׂמֹאל וְלֹא לְיָמִין.</p>"],[9514012065,"<p>מַה כְּתִיב אַחֲרֵי כֵן. (שם) וַיָּשֶׁב אֵת כָּל הָרְכֻשׁ וְגַם אֶת לוֹט. אָמַר רִבִּי אַבָּהוּ, בְּעַל כָּרְחָם הֵם חוֹזְרִים בִּתְשׁוּבָה. דִּכְתִיב וְגַם אֶת לוֹט אָחִיו וּרְכוּשׁוֹ הֵשִׁיב. וַאֲפִילּוּ יֵצֶר הָרָע, בְּעֲל כֹּרְחוֹ שָׁב בִּתְשׁוּבָה. וְאָמַר רִבִּי אַבָּהוּ, בֹּא וּרְאֵה כַּמָּה שְׂכָרוֹ שֶׁל אָדָם הָעוֹשֶׂה לַאֲחֵרִים לַחֲזוֹר בִּתְשׁוּבָה. מְנָא לָן, מִמַּה דִּכְתִיב אַחֲרָיו, (שם) וּמַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם.</p>"],[9514012066,"<p>תָּאנֵי רַבִּי חִיָּיא רַבָּה, בְּשָׁעָה שֶׁנִּשְׁמַת הַצַּדִּיק, הַמַּחֲזִיר בִּתְשׁוּבָה לַאֲחֵרִים, יוֹצְאָה מִן הַגּוּף, מִיכָאֵל הַשַּׂר הַגָּדוֹל הַמַּקְרִיב נַפְשׁוֹת הַצַּדִּיקִים לִפְנֵי בּוֹרְאוֹ, הוּא יוֹצֵא וּמַקְדִּים שָׁלוֹם לְנִשְׁמָתוֹ שֶׁל אוֹתוֹ צַדִּיק, שֶׁנֶּאֱמַר וּמַלְכִּי צֶדֶק, זֶהוּ מִיכָאֵל רֹאשׁ שׁוֹמְרֵי שַׁעֲרֵי צֶדֶק. מֶלֶךְ שָׁלֵם, זוֹ יְרוּשָׁלַיִם שֶׁל מַעְלָה. הוֹצִיא לֶחֶם וָיָיִן, שֶׁמַּקְדִּים וְיוֹצֵא לִקְרָאתוֹ, וְאוֹמֵר לוֹ שָׁלוֹם בּוֹאֲךָ.</p>"],[9514012067,"<p>אָמַר רִבִּי חִיָּיא, מִכָּאן לָמַדְנוּ, כָּל הַמַּקְדִּים וְיוֹצֵא לִקְרַאת הַבָּא מִן הַדֶּרֶךְ, וְנוֹתֵן לוֹ שָׁלוֹם, מַעֲלֶה עָלָיו הַכָּתוּב כְּאִלּוּ אֲכִילָה וּשְׁתִיָּה הוּא נוֹתֵן לוֹ. מְנָא לָן, מֵהַאי קְרָא, דִּכְתִיב (דברים כ״ג:ד׳-ה׳) עַל דְּבַר אֲשֶׁר לֹא קִדְּמוּ אֶתְכֶם בַּלֶּחֶם וּבַמַּיִם. וְכִי צְרִיכִין יִשְׂרָאֵל לְלֶחֶם וּלְמַיִם, וַהֲלֹא הַמָּן יוֹרֵד לָהֶם, שֶׁהָיָה טַב וְשַׁפִּיר מִכָּל אֲכִילָה שֶׁבָּעוֹלָם.</p>"],[9514012068,"<p>אֶלָּא מִפְּנֵי שֶׁלֹּא בָּאוּ לְהַקְדִּים לָהֶם שָׁלוֹם, הֶעֱלָה עֲלֵיהֶם הַכָּתוּב כְּאִילּוּ חִסְּרוּ מִחְיָיתָם. וְכָל הַמַּקְדִּים שָׁלוֹם לַחֲבֵירוֹ, וְיוֹצֵא לוֹ לַדֶּרֶךְ, מַעֲלֶה עָלָיו הַכָּתוּב, כְּאִלּוּ נוֹתֵן לוֹ לֶאֱכוֹל וְלִשְׁתּוֹת. וְכֵן אָמַר רִבִּי חִיָּיא רַבָּה, מִיכָאֵל וְגַבְרִיאֵל וּמַלְאֲכֵי הַשָּׁרֵת הַשּׁוֹמְרִים שַׁעֲרֵי צֶדֶק, יוֹצְאִין לִקְרָאתוֹ וּמַקְדִּימִין לוֹ שָׁלוֹם.</p>"],[9514012069,"<p>וְהוּא כֹהֵן לְאֵל עֶלְיוֹן, דְּתָאנֵי רַב יוֹסֵף, כְּשֵׁם שֶׁכֹּהֵן גָּדוֹל לְמַטָה, כָּךְ מִיכָאֵל הַשַּׂר הַגָּדוֹל הוּא כֹּהֵן לְמַעְלָה, וְהוּא מַקְדִּים וּמְבָרֵךְ לַנְּשָׁמָה קוֹדֶם, וְאַחַר כַּךְ מְבָרֵךְ להַקָדוֹשׁ בָּרוּךְ הוּא. וְאִלְמָלֵא מִקְרָא כָּתוּב אִי אֶפְשָׁר לְאוֹמְרוֹ, שֶׁנֶּאֱמַר (בראשית י״ד:י״ט) וַיְבָרַכֵהוּ וַיֹּאמַר בָּרוּךְ אַבְרָם לְאֵל עֶלְיוֹן קוֹנֵה שָׁמַיִם וָאָרֶץ. אַשְׁרֶיךָ שֶׁזָּכִיתָ לְכָךְ, וְאַחַר כַּךְ וּבָרוּךְ אֵל עֶלְיוֹן אֲשֶׁר מִגֵּן צָרֶיךָ בְּיָדֶךָ, אֵלּוּ הָרְשָׁעִים שֶׁזִּיכִּיתָם בִּתְשׁוּבָה, וְעָשִׂיתָ אֶת נִשְׁמָתָם.</p>"],[9514012070,"<p>(שם) וַיִּתֵּן לוֹ מַעֲשֵׂר מִכֹּל, אָמַר רִבִּי יִצְחָק, הַאי קְרָא לֹא יָדַעְנוּ, מִי נָתַן מַעֲשֵׂר לְמִי. אֶלָּא הַקָדוֹשׁ בָּרוּךְ הוּא נוֹתֵן לוֹ מַעֲשֵׂר. נוֹטֵל אוֹת א' מִתַּחַת כִּסֵּא הַכָּבוֹד, וְנוֹתֵן אוֹתָהּ עֲטָרָה עַל הַנְּשָׁמָה, שֶׁהוּא אַבְרָם. וִאֵיזוֹ הִיא אוֹת אַחַת. אוֹת ה'. כַּאֲשֶׁר נִבְרָא הָעוֹלָם בָּהּ, לִהְיוֹת צְרוּרָה בִּצְרוֹר הַחַיִּים, וְנִשְׁלֶמֶת בְּהַשְׁלָמָתוֹ. הֲדָא הוּא דִכְתִיב, (שם יז) וְלֹא יִקָּרֵא עוֹד אֶת שִׁמְךָ אַבְרָם וְהָיָה שִׁמְךָ אַבְרָהָם, וְזֶהוּ הַמַּעֲשֵׂר שֶׁנָּתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9514012071,"<p>אָמַר רִבִּי יְהוּדָה, מַהוּ מִכֹּל, הוּא שְׁכִינָתוֹ שֶׁל מָקוֹם, דְּהָא תָּנִינָן, אָמַר רִבִּי בְּרֶכְיָה, מַאי דִּכְתִיב (בראשית כ״ד:א׳) וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל, שֶׁהִשְׁרָה שְׁכִינָתוֹ עִמּוֹ.</p>"],[9514012072,"<p>אָמַר רַב חִסְדָּא, אֵין הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה מִשְׁפָּט בָּרְשָׁעִים בָּעוֹלָם הַבָּא, עַד שֶׁנִּמְלַךְ בְּנִשְׁמָתָן שֶׁל צַדִּיקִים, שֶׁנֶּאֱמַר (איוב ד׳:ט׳) מִנִּשְׁמַת אֱלוֹהַּ יֹאבֵדוּ. וּכְשֶׁהֵן אוֹבְדִין, אֵין אוֹבְדִין אֶלָּא מֵאוֹתוֹ הַדִּין, שֶׁהַנְּשָׁמָה דָּנָה לָרְשָׁעִים.</p>"],[9514012073,"<p>וְתָאנָא, ערסיאָמַר לֵיהּ שָׂרוֹ שֶׁל גֵּיהִנֹּם, עוֹמֵד לִפְנֵי נִשְׁמַת הַצַּדִּיקִים שֶׁלּא יִתְפַּלְּלוּ עַל הָרְשָׁעִים לִפְנֵי הַקָדוֹשׁ בָּרוּךְ הוּא, וְשֶׁיִּתְּנֵם בִּרְשׁוּתוֹ לְהוֹרִידָם לִבְאֵר שַׁחַת, הֲדָא הוּא דִכְתִיב, (בראשית י״ד:כ״א) וַיֹּאמֶר מֶלֶךְ סְדֹם אֶל אַבְרָם תֶּן לִי הַנֶּפֶשׁ. מֶלֶךְ סְדוֹם זֶהוּ שָׂרוֹ שֶׁל גֵּיהִנֹּם, הָעוֹמֵד עַל הָרְשָׁעִים, וְהוּא מֶלֶךְ סְדוֹם.</p>"],[9514012074,"<p>וּמָה אוֹמֵר לַנְּשָׁמָה שֶׁהוּא אַבְרָם, תֵּן לִי הַנֶּפֶשׁ, שֶׁהִיא הַחוֹטֵאת, כְּמָה דְאַתְּ אָמֵר (יחזקאל י״ח:ד׳) הַנֶּפֶשׁ הַחֹטֵאת הִיא תָמוּת. כְּלוֹמַר תֵּן לִי אוֹתָהּ הַנֶּפֶשׁ שֶׁהִיא מִתְאַוָּה בַּחֲטָאוֹת, כְּדֵי שֶׁתְּהֵא נִדּוֹנֵית כְּפִי רִשְׁעָתָהּ, וְלֹא תִקָּחֶנָּה בְּתַחֲנוּנֶיךָ. וְהָרְכוּשׁ קַח לָךְ, אוֹתָם אֲשֶׁר שָׁבוּ בִּתְשׁוּבָה בְּנַפְשׁוֹתָם מִדַּרְכָּם הָרָעָה, קַח לָךְ, וְהַצִּילֵם מִדִּינָהּ שֶׁל גֵּיהִנֹּם.</p>"],[9514012075,"<p>אָמַר רִבִּי יְהוּדָה, בְּאוֹתָהּ שָׁעָה הַנְּשָׁמָה מָה הִיא אוֹמֶרֶת, וַיֹּאמֶר אַבְרָם אֶל מֶלֶךְ סְדֹם הֲרִמֹתִי יָדִי אֶל ה' אֵל עֶלְיוֹן, בִּשְׁבוּעָה, שֶׁלֹּא אֶתְפַּלֵּל וְלֹא אֶקַח לְאוֹתָם הָרְשָׁעִים, שֶׁהָיִיתִי מַכְרִיז לִפְנֵיהֶם בְּאוֹתוֹ עוֹלָם, וְהוֹכַחְתִים לַחֲזוֹר בִּתְשׁוּבָה, וּפֵרַשְׁתִּי לָהֶם כָּל מִשְׁפְּטֵי גֵּיהִנֹּם, וְלֹא שָׁמְעוּ לִי. אִם אֶקַּח מִכָּל אֲשֶׁר לָךְ, שֶׁלְּךָ הֵם, וּבִרְשׁוּתְךָ הֵם.</p>"],[9514012076,"<p>דְּארִבִּי יְהוֹשֻׁעַ בֶּן לֵוִי, זִמְנָא חָדָא חָזֵי הֲוֵית וַעֲרָעִית סָמוּךְ לְתַרְעָא דְּגֵיהִנֹּם, וּשְׁמָעִית קָל חַיָּיבַיָא, דַּהֲווֹ טְרִידִין בַּגֵּיהִנֹּם בְּדִינָא רַבָּא, דְּדָיְינִין לְחַיָּיבַיָא בְּעָלְמָא דְאָתֵי, וַהֲווּ אָמְרִין, פּוּתְקָנָא סְיָיפָנָא, שְׁמַעְנָא, וְלָא אָרִיכְנָא אוּדְנָנָא, וַוי לָן, מִילְּתָא דְּצַדִּיקַיָא לָא עָבַדְנָא.</p>"],[9514012077,"<p>בָּכֵינָא, שְׁמָעִית הַהוּא קָלָא דַּאֲמַר, בַּר לֵיוָאֵי בַּר לֵיוָאֵי, סַק סִיקְתָךְ וּסְתוֹם פּוּמָךְ, לֵית לָךְ רְשׁוּתָא לְצַלָּאָה עֲלוֹהִי, וְאַתְּ וְחַבְרַיָיא כְּתִיב בְּכוֹ (מלאכי ג׳:כ״א) וְעַסּוֹתֶם רְשָׁעִים כִּי יִהְיוּ אֵפֶר תַּחַת כַּפּוֹת רַגְלֵיכֶם.</p>"],[9514012078,"<p>וְארִבִּי יְהוֹשֻׁעַ בֶּן לֵוִי, שִׁבְעָה מְדוֹרוֹת יֵשׁ בַּגֵּיהִנֹּם, בַּאֲשֶׁר נִדּוֹנִין הָרְשָׁעִים לֶעָתִיד לָבֹא. וְשִׁבְעָה פְּתָחִים יֵשׁ בַּגֵּיהִנֹּם, כְּנֶגֶד שִׁבְעָה פְּתָחִים שֶׁיֵּשׁ לְנִשְׁמוֹת הַצַּדִּיקִים לְהִכָּנֵס בָּהֶם. כְּנֶגְדָן, יֵשׁ לְנֶפֶשׁ הָרָשָׁע שִׁבְעָה פְּתָחִים לְהִכָּנֵס בָּהֶם, וְאֵלּוּ הֵן: אוֹפֶל, צַלְמָוֶת, שַׁעֲרֵי מָוֶת, בְּאֵר שַׁחַת, טִיט הַיָּוֵן, שְׁאוֹל וַאֲבַדּוֹן. וְשָׁם נִידּוֹנִים שְׁנֵים עָשָׂר חֹדֶשׁ.</p>"],[9514012079,"<p>דְּאָמַר רִבִּי שִׁמְעוֹן, מִשְׁפַּט רְשָׁעִים בַּגֵּיהִנֹּם, שְׁנֵים עָשָׂר חֹדֶשׁ, וְשָׁם יְצַפְצְפוּ בִּתְשׁוּבָה. וְנִשְׁמָתָם שֶׁל צַדִּיקִים פּוֹגְעִין לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּמַעֲלִין אוֹתָן מִשְּׁאוֹל, שֶׁהוּא הַמָּדוֹר הַשִּׁשִּׁי, שֶׁנֶּאֱמַר (שמואל א ב׳:ו׳) מוֹרִיד שְׁאוֹל וַיָּעַל.</p>"],[9514012080,"<p>וּמִי שֶׁנִּכְנַס בַּמָּדוֹר הַתַּחְתּוֹן שֶׁהוּא אֲבַדּוֹן, שׁוּב אֵינוֹ עוֹלֶה. דְּתָאנָא, אָמַר רִבִּי יְהוּדָה, אַף עַל פִּי שֶׁנִּכְנַס בַּשְּׁאוֹל, עוֹלֶה בִּתְשׁוּבָה, שֶׁנֶּאֱמַר (יונה ב׳:ג׳) מִבֶּטֶן שְׁאוֹל שִׁוַּעְתִּי שָׁמַעְתָּ קוֹלִי.</p>"],[9514012081,"<p>דָּבָר אַחֵר (בראשית י״ד:כ״ב) הֲרִמֹתִי יָדִי אֶל ה' אֵל עֶלְיוֹן וְגו' אִם מִחוּט וְגו' אָמַר רִבִּי אֶלְעָזָר הָרְאוּיִם לְךָ, שֶׁהֵם רְשָׁעִים גְמוּרִים, שֶׁלֹּא שָׁבוּ בִּתְשׁוּבָה מֵעוֹלָם, בִּשְׁבוּעָה שֶׁלֹּא אֶקָּחֵם לְעוֹלָם.</p>"],[9514012082,"<p>בִּלְעָהַי רַק אֲשֶׁר אָכְלוּ הַנְּעָרִים. אָמַר רִבִּי תַּנְחוּם, בֹּא וּרְאֵה כַּמָּה חֲבִיבָה הַתּוֹרָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁבִּשְׁבִילָהּ זוֹכֶה הָאָדָם לְחַיֵּי הָעוֹלָם הַבָּא, וְכָל הַמְלַמֵּד תּוֹרָה לַאֲחֵרִים, יוֹתֵר מִכּוּלָּם. בֹּא וּרְאֵה מַה כְּתִיב בְּכָאן, אִם אֶקַּח מִכָּל אֲשֶׁר לָךְ, אוֹתָם הָרְשָׁעִים הָרְאוּיִם לָךְ. בִּלְעָדַי רַק אֲשֶׁר אָכְלוּ הַנְּעָרִים, חוּץ מֵאוֹתָם הַמּוֹרִים תּוֹרָה לַאֲחֵרִים וּלְתִינוֹקוֹת, שֶׁשְּׂכָרָם כָּפוּל.</p>"],[9514012083,"<p>דְּאָמַר רִבִּי יִצְחָק, הַמְלַמֵּד תּוֹרָה לְתִינוֹקוֹת, דִּירָתוֹ עִם הַשְּׁכִינָה. וְהַיְינוּ דְּאָמַר רִבִּי שִׁמְעוֹן, כַּד הֲוָה אָתֵי לְמֶחֱמֵי עוּלֵימַיָיא בְּבֵי רַב, הֲוָה אֲמַר, אֲזַלְנָא לְמֶחֱמֵי אַפֵּי שְׁכִינְתָּא.</p>"],[9514012084,"<p>וְאוֹמֵר (שם) רַק אֲשֶׁר אָכְלוּ הַנְּעָרִים, חוּץ מֵאוֹתָם אֲשֶׁר לִמְּדוּ לַנְּעָרִים תּוֹרָה, וְחֵלֶק הָאֲנָשִׁים אֲשֶׁר הָלְכוּ אִתִּי בְּאוֹתוֹ הָעוֹלָם, תֵּדַע שֶׁאַחֲזִיק בָּהֶם, וְלֹא אֶתְּנֵם לְךָ, אַף עַל פִּי שֶׁרְאוּיִם לֵיעָנֵשׁ.</p>"],[9514012085,"<p>כָל כָךְ יֵשׁ לְנִשְׁמַת הַצַּדִּיק עִם מֶלֶךְ סְדוֹם, שֶׁהוּא שָׂרוֹ שֶׁל גֵּיהִנֹּם, הַמּוֹשֵׁל עַל הָרְשָׁעִים. וְעוֹד אוֹמֵר לוֹ, לֹא אֲנִי לְבַדִּי אַחֲזִיק בְּאֵלּוּ, אֶלָּא עָנֵר אֶשְׁכּוֹל וּמַמְרֵא, שֶׁהֵם הָאָבוֹת, הֵם יִקְחוּ חֶלְקָם.</p>"],[9514012086,"<p>רַבִּי אֶלְעָזָר בַּר רַבִּי שִׁמְעוֹן פָּגַע בֵּיהּ בְּאֵלִיָּהוּ, בִּדְיוֹקְנָא דְּסָבָא חָדָא, וְעֶלֶם זְעֵיר עִמֵּיהּ, וַהֲוָה מַעֲבַר נַהֲרָא דְמַיָיא רַבָּא, לְאַעֲבָרָא לְהַךְ גִּיסָא, אָמַר לֵיהּ סָבָא, אֲרָמֵי אַכִּתְפָאי רַבְיָיא דֵין, וְאַתְּ בְּאִידָךְ גִּיסָא, וְאַעֲבַר לְכוֹן מַעַבְרָא דְמַיָא.</p>"],[9514012087,"<p>אֲמַר, וְלָאו מָארֵי דְדָרָא אַתְּ, וְלָא תֵיכוֹל לְאַעַבְרִינָנָא. אָמַר לֵיהּ סָבָא, אִי אַתְּפְסָךְ בִּתְרֵי יָדַי, לָךְ וְלֵיהּ, אֲרָמֵי יָתְכוֹן לְאִידָךְ גִּיסָא בְּפַלְגוּת מִילָּא.</p>"],[9514012088,"<p>אָמַר לֵיהּ, וְלָעִית בְּאוֹרַיְיתָא. אָמַר לֵיהּ אֵין. אָמַר לֵיהּ וְלָא נִקְרֵאת תּוּשִׁיָּה, שֶׁמַּתֶּשֶׁת כֹּחוֹ שֶׁל אָדָם. אָמַר לֵיהּ וְלָא נִקְרֵאת אַסְוָותָא, וְשִׁקּוּיָיא, שֶׁנֶּאֱמַר (משלי ג׳:ח׳) רִפְאוּת תְּהִי לְשָׁרֶךָ וְשִׁקּוּי לְעַצְמוֹתֶיךָ. אַף אֲנָא שָׁתֵי מֵאוֹרַיְיתָא סַגִּיאָה, כְּמַאן דְּשָׁתֵי מָאנָא דְּאַסְוָותָא וְאִתְיַישֵׁר חֵילִי. אַעַבְרִינוּן.</p>"],[9514012089,"<p>אָמַר לֵיהּ סָבָא סָבָא, מָאן רַבְיָא דֵין גַּבָּךְ. אָמַר לֵיהּ אֲנָא מֵלִיף לֵיהּ בְאוֹרַיְיתָא. אָמַר לֵיהּ, סָבָא סָבָא, חֵילִי סַגְיָא בְּעָלְמָא דֵין וּבְעָלְמָא דְאָתֵי, וּבְגִינֵיהּ דְּרַבְיָיא דֵין, לָא אֶשְׁבּוֹק לְמַלְאָכָא דְּגֵיהִנֹּם, לְמִינְגַע בָּךְ, וַאֲנָא עַיְילָנָא לָךְ לְעָלְמָא דְאָתֵי, בִּתְקֵיף חֵילִי דְּאִית לִי תַמָּן.</p>"],[9514012090,"<p>אָמַר לֵיהּ, רַבִּי ר', חֵילָךְ סַגִּיאָה לְעָלְמָא דְאָתֵי, כְּחַד מִן שַׁמָּשׁוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא דִּמְשַׁמְּשִׁין קֳדָמוֹהִי. עַד דְּאַשְׁגַּח בֵּיהּ, לָא חַזְיֵיהּ. אֲמַר שְׁמַע מִינָּהּ דְּאֵלִיָּהוּ הֲוָה, וַהֲוָה חָדֵי בְּעוֹבָדוֹי דַּעֲבַד לֵיהּ.</p>"],[9514012091,"<p>וּמִן יוֹמָא הַהוּא כַּד הֲוָה חָמֵי דִּיוּקְנָא דַּאֲבוּי, הֲוָה אָמַר לֵיהּ אַבָּא אַבָּא, אֵימָא לְהַהוּא סָבָא, שְׁפָמִין סַגִּיאִין מֵאוֹרַיְיתָא הֲוָה. אָמַר לֵיהּ אֵימָא לֵיהּ סָבָא דְּקַדְמָאי, סָבָא דְּפוֹתְקָא. וּמִיָּד יִתְיַישֵׁר חֵילָךְ.</p>"],[9514012092,"<p>(בראשיתטו) אַחַר הַדְּבָרִים הָאֵלֶּה הָיָה דְּבַר ה' אֶל אַבְרָם וְגו', ר' עֲזַרְיָה פְּתַח, (שיר השירים א׳:ד׳) מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה. אָמַר רִבִּי יִצְחָק, כָּל הַקּוֹרֵא קְרִיאַת שְׁמַע כְּתִקֻּנָּהּ עַל מִטָתוֹ, עוֹלָה נִשְׁמָתוֹ לָשׁוּט בְּאֶרֶץ הַחַיִּים.</p>"],[9514012093,"<p>אָמַר רִבִּי אַיְיבוּ, מַאי כְּתִקֻּנָּהּ, תָּא שְׁמַע, שִׁשִּׁים אוֹתִיּוֹת יְדוּעוֹת יֵשׁ בִּקְרִיאַת שְׁמַע שֶׁל לַיְלָה, שֶׁיְהֵא מְכַוֵּין בָּהֶם לָדַעַת, הַסּוֹבְבִים אֶת כִּסֵּא הַכָּבוֹד, שֶׁהֵם שִׁשִּׁים. הֲדָא הוּא דִכְתִיב, (שם ג) שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ מִגִּבּוֹרֵי יִשְׂרָאֵל. וְהָא ע' אִינוּן. אֶלָּא עֶשֶׂר מְמוּנִּים לְמֵיעְבַּד דִּינָא, שֶׁנֶּאֱמַר (תהילים פ״ב:א׳) אֱלֹקִים נִצָּב בַּעֲדַת אֵל.</p>"],[9514012094,"<p>תָּנוּ רַבָּנָן, זִמְנָא חָדָא, אָזַל רַבִּי דוֹסְתָּאי לְמֶחֱמֵי לְר' אֶלְעָזָר בֶּן עֲרָךְ, אִזְדַּמַּן לֵיהּ רַבִּי חַגַּי, אָמַר לֵיהּ לֵימָא לָן מַר אוֹרְחָא דְּתַקְנָא קַמֵּיהּ, לְמַאן אָזַל. אָמַר לֵיהּ לְמֶחֱמֵי סְבַר אַפֵּי יוֹמִין. אָמַר לֵיהּ מַאן הוּא. אָמַר לֵיהּ, מַאן דְּנַחֲתִין קַמֵּיהּ רַבְרְבֵי עִילָּאֵי דְּמַלְכָּא בְּרִיךְ הוּא.</p>"],[9514012095,"<p>אָמַר לֵיהּ, נִיחָא לֵיהּ לְמַר דְּאֵיזִיל עִמֵּיהּ לְאוֹרְחֵיהּ. אָמַר לֵיהּ, אִי תֵיכוֹל לְמִסְבַּר סְבָרָא לְמַאי דְתִשְׁמַע, זִיל. וְאִי לָא, סְטֵי אֲבַתְרָךְ, כִּי הֵיכֵי דְּלָא תֵעָנֵשׁ. אָמַר לֵיהּ לָא לֵיחוּשׁ מַר לְהַאי, דְּהָא שְׁמָעִית מִילְּתָא דְרָזָא עִילָּאָה, וְאִסְתַּכָּלִית בֵּיהּ, וּסְבָרִית סְבָרָא.</p>"],[9514012096,"<p>אָמַר לֵיהּ וּמַאי הִיא, אָמַר לֵיהּ שְׁמָעִית הַאי רָזָא דְהַאי פְּסוּקָא, (שיר השירים ג׳:ז׳) הִנֵּה מִטָתוֹ שֶׁלִּשְׁלמֹה, הִיא כּוּרְסְיָיא יְקָרָא דְמַלְכָּא דִּשְׁלָמָא כּוֹלָא דִילֵיהּ. שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ, אִלֵין שִׁתִּין רַבְרְבַיָא מְשַׁמְּשִׁין עִילָּאִין קַדִּישִׁין, דְּאִינוּן מְשַׁמְּשִׁין גַּבֵּי כּוּרְסָא יְקָרָא דְמַלְכָּא עִילָּאָה. מִגִּבּוֹרֵי יִשְׂרָאֵל, דְּאִנוּן מְמַנָּן תְּחוֹת שׁוּלְטָנָא רַבְרְבָא קַדִּישָׁא, מִיכָאֵל אַפּוֹטְרוֹפְּסָא דְיִשְׂרָאֵל. בְּגִין דְּאִינוּן תְּחוֹת יָדֵיהּ, כָּלְהוֹ רַבְרְבִין אַפּוֹטְרוֹפִּין דְּיִשְׂרָאֵל, הֲדָא הוּא דִכְתִיב מִגִּבּוֹרֵי יִשְׂרָאֵל.</p>"],[9514012097,"<p>אָמַר לֵיהּ ר' דּוֹסְתָּאי, יָאוֹת אַנְתְּ יַתִּיר מִנִּי, לְמֵיזַל לְמֶחֱמֵי סְבַר אַפֵּי יוֹמִין. אֲזָלוּ, כַּד מָטוֹ לְגַבֵּיהּ וְחָמָא לוֹן, אֲמַר לְשַׁמָּשֵׁיהּ זִיל וְאֵימָא לוֹן, דְּכוּרְסְיָיא דִּתְלַת קָיְימָא מַאי הִיא בְּלָא חָד.</p>"],[9514012098,"<p>שָׁמַע רַבִּי דוֹסְתָּאי, אִסְתַּכֵּל בְּנַפְשֵׁיהּ מִילְּתָא, וַאֲמַר לְשַׁמָּשָׁא זִיל וְאֵימָא לֵיהּ לְמַר, דְּלָאו לְמַגָּנָא אֲמַר דָּוִד, (תהילים קי״ח:כ״ב) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה, דָּא דָוִד מַלְכָּא דְּאִיהוּ רְבִיעָאָה.</p>"],[9514012099,"<p>אֲזַל שַׁמָּשֵׁיהּ וְאָמַר לֵיהּ הַאי מִילְּתָא. אָמַר לֵיהּ מֵימַר שַׁפִּיר קָאֲמַרְתְּ, אֶלָּא זִיל וְאֵימָא לֵיהּ, אָן גָּעֲלוּ בֵּיהּ בְּדָוִד, דַּאֲמַר אֶבֶן מָאֲסוּ הַבּוֹנִים.</p>"],[9514012100,"<p>אָמַר לֵיהּ לְר' חַגַּי, שָׁמַעְתְּ בְּהַאי מִילְּתָא פִתְגָּם, אָמַר לֵיהּ תְּלַת עִנְיָינֵי שְׁמָעִית, חַד הוּא דְרָשָׁא, אָמַר לֵיהּ לָאו לִדְרָשָׁא קָא אָתֵינָא הָכָא. דְּעוֹבָדָא דְּיִשַּׁי וּבְנוֹי שְׁמַעֲנָא, אֲבָל עִיקָּרָא דְמִלְּתָא אִי שָׁמַעְתְּ, אֵימָא.</p>"],[9514012101,"<p>אֲמַר, עִיקָּרָא דְמִלְּתָא אִינוּן תְּרֵי עִנְיָינֵי דִּשְׁמָעִית, חָדָא הוּא דַּאֲמַר אַבָּא, בְּיוֹמָא דְּאִתְבְּנֵי בֵּי מַקְדְּשָׁא עֲבַד קוּדְשָׁא בְּרִיךְ הוּא טִיבוּ סַגֵּי לְדָוִד מַלְכָּא.</p>"],[9514012102,"<p>דְּבָתַר דְּאִזְדַּמַּן לֵיהּ הַהוּא חוֹבָא, וְאַף עַל גַּב דְּמָחַל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, כַּד נָפַק מֵהַאי עָלְמָא, לָא שָׁבְקוּהוּ מַלְאֲכֵי עִילָּאֵי לְמֶעֱבַר תַּרְעֵי יְרוּשָׁלַיִם דִּלְעֵילָא, וַהֲוָה יָתֵיב אַבָּרָאי.</p>"],[9514012103,"<p>וּבְיוֹמָא דְּאִתְבְּנֵי בֵּי מַקְדְּשָׁא, קָרָא קוּדְשָׁא בְּרִיךְ הוּא לְמִיכָאֵל רַבְרְבָא קַדִּישָׁא, וּמַנֵּי לֵיהּ לְמֶהֱוֵי הוּא, וְשִׁתִּין קַדִּישִׁין עִילָּאִין, אַפּוֹטְרוֹפְּסִים דְּיִשְׂרָאֵל, אִינוּן דְּאַסְחָרוּ כּוּרְסֵי קַדִּישָׁא דִּיקָרֵיהּ.</p>"],[9514012104,"<p>וּמַנֵּי לֵיהּ לְמִיכָאֵל, לְמֵיעַל לְדָוִד מְשִׁיחָא בְּתַרְעֵי יְרוּשָׁלַיִם דִּלְעֵילָא, וּלְאַתְקָנָא לֵיהּ עִם אַבְהָתָנָא, רְתִיכָא קַדִּישָׁא עִילָּאָה, הֲדָא הוּא דִכְתִיב, (מלכים א ח) עַל כָּל הַטוֹבָה אֲשֶׁר עָשָׂה ה' לְדָוִד עַבְדּוֹ וּלְיִשְׂרָאֵל עַמּוֹ.</p>"],[9514012105,"<p>וְאִיהָךָ, עִנְיָנָא הוּא, דִּכְתִיב בִּיהוּדָה סָבוֹי, דְּגָעֲלוֹי בֵּיה אֲחוֹי. הֲדָא הוּא דִכְתִיב, (בראשית לח) וַיֵּרֶד יְהוּדָה מֵאֵת אֶחָיו, דְּסָרוֹ לֵיהּ מִגֵּאוּתֵיהּ. וְקוּדְשָׁא בְּרִיךְ הוּא לָא נִיחָא קַמֵּיהּ מִכָּל בְּנוֹי דְּיַעֲקֹב לְמֶהֱוֵי שׁוּלְטָנָא דְּמַלְכוּתָא דְעָלְמִין, אֶלָּא לִיהוּדָה. הֲדָא הוּא דִכְתִיב, (שם מט) לֹא יָסוּר שֵׁבֶט מִיהוּדָה וכו' וְלוֹ יִקְהַת עַמִּים, הוּא בִּלְחוֹדוֹי, וְלָא לִשְׁאָר בְּנוֹי דְיַעֲקֹב, וְהַיְינוּ מִלְּתָא דְּהֲוָה אֲמַר אֲבוּי.</p>"],[9514012106,"<p>וְתוּ שְׁמַעְנָא, מַאי חָמָא קוּדְשָׁא בְּרִיךְ הוּא לְמֵיהַב שׁוּלְטָנוּתָא לִיהוּדָה מִכָּל שְׁאָר אֲחוֹי. אֶלָּא, אִסְתַּכֵּל קוּדְשָׁא בְּרִיךְ הוּא בִּשְׁמֵיהּ הַגָּדוֹל דְּהֲוָה רָשִׁים בִּשְׁמֵיהּ דִּיהוּדָה, וּבְגִינֵיהּ אַשְׁלְטֵיהּ עַל כֹּלָּא, וְשׁוּלְטָנֵיהּ לָא תַעֲדֵי. אֲתָא ר' דוֹסְתָּאי וּנְשָׁקֵיהּ בְּרֵישֵׁיהּ.</p>"],[9514012107,"<p>שָׁמַע רַבִּי אֶלְעָזָר, וּנְפַק לְגַבֵּיהוֹן, אֲמַר אַתּוּן מָארֵיהוֹן דִּמְתִיבְתָּא עִילָּאָה, פַּלְגוּתָא וּשְׁלֵימָתָא אַיְיתוּ גַּבָּאי, וְתֶחֱמוּן וְתֵיחוּן. מַה דְּלָא הֲוָה גָלֵי לְעָלְמִין, דִּכְתִיב (שמות לג) כִּי לֹא יִרְאַנִי הָאָדָם וָחָי. וְאַתּוּן תֶּחֱזוּן וְתֵיחוּן.</p>"],[9514012108,"<p>יָתְבוֹן קַמֵּיהּ, אִשְׁתִּיק, וְאִינוּן אִשְׁתִּיקוּ. עָאל לְאִדְרוֹנָא, שָׁמַע הַהוּא קָלָא דְּהֲוָה אֲמַר, אֵימָא לוֹן מָה דְּאִינוּן בָּעָאן, דְּזַכָּאִין אִינוּן. עַד דְּנָחֵית, רָמַשׁ לֵילְיָא. אֲכָלוּ. עַד דַּהֲווֹ אָכְלֵי, אִשְׁתִּיק, וְאִינוּן אִשְׁתִּיקוּ. כַּד אֲכָלוּ, קָמוּ לְמִשְׁכַּב, אֲמַר לוֹן אִי אִית מִנְּכוֹן, דְּשָׁמַע מִילְּתָא לֵימָא לִי.</p>"],[9514012109,"<p>פָּתַח רַבִּי דוֹסְתָּאי וַאֲמַר, אֲנַן סְבָרָא נִסְבּוֹר, וְטִיבוּ לְמִינְדַע, אַתְּ אֵימָא לָן. אֲמַר לוֹן, שְׁמַעְתּוּן הַאי מִילְּתָא דְאָמַר רִבִּי יִצְחָק, כָּל הַקּוֹרֵא קְרִיאַת שְׁמַע כְּתִקֻּנָּהּ עַל מִטָתוֹ, נִשְׁמָתוֹ עוֹלָה לָשׁוּט בְּאֶרֶץ הַחַיִּים. הֲדָא הוּא דִכְתִיב, (שיר השירים ג) שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ מִגִּבּוֹרֵי יִשְׂרָאֵל. אֲמָרוּ לֵיהּ לֵימָא מַר.</p>"],[9514012110,"<p>אֲמַר לוֹן, בִּקְרִיאַת שְׁמַע אִית שִׁתִּין אַתְוָותָא יְדִיעָאן, עַד וּבִשְׁעָרֶיךָ. וְעַל כָּל אָת וְאָת אִית סוֹד יְקָרָא דְמַלְכוּתָא קַדִּישָׁא, דְּשַׁלִּיטָא עִילָּאָה. וּפוּלְחָנֵיהּ דְּבַר נַשׁ קַמֵּיהּ, עַד דִּיקָרֵב דַּעְתֵּיהּ, לְכוּרְסֵי יְקָרָא דְמַלְכוּתָא קַדִּישָׁא.</p>"],[9514012111,"<p>וּבְהַהוּא שַׁעֲתָא, נָסֵיב לוֹן מִן פּוּמֵיהּ מָארֵיהּ דְּאַפַּיָּיא, דִּי שְׁמֵיהּ כִּשְׁמָא דְמָרֵיהּ, וְהוּא אַסֵּיק לְהוֹן לְעֵילָא עִם נִשְׁמוֹתֵיהֶן דְּצַדִּיקַיָיא, קַמֵּי מַדְבְּחָא יְקָרָא דִלְעֵילָא.</p>"],[9514012112,"<p>וְנָסְבִין לוֹן, שִׁתִּין מַלְאָכִין, דְּסָחֲרִין כּוּרְסֵי יְקָרָא, כָּל חַד וְחַד אָת חַד, וּמְזַמְּרִין בְּהוֹן כָּל לֵילְיָא. הֲדָא הוּא דִכְתִיב, (דברים כו) וְלָקַח הַכֹּהֵן הַטֶנֶא מִיָּדֶךָ וְהִנִּיחוֹ לִפְנֵי מִזְבַּח ה' אֱלֹהֶיךָ. וְלָקַח הַכֹּהֵן, דָּא הוּא מטטרו\"ן, הַטֶנֶ\"א, אִלֵּין שִׁתִּין אַתְוָותָא דִּקְרִיאַת שְׁמַע דְּלֵילְיָא.</p>"],[9514012113,"<p>אוֹלִיף לְהוֹ, נָפַק נִשְׁמַתְהוֹן מִנַּיְיהוּ, וְחָמוֹ מַה דְּחָמוֹ, וְאִיתְעָרוּ. אֲמַר חַד לְחַד, לָא נֵיתֵיב כָּאן, לֵית אֲנַן חַזְיָין לְהַאי. מַאן דְּאִיהוּ מַלְאָכָא עִילָּאָה, לֶהֱוֵי בְּהַאי יְקָר. מַאי הֲוָה דַעְתַּיְיהוּ. חָזוֹ דְּמַלְאָכַיָיא דַּחְיָין לְהוֹ לְבַר, וְאִצְטְעָרוּ, עַד דְחָמוֹ מַאי דְּחָמוֹ, וְנִשְׁמָתֵיהּ דְּרַבִּי אֶלְעָזָר אַעֲבַר לְהוֹ, וְאִשְׁתְּזֵיבוּ.</p>"],[9514012114,"<p>חָמוֹ לְהַהוּא כַּהֲנָא רַבָּא, דַּאֲתָא לְקַבְּלָא אוּלְפָנֵיהּ דְּרַבִּי אֶלְעָזָר, וַאֲמַר, רַבָּה קַדִּישָׁא, סַק סַק, אָמַר לֵיהּ, מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה. אָמַר לֵיהּ, מַאן אִלֵּין גַּבָּךְ. אָמַר לֵיהּ רַבְרְבֵי דָרָא אִינוּן. אָמַר לֵיהּ לֵית לִי רְשׁוּתָא, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא אֲמַר לִי לְקַבְּלָא אַפָּךְ, וַאֲנָא עַיְילָנָא קַמֵּיהּ, הֲדָא הוּא דִכְתִיב, (שיר השירים א׳:ד׳) הֱבִיאַנִי הַמֶּלֶךְ חֲדָרָיו. וּבְחַיָּיךְ קַדִּישָׁא כָּל חֵילֵי דִשְׁמַיָיא, נָגִילָה וְנִשְׂמְחָה בָךְ.</p>"],[9514012115,"<p>אָמַר רִבִּי יִצְחָק, כָּךְ, לְכָל צַדִּיקַיָּיא, עָבִיד קוּדְשָׁא בְּרִיךְ הוּא, לְמטטרו\"ן שַׂר הַפָּנִים, דִּיסַלֵּק נִשְׁמָתַיְיהוּ לְעֵילָא. הוּא אוֹמֵר סַק סַק, ונִשְׁמָתֵיהּ אָתֵיב לֵיהּ וְאוֹמֵר, מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה הֱבִיאַנִי הַמֶּלֶךְ חֲדָרָיו. הוֹאִיל וּרְעוּתֵיהּ דַּאֲנָא עָיֵיל לְאִידְרִין עִילָאִין נָגִילָה וְנִשְׂמְחָה בָךְ. הֲדָא הוּא דִכְתִיב (תהילים קמ״ט:ה׳) יַעְלְזוּ חֲסִידִים בְּכָבוֹ\"ד, דָּא מטטרון.</p>"],[9514012116,"<p>אָמַר רִבִּי יִצְחָק, בְּאוֹתָהּ שָׁעָה שֶׁנִּשְׁמָתוֹ שֶׁל אוֹתוֹ צַדִּיק עוֹלָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, עוֹשֶׂה לוֹ הַבְטָחָה, וּמְבָרֵךְ לוֹ. הֲדָא הוּא דִכְתִיב, (בראשית ט״ו:א׳) אַחַר הַדְּבָרִים הָאֵלֶּה הָיָה דְּבַר ה' אֶל אַבְרָם בַּמַּחֲזֶה לֵאמֹר אַל תִּירָא אַבְרָם אָנֹכִי מָגֵן לָךְ שְׂכָרְךָ הַרְבֵּה מְאֹד. אֶל אַבְרָם, זוֹ הִיא הַנְּשָׁמָה. בַּמַּחֲזֶה, כְּשֶׁהוּא שׁוֹכֵב עַל מִטָתוֹ. וּמַה אוֹמֵר לוֹ, אַל תִּירָא אַבְרָם אָנֹכִי מָגֵן לָךְ שְׂכָרְךָ הַרְבֵּה מְאֹד.</p>"],[9514012117,"<p>דָּבָר אַחֵר בַּמַּחֲזֶה, זֶהוּ שֶׁנֶּאֱמַר (שמות כ״ד:י״ז) וּמַרְאֵה כְבוֹד ה' כְּאֵשׁ אוֹכֶלֶת בְּרֹאשׁ הָהָר. וְזֶהוּ מטטרו\"ן, הַמּוֹלִיכוֹ לִפְנֵי בּוֹרְאוֹ.</p>"],[9514012118,"<p>דָּבָר אַחֵר אָמַר רִבִּי תַּנְחוּם, מַה כְּתִיב לְמַעְלָה מִן הָעִנְיָן, רַק אֲשֶׁר אָכְלוּ הַנְּעָרִים, וּכְתִיב בַּתְרֵיהּ אַחַר הַדְּבָרִים הָאֵלֶּה הָיָה דְּבַר ה' אֶל אַבְרָם. בְּאוֹתָהּ שָׁעָה שֶׁהַנְּשָׁמָה יוֹשֶׁבֶת וְנִזּוֹנֵת מֵאוֹתוֹ הָאוֹר שֶׁל מַעְלָה, וּמִתְלַבֶּשֶׁת בּוֹ. דְּאָמַר רִבִּי תַּנְחוּם, לְבוּשׁ הַנְּשָׁמָה לָעוֹלָם הַבָּא, הוּא אוֹר זוֹהֵר שֶׁלְּמַעְלָה מִכִּסֵּא הַכָּבוֹד הוּא, שֶׁנֶּאֱמַר (תהילים צ״ז:י״א) אוֹר זָרוּעַ לַצַּדִּיק וּלְיִשְׂרֵי לֵב שִׂמְחָה. וּכְתִיב (ישעיהו ס׳:כ׳) וְהָיָה לָךְ ה' לְאוֹר עוֹלָם. וְלֹא מַלְאָךְ וְלֹא כִסֵּא הַכָּבוֹד. וְדָוִד אָמַר (תהילים כ״ז:א׳) ה' אוֹרִי וְיִשְׁעִי מִמִּי אִירָא.</p>"],[9514012119,"<p>וְאָזְלָא הָא, כִּי הָא דְאָמַר רִבִּי יְהוּדָה, נִשְׁמָתוֹ שֶׁל צַדִּיק נִיטְלָה מֵאוֹר כִּסֵּא הַכָּבוֹד, וְנִכְנַס בָּעוֹלָם הַזֶּה. אִי זָכְתָה וְעוֹלָה לְמַעְלָה, אֵינוֹ דִין שֶׁיִּתּוֹסַף לָהּ יוֹתֵר אוֹר מִמַּה שֶּׁקִּבְּלָה בָּרִאשׁוֹנָה לִיכָּנֵס בָּעוֹלָם הַזֶּה. וּמִמִּי מְקַבֶּלֶת אוֹתוֹ הָאוֹר, אָמַר רִבִּי יְהוּדָה, אִלְמָלֵא מִקְרָא כָּתוּב אִי אֶפְשָׁר לְאוֹמְרוֹ, דִּכְתִיב (בראשית ט״ו:א׳) אַל תִּירָא אַבְרָם אָנֹכִי מָגֵן לָךְ, אָנֹכִי וְלֹא אַחֵר, וְלָמָּה, בִּשְׁבִיל שֶׁשְּׂכָרְךָ הַרְבֵּה מְאֹד.</p>"],[9514012120,"<p>דָּבָר אַחֵר שְׂכָרְךָ הַרְבֵּה מְאֹד, יֵשׁ לָךְ שָׂכָר הַרְבֵּה מְאֹד, עַל שֶׁהָיָה לְךָ בָּרִאשׁוֹנָה. וּמִתְלַבֶּשֶׁת מֵאוֹתוֹ הָאוֹר, וְהַקָדוֹשׁ בָּרוּךְ הוּא נוֹטֵל אוֹת א' מִשְׁמוֹ, וְנוֹתְנָהּ בְּרֹאשָׁהּ. כִּי הָא דִּתְנַן, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִהְיוֹת עֲטָרָה בְּרֹאשׁ כָּל צַדִּיק וְצַדִּיק לָעוֹלָם הַבָּא. וְאֵיזֶהוּ, זֶה אוֹת ה\"א, כַּאֲשֶׁר בָּרָא שָׁמַיִם וָאָרֶץ, דִּכְתִיב (בראשית ב) בְּהִבָּרְאָם, בְּה\"א בְּרָאָם.</p>"],[9514012121,"<p>הֲדָא הוּא דִכְתִיב, (שם יז) וְלֹא יִקָּרֵא עוֹד אֶת שִׁמְךָ אַבְרָם וְהָיָה שִׁמְךָ אַבְרָהָם. לִהְיוֹת הַנְּשָׁמָה שְׁלֵימָה בְּתַכְלִית הַשְּׁלֵימוּת וְהַטוֹב, הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ד:ג׳) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתֶךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ.</p>"],[9514012122,"<p>רַבִּי יְהוּדָה בֶּן פַּזִי, הֲוָה לֵיהּ הַהוּא אֲרִיסָא, וַהֲוָה קָא מְצַעֵר לֵיהּ, אָתוֹ לְקַמֵּיהּ ר' זֵירָא וְר' אַבָּא, אֲמָרוּ לֵיהּ מַאי עָבִיד מַר בַּאֲרִיסֵיהּ. אֲמַר לְהוֹן גַּבְרָא כִּי גָנִיב, מָארֵיהּ דְּשִׁמְשָׁא יַזְהֵר עֲלֵיהּ זִיהֲרָא. אֲמָרוּ לֵיהּ, לָא לְעַיֵּין מַר בְּמִלֵּיהּ. אֲמַר לְהוֹ, וּמָה אַעֲבֵיד וְהוּא מְצַעֵר לִי. אֲמָרוּ לֵיהּ, יִתְפְּרֵשׁ מַר מִינֵיהּ, וְיִתְהַנֵּי לָךְ.</p>"],[9514012123,"<p>עַד דַּהֲווֹ יָתְבֵי, אֲמָרוּ לֵיהּ לָאו לְהַאי אָתֵינָא גַבָּךְ, אֶלָּא לֵימָא לָן מַר, הַשְּׁבָטִים בְּנֵי יַעֲקֹב, מָה אִינוּן לְעָלְמָא דְאָתֵי. אֲמַר לְהוֹ, קוּדְשָׁא בְּרִיךְ הוּא סָלֵיק לְהוֹ לִמְתִיבְתָּא דִּרְקִיעָא, וְכָל נִשְׁמָתָא דְּצַדִּיק דְּסָלֵיק, אִינוּן סַהֲדִין עַל עוֹבָדוֹי.</p>"],[9514012124,"<p>הֲדָא הוּא דִכְתִיב, (תהילים קכ״ב:ד׳) יְרוּשָׁלַיִם הַבְּנוּיָה, זוֹ יְרוּשָׁלַיִם שֶׁל מַעְלָה. שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל, כְּדֵי לְהָעִיד עַל כָּל צַדִּיק וְצַדִּיק מִיִּשְׂרָאֵל. וְלָמָּה, לִהְיוֹת כֻּלָּם מוֹדִים וּמְבָרְכִים לִשְׁמוֹ. הֲדָא הוּא דִכְתִיב, עֵדוּת לְיִשְׂרָאֵל לְהֹדוֹת לְשֵׁם ה'. וְכָל אֶחָד וְאֶחָד מַכִּיר אֶת שֶׁלּוֹ וּמִשְׁתַּבֵּחַ וְאוֹמֵר, רִבּוֹנוֹ שֶׁל עוֹלָם רְאֵה מַה הִנַּחְתִּי בָּאָרֶץ, וְזֶהוּ לְהוֹדוֹת לְשֵׁם ה'.</p>"],[9514012125,"<p>וְהַיְינוּ דִתְנַן, כָּל צַדִּיק וְצַדִּיק יֵשׁ לוֹ מָדוֹר לְפִי כְבוֹדוֹ, וּלְפִי הָרָאוּי לוֹ. מַאן דְּאָתֵי מֵרְאוּבֵן, שָׁם מְדוֹרוֹ עִם הַצַּדִּיקִים מִן רְאוּבֵן, וְכֵן כָּל שֵׁבֶט וְשֵׁבֶט. וּמַאן דְּהוּא גֵּר מאוּמוֹת הָעוֹלָם וְנִתְגַּיֵּיר, מְדוֹרוֹ בַּמָּדוֹר שֶׁל גֵּרִים. וְהַשְּׁבָטִים, עוֹמְדִים לְעֵדִים לְכָל צַדִּיק וְצַדִּיק. הֲדָא הוּא דִכְתִיב, שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל לְהֹדוֹת לְשֵׁם ה'.</p>"],[9514012126,"<p>אָמַר רִבִּי יְהוּדָה, נִשְׁמָתוֹ שֶׁל צַדִּיק, יוֹדַעַת וּמַכֶּרֶת לָעוֹלָם הַבָּא, מַה שֶּׁאֵינוֹ יוֹדֵעַ וּמַכִּיר מַלְאָךְ הַמְשָׁרֵת. הֲדָא הוּא דִכְתִיב, (ישעיהו ג׳:י׳) אִמְרוּ צַדִּיק כִּי טוֹב, כִּי טוֹב מִמַלְאָךְ הַשָׁרֵת. וּכְתִיב (תהילים צ״ז:י״א) אוֹר זָרוּעַ לַצַּדִּיק וּלְיִשְׁרֵי לֵב שִׂמְחָה.</p>"],[9514012127,"<p>רַבִּי אַבָּא פָּתַח וְאָמַר, (מיכה ז׳:ט״ו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרַיִם אַרְאֶנּוּ נִפְלָאוֹת, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד פּוּרְקָנָא לִבְנוֹי, כְּאִינוּן יוֹמִין דְּשָׁלַח קוּדְשָׁא בְּרִיךְ הוּא לַאֲפָקָא לְיִשְׂרָאֵל, וְאַלְקֵי בְּאִינוּן מַכְתְּשִׁין לְמִצְרַיִם, בְּגִינֵיהוֹן דְּיִשְׂרָאֵל.</p>"],[9514012128,"<p>תָּא חֲזֵי, מַה בֵּין פּוּרְקָנָא דָא, לְפוּרְקָנָא דְמִצְרַיִם. פּוּרְקָנָא דְמִצְרַיִם הֲוָה, בְּחַד מַלְכָּא וּבְמַלְכוּ חַד. הָכָא, בְּכָל מַלְכִין דְּעָלְמָא, וּבְכָל מַלְכוּתָא דְעָלְמָא. וּכְדֵין אִתְיַיקַר קוּדְשָׁא בְּרִיךְ הוּא בְּכָל עָלְמָא, וּבְכָל אַרְעָא, וְיִנְדְּעוּן כֹּלָּא שׁוּלְטָנֻתֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא בְּכָל עָלְמָא, וְכָלְהוֹ יִלְקוֹן בְּמַכְתְּשִׁין עִילָּאִין עַל חַד תְּרֵין, בְּגִין דִּי סֵרְבוּן בְּהוֹן בְּיִשְׂ רָאֵל.</p>"],[9514012129,"<p>וְכַד יִנְדְּעוּן שׁוּלְטָנוּתֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, כְּמָא דִכְתִיב, (זכריה י״ד:ח׳-ט׳) וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ. כְּדֵין כָּלְהוֹ יִתְנַדְּבוּן בְּהוּ בְּיִשְׂרָאֵל לְקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ו:כ׳) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם מִכָּל הַגּוֹיִם מִנְחָה לַה'. כְּדֵין יִזְדַּמְּנוּן אֲבָהָן בְּחֶדְוָה, לְמֶחֱמֵי פּוּרְקָנָא דִבְנַיְיהוּ כְּמִלְּקַדְּמִין. הֲדָא הוּא דִכְתִיב כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרַיִם אַרְאֶנּוּ נִפְלָאוֹת.</p>"],[9514012130,"<p>(בראשית יח) וְאַבְרָהָם הָיֹה יִהְיֶה: יִהְיֶה בְּגִי' שְׁלשִׁים. יוֹמָא חַד נָפַק ר' שִׁמְעוֹן, וְחָזָא עָלְמָא דְּחָשֵׁיךְ וְאָפֵיל, וְאִסְתַּתֵּם נְהוֹרֵיהּ. אָמַר לֵיהּ רַבִּי אֶלְעָזָר, תָּא וְנֶחֱזֵי מַה בָּעָא קוּדְשָׁא בְּרִיךְ הוּא. אֲזָלוּ, וְאַשְׁכָּחוּ חַד מַלְאָכָא, דְּדָמֵי לְטוּרָא רַבְרְבָא, וְאַפֵּיק תְּלָתִין שַׁלְהוֹבִין דְּנוּרָא מִפּוּמֵיהּ.</p>"],[9514012131,"<p>אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, מָה אַתְּ בָּעֵי לְמֵיעְבַּד, אָמַר לֵיהּ בָּעֵינָא לְמִחְרְבֵיהּ לְעָלְמָא, בְּגִין דְּלָא שְׁכִיחֵי תְּלָתִין זַכָּאִין בְּדָרָא. דְּהָכֵי גָּזַר קוּדְשָׁא בְּרִיךְ הוּא עַל אַבְרָהָם, וְאַבְרָהָם הָיֹה יִהְיֶה, יִהְיֶה בְּגי' תְּלָתִין הֲווֹ. אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, בְּמָטוּ מִינָךְ זִיל קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְאֵימָא לֵיהּ, בַּר יוֹחָאי שְׁכִיחַ בְּעָלְמָא.</p>"],[9514012132,"<p>אֲזַל הַהוּא מַלְאָכָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, אָמַר לֵיהּ, מָארֵי עָלְמָא גְּלֵי קַמָּךְ מַה דַּאֲמַר לִי בַּר יוֹחָאי, אֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, זִיל אַחְרְבֵיהּ לְעָלְמָא, וְלָא תַשְׁגַּח בֵּיהּ בְּבַר יוֹחָאי.</p>"],[9514012133,"<p>כַד אָתָא, חַזְיֵיהּ רַבִּי שִׁמְעוֹן לְמַלְאָכָא, אָמַר לֵיהּ אִי לָא תֵיזֵל, גָּזַרְנָא עֲלָךְ דְּלֹא תֵיעוֹל לִשְׁמַיָיא, וְתֶהֱוֵי בַּאֲתַר דַּעֲזָא וַעֲזָאֵל. וְכַד תֵיעוֹל קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא אֵימָא לֵיהּ, וְאִי לֵית תְּלָתִין זַכָּאִין בְּעָלְמָא, לֶיהֱווֹן עֶשְׂרִים. דְּהָכֵי כְּתִיב לֹא אֶעֱשֶׂה בַּעֲבוּר הָעֶשְׂרִים. וְאִי לֵית עֶשְׂרִים, לֶהֱווֹ עֲשָׂרָה, וְאַחַר כַּךְ כְּתִיב, לֹא אַשְׁחִית בַּעֲבוּר הָעֲשָׂרָה. אִי לֵית עֲשָׂרָה לֶהֱווֹן תְּרֵין, דְּאִינוּן אֲנָא וּבְרִי. דְּהָכֵי כְּתִיב, (דברים יט) עַל פִּי שְׁנַיִם עֵדִים יָקוּם דָּבָר, וְאֵין דָּבָר אֶלָא עוֹלָם, דִּכְתִיב (תהלים לג) בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ וכו'. וְאִי לֵית תְּרֵין, הָא אִית חַד, וַאֲנָא הוּא. דִּכְתִיב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. בֵּיהּ שַׁעֲתָא נְפַק קָלָא מִן שְׁמַיָא וַאֲמַר, זַכָּאָה חוּלָקָךְ רַבִּי שִׁמְעוֹן, דְּקוּדְשָׁא בְּרִיךְ הוּא גָּזַר לְמַעְלָה, וְאַתְּ מְבַטֵל לְתַתָּא, בְּוַדַּאי עֲלָךְ כְּתִיב (תהלים קמה) רְצוֹן יְרֵאָיו יַעֲשֶׂה.</p>"],[9514012134,"<p>(בראשית כ״ה:ל׳) וַיֹּאמֶר עֵשָׂו אֶל יַעֲקֹב הַלְעִיטֵנִי נָא מִן הָאָדֹם הָאָדֹם הַזֶּה. אַמַּאי כְּתִיב תְּרֵי זִמְנֵי הָאָדוֹם. אֶלָּא, בְּגִין דְּכָל מַה דְּאִית לֵיהּ אֱדוֹם, הוּא אָדוֹם, כְּמָה דְאַתְּ אָמֵר (שם) וַיֵּצֵא הָרִאשׁוֹן אַדְמוֹנִי. וְתַבְשִׁילָא דִילֵיהּ אָדוֹם, דִּכְתִיב הַלְעִיטֵנִי נָא מִן הָאָדֹם הָאָדֹם הַזֶּה. וְאַרְעָא דִילֵיהּ אֲדוּמָה, דִּכְתִיב אַרְצָה שֵׂעִיר שְׂדֵה אֱדוֹם. וְגוּבְרִין דִּילֵיהּ אֲדוּמִין, דִּכְתִיב (בראשית ל״ו:ט׳) הוּא עֵשָׂו אֲבִי אֱדוֹם. וּמַאן דְּזַמִּין לְאִתְפְּרָעָא מִנֵּיהּ אָדוֹם, דִּכְתִיב דּוֹדִי צַח וְאָדוֹם. וּלְבוּשֵׁיהּ אָדֹם, דִּכְתִיב (ישעיהו ס״ג:ב׳) מַדּוּעַ אָדֹם לִלְבוּשֶׁךָ, וּכְתִיב (שם) מִי זֶה בָּא מֵאֱדוֹם.</p>"],[9514012135,"<p><Noneb> סִתְרֵי תּוֹרָה </b></p>"],[9514012136,"<p>תָּא חֲזֵי, שִׁבְעָה יוֹמִין עִלָּאִין, בָּרָא קוּדְשָׁא בְּרִיךְ הוּא בְּעָלְמָא. וַעֲלַיְיהוּ שָׁתֵיל וּבָנֵי עָלְמִין. הֲדָא הוּא דִכְתִיב (שמות כ׳:י״א) כִּי שֵׁשֶׁת יָמִים עָשָׂה ה', וְלֹא כְתִיב בְּשֵׁשֶׁת.</p>"],[9514012137,"<p>וְלָקֳבֵיל אִינוּן שִׁבְעָה יוֹמִין עִילָּאִין, בָּרָא בְּאַרְעָא שִׁבְעָה זַכָּאֵי קְשׁוֹט, לְקָיְימָא לוֹן, וּלְאַנְהָרָא לוֹן, כָּל חַד וְחַד לָקֳבֵיל יוֹמֵיהּ. וְשָׁתֵיל לְהוֹ, כָּל חַד וְחַד בְּדָרָא דְּאִתְחֲזֵי לֵיהּ. וְאִינוּן אֲבָהָן דְּעָלְמָא, אַבְרָהָם יִצְחָק וְיַעֲקֹב וְיוֹסֵף וּמשֶׁה וְאַהֲרֹן וְדָוִד.</p>"],[9514012138,"<p>וְאִינוּן אִיקְרוּן הָרִים, הַרְרֵי קֶדֶם, דְּאִינוּן תַּלְיָיִן מֵאִינוּן שִׁבְעָה יוֹמִין עִילָּאִין דַּאֲמָרָן. ו' יוֹמֵי בְּרֵאשִׁית, וְז' דְּקָיְימָא קַמַּיְיהוּ, הֲדָא הוּא דִכְתִיב, (זכריה י״ב:ח׳) וּבֵית דָּוִד כֵּאלֹהִים כְּמַלְאַךְ ה' לִפְנֵיהֶם.</p>"],[9514012139,"<p>וְאַף עַל גַּב דְּאִיהוּ שְׁבִיעָאָה, רְבִיעָאָה אִיהוּ בְּיוֹמִין. וְיוֹסֵף אִיהוּ שְׁבִיעָאָה. אֲבָל כַּד אִתְכְּלִילַת בֵּיהּ בְּיוֹסֵף, וְיָהֵיב לֵיהּ תּוֹסֶפֶת תַּפְנוּקָא מִבֵּי מַלְכָּא, אִקְרֵי אוּף אִיהִי שְׁבִיעָאָה.</p>"],[9514012140,"<p>וְכָלְהוֹ אֲחִידוּ בַּה בִּשְׁכִינְתָּא, בְּרָזָא דְּשִׁבְעָה. בְּגִין דִּשְׁכִינְתָּא אִיקְרֵי בַּת שֶׁבַע. בַּת מֵאִימָּא עִילָּאָה, דְּאִיהִי כְּלָלָא דְּשֶׁבַע דַּרְגִּין דְּעִמַּהּ. וְאִיהִי דַּרְגָּא דְּצֶדֶק, עֲשִׂירָאָה דְּאִינוּן סְפִירִין, דְּאִיקְרֵי בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9514012141,"<p>וְאִיקְרֵי שְׁבִיעָאָה בִּקְרָא, (דברי הימים א כ״ט:י״א) דִּלְךָ ה' הַגְּדֻלָּה וְהַגְּבוּרָה וְהַתִּפְאֶרֶת וְהַנֵּצַח וְהַהוֹד כִּי כֹל וכו', עַד הַמַּמְלָכָה. וּמַאי טַעְמָא, וְהָא רְבִיעָאָה הִיא לְיוֹמֵי. אֶלָּא בְּגִין דְּאִיהִי נְטִיעָה בַּתְרָאָה, וְאִתְכְּלִילַת בִּשְׁבִיעָאָה, בְּגִין כָּךְ נָטְלָה שְׁמֵיהּ, וְכוֹלָּא חַד.</p>"],[9514012142,"<p>וְכָל חַד וְחַד מֵאֲבָהָן, יָדַע לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, מִגּוֹ אַסְפַּקְלַרְיָא דִילֵיהּ. אַבְרָהָם יָדַע לֵיהּ, מִגּוֹ חֶסֶד, דְּאִיהוּ מִדַּת הַגְּדוּלָּה, מִדַּת הַחֶסֶד, יָמִינָא דְמַלְכָּא. וְעַל דָּא אָחִיד בָּהּ, וְלָא שָׁבִיק לָהּ לְעָלְמִין, וְעָבִיד טִיבוּ עִם בְּנֵי נָשָׁא, וְאוֹקְמוּהָ. דְּהָא עוֹבָדוֹי סְלִיקוּ לֵיהּ בְּהַאי דַרְגָּא.</p>"],[9514012143,"<p>יִצְחָק יָדַע לֵיהּ בְּדַרְגָּא דִּגְבוּרָה, דְּאִקְרֵי פַּחַד יִצְחָק, וְדָחִיל לֵיהּ לְעָלְמִין. יַעֲקֹב יָדַע לֵיהּ מִגּוֹ דַּרְגָּא דְּתִפְאֶרֶת. דְּאִיהוּ כָּלִיל מֵחֶסֶד וּמִפַּחַד, וְאִקְרֵי אֱמֶת, וְאָחִיד בַּהּ. הֲדָא הוּא דִכְתִיב, (מיכה ז׳:כ׳) תִּתֵּן אֱמֶת לְיַעֲקֹב.</p>"],[9514012144,"<p>יוֹסֵף יָדַע לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא מִגּוֹ הַהִיא אַסְפַּקְלַרְיָא, דְּאִקְרֵי כֹל. וְעַל דָּא אִיקְרֵי יוֹסֵף כִּלְכֵּל, דִּכְתִיב (בראשית מ״ז:י״ב) וַיְכַלְכֵּל יוֹסֵף. וְאִיקְרֵי יְסוֹד עוֹלָם.</p>"],[9514012145,"<p>משֶׁה וְאַהֲרֹן אִינוּן תְּרֵין כְּרוּבִין, דְּאִשְׁתְּמַע קָלָא דִּלְעֵילָא מִבֵּינַיְיהוּ, וְעַל דָּא אִתְיְיהִיבַת אוֹרַיְיתָא עַל יָדַיְיהוּ. הֲדָא הוּא דִכְתִיב, וְנוֹעַדְתִּי לְךָ שָׁם וְדִבַּרְתִּי אִתְּךָ וְגוֹמֵר. וְאִינוּן תְּרֵין כְּרוּבִין דִּלְעֵילָא, אִינוּן נֵצַח וָהוֹד, וְאִינוּן תְּרֵין סַמְכִין דְּגוּפָא.</p>"],[9514012146,"<p>כְגַוְונָא דָא, אִית לָהּ לְמַטְרוֹנִיתָא לְתַתָּא, תְּרֵין כְּרוּבִין תְּחוֹתָהּ, דְּיָנְקִין מִינָהּ. וְאִינוּן עִילָּאִין וַדַּאי, עַל אֲרוֹן הָעֵדוּת, דְּאִיקְרֵי צֶדֶק, אֲרוֹנָא דְעֵדוּת. וּמַאן עֵדוּת, דָּא יוֹסֵף, הֲדָא הוּא דִכְתִיב, (תהילים פ״א:ו׳) עֵדוּת בִּיהוֹסֵף שָׂמוֹ. וְאִיקְרֵי תּוֹרָה שֶׁבִּכְתַב, וְהַאי אֲרוֹנָא תּוֹרָה שֶׁבְּעַל פֶּה.</p>"],[9514012147,"<p>תָּא חֲזֵי, כָּל אִינוּן אֲבָהָן עִילָּאִין דַּאֲחִידָן לְעֵילָא, רְמִיזָן כָּלְהוֹ בַּתּוֹרָה שֶׁבִּכְתָב, תּוֹרַת ה'. וְדָוִד דְּאִיהוּ אָחִיד בְּבָרְיָיתָא, דְּאִיהִי תּוֹרָה שֶׁבְּעַל פֶּה, רְמִיזָא בְּדִבְרֵי קַבָּלָה. וּבְגִין כָּךְ אִקְרֵי קַבָּלָה, דִּמְקַבֶּלֶת נְהִירוּ מִתּוֹרָה שֶׁבִּכְתָב, דְּאִיקְרֵי צַדִּיק, וְאִיקְרֵי יוֹסֵף, וְאִיקְרֵי כֹל.</p>"],[9514012148,"<p>וְאִינוּן תְּרֵין כְּרוּבִין עִילָּאִין, קָיְימִין עַל הַהוּא סַהֲדוּתָא דַּאֲרוֹנָא, הֲדָא הוּא דִכְתִיב, (דברי הימים א כ״ט:י״א) וְהַנֵּצַח וְהַהוֹד, כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ, וְדָא אִיהוּ סִיּוּמָא דִּשְׁמַיָא וּמְזַוֵּוג לְהַאי אֶרֶץ.</p>"],[9514012149,"<p>וְהָכֵי הוּא, דְּכָל מַה שֶּׁבָּרָא קוּדְשָׁא בְּרִיךְ הוּא לְעֵילָא, בָּרָא לְקִבְלֵיהּ לְתַתָּא. וְיוֹסֵף אִקְרֵי עֵדוּת, הֲדָא הוּא דִכְתִיב עֵדוּת בִּיהוֹסֵף שָׂמוֹ. וְעַל דָּא שְׁמָא דְיוֹסֵף שְׁלִים בְּכֹלָּא לְעֵילָא וְתַתָּא.</p>"],[9514012150,"<p>וְעַל דָּא תָּנִינָן, אָרוֹן דְּיוֹסֵף וְאָרוֹן דִּשְׁכִינְתָּא, בַּהֲדֵי הֲדָדֵי הֲווֹ אָזְלִין בְּמַדְבְּרָא, וַהֲווּ כּוּלֵּי עָלְמָא אָמְרֵי מַה טִיבָן שֶׁל שְׁנֵי אֲרוֹנוֹת אֵלּוּ. וּמְתִיבִין לוֹן, קִיִּים זֶה מַה שֶּׁכָּתוּב בָּזֶה. קִיִּי\"ם וַדַּאי, הֲדָא הוּא דִכְתִיב, (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם, אִיהוּ קִיּוּמָא דְעָלְמָא.</p>"],[9514012151,"<p>אָתָא דָוִד דְּאִיהוּ שְׁבִיעָאָה, דַּאֲבָהָן אָחִיד בַּהּ, בְּהַאי בַּת שֶׁבַע, דְּאִיהִי מַמְלָכָה, וְלָא שָׁבִיק לָהּ לְעָלְמִין. הֲדָא הוּא דִכְתִיב, (יחזקאל ל״ז:כ״ה-כ״ו) וְדָוִד עַבְדִּי נָשִׂיא לָהֶם לְעוֹלָם. וּכְתִיב, (תהלים פט) כִּסְאוֹ כַּשֶּׁמֶשׁ נֶגְדִּי. וְכָל דָּא אוֹלִיף לָן אוֹרַיְיתָא, דְּכָלְהוֹ אֲחִידָן בַּהּ בִּשְׁכִינְתָּא בְּרָזָא דְּשֶׁבַע.</p>"],[9514012152,"<p>תָּא חֲזֵי, אַבְרָהָם בּוּצִינָא קַדְמָאָה קַדִּישָׁא דְעָלְמָא, כַּד בָּעָא לְסַלְקָא לְדַרְגֵּיהּ, לָא יָכִיל, עַד דְּסָלֵיק וְאִשְׁתְּמוֹדַע בְּאִינוּן תְּלַת דַּרְגִּין עִילָּאִין דַּעֲלֵיהּ, דְּהַהוּא חוּלָקָא דִילֵיהּ.</p>"],[9514012153,"<p>כֵיוָן דְּסָלֵיק וְאִשְׁתְּמוֹדַע לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, מִגּוֹ אִינוּן תְּלַת דַּרְגִּין, דְּעִם אִינוּן שִׁבְעָה, דְּאִיקְּרוֹן כֶּתֶר עֶלְיוֹן חָכְמָה בִּינָה, וְאִינוּן שְׁלִימוּ דְּעֶשֶׂר סְפִירָן, דְּאִיקְרֵי בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא. וְכֵיוָן דְּסָלֵיק אַחַר כַּךְ בְּאִינוּן תְּלָתָא, דְּאִינוּן עַתִּיקָא וְאַבָּא וְאִימָא, דְּנָגֵיד מִנְּהוֹן נְהִירוּ לְתַתָּא, כְּדֵין אָחִיד לְחוּלָקֵיהּ, הַהוּא דַרְגָּא דִּתְחוֹתַיְיהוּ דְּאִינוּן תְּלָתָא, דְּאִיקְרֵי חֶסֶד.</p>"],[9514012154,"<p>וְכָלְהוֹ אַדְבֵּיק לוֹן, מִגּוֹ אַסְפַּקְלַרְיָא דְּשָׁלְטָא בְּלֵילְיָא, דִּבְהוֹ מַמָּשׁ לָא הֲוָה בַּר נָשׁ דְּיָדַע כְּלוּם. וְעַל דָּא תָּנִינָן, בֶּן שְׁלשָׁה שָׁנִים, הִכִּיר אַבְרָהָם אֶת בּוֹרְאוֹ, בֶּן שְׁלשָׁה דַּיְיקָא.</p>"],[9514012155,"<p>וְתָּא חֲזֵי, רָזָא דְּהַנֵּי שְׁלשָׁה שְׁנִין, וְלָא פָּחוֹת, בְּגִין דִּשְׁכִינְתָּא אִקְרֵי בַּת שֶׁבַע, וְלָא יָכֵיל לְאִתְקְרָבָא בַּהֲדָהּ, עַד דְּסָלֵיק בְּאִינוּן תְּלַת דַּרְגִּין עִילָּאִין, דְּעִם אִינוּן ז', לְאִשְׁתְּמוֹדְעָא מִגַּוָּון, וּלְאִתְנַהֲרָא בְּכָל מַאי דְּאִיהוּ לְתַתָּא, וְג' וְז', הָא עֶשֶׂר דַּרְגִּין עִלָּאִין, רָזָא דִּשְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9514012156,"<p>וְכֵיוָן דְּהֲוָה מִתְנְהֵיר בְּאִינוּן שְׁלשָׁה, בָּעָא לְסַלְקָא בְּאִינוּן שֶׁבַע, בְּרָזָא דִּכְתִיב, (בראשית כ״א:כ״ח) וַיַּצֶּב אַבְרָהָם אֶת שֶׁבַע כִּבְשׂת הַצֹּאן. וְרָזָא דָא רָמֵיז לַאֲבִימֶלֶךְ, דְּלָא יִשְׁלְטוּן עֲלֵיהוֹן בְּנוֹי, עַד דְּיִשְׁתְּלִימוּ אִינוּן שִׁבְעָה זַכָּאֵי קְשׁוֹט בְּיִשְׂרָאֵל, לָקֳבֵיל אִינוּן שִׁבְעָה דַרְגִּין דִּלְעֵילָא.</p>"],[9514012157,"<p>כֵיוָן דְּיִשְׁתְּלִימוּ, יָתֵיב עָלְמָא תַּתָּאָה כְּגַוְונָא דְּעָלְמָא עִילָּאָה. בְּקִיּוּמָא שְׁלִים. וְיֵיתֵי דָוִד, דְּאִיהוּ שְׁבִיעָאָה, וְיִתְעַר לְהַהִיא בַּת שֶׁבַע דִּלְעֵילָא, דְּאִיהִי נָקְמָא נִקְמַתְהוֹן דְּיִשְׂרָאֵל, וְיִתְפְּרַע מִנְּהוֹן.</p>"],[9514012158,"<p>הֲדָא הוּא דִכְתִיב, (שמואל ב ח׳:א׳) וַיְהִי אַחֲרֵי כֵן וַיַּךְ דָּוִד אֶת פְּלִשְׁתִּים וַיַּכְנִיעֵם וַיִּקַּח דָּוִד אֶת מֶתֶג הָאַמָּה מִיַּד פְּלִשְׁתִּים. מַאי וַיְהִי אַחֲרֵי כֵן. בָּתַר דְּאִשְׁתְּלִימוּ יִשְׂרָאֵל, וַהֲווּ כְּגַוְונָא דִּלְעֵילָא, כְּדֵין וַיַּךְ דָּוִד אֶת פְּלִשְׁתִּים וַיַּכְנִיעֵם. דְּהָא עַד הַשְׁתָּא לָא יָכִילוּ יִשְׂרָאֵל לְמִיתְבַּר תּוֹקְפֵיהוֹן, וְהָא אִיתְעָרוּ חַבְרַיָיא בְּהַהוּא מֶתֶג הָאַמָּה, וְאוֹקְמוּהָ.</p>"],[9514012159,"<p>וְתָּא חֲזֵי, הַאי דְּרָמַז לֵיהּ אַבְרָהָם בְּכִבְשׂוֹת הַצֹּאן, וְלֹא בְּעִזִּים, וְלֹא בְּמִילֵי אַחֲרִינֵי, בְּגִין דְּאִינוּן מִסִּטְרָא דְחֶסֶד, מֵאִינוּן מְמַנָּן דְּיָנְקִין מִסִּטְרָא דְחֶסֶד, יָנְקִין לְתַתָּא אִינוּן כְּבָשִׂים, תְּחוֹת שׁוּלְטָנֵיהוֹן. וְאַבְרָהָם אָחִיד לְחוּלָקֵיהּ מִדַּת הַחֶסֶד, וְכוֹלָּא בְּרָזָא דְּחָכְמְתָא.</p>"],[9514012160,"<p>וְעַל דָּא תָּנִינָן, מַאן דְּשָׁרֵי גוֹ עָאנָא, לָא מִסְתַּכֵּן לְעָלְמִין. וְאִי אִיהוּ שָׁרֵי גּוֹ עִזַּיָּיא, וְרָעֵי לוֹן, כַּמָּה גַרְדִּינֵי נִימוּסִין, יָתְבִין לְקִבְלֵיהּ לְאַסְטָאָה לֵיהּ, בְּגִין דְּאִינוּן מִסִּטְרָא דְּדִינָא קַשְׁיָא.</p>"],[9514012161,"<p>אֲבָל כַּד אָתָא יִצְחָק לְמִגְזַר עִמֵּיהּ קְיָים, גָּזַר עִמֵּיהּ בְּשִׁבְעָה, דְּאִתְגַּלְּיָיא מִגּוֹ הַהִיא בֵּירָא, דִּכְתִיב (בראשית כ״ו:ל״ג) וַיִּקְרָא אוֹתָהּ שִׁבְעָה.</p>"],[9514012162,"<p>תָּא חֲזֵי, אַבְרָהָם קָרָא לְהַהִיא בֵּירָא דְמַיִּין, בְּאֵר שֶׁבַע. יִצְחָק קָרָא לָהּ, שִׁבְעָה. מַה בֵּין הַאי לְהַאי. אֶלָּא בְּגִין דְּיִצְחָק אָחִיד לְחוּלָקֵיהּ דַּרְגָּא דְּפַחַד, דְּאִיהוּ דִּינָא, וְעַל דָּא אוֹסֵיף בָּהּ ה'. וְה' בְּכָל אֲתַר מִדַּת הַדִּין. וְסִימָנָךְ (יחזקאל ט״ז:מ״ג) הֵא דַּרְכֵּךְ בְּרֹאשׁ נָתַתִּי. הֲדָא הוּא דִכְתִיב וַיִּקְרָא אוֹתָהּ שִׁבְעָה. דְּלָא עֲבַד בְּחוּרְפַן, כְּמָה דַּעֲבַד אֲבוּהָּ, וְכֹלָּא בְּרָזָא דְחָכְמְתָא, וְאוֹסֵיף בָּהּ ה', לְאַחֲזָאָה דְּאִיהִי חוּלָקֵיהּ.</p>"],[9514012163,"<p>תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, בָּרָא לֵיהּ בְּדִינָא. כֵּיוָן דְּחָזָא דְּלָא מִתְקַיֵּים, שִׁתֵּף בֵּיהּ חֶסֶד. הֲדָא הוּא דִכְתִיב כ (בראשית ב׳:ד׳) בְּהִבָּרְאָם, בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים, וְאוֹקְמוּהָ בְּאַבְרָהָם אִיתְקַיִּים עָלְמָא. בְּגִין כָּךְ הַאי בֵּירָא, בֵּיתָא דְעָלְמָא, עַל שְׁמֵיהּ אִיתְקְרֵי. הֲדָא הוּא דִכְתִיב, (שם כא) עַל כֵּן קָרָא לַמָּקוֹם הַהוּא בְּאֵר שָׁבַע. אַף עַל גַּב דְּהַאי בֵּירָא אִתְדַבַּק בְּיִצְחָק, דִּכְתִיב (שם כו) וַיִּקְרָא אֹתָהּ שִׁבְעָה. שְׁמָהּ בְּאֵר שָׁבַע, סִטְרָא דְאַבְרָהָם, וְלֹא בְּאֵר שִׁבְעָה, הֲדָא הוּא דִכְתִיב, (שיר השירים ב) וִימִינוֹ תְחַבְּקֵנִי.</p>"],[9514012164,"<p>וְתָּא חֲזֵי, ד' מֵאִינוּן שִׁבְעָה זַכָּאֵי קְשׁוֹט, כַּד בָּעוֹ לְאִתְקְרָבָא בִּשְׁכִינְתָּא, בְּרָזָא דְּשֶׁבַע, כָּלְהוֹ אִיעָרְעוּ בְּהַאי בְּאֵר, דְּלָא פָּסְקוּ מֵימוֹי לְעָלְמִין.</p>"],[9514012165,"<p>אַבְרָהָם כָּרֵי לָהּ לְהַאי בֵּירָא, בְּגִין דְּאִיהוּ אוֹלִיף לְכָל בְּנֵי עָלְמָא, דְּיִפְלְחוּן לְקוּדְשָׁא בְּרִיךְ הוּא. וְכֵיוָן דְּכָרֵי לָהּ, אַפֵּיק מַיִין נָבְעִין דְּלָא פָּסְקִין לְעָלְמִין.</p>"],[9514012166,"<p>וְכֵיוָן דְּמֵת אַבְרָהָם, מַה כְּתִיב (בראשית כו) וְכָל הַבְּאֵרֹת אֲשֶׁר חָפְרוּ עַבְדֵּי אָבִיו בִּימֵי אַבְרָהָם. בְּאֵרֹת כְּתִיב, וְחַד הֲוָה, דִּכְתִיב בְּאֵר שָׁבַע, וְקָרוֹ לֵיהּ בְּאֵרוֹת, דְּמַשְׁמַע דְּסַגִּיאִין הֲווֹ. בְּגִין דְּהַאי בֵּירָא, מִתְחֲזֵי לוֹן לַאֲבָהָן בְּכָל דּוּכְתָּא דַּהֲווֹ אָזְלִין, וַהֲוָה מִתְחֲזֵי לוֹן כְּבֵירִין סַגִּיאִין.</p>"],[9514012167,"<p>כֵיוָן דְּמִילְּאוּ פְּלִשְׁתִּים עַפְרָא, רָזָא דְּאַהַדְּרוּ בְּנֵי עָלְמָא לַעֲבוֹדָה זָרָה, הֲוָה עָלְמָא שָׁמֵם, דְּלֵית דְּיָדַע לְקוּדְשָׁא בְּרִיךְ הוּא. כֵּיוָן דְאָתָא יִצְחָק, מַה כְּתִיב, וַיָּשָׁב יִצְחָק וַיַּחְפֹר אֶת בְּאֵרֹת הַמַּיִם אֲשֶׁר חָפְרוּ בִּימֵי אַבְרָהָם אָבִיו. מַאי וַיָּשָׁב, אֶלָּא דַּאֲתֵיב עָלְמָא לְתִיקּוּנֵיהּ, וְאוֹלֵיף לוֹן לִבְנֵי עָלְמָא דְּיֵדְעוּן לְקוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב, (שם כה) וַיְהִי אַחֲרֵי מוֹת אַבְרָהָם וַיְבָרֶךְ אֱלֹהִים אֶת יִצְחָק בְּנוֹ.</p>"],[9514012168,"<p>וַיֵּשֶׁב יִצְחָק עִם בְּאֵר לַחַי רֹאִ\"י, הַאי בֵּירָא מִמַּאן הוּא. מִמַּאן דְּכָל חַיִּין עִילָּאִין וְתַתָּאִין וְקִיּוּמֵיהוֹן תַּלְיָין בֵּיהּ. וְחָזֵי כֹּלָּא. הֲדָא הוּא דִכְתִיב, (דניאל ב׳:כ״ב) יָדַע מַה בַּחֲשׁוֹכָא וּנְהוֹרָא עִמֵּיהּ שְׁרֵא.</p>"],[9514012169,"<p>וְתָּא חֲזֵי, אִינוּן עַבְדֵּי יִצְחָק בְּגִין דְּאִינוּן מִסִּטְרָא דְדִינָא קַשְׁיָיא, כַּד חָפְרוּ לָהּ, מַה כְּתִיב, שִׂטְנָה, וְהָא אוֹקְמוּהָ, עַד דְּאָתָא אִיהוּ (בראשית כ״ו:כ״ב) וַיַּחְפֹּר בְּאֵר אַחֶרֶת וְגו', וַיִּקְרָא שְׁמָהּ רְחוֹבוֹת וַדַּאי. אֲבָל עַבְדֵּי אָבִיו, בְּגִין דְּכָלְהוֹ אַתְיָין מִסִּטְרָא דְּיָמִינָא, לָא הֲוָה שִׂטְנָא בְּעָלְמָא, וְלָא נָפֵיק דִּינָא בְּהַאי בֵּירָא, לְאַשְׂטָנָא לוֹן, כַּד לָא מַכְשְׁרֵי עוֹבָדֵיהוֹן.</p>"],[9514012170,"<p>וּמֵהַאי בֵּירָא, אִיהוּ פִּתְחָא לְמִינְדַע לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב, (תהילים קי״ח:י״ט) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבֹא בָם אוֹדֶה יָהּ. וְעַד דְּלָא סָלֵיק יִצְחָק מֵעָלְמָא, בָּרִיךְ לֵיהּ לְיַעֲקֹב, וּשְׁלָחֵיהּ לְחָרָן, לְאִזְדַּוְגָא. וְכַד אָזֵיל לְחָרָן מַה כְּתִיב (בראשית כ״ט:ב׳) וַיַּרְא וְהִנֵּה בְּאֵר בַּשָּׂדֶה, כֵּיוָן דְּחָזָא יַעֲקֹב יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא, מִגּוֹ הַהוּא בֵּירָא, דְּאִקְרֵי בְּאֵר שָׁבַע. כְּדֵין אָמַר לֵיהּ לְלָבָן, אֶעֱבָדְךָ שֶׁבַע שָׁנִים בְּרָחֵל בִּתְּךָ הַקְּטַנָּה דַּיְיקָא.</p>"],[9514012171,"<p>תָּא חֲזֵי, לָקֳבֵל אִינוּן שִׁבְעָה זַכָּאִין, פָּקֵיד קוּדְשָׁא בְּרִיךְ הוּא בְּאוֹרַיְיתָא, לְקָרָבָא קָרְבַּן מוּסַף, בְּשֶׁבַע זִמְנִין בְּשַׁתָּא. בְּגִין לְאוֹסָפָא לְהוֹ עִדּוּנִין וְתַפְנוּקִין מִבֵּי מַלְכָּא, דְּיִשְׂבְּעוּן אֲבָהָן בְּקַדְמִיתָא, וּבָתַר כֵּן בְּנִין. וְאִינוּן ז' זִמְנִין וְלָא יַתִּיר.</p>"],[9514012172,"<p>בְּשַׁבַּתָּא לָקֳבֵל צַדִּיק יְסוֹד עוֹלָם, דְּאִקְרֵי כֹל, וְאִקְרֵי שַׁבָּת, לְאוֹסָפָא לֵיהּ עִידּוּנִין מִמּוֹחָא סְתִימָאָה, וּבְרֵישׁ יַרְחָא, לָקֳבָל כְּנֶסֶת יִשְׂרָאֵל, דְּאִתְקְרִיאַת סִיהֲרָא.</p>"],[9514012173,"<p>וּבְט\"ו יוֹמָא לְיַרְחָא קַדְמָאָה, לָקֳבֵיל אַבְרָהָם אֲבוּהוֹן, דְּאָחִיד בְּמִדַּת הַחֶסֶד, וְאִקְרֵי רִאשׁוֹן. וּבַעֲצֶרֶת דְּבַחֹדֶשׁ הַג', דְּאִתְיְיהִיבַת בֵּיהּ אוֹרַיְיתָא בְּשִׁבְעָה קוֹלוֹת, לָקֳבֵיל יַעֲקֹב, דְּאִיהוּ תְּלִיתָאי לַאֲבָהָן, וְאָחִיד בְּקוֹל קוֹל יַעֲקֹב. וּבְרֹאשׁ הַשָּׁנָה, לָקֳבֵיל יִצְחָק, דְּאִתְיְלֵיד בֵּיהּ, וַאֲנַן מַדְכְּרִינָן בֵּיהּ עֲקֵדַת יִצְחָק, וְאִיהוּ יוֹמָא דְדִינָא, לָקֳבֵל מִדַּת הַדִּין דְּאָחִיד בַּהּ.</p>"],[9514012174,"<p>בְּיוֹם הַכִּפּוּרִים, לָקֳבֵיל משֶׁה, דְּקַבֵּיל קוּדְשָׁא בְּרִיךְ הוּא בֵּיהּ צְלוֹתֵיהּ, וְחָס עַל יִשְׂרָאֵל, וְאַהֲדַר לֵיהּ לוּחֵי אוֹרַיְיתָא. בְּחַג הַסֻּכּוֹת, לָקֳבֵיל אַהֲרֹן, דְּבִזְכוּתֵיהּ הֲווֹ אָזְלִין שִׁבְעָה עֲנָנִין, דְּחָפָן עַל יִשְׂרָאֵל כְּסוּכּוֹת, וּבְגִין כָּךְ אִינוּן עָבְדִין סוּכָּה. וְכָל אוֹרַיְיתָא, כַּמָּה רָזִין עִילָּאִין סְתִימִין בַּהּ, וְכַד אִלֵּין שִׁבְעָה מִתּוֹסְפִין בְּבִרְכָאן, כָּל עָלְמָא בִּשְׁלִימוּ סַגִּיאָה.</p>"],[9514012175,"<p>פְּתַח הַהוּא יוּדָאי וַאֲמַר, (בראשית ל׳:ל״ז) וַיִּקַּח לוֹ יַעֲקֹב מַקַּל לִבְנֶה לַח וְלוּז וְעַרְמוֹן. וַיִּקַּח לוֹ לְגַרְמֵיהּ, וּלְתִקּוּנֵיהּ. מַקַּל לִבְנֶה, דָּא רָזָא דְּוא\"ו דִּשְׁמָא קַדִּישָׁא, דְּאִקְרֵי תִּפְאֶרֶת. דְּאִיהוּ אָחִיד בָּהּ. וְאִיהוּ כְּגַוְונָא דְּמַקֵּל. לִבְנֶה, בֶּן לְהַאי עִילָּאָה סְתִימָאָה. לַח, מִסִּטְרָא דְמַיָא דְּאִקְּרוֹן חֶסֶד. וְלוּז, מִסִּטְרָא דְּאֵשׁ דְּאִיקְּרֵי גְּבוּרָה. וְעַרְמוֹן, מִסִּטְרָא דְּגַרְמֵיהּ וְחוּלָקֵיהּ. כְּלָלָא דְּכָל גְּוָונִין. דְּהָא יַעֲקֹב חַכִּימָא הֲוָה בְּעַרְמִימוּתָא.</p>"],[9514012176,"<p>וַיְפַצֵּל בָּהֶם פְּצָלוֹת לְבָנוֹת. בָּהֶם, בּוֹ הֲוָה לֵיהּ לְמֵימַר, דְּהָא מַקֵּל חַד הֲוָה. מַאי בָּהֶם, בְּכָל אִינוּן ז' דַּרְגִּין, דִּרְמִיזִין בִּקְרָא, (דברי הימים א כ״ט:י״א) דִּלְךָ ה' הַגְּדֻלָּה וְהַגְּבוּרָה. אַשְׁלִים לוֹן בְּאִינוּן קִילוּפִין חִוְורִין, דְּקָלִיף בְּהוּ סִטְרָא דְּאֵשׁ, וְאַסְחַר לוֹן לְסִטְרָא דְּמַיִם. הֲדָא הוּא דִכְתִיב מַחְשׂף הַלָּבָן אֲשֶׁר עַל הַמַּקְלוֹת.</p>"],[9514012177,"<p>תָּא חֲזֵי, ז' מַעֲלוֹת מִמַּקְלוֹת, רְמִיזִין בְּהַנֵּי קְרָאֵי. וַיִּקַּח לוֹ יַעֲקֹב מַקַּל, חַד. אֲשֶׁר עַל הַמַּקְלוֹת, תְּרֵין. הָא תְּלַת. וַיַּצֵּג אֶת הַמַּקְלוֹת, תְּרֵין, הָא חֲמִשָּׁה. יֶחֱמוּ הַצֹּאן אֶל הַמַּקְלוֹת, הָא ז'.</p>"],[9514012178,"<p>וְאִינוּן רָזָא דְז' קוֹלוֹת, וְאִינוּן רָזָא דִּכְתִיב, (משלי ט) חָצְבָה עַמּוּדֶיהָ שִׁבְעָה. וְאִינוּן ז' יוֹמֵי בְּרֵאשִׁית, דְּנָהֲרִין מֵרֵאשִׁית, דְּאִיקְּרֵי חָכְמָה. וְאִינוּן ז' סָמְכִין, דְּאָקֵים קוּדְשָׁא בְּרִיךְ הוּא עֲלַיְיהוּ עָלְמָא, וְכוֹלָּא בְּרָזָא דִשְׁמָא קַדִּישָׁא.</p>"],[9514012179,"<p>תָּא חֲזֵי, כַּד הֲוָה הַאי מַקֵּל בִּידוֹ דְּיַעֲקֹב שְׁלֵימָא, קָרֵי לֵיהּ אוֹרַיְיתָא מַקֵּל. וְכַד הֲוָה בִּידַיְיהוּ דְמשֶׁה וְאַהֲרֹן, קָרֵי לֵיהּ מַטֶה. הֲדָא הוּא דִכְתִיב, (שמות ד׳:כ׳) וַיִּקַּח משֶׁה אֶת מַטֶה הָאֱלֹהִים בְּיָדוֹ. וְאַהֲרֹן נָמֵי אָחִיד בֵּיהּ. מַה בֵּין הַאי לְהַאי.</p>"],[9514012180,"<p>אֶלָּא רָזָא עִילָּאָה הוּא, כַּד הֲוָה בִּידוֹי דְּיַעֲקֹב, קָרֵי לֵיהּ אוֹרַיְיתָא מַקֵּל, מִסִּטְרָא דְּקָל, דְּהָא יַעֲקֹב קוֹל אִיקְּרֵי, דִּכְתִיב (בראשית כ״ז:כ״ב) הַקֹּל קוֹל יַעֲקֹב. וּבְקוֹל אָחִיד, דְּהָא דַּרְגֵּיהּ הוּא.</p>"],[9514012181,"<p>וְכַד הֲוָה בִּידַיְיהוּ דְמשֶׁה וְאַהֲרֹן, דְּאִינוּן אֲחִידִין בְּנֵצַ\"ח וָהוֹ\"ד, דְּאִינוּן תְּרֵין סַמְכִין, אִיקְּרֵי מַטֶה, לִישְׁנָא דִּסְמָכָא. דְּהָא עַל יְדֵי אִסְתְּמִיךְ עָלְמָא בְּאוֹרַיְיתָא, דְּנָפֵיק מִבֵּין תְּרֵין לִמּוּדֵי ה' וְאִתְיְיהִיבָא עַל יָדַיְיהוּ. וְעַל דְּאִינוּן סָמְכִין לְעָלְמָא בְּאוֹרַיְיתָא, דְּנָפֵיק מִבֵּין נֶצַ\"ח וָהוֹ\"ד, דַּאֲחִידָן בְּהוּ. קְרָא לֵיהּ מַטֶה. וּמַאן דְּאָחֵיד בְּאוֹרַיְיתָא, סָמְכָא לֵיהּ, וּמַחְזְקָא לֵיהּ עַל יַרְכוֹי, דְּלָא יִסְטֵי לְיָמִינָא וּשְׂמָאלָא.</p>"],[9514012182,"<p>זַכָאִין אִינוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא יְהֵיב לְהוֹן אוֹרַיְיתָא, לְגַלָּאָה לוֹן רָזִין עִילָּאִין. מַאן דְּאָחֵיד בְּאוֹרַיְיתָא, סָמְכָא לֵיהּ, וּמַחְזְקָא לֵיהּ עַל יַרְכוֹי, דְּלָא יִסְטֵי לְיָמִינָא וְלִשְׂמָאלָא. זַכָּאִין אִינוּן יִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא יְהַב לוֹן אוֹרַיְיתָא, לְגַלָּאָה לוֹן רָזִין עִילָּאִין. עֲלַיְיהוּ כְּתִיב (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.</p>"],[9514012183,"<p><Noneb> מִדרָשׁ הַנֶּעְלָם </b></p>"],[9514012184,"<p>וַיֵּצֵא יַעֲקֹב. א (דניאל ב) יָדַע מַה בַּחֲשׁוֹכָא וּנְהוֹרָא עִמֵּיהּ שְׁרֵי, אַף עַל גַּב דִּנְהוֹרָא עִמֵּיהּ שְׁרֵי, יָדַע מַה בַּחֲשׁוֹכָא. וְהַיְינוּ דִכְתִיב, (ירמיה כג) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ נְאֻם ה'. וּמִי אר\"י הָכֵי, וְהָא אֲמָרָן דְּהָא חָכְמְתָא הֲוָה בִּסְמִיכוּתָא דִּקְרָאֵי, בְּכָל מַה דְּאִיתְּמָר, וְהָאִידְנָא פְּשִׁיטוּתָא דִקְרָא צְרִיכְנָא, דְּאַבְרָהָם הֲוָה, וְיִצְחָק הֲוָה, וְיַעֲקֹב הֲוָה. אָמַר לֵיהּ אַף עַל גַּב דַּהֲווֹ, חָכְמְתָא דִקְרָאֵי אִסְתַּכַּלְנָא לְמִנְדַע.</p>"],[9514012185,"<p>רַבִּי יִצְחָק פְּתַח, (תהלים טו) מִזְמוֹר לְדָוִד ה' מִי יָגוּר בְּאָהֳלֶךָ מִי יִשְׁכֹּן בְּהַר קָדְשֶׁךָ הוֹלֵךְ תָּמִים וּפֹעֵל צֶדֶק וְדֹבֵר אֱמֶת בִּלְבָבוֹ וְגו'. מַאי מַשְׁמַע, אָמַר רִבִּי יְהוּדָה בַּר רַבִּי יוֹסֵי, אִלֵּין עֲשָׂרָה, אִינוּן כְּנֶגֶד עֲשֶׂרֶת הַדִּבְּרוֹת, שֶׁעֲתִידִין בָּנָיו שֶׁל יַעֲקֹב, לְקַיֵּים בַּמָּקוֹם הַהוּא.</p>"],[9514012186,"<p>אָמַר רִבִּי יוֹסֵי, וְהָא חַד סַר אִינוּן. אָמַר לֵיהּ לֹא רָגַל עַל לְשׁוֹנוֹ, לֹא עָשָׂה לְרֵעֵהוּ רָעָה, חַד מִלָּה אִינוּן. דְּכָל הַמְרַגֵּל בַּחֲבֵרוֹ, מִיָּד עָשָׂה עִמּוֹ רָעָה. לֹא רָגַל בִּלְשׁוֹנוֹ לֹא עָשָׂה עִמּוֹ רָעָה. וְכִי מַאן שַׁוְיָא לְאִלֵּין, כְּנֶגֶד עֲשֶׂרֶת הַדִּבְּרוֹת.</p>"],[9514012187,"<p>אָמַר רַבִּי, כָּלְהוֹ עֲשֶׂרֶת הַדִּבְּרוֹת, מִשְׁתַּמְעֵי מִינַיְיהוּ. הוֹלֵךְ תָּמִים, כְּנֶגֶד אָנֹכִי ה' אֱלֹהֶיךָ. מְלַמֵּד שֶׁצָּרִיךְ אָדָם לְקַבֵּל עָלָיו אֵימַת עוֹל מַלְכוּת שָׁמַיִם, וְאֵין לוֹ רְשׁוּת לְהַרְהֵר בַּמֶּה שֶׁאֵינוֹ יָכוֹל לְהַשִּׂיג, מַשְׁמַע דִּכְתִיב אָנֹכִי ה' אֱלֹהֶיךָ סְתָם. כְּתִיב הָכָא הוֹלֵךְ תָּמִים, וּכְתִיב הָתָם (דברים יח) תָּמִים תִּהְיֶה עִם ה' אֱלֹהֶיךָ. וְאֵין לְךָ רְשׁוּת לְהַרְהֵר עַל מַה שֶּׁלֹּא הוּרְשֵׁיתָ.</p>"],[9514012188,"<p>וּפֹעֵל צֶדֶק, כְּנֶגֶד לֹא יִהְיֶה לְךָ אֱלֹהִים אֲחֵרִים עַל פָּנַי לֹא תִשְׁתַּחֲוֶה לָהֶם וְלֹא תָעָבְדֵם. מִכָּאן אָמַר רִבִּי יְהוּדָה, אֵין לְךָ דָּבָר עוֹמֵד כְּנֶגֶד חִילּוּל ה'. מְנָא לָן. מִמֵּסִית. דִּכְתִיב (שם יג) יָדְךָ תִּהְיֶה בוֹ בָּרִאשׁוֹנָה לַהֲמִיתוֹ. לָמָּה, כִּי בִּקֵּשׁ לַהֲדִיחֲךָ מֵעַל ה' אֱלֹהֶיךָ. וְאִי קָטִיל לֵיהּ, נִקְרָא צַדִּיק, מְקַנֵּא, וּפוֹעֵל צֶדֶק, וְזֶהוּ וּפֹעֵל צֶדֶק.</p>"],[9514012189,"<p>וְדֹבֵר אֱמֶת בִּלְבָבוֹ, כְּנֶגֶד לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךָ לַשָּׁוְא. אָמַר רִבִּי יְהוּדָה, לֵית אִינוּן כְּסִדְּרָן, וְאַף עַל גַּב דְּלֵית אִינוּן כְּסִדְּרָן, לֵית לָן בָהּ. לֹא רָגַל עַל לְשׁוֹנוֹ לֹא עָשָׂה לְרֵעֵהוּ רָעָה, כְּנֶגֶד לֹא תַעֲנֶה בְרֵעֲךָ עֵד שָׁקֶר. וְחֶרְפָּה לֹא נָשָׂא עַל קְרוֹבוֹ, כְּנֶגֶד מְחַלֵּל שַׁבָּתוֹת בְּפַרְהֶסְיָא. ר' יוֹסֵי אוֹמֵר, כְּנֶגֶד לֹא תִגְנוֹב. דִּכְתִיב, (שמות כ״ב:ב׳) אִם זָרְחָה הַשֶּׁמֶשׁ עָלָיו.</p>"],[9514012190,"<p>(תהלים טו) נִבְזֶה בְּעֵינָיו נִמְאָס, כְּנֶגֶד לֹא תִרְצָח. מַאן דְּאִיהוּ נִבְזֶה בְּעֵינָיו, לֹא יַעֲבֵיד קְטָטָה דְּיִקְטוֹל, וְלָא יִקְטְלוּנֵיהּ.</p>"],[9514012191,"<p>וְאֶת יִרְאֵי ה' יְכַבֵּד, כְּנֶגֶד כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ. אָמַר רִבִּי יוֹסֵי, עַל הַכֹּל חַיָּיב אָדָם לְכַבֵּד אָבִיו וְאִמּוֹ, יָצָא מִכְּלַל זֶה, אִם יֹאמְרוּ לוֹ לַעֲבוֹר עַל דִּבְרֵי תוֹרָה אוֹ לַעֲבוֹד עֲבוֹדָה זָרָה, שֶׁאֵינוֹ חַיָּיב לְכַבְּדָם. הֲדָא הוּא דִכְתִיב וְאֶת יִרְאֵי ה' יְכַבֵּד.</p>"],[9514012192,"<p>נִשְׁבַּע לְהָרַע וְלֹא יָמִיר, כְּנֶגֶד לֹא תִנְאָף. דְּהָא אִם יִצְרוֹ בָּעֵי לְשַׁלְּטָאָה עֲלֵיהּ, יַטִיל שְׁבוּעָה עַל יִצְרוֹ, כְּבוֹעַז, דְּאָמַר (רות ג) חַי ה' שִׁכְבִי עַד הַבֹּקֶר.</p>"],[9514012193,"<p>(תהלים טו) כַּסְפּוֹ לֹא נָתַן בְּנֶשֶׁךְ, הַאי הוּא כְּנֶגֶד לֹא תִגְנוֹב. דְּאִי הוּא לָא אוֹזִיף בְּרִבִּיתָא, וַדַּאי לָא יֵזֵיל וְיִגְנוֹב. וְשֹׁחַד עַל נָקִי לֹא לָקָח, כְּנֶגֶד לֹא תַחְמֹד.</p>"],[9514012194,"<p>אָמַר רִבִּי יוֹסֵי בֶּן קִיסְמָא, כְּנֶגֶד אֵלּוּ נֶאֱמַר בְּיַעֲקֹב עֲשָׂרָה אֲחֵרִים, דִּכְתִיב (בראשית כח) וַיִּפְגַּע בַּמָּקוֹם, א'. וַיָּלֶן שָׁם, ב'. כִּי בָא הַשֶּׁמֶשׁ, ג'. וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם, ד'. וַיָּשֶׂם מֵרַאֲשׁוֹתָיו, ה'. וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא, ו'. וַיַּחֲלוֹם וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה, ז'. וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמָיְמָה, ח'. וְהִנֵּה מַלְאֲכֵי אֱלֹהִים, ט'. עוֹלִים וְיוֹרְדִים בּוֹ, י'. הָא עֲשָׂרָה.</p>"],[9514012195,"<p>דָּבָר אַחֵר וַיִּפְגַּע בַּמָּקוֹם, רַבִּי בּוֹ פָּתַח, (שיר השירים א) אַל תִּרְאֻנִי שֶׁאֲנִי שְׁחַרְחֹרֶת שֶׁשְּׁזָפַתְנִי הַשָּׁמֶשׁ בְּנֵי אִמִּי נִחֲרוּ בִי שָׂמֻנִּי נֹטֵרָה אֶת הַכְּרָמִים כַּרְמִי שֶׁלִּי לֹא נָטָרְתִּי. הָא אִתְחַזַּר עַל יַעֲקֹב, דְּשֻׁלְטָנָא דְּיַעֲקֹב בְּקַדְמִיתָא הֲוָה שִׁמְשָׁא, וְאִתְחַזַּר הַהוּא שׁוּלְטָנָא לְעֵשָׂו, וְאִתְעֲבַר מִנֵּיהּ. וְיַעֲקֹב אָמַר, אַל תִּרְאֻנִי שֶׁאֲנִי שְׁחַרְחֹרֶת, דְּהָא אִתְיְיהִיבַת לִי שֻׁלְטָנָא דְּסִיהֲרָא, דְּהִיא אוּכְמָא לְעִידָנִין וְזִמְנִין. שֶׁשְּׁזָפַתְנִי הַשֶּׁמֶשׁ, כַּד אִתְעֲבַר מִנִּי שֻׁלְטָנָא דְּשִׁמְשָׁא.</p>"],[9514012196,"<p>בְּנֵי אִמִּי נִחֲרוּ בִי, זֶהוּ עֵשָׂו. דִּכְתִיב, (בראשית כז) וַיִּשְּׂטֹם עֵשָׂו אֶת יַעֲקֹב. שָׂמֻנִי נֹטֵרָה אֶת הַכְּרָמִים, דִּכְתִיב (שם לא) הָיִיתִי בַיּוֹם אֲכָלַנִי חֹרֶב וְקֶרַח בַּלָּיְלָה. כַּרְמִי שֶׁלִּי לֹא נָטָרְתִּי, דִּכְתִיב (שם ל) וְעַתָּה מָתַי אֶעֱשֶׂה גַּם אָנֹכִי לְבֵיתִי.</p>"],[9514012197,"<p>(שם כח) וַיִּפְגַּע בַּמָּקוֹם, רַבִּי יִצְחָק אָמַר, בְּאֵיזֶה מָקוֹם פָּגַע, בַּמָּקוֹם שֶׁעָתִיד לַעֲמוֹד בֵּית הַמִּקְדָּשׁ, וְהִתְפַּלֵּל שָׁם. רַבִּי יְהוּדָה אוֹמֵר, הַיּוֹם הָיָה גָּדוֹל, וְרָצָה לַהֲלוֹךְ וְלָא יָכֵיל.</p>"],[9514012198,"<p>אָמַר רִבִּי יוֹסֵי, הִתְפַּלֵּל בְּאוֹתוֹ מָקוֹם, וְהִתְחִיל לְהִתְרָעֵם לִפְנֵי קוֹנוֹ, עַל דְּאִתְעֲבַר מִנֵּיהּ הַהוּא שׁוּלְטָנָא דְּשִׁמְשָׁא, הֲדָא הוּא דִכְתִיב וַיָּלֶן שָׁם. כְּמָה דְאַתְּ אָמֵר (שמות טו) וַיִּלּוֹנוּ הָעָם עַל משֶׁה, לָשׁוֹן תַּרְעוֹמוֹת. וְלָמָּה, מִפְּנֵי כִּי בָא הַשֶּׁמֶשׁ, דְּאִתְעֲבַר מִנֵּיהּ וְאִתְיְיהִיבַת לְעֵשָׂו.</p>"],[9514012199,"<p>מֶה עָשָׂה יַעֲקֹב, הִתְחִיל בּוֹכֶה. מִיָּד וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם וַיָּשֶׂם מֵרַאֲשׁוֹתָיו, כְּדֵי לְצַעֵר נַפְשׁוֹ. כַּיּוֹצֵא בַּדָּבָר וַיִּקְחוּ אֶבֶן וַיָּשִׂימוּ תַחְתָּיו וַיֵּשֶׁב עָלֶיהָ.</p>"],[9514012200,"<p>וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם, אָמַר רִבִּי יוֹסֵי אֶבֶן אַחַת מַמָּשׁ הָיְתָה. מַשְׁמַע דִּכְתִיב מֵאַבְנִי, וְלֹא אַבְנֵי. כְּמָה דְאַתְּ אָמֵר מִבְּנוֹת הַכְּנַעֲנִי, וְלֹא אָמַר אֶלָּא אַחַת. הֲדָא הוּא דִכְתִיב, (בראשית כד) אֲשֶׁר לֹא תִקַּח אִשָּׁה לִבְנִי מִבְּנוֹת הַכְּנַעֲנִי, אַחַת מֵהֶן.</p>"],[9514012201,"<p>רַבִּי זֵירָא עָאל קַמֵּי רַבִּי אֶלְעָזָר בֶּן עֲרָךְ, אַשְׁכְּחֵיהּ דְּהֲוָה יָתִיב, וְעֵינוֹי נָבְעִין מַיָּא, וַהֲוָה מַרְחֵישׁ בְּשִׂפְוָותֵיהּ וּבָכֵי, חָזַר לַאֲחוֹרוֹי רַבִּי זֵירָא. אֲמַר לְשַׁמָּשֵׁיהּ, מַאי הַאי דְּיָתֵיב מַר וּבָכֵי, אֲמַר תְּרֵי זִמְנֵי עַיְילִינָא לְקָרְבָא גַבּוֹי, וְלָא יָכֵילְנָא. עַד דַּהֲווֹ יָתְבֵי, חָמוֹן לֵיהּ דְּעָאל לְאִדְּרֵיהּ, עַד דְּנָחַת, הֲוָה קָלֵיהּ אָזֵיל בְּבֵיתָא וּבָכֵי.</p>"],[9514012202,"<p>שְׁמַע דְּהֲוָה אֲמַר, אַבְנָא אַבְנָא, אַבְנָא קַדִּישָׁא עִילָּאָה עַל כָּל עָלְמָא, בִּקְדוּשָּׁתָא דְּמָארָךְ, זְמִינֵי בְּנֵי עֲמָמַיָא לְאִתְזַלְזְלָא בָּךְ, וּלְאוֹתָבָא גּוֹלְמֵי מְסָאֲבִין עֲלָךְ, לְסָאֲבָא אַתְרָךְ קַדִּישָׁא, וְכָל מְסָאֲבִין יִקְרְבוּן בָּךְ, וַוי לְעָלְמָא בְּהַהוּא זִמְנָא.</p>"],[9514012203,"<p>נְחַת וִיתֵיב בְּסוּלְסְלָנֵיהּ, אָמַר רִבִּי זֵירָא לְשַׁמָּשֵׁיהּ, זִיל וְאֵימָא לֵיהּ לְמַר, אִי אֵיעוֹל קַמֵּיהּ. עָאל שַׁמָּשֵׁיהּ, אֲמַר הָא רַבִּי זֵירָא הָכָא, לָא אַשְׁגַּח בֵּיהּ, וְלָא זְקֵיף עֵינוֹהִי.</p>"],[9514012204,"<p>לְבָתַר אֲמַר, רַבִּי זֵירָא לֵיעוֹל, וְאַתְּ תִּיב לְבַר. עָאל ר' זֵירָא, וְאַרְכִין בִּרְכּוֹי, וִיתֵיב קַמֵּיהּ. חָמָא ר' אֶלְעָזָר, בָּטַשׁ בְּרַגְלֵיהּ, אֲמַר קוּם מֵהָתָם, וְתִיב כְּאָרְחָךְ, קָם וִיתֵיב כְּאָרְחֵיהּ.</p>"],[9514012205,"<p>אָמַר רִבִּי זֵירָא, הַאי דְּמַר דְּהֲוָה בָּכֵי, מַאי חָזָא. אֲמַר, אַרְכַּבְתָּא תְּבִירָא סַגִּיאָה דְּכָל עָלְמָא, חָזֵינָא הַהוּא אַבְנָא יַקִּירָא קַדִּישָׁא, דְמִינָהּ אִשְׁתֵּיל עָלְמָא. וְהַהוּא אַבְנָא הֲוָה, דְּשַׁוֵּי יַעֲקֹב רֵישֵׁיהּ עֲלָהּ.</p>"],[9514012206,"<p>וְכִי אַבְנָא דְּמִינָהּ אִשְׁתֵּיל כָּל עָלְמָא, וַהֲוָה רֵישֵׁיהּ מְשַׁקְעָא בִּתְהוֹמָא רַבָּא, הֵיךְ יָכוֹל יַעֲקֹב לְנַעְנְעָה לָהּ. אֶלָּא הַהוּא אַבְנָא, זִוְיָיתֵיהּ מְשַׁקְעָן בִּתְהוֹמָא רַבָּא, וְרֵישֵׁיהּ אִתְמַגּוֹס בְּבֵי מַקְדְּשָׁא, וַעֲלָהּ קֹדֶשׁ קוּדְשִׁין, וּשְׁכִינְתָּא יְקָרָא עִילָּאָה עֲלָהּ. הֲדָא הוּא דִכְתִיב, (בראשית מ״ט:כ״ד) מִשָּׁם רוֹעֶה אֶבֶן יִשְׂרָאֵל. וּשְׁמָא קַדִּישָׁא דְמַלְכָּא עִילָּאָה הֲוָה גָּלִיף עֲלָהּ.</p>"],[9514012207,"<p>כַד אָתָא יַעֲקֹב, קָרָא הַהוּא שְׁמָא קַדִּישָׁא, וּנְסָבָהּ מִכָּאן, וְשַׁוְיָהּ בְּהַהוּא אֲתַר דְּקֹדֶשׁ קֳדָשִׁין הֲוָה תַּמָּן. אֲמַר רַבִּי זֵירָא, אֲנָא שְׁמַעְנָא בְּשֵׁם ר' בּוֹ, דַּאֲמַר רָזָא דְּמִלָּה בְּהַאי, וְלָא אִדְכַּרְנָא.</p>"],[9514012208,"<p>אָמַר רִבִּי אֶלְעָזָר, אִי רַבִּי זֵירָא דַּעְתִּי אָחֵיס עֲלָךְ. וְדִילְמָא הַאי מִלָּה שְׁמַעְתְּ, וְכָךְ הוּא בְּרִירָא דְּמִלְּתָא, דִּכְתִיב (שם כח) וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם, אֶבֶן אַחַת מֵאַבְנֵי הַמָּקוֹם. מֵאֵיזֶה מָקוֹם, מִמָּקוֹם הַיָּדוּעַ, שֶׁהוּא מְקוֹם הַתְּהוֹם, שֶׁשָּׁם אֲבָנִים שֶׁשּׁוֹחֲקִים מַיִם לְכָל הָעוֹלָם. הֲדָא הוּא דִכְתִיב, (איוב י״ד:י״ט) אֲבָנִים שָׁחֲקוּ מַיִם.</p>"],[9514012209,"<p>הָאֶבֶן הַזֹּאת, הָיְתָה עִיקָּר לְכֻלָּם, וְהָיְתָה עוֹלָה עַד מָקוֹם שֶׁהָיָה שָׁם בֵּית הַמִּקְדָּשׁ. וְיַעֲקֹב לֹא הָיְתָה כַּוָּונָתוֹ עַל שׁוּם אַחַת מֵהֶן, אֶלָּא עָלֶיהָ, מִשּׁוּם דִּרְמִיזָא לֵיהּ רְמִיזָא. מַה הִיא הַכֹּל אִשְׁתֵּיל מִינָּהּ, כָּךְ יַעֲקֹב כָּל עָלְמָא אִשְׁתֵּיל מִנֵּיהּ. בְּאוֹתָהּ שָׁעָה וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם, שֶׁהִיא עִיקַּר כָּל הָעוֹלָם, וַיָּשֶׂם מֵרַאֲשׁוֹתָיו, שָׂם בְּלִבּוֹ שֶׁהִיא מֵרַאשׁוֹתָיו, דּוּגְמַת זֶה כָּזוֹ. מִיָּד וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא, כְּלוֹמַר, נִתְיַשְּׁבָה דַּעְתּוֹ בְּאוֹתוֹ מָקוֹם.</p>"],[9514012210,"<p>וְסִימָן יָדוּעַ לָקַח, אָמַר זוֹ הִיא דּוּגְמָא שֶׁלִּי, וְאִם לָזוֹ תִּהְיֶה שׁוּם מַעְלָה, בְּיָדוּעַ שֶׁיִּהְיֶה לִי מַעֲלָה. וְעַל כָּךְ שָׂם לִבּוֹ עָלֶיהָ, וְנָדַר נְדֶר, דִּכְתִיב, (בראשית כ״ח:כ״ב) וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה. כְּלוֹמַר, אִם הָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אֱלֹהִים, מִיָּד וְכֹל אֲשֶׁר תִּתֶּן לִי עֲשֵׂר אַעֲשְׂרֶנּוּ לָךְ. נָדַר הַמַּעֲשֵׂר. אָמַר רִבִּי זֵירָא, הָא וַדַּאי שָׁמַעְנָא.</p>"],[9514012211,"<p>אָמַר לֵיהּ, עַל הַאי אִתְקְרֵי (שם מט) אֶבֶן יִשְׂרָאֵל. כְּלוֹמַר, נִקְרְאָה כָּךְ עַל שְׁמוֹ, עַל שֶׁנָּתַן לִבּוֹ וְעֵינָיו עָלֶיהָ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אוֹתָהּ בֵּית עוֹלָמִים, וְשָׁם הָיְתָה שְׁכִינָתוֹ.</p>"],[9514012212,"<p>וְעַל דָּא בָּכִינָא, דַּחֲזֵינָא דְּעַל הַאי אַבְנָא, זְמִינִין לְשַׁוָּאָה סוֹאֲבַת עַמְמַיָא, וּפִגְרֵי מֵיתַיָיא. מַאן לָא יִבְכֵּי, וַוי לְעָלְמָא, וַוי לְהַהוּא זִימְנָא, וַוי לְהַהוּא דָרָא. בְּכָה כַּד בְּקַדְמִיתָא, אִתְנַח וְאִשְׁתִּיק. לְבָתַר חָזַר וַאֲמַר, וַוי לְאִינוּן דִּיהוֹן זְמִינִין בְּעָלְמָא, כַּד יִתְעַר מַלְכָּא עִילָּאָה דְעָלְמָא.</p>"],[9514012213,"<p>בְּכָה רַבִּי זֵירָא, אֲמַר מַלְאָכָא קַדִּישָׁא יָדַע דֵּין, יָאוֹת הוּא לְמִבְכֵּי עֲלָהּ. זַכָּאִין אַתּוּן צַדִּיקַיָּא, דְּאַתּוּן קַדִּישִׁין בְּעָלְמָא דֵין, וּבְעָלְמָא דְאָתֵי.</p>"],[9514012214,"<p>פָּרְשָׁתָא יח. (שם כח) וַיַּחֲלֹם וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה וְגו', עֹלִים וְיֹרְדִים בּוֹ. רַבִּי פְּתַח בְּהַאי קְרָא, (שיר השירים ד׳:ד׳) כְּמִגְדַּל דָּוִד צַוָּארֵךְ בָּנוּי לְתַלְפִּיּוֹת אֶלֶף הַמָּגֵן תָּלוּי עָלָיו כֹּל שִׁלְטֵי הַגִּבֹּרִים. אָמַר רַבִּי, כָּל הַדְּבָרִים יִכְלוּ וְהַתּוֹרָה לֹא תִכְלֶה. וְאֵין דָּבָר חָבִיב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ הַתּוֹרָה וְלוֹמְדֶיהָ. דִּתְנַן, כָּל הַמִּתְעַסֵּק בַּתּוֹרָה בְּכָל יוֹם, יִתְחַדְּשׁוּ לוֹ סְתָרִים שֶׁל מַעְלָה. וְהַתּוֹרָה אוֹמֶרֶת לוֹ, (שם ח) אַשְׁקְךָ מִיַּיִן הָרֶקַח מֵעֲסִיס רִמֹּנִי. זֶהוּ יֵינָהּ שֶׁל תּוֹרָה. וְזֶהוּ יַיִן הַמְשׁוּמָּר בַּעֲנָבָיו מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית. וְהֵם דְּבָרִים הָעֲתִידִים לְהִגָּלוֹת לַצַּדִּיקִים לֶעָתִיד לָבֹא.</p>"],[9514012215,"<p>קָם רַבִּי בּוֹ עַל רַגְלָיו וַאֲמַר, אִי כָּךְ הוּא, לָא הֲוָה לֵיהּ לְמֵימַר, אֶלָּא יַיִן הַמְשׁוּמָּר בַּעֲנָבָיו מֵהַר סִינַי, מַהוּ מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית. אָמַר לֵיהּ, אִינוּן עוֹמְקֵי סִדְרֵי בְרֵאשִׁית, דְּלָא אִיתְגַּלּוּ לְבַר נָשׁ, וּזְמִינִין צַדִּיקַיָא לְמִנְדַע לוֹן, כְּגַוְונָא דָא יִנְדְּעוּן אִינוּן דְעָסְקוּ בְּאוֹרַיְיתָא תָּדִיר.</p>"],[9514012216,"<p>וְתָאנָא, אֲמַר רַבִּי יְהוּדָה, רָזָא אוֹרַיְיתָא לְחַכִּימִין אִתְיְהִיבוּ, לְאִינוּן דְּאִתְעֲסִיקוּ בְּאוֹרַיְיתָא תָּדִיר. וְתָנֵי רַבִּי יְהוּדָה, כָּל מַאן דְּהוּא עָסִיק בְּאוֹרַיְיתָא כָּל צָרְכּוֹ, סָלְקִין לֵיהּ לְנִשְׁמָתֵיהּ לְעֵילָא, כַּד אִיהוּ נָאִים בְּשִׁינְתֵיהּ, וְאוֹלְפִין לֵיהּ מֵעוֹמְקֵי תּוֹרָה. וּמִינָהּ דּוֹבְבָן וּמְרַחֲשָׁן שִׂפְוָותֵיהּ בִּימָמָא, הֲדָא הוּא דִכְתִיב, (שם ז) דּוֹבֵב שִׂפְתֵי יְשֵׁנִים.</p>"],[9514012217,"<p>אָמַר רִבִּי יִצְחָק, כָּל הַמִּתְעַסֵּק בַּתּוֹרָה לִשְׁמָהּ, כְּשֶׁהוּא יָשֵׁן בַּלַיְלָה, נִשְׁמָתוֹ עוֹלָה לְמַעְלָה וּמַרְאִין לָהּ אוֹתָן הַדְּבָרִים הָעֲתִידִין לִהְיוֹת בָּעוֹלָם.</p>"],[9514012218,"<p>רַבִּי יוֹסֵי הֲוָה יָתִיב וְעָסִיק בְּאוֹרַיְיתָא, אֲתָא לְגַבֵּיהּ רַבִּי אַבָּא, אָמַר רִבִּי יוֹסֵי מָארֵי דִשְׁמַעְתָּא אָתָא. קָם קַמֵּיּה, יָתְבוּ וְאִתְעַסְּקוּ בְּאוֹרַיְיתָא, עַד דַּהֲווֹ יָתְבֵי, רָמַשׁ לֵילְיָא, יָתְבוּ וְאִתְעַסְּקוּ בָּהּ, עַד פַּלְּגוּת לֵילְיָא.</p>"],[9514012219,"<p>אִהְמִיךָ רַבִּי אַבָּא, וְרַבִּי יוֹסֵי הֲוָה יָתִיב, חָמָא לְרַבִּי אַבָּא, דְּאַנְפּוֹי מְסַמְקֵי טְפֵי, וְהוּא חָיֵיךְ, וַחֲמָא נְהוֹרָא רַבָּא בְּבֵיתָא. אָמַר רִבִּי יוֹסֵי, שְׁמַע מִינֵיהּ דִּשְׁכִינְתָּא הָכָא. אַרְכִין עֵינוֹי, יָתִיב תַּמָּן. עַד דְּהֲוָה סָלֵיק שַׁחֲרוּתָא דְצַפְרָא, וּנְהוֹרָא הֲוָה נָהֵיר בְּבֵיתָא, עַד דְּזָקַף עֵינוֹי, חָמָא צַפְרָא וְאִתְחַשַּׁךְ בֵּיתָא.</p>"],[9514012220,"<p>אִיתְעַר רַבִּי אַבָּא, וְאַנְפּוֹי הֲווֹ נְהִירִין, וְעֵינוֹי חָיְיכִין. אָחִיד בֵּיהּ רַבִּי יוֹסֵי, אָמַר רִבִּי אַבָּא, אֲנָא יְדַעְנָא מָה אַתְּ בָּעֵי. חַיָּיךְ, רָזִין עִלָּאִין חָמִית, וּבְשַׁעֲתָא דְּאָחֵיד נִשְׁמָתָא דִילִי מָארֵי דְּאַפַּיָּיא, סָלֵיק לָהּ לְאִדְרִין רַבְרְבִין וְעִילָּאִין.</p>"],[9514012221,"<p>וְחָמֵית נִשְׁמַתְהוֹן דִּשְׁאָר צַדִּיקַיָא דְּסָלְקֵי תַּמָּן, וַאֲמַר לוֹן זַכָּאִין אַתּוּן צַדִּיקַיָא, דִּבְגִינֵיכוֹן אֲנָא אִתְבְּנֵי בְּבִנְיָינָא קְדוֹשָׁא, דִּשְׁמָא יְקָרָא, לְאַעֲנָאָה לְחֵילוֹי דְּמַלְכָּא עִילָּאָה. וְחָמֵית אוֹרַיְיתִי, דְּהֲוָה מַנְחָא תַּמָּן תִּלֵּי תִּלִּים כְּמִגְדְּלָא רַבָּא. וּבְגִינֵי כָּךְ חָדֵינָא בְּחוּלָקִי, וְחָיְיכִין עֵינָאי.</p>"],[9514012222,"<p>אָמַר רִבִּי יִצְחָק, אַל תִּתְמַהּ עַל הָא דְרַבִּי אַבָּא, דְּהָא קְרָא אַסְהֵיד כָּךְ. דְּתָנִינָן, עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לָזֶה הַמְמוּנֶּה תַּחְתָּיו, וְתָלָה מִמֶּנּוּ כָּל שְׁאָר הַצְּבָאוֹת, כְּהַאי צַוָּאר, שֶׁכָּל הַגּוּף תָּלוּי מִמֶּנּוּ. וּבְשָׁעָה שֶׁהַצַּדִּיקִים עוֹסְקִים בַּתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹנֶה עוֹלָמוֹ, וְנוֹתֵן שְׁמוֹ בְּקִרְבּוֹ, לְהַגִּיעַ לַכֹּל, וּלְהַסְפִּיק לָעוֹלָם מִטוּבוֹ שֶׁל מָקוֹם.</p>"],[9514012223,"<p>וּכְשֶׁאֵין הַצַּדִּיקִים עוֹסְקִין בַּתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹטֵל שְׁמוֹ מִקִּרְבּוֹ, וַאֲזַי הָעוֹלָם חָסֵר, וְהוּא אֵינוֹ בְּמַעֲלוֹת הַיְכוֹלֶת. מְנָא לָן, דִּכְתִיב, (שיר השירים ד׳:ד׳) כְּמִגְדַּל דָּוִד צַוָּארֵךְ בָּנוּי לְתַלְפִּיּוֹת. אִם מַרְבִּים וּמְגַדְּלִים הַצַּדִּיקִים תּוֹרָה כְּהַאי מִגְדָּל, מִיָּד צַוָּארֵךְ בָּנוּי לְתַלְפִּיּוֹת. זֶהוּ שֶׁהוּא צַוָּארוֹ שֶׁל עוֹלָם, בָּנוּי בְּבִנְיָן קָדוֹשׁ, שֶׁכָּל הַפִּיּוֹת תָּלוּ וְנִלְאוּ לָדַעַת הַשְׁגָּחָתוֹ, וְזֶהוּ תַּלְפִּיּוֹת, כְּמָא דְאַתְּ אָמֵר (בראשית מ״ז:י״ג) וַתֵּלַהּ אֶרֶץ מִצְרָיִם.</p>"],[9514012224,"<p>וְאָז אֶלֶף הַמָּגֵן תָּלוּי עָלָיו, וְכֹל שִׁלְטֵי הַגִּבּוֹרִים, אוֹתָן הַנִּקְרָאִים אֶלֶף אַלְפִין, וְכָל הַנִּשְׁאָר תְּלוּיִם עָלָיו, וְכָל הַשַּׁלִּיטִין, וְכָל הָעוֹלָמוֹת, מְלֵאִים מִטוּבוֹ שֶׁל מָקוֹם.</p>"],[9514012225,"<p>אָמַר רִבִּי יְהוּדָה, וְהַיְינוּ דִּכְתִיב (שם כח) וַיַּחֲלֹם וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה, כְּלוֹמַר, כְּשֶׁהַצַדִיקִים אֵינָם עוֹסְקִים בַּתּוֹרָה, סֻלָּם מֻצָּב אַרְצָה, וְאֵינוֹ בְּמַעֲלָה. זָכוּ הַצַּדִיקִים וְעָסְקוּ בַּתּוֹרָה, רֹאשׁוֹ מַגִּיעַ הַשָּׁמָיְמָה, אַזַי יֵש לוֹ מַעֲלָה, וְכָל טוּב לֹא יֶחְסַר, וּמִיַּד וְהִנֵה מַלְאֲכֵי אֱלֹהִים עוֹלִים וְיֹרְדִים בּוֹ. מַאי בּוֹ. אָמַר רִבִּי יְהוּדָה, בִשְׁמוֹ שֶׁל מָקוֹם. כְּמָה דְאַתְּ אָמֵר (תהילים קי״ח:כ״ד) נָגִילָה וְנִשְׂמְחָה בוֹ.</p>"],[9514012226,"<p>אָמַר רִבִּי יִצְחָק, בוֹ, בְּהַהוּא מְמוּנֶה. וּמִפְּנֵי מַה. דִּכְתִיב אַחֲרָיו, (בראשית כ״ח:י״ג) וְהִנֵּה ה' נִצָּב עָלָיו, עַל הַהוּא מְמוּנֶה. מִפְּנֵי זֶה עוֹלִים וְיוֹרְדִים בִּשְׁבִילוֹ. מִפְּנֵי שְׁמוֹ שֶׁל מָקוֹם, שֶׁהוּא נִצָּב עָלָיו. אָמַר רִבִּי תַּנְחוּם, לָמָּה נִקְרָא שְׁמוֹ מֶלֶךְ שָׁלֵם, מִכָּל שְׁאָר הַצְבָאוֹת. שֶׁאֵין לָּךְ נוֹשֵׂא שְׁמוֹ שֶׁל מָקוֹם בְּקִרְבּוֹ כְּמוֹ זֶה.</p>"],[9514012227,"<p>אָמַר רִבִּי יַעֲקֹב, רָמְזּוּ לְיַעֲקֹב, וְהֵשִׁיבוּ עַל מַה שֶׁנִתְּרַעֵם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. כְּלוֹמַר, שֶׁאִם בָנָיו יִזְכּוּ לַעֲסוֹק בַּתּוֹרָה וּבַמִּצְווֹת, יֵשׁ מַעֲלָה לָזֶה, וּמַעֲלָה לְבָנָיו. לֹא זָכוּ לַעֲסֹק בַּתּוֹרָה וּבַמִּצְוֹת, אֵין מַעֲלָה לָזֶה, וְאֵין מַעֲלָה לְבָנָיו. הֲדָא הוּא דִכְתִיב, (שם) וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ. מַלְאֲכֵי אֱלֹהִים, אֵלּוּ בָּנָיו שֶׁל יַעֲקֹב, וּבוֹ עוֹלִים. לֹא זָכוּ, יוֹרְדִּים. בּוֹ: בִּשְׁבִילוֹ. בּוֹ: כְּשֶׁיֵּשׁ לוֹ מַעֲלָה יֵשׁ לָהֶם.</p>"],[9514012228,"<p>אָמַר רִבִּי יִצְחָק, כָּל שָׂרֵי הָאוּמּוֹת, הָיוּ עוֹלִים אוֹ יוֹרְדִים בִּשְׁבִיל זֶה. כְּשֶׁיֵּשׁ לוֹ מַעֲלָה, יוֹרְדִים שָׂרֵי הָאוּמּוֹת. כְּשֶׁיֵּשׁ לוֹ יְרִידָה, עוֹלִים. וְהַכֹּל תָּלוּי בְּבָנָיו שֶׁל יַעֲקֹב. אָמַר רִבִּי יְהוּדָה בַּר שָׁלוֹם, אֵין טוֹב וְאֵין רָע בָּא לָעוֹלָם, אֶלָּא בִּשְׁבִיל בָּנָיו שֶׁל יַעֲקֹב.</p>"],[9514012229,"<p>הֶגְמוֹן אֶחָד בָּא לְרַבִּי אַבָּהוּ, וַאֲמַר, אִית לְאִתְכַּנְפָא כָּל עָלְמָא עֲלַיְיכוּ, כְּעַל הַאי גוּבָא, לְאוֹבָדָא לְכוֹן מִן עָלְמָא בְּשַׁעֲתָא חָדָא. אוּמָּה דָא הִיא לָא פָלְחָה לְמָארָה, כְּתִיב (דברים י״א:י״ז) וְעָצַר אֶת הַשָּׁמַיִם וְלֹא יִהְיֶה מָטָר וְהָאֲדָמָה לֹא תִתֵּן אֶת יְבוּלָה. אִי הִיא סַטְיָיא, כָּל עָלְמָא יֵיבַד בְּגִינָהּ. אָמַר לֵיהּ, וְהָא אַתּוּן עָבְדִין לָהּ דְּתִסְטֵי וְלָא תְהַךְ בְּאוֹרְחָא דְכַשְׁרָא. אָמַר לֵיהּ חוֹבַתְכוֹן עָבְדִין לְאִתְעָרָא לָן. אָמַר רִבִּי יְהוּדָה שַׁפִּיר קָאָמַר הַהוּא הֶגְמוֹן.</p>"],[9514012230,"<p>תָּנוּ רַבָּנָן, (בראשית כ״ח:י״ב) וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה, זֶהוּ בֵּית עוֹלָמִים. וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמַיְמָה, כְּמָה דְאַתְּ אָמֵר (שמות ט״ו:י״ז) מָכוֹן לְשִׁבְתְּךָ פָּעַלְתָּ ה'. אֵיזֶהוּ רֹאשׁוֹ, זֶהוּ צִיּוֹן, שֶׁשָּׁם הַשְּׁכִינָה, וְהַכְּרוּבִים, וְקֹדֶשׁ הַקֳּדָשִׁים. אָמַר רִבִּי אַבָּא, סוּלָּם זֶה סִינַי, שֶׁבּוֹ נִיתְּנָה תּוֹרָה, וְשָׁם נִגְלוּ מֶרְכְּבוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>"],[9514012231,"<p>רַבִּי בָּא בְּשֵׁם ר' יוֹחָנָן אֲמַר, עוֹד אִית לְאִסְתַּכָּלָא בְּהַאי קְרָא כִּדְבְקַדְמֵיתָא, (שיר השירים ד׳:ד׳) כְּמִגְדַּל דָּוִד צַוָּארֵךְ בָּנוּי לְתַלְפִּיּוֹת, דְּהָא תָּנִינָן, אָמַר רִבִּי שִׁמְעוֹן אָמַר רִבִּי זֵירָא, כָּל זְמַן שֶׁיִּשְׂרָאֵל הָיוּ עוֹסְקִים בַּתּוֹרָה, בֵּית הַמִּקְדָּשׁ הָיָה קַיָּים, הֲדָא הוּא דִכְתִיב כְּמִגְדַּל דָּוִד צַוָּארֵךְ בָּנוּי. אִי מְגַדְּלִים תּוֹרָה, כְּהַאי מִגְדָּל, צַוָּארֵךְ בָּנוּי. מַהוּ צַוָּארֵךְ, זֶה בֵּית הַמִּקְדָּשׁ. הֲדָא הוּא דִכְתִיב, (בראשית מ״ה:י״ד) וַיִּפֹּל עַל צַוְּארֵי בִּנְיָמִין אָחִיו וַיֵּבְךְ, מְלַמֵּד שֶׁבָּכָה עַל מִקְדָּשׁ רִאשׁוֹן וְעַל מִקְדָּשׁ שֵׁנִי.</p>"],[9514012232,"<p>אָמַר רִבִּי יִצְחָק, מַהוּ מִגְדָּל. אֶלָּא מַה מִּגְדַּל דָּוִד, מִגְדָּל חָזָק, אַף הַמִּתְעַסְּקִים בַּתּוֹרָה, צְרִיכִין חִיזּוּק, וּבִנְיַן חָזָק. ר' תַּנְחוּם אָמַר, מִגְדַּל דָּוִד, מַה דָּוִד הָיָה מִתְגַּדֵּל בַּתּוֹרָה יוֹתֵר מִכָּל בְּנֵי דוֹרוֹ, כָּךְ הַמִּתְעַסְּקִים בַּתּוֹרָה, צְרִיכִין לְהִתְגַּדֵּל בַּתּוֹרָה וְשֶׁלֹּא יִתְבַּטְלוּ מִמֶּנָּהּ.</p>"],[9514012233,"<p>מַה דָּוִד הָיָה עוֹסֵק בַּתּוֹרָה לַיְלָה וְיוֹמָם, כָּךְ צָרִיךְ הָאָדָם לְהִתְעַסֵּק בַּתּוֹרָה לַיְלָה וְיוֹמָם, וּבְעוֹד שֶׁיִּתְעַסְּקוּ בָּהּ, וְיִתְגַּדְּלוּ בָּהּ, כְּמִגְדַּל דָּוִד הַצַּוָּאר בָּנוּי בִּנְיָן חָזָק וְגָדוֹל.</p>"],[9514012234,"<p>וְאִם לָאו, אֶלֶף הַמָּגֵן תָּלוּי עָלָיו, אֵלּוּ אֶלֶף שָׁנִים שֶׁיִּהְיוּ בַּגָּלוּת, וְהַדָּבָר תָּלוּי אִם יִגָּאֲלוּ בוֹ וְאִם לָאו. זָכוּ בַּתּוֹרָה, יִגָּאֲלוּ בְּאֶלֶף שָׁנִים. לֹא זָכוּ, כָּל שִׁלְטֵי הַגִּבּוֹרִים, אָמַר רִבִּי תַּנְחוּם, כָּל שִׁלְטֵי הַגִּבּוֹרִים יִשְׁתַּעְבְּדוּ בָּהֶם, וּלְאַחַר כֵּן יִגָּאֲלוּ.</p>"],[9514012235,"<p>מִכָאן אָמַר רַבִּי בָּא, וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה, זֶהוּ בֵּית עוֹלָמִים, הַנִּצַּב בְּבִנְיָנוֹ, בִּשְׁבִיל אוֹתָן הָעוֹסְקִין בַּתּוֹרָה בָּאָרֶץ. וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמַיְמָה, שֶׁהַמִּקְדָּשׁ הוּא בְּמַעֲלָה גְדוֹלָה, עַל כָּל הָעוֹלָם. וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עוֹלִים וְיוֹרְדִים בּוֹ, אֵלּוּ כֹּהֲנֵי מִשְׁמוֹרֶת.</p>"],[9514012236,"<p>ר' אֱלִיעֶזְר אוֹמֵר, עַל שֶׁהוּא מְכֻוָּון כְּנֶגֶד יְרוּשָׁלַיִם שֶׁל מַעְלָה. וְאוֹתָם הַשּׁוֹמְרִים יְרוּשָׁלַיִם שֶׁל מַעְלָה, הֵם שׁוֹמְרִים יְרוּשָׁלַיִם שֶׁל מַטָה. מַשְׁמַע, עוֹלִים וְיוֹרְדִים.</p>"],[9514012237,"<p>מַה מַּעֲלָה יוֹתֵר יֵשׁ בּוֹ. אָמַר רִבִּי אֱלִיעֶזְר, זֶהוּ דִּכְתִיב וְהִנֵּה ה' נִצָּב עָלָיו. כְּמָה דְאַתְּ אָמֵר (תהילים קכ״ז:א׳) אִם ה' לֹא יִשְׁמָר עִיר שָׁוְא שָׁקַד שׁוֹמֵר. וְהַיְינוּ דִכְתִיב, וְהִנֵּה ה' נִצָּב עָלָיו, לִהְיוֹת שׁוֹמֵר עַל אוֹתָן הַשּׁוֹמְרִים.</p>"],[9514012238,"<p>מַהוּ עָלָיו. אָמַר רִבִּי אֶלְעָזָר, לִשְׁמִירָה. כְּמָה דְאַתְּ אָמֵר, (ירמיהו ל״ט:י״ב) וְעֵינֶיךָ שִׂים עָלָיו. כָּךְ (מלכים א ט׳:ג׳) וְהָיוּ עֵינַי וְלִבִּי שָׁם כָּל הַיָּמִים. וּלֶעָתִיד לָבֹא, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַחֲזוֹר לִירוּשָׁלַיִם, וְלִהְיוֹת חוֹמָה לְשׁוֹמְרָהּ. כְּמָה דְאַתְּ אָמֵר, (זכריה ב׳:ט׳) וַאֲנִי אֶהְיֶה לָהּ נְאֻם ה' חוֹמַת אֵשׁ סָבִיב וּלְכָבוֹד אֶהְיֶה בְתוֹכָהּ.</p>"],[9514012239,"<p>(בראשית כ״ח:י״ג) הָאָרֶץ אֲשֶׁר אַתָּה שׁוֹכֵב עָלֶיהָ. אָמַר רִבִּי יִצְחָק, מְלַמֵּד שֶׁקִּפֵּל לוֹ אֶרֶץ יִשְׂרָאֵל. אָמַר רִבִּי יְהודָה, בֵּית הַמִּקְדָּשׁ מַמָּשׁ הָיָה, וְעָלָיו נִתְבַּשֵּׂר, וְעָלָיו הָיָה שׁוֹכֵב. מַשְׁמַע דִּכְתִיב (שם) וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא.</p>"],[9514012240,"<p>אָמַר רִבִּי יְהוּדָה, מִן הַג' אָבוֹת לֹא נִתְבַּשֵּׂר אֶחָד מֵהֶם עַל בֵּית הַמִּקְדָּשׁ, אֶלָּא יַעֲקֹב, שֶׁהוּא שְׁלִישִׁי מִן הָאָבוֹת. וּכְנֶגֶד אֵלּוּ הַשְׁלשָׁה: יִשַּׁי, דָּוִד, שְׁלמֹה. שְׁלֹמֹה שֶׁהוּא הַג' בְּנָאוֹ.</p>"],[9514012241,"<p>אָמַר רִבִּי יְהוּדָה, יַעֲקֹב שֶׁהוּא הַג' נִתְבַּשֵּׂר עַל שְׁלֹמֹה, שֶׁהוּא הַג', שֶׁיִּבְנֵהוּ. זֶה אוֹהֵב נָשִׁים, וְזֶה אוֹהֵב נָשִׁים. זֶה עוֹמֵד בְּתוּמוֹ, וְזֶה לֹא עוֹמֵד בְּתוּמוֹ, דִּכְתִיב (מלכים א י״א:ד׳) וַיְהִי לְעֵת זִקְנַת שְׁלֹמֹה נָשָׁיו הִטוּ אֶת לְבָבוֹ.</p>"],[9514012242,"<p>ר' יוֹסֵי פָּתַח, יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ הַר צִיּוֹן יַרְכְּתֵי צָפוֹן קִרְיַת מֶלֶךְ רָב. (תהילים מ״ח:ג׳) יְפֵה נוֹף, זֶהוּ יְרוּשָׁלַיִם, שֶׁהוּא מָתוֹק לַנֶּפֶשׁ וּמַרְפֵּא לָעֶצֶם. כְּמָה דְאַתְּ אָמֵר (שיר השירים ד׳:י״א) נוֹפֶת תִּטוֹפְנָה שִׂפְתוֹתַיִךְ.</p>"],[9514012243,"<p>אָמַר רִבִּי יְהוּדָה, אֶרֶץ מִצְרַיִם כָּל יוֹפִי שֶׁבָּהּ נוֹף וְתַחְפַּנְחֵס הָיוּ. נוֹף הָיָה הַמְשׁוּבָּח מִכֻּלָּם, שֶׁהָיְתָה בִּשְׁלשׁ מֵאוֹת וְתִשְׁעִים וְחָמֵשׁ תַּכְשִׁיטִין שֶׁל יוֹפִי. וְצִיּוֹן גָּדְלָה בְּיוֹפִי וְהָדָר עַל נוֹף. דְּאָמַר רִבִּי יְהוּדָה לָמָּה נִקְרָא שְׁמָהּ צִיּוֹן, מַה הַצִּיּוּן עוֹמֵד לְנֵס לְהִסְתַּכֵּל בּוֹ כו'.</p>"],[9514012244,"<p>וְהָיְתָה גְדוֹלָה בְּיוֹפִי מִנּוֹף, הֲדָא הוּא דִכְתִיב, (תהילים מ״ח:ג׳) יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ הַר צִיּוֹן יַרְכְּתֵי צָפוֹן, שֶׁכָּל מִי שֶׁהָיָה רוֹאֶה אוֹתָהּ, הָיָה שָׂמֵחַ. דְּתַנְיָא, אָמַר רִבִּי יוֹסֵי אָמַר רִבִּי חִיָּיא, מֵעוֹלָם לֹא נִכְנַס אָדָם בִּירוּשָׁלַיִם וְהָיָה עָצֵב, לְקַיֵּים מַה שֶּׁנֶּאֱמַר מְשׂוֹשׂ כָּל הָאָרֶץ.</p>"],[9514012245,"<p>אָמַר רִבִּי יִצְחָק, כֵּיוָן שֶׁשָּׁכַב יַעֲקֹב עָלֶיהָ, נִתְיַשֵּׁב דַּעְתּוֹ, וְנִגְלְתָה עָלָיו הַשְּׁכִינָה וְדִבְּרָה עִמּוֹ, מַה שֶּׁלֹּא הָיָה קוֹדֶם לָכֵן. דְּאָמַר רִבִּי יִצְחָק, עַד שֶׁעָמַד יַעֲקֹב בְּאוֹתוֹ מָקוֹם, לֹא נִגְלְתָה עָלָיו הַשְּׁכִינָה.</p>"],[9514012246,"<p>כֵיוָן שֶׁרָאָה יַעֲקֹב כָּךְ, יָדַע שֶׁהַמָּקוֹם גָּרַם לוֹ, וְהֵקִיץ מִשְּׁנָתוֹ, וְנִתְיָירֵא שֶׁמָּא דָּבָר אַחֵר הָיָה, וַיִּשְׁכַּב כְּבַתְּחִלָּה. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, יַעֲקֹב, לֹא כָּךְ הוּא, אֲנִי ה' אֱלֹהֵי אַבְרָהָם אָבִיךָ וֵאלֹהֵי יִצְחָק. וְעוֹד הָאָרֶץ אֲשֶׁר אַתָּה שׁוֹכֵב עָלֶיהָ לְךָ אֶתְּנֶנָּה וּלְזַרְעֶךָ. וְלֹא אֶתְגַּלֶּה לְאוּמָּה אַחֶרֶת, בְּגִילּוּי הַשְּׁכִינָה עַל הָאָרֶץ.</p>"],[9514012247,"<p>אָמַר רִבִּי יוֹסֵי, מַהוּ אֲשֶׁר אַתָּה שׁוֹכֵב עָלֶיהָ. אֶלָּא כְּשֵׁם שֶׁאַתָּה שׁוֹכֵב עָלֶיהָ וּנְבוּאָה עִמָּךְ, כָּךְ זַרְעֲךָ הַנְּבוּאָה תִּהְיֶה מְצוּיָה עִמָּהֶם, וְלֹא עִם אוּמָּה אַחֶרֶת.</p>"],[9514012248,"<p>ר' יַעֲקֹב פָּתַח, (ישעיהו כ״ו:י׳) יֻחַן רָשָׁע בַּל לָמַד צֶדֶק. תַּנְיָא, אָמַר רִבִּי יַעֲקֹב, וַוי שֶׁהָרָשָׁע יוּחַן בָּעוֹלָם הַזֶּה, זֶה זַרְעוֹ שֶׁל עֵשָׂו הָרָשָׁע. וּמִפְּנֵי מָה יֵשׁ לָהֶם חֵן וְרַחֲמִים. מִפְּנֵי שֶׁזַּרְעוֹ שֶׁל יַעֲקֹב לֹא לָמַד צֶדֶק. בְּאֶרֶץ נְכֹחוֹת יְעַוֵּל, זוֹ יְרוּשָׁלַיִם, שֶׁהִיא אֶרֶץ נְכוֹחוֹת.</p>"],[9514012249,"<p>מַהוּ יְעַוֵּל, אָמַר רִבִּי יַעֲקֹב, אֲוִירָא דְאַרְעָא יִשְׂרָאֵל מַחְכִּים. וּמְרַמֵּז נְבוּאָה. וְזַרְעוֹ שֶׁל עֵשָׂו יְעַוֵּול הָאֲוִיר וְהַנְּבוּאָה. מִפְּנֵי מָה, מִפְּנֵי שֶׁזַּרְעוֹ שֶׁל יַעֲקֹב לֹא רָאָה גֵּאוּת ה', וְאֵינָם עוֹסְקִים בַּתּוֹרָה, וְעַל כֵּן יוּחַן רָשָׁע וִיעַוֵּל טוּב הָאָרֶץ וְהַנְּבוּאָה. ר\"י בְּר' יְהוֹשֻׁעַ אָמַר, יוּחַן רָשָׁע, אֵלּוּ אוּמוֹת הָעוֹלָם שֶׁיֵּשׁ לָהֶם מֶמְשָׁלָה בָּעוֹלָם הַזֶּה, מִפְּנֵי שֶׁלֹּא לָמַד יִשְׂרָאֵל צֶדֶק.</p>"],[9514012250,"<p>תָּא חֲזֵי, כַּמָּה שְׁנִין יָתֵיב הַהוּא צַדִּיק, דְּלָא חָזָא לַאֲבוּהָ עֶשְׂרִין וּתְרֵין שְׁנִין. הָא אִינוּן יָתְבוּ בְּמִצְרַיִם, עֶשְׂרִים וּתְרֵין שְׁנִין, לְכָל שֵׁבֶט וְשֵׁבֶט מֵאִינוּן עֶשֶׂר שְׁבָטִין דְּזַבִּינוּ לֵיהּ, לְפוּם חוּשְׁבְּנָא הֲווֹ מָאתָן וְעֶשְׂרִין שְׁנִין לְכָלְהוֹ, דַּל מִינַיְיהוּ עֶשֶׂר שְׁנִין, דִּנְכִיתוּ לוֹן בְּדִינָא דִלְעֵילָא, בְּגִין עֶשֶׂר שְׁבָטִין קַדִּישִׁין דְּמִיתוּ תַּמָּן בְּמִצְרַיִם, אִשְׁתָּאֲרוּ מָאתַן וְעֶשֶׂר, הֲדָא הוּא דִכְתִיב רְדוּ שָׁמָּה.</p>"],[9514012251,"<p>תָּא חֲזֵי, כַּד גָּרְמוּ חוֹבִין, וְהַאי שַׁבָּת לָא אִתְנְטֵיר כִּדְקָא יָאוֹת, דִּכְתִיב (ירמיה יז) וְלֹא תוֹצִיאוּ מַשָּׂא מִבָּתֵּיכֶם בְּיוֹם הַשַּׁבָּת. לָא תִטְלוּן עֲלֵיכוֹן מָטוֹלָא דְּחוֹבִין, דְּהֲוָה מֵגִין עֲלֵיכוֹן מִנַּיְיהוּ, יוֹם הַשַּׁבָּת.</p>"],[9514012252,"<p>וְלָא שְׁמָעוּ לֵיהּ לִנְבִיאָה, וְאִיתְעַר עֲלֵיהֶן חֶרֶב נוֹקֶמֶת נְקַם בְּרִית. מַאן בְּרִית, דָּא שַׁבָּת, דִּכְתִיב לְדוֹרוֹתָם בְּרִית עוֹלָם. וּבְרִית מִילָה, דִּכְתִיב (שם יא) וּבְשַׂר קֹדֶשׁ יַעַבְרוּ מֵעָלָיִךְ. וּבְרִית צַדִּיק דְּזַבִּינוּ לֵיהּ.</p>"],[9514012253,"<p>וְכֹלָּא בְּחַד דַּרְגָּא, שַׁבָּת, וּבְרִית מִילָה, וְצַדִּיק. וְרָזָא דָא, (עמוס ב) עַל ג' פִּשְׁעֵי יִשְׂרָאֵל וְעַל אַרְבָּעָה לֹא אֲשִׁיבֶנּוּ, וְכָלְהוֹ תָּלֵי בְּמִכְרָם בַּכֶּסֶף צַדִּיק. וּכְדֵין שָׁרוֹ לְאִשְׁתַּעְבְּדָא שֶׁבַע עַל חַטָאתָם. וְאִתְגְּזַר עֲלֵיהוֹן בְּגָלוּתָא דְּבָבֶל, שִׁבְעִין שְׁנִין, בְּחוֹבִין דִּשְׁמִטָה וְיוֹבֵל, דְּתַלְיָין בְּשַׁבָּת הַגָּדוֹל, וְשַׁבָּת סְתָם.</p>"],[9514012254,"<p>וּלְבָתַר אָתוֹ לְאַרְעָא קַדִּישָׁא, וְאִתְיַישְׁבוּ בָהּ ת\"כ שְׁנִין, לְתַשְׁלוּם שִׁבְעִין שָׁבוּעִין, וְשִׁבְעִין שְׁנִין, עֲשָׂרָה שְׁנִין לְכָל יוֹמָא, מֵאִינוּן דְּיַנְקִין מִשְּׁבִיעִי, דְּשַׁבָּת הַגָּדוֹל אוּף הָכֵי אִיקְרֵי שְׁבִיעִי מִתַּתָּא לְעֵילָא. דְּכָלֵיל כְּאֶחָד זָכוֹר וְשָׁמוֹר. וּלְבָתַר אִתְקַיְּימוּ ת\"כ שְׁנִין בְּאַרְעָא, עַל חֵילָא דְאוֹרַיְיתָא, דַּהֲווֹ מִתְעַסְּקֵי.</p>"],[9514012255,"<p>וְכַד גָּרַם חוֹבָא דְּשִׂנְאַת חִנָּם, אִתְעָרֵי שִׂנְאַת חִנָם דִּבְקַדְמֵיתָא. הֲדָא הוּא דִכְתִיב, (בראשית לז) וַיִּשְׂנְאוּ אוֹתוֹ, לְהַהוּא זַכָּאָה. וּכְדֵין יְהֵיב לוֹן קוּדְשָׁא בְּרִיךְ הוּא, בְּיַד מַאן דְּסָנֵי לוֹן שִׂנְאַת חִנָּם. הֲדָא הוּא דִכְתִיב בֶּאֱדוֹם, (יחזקאל לה) יַעַן הֱיוֹת לְךָ אֵיבַת עוֹלָם וַתַּגֵּר אֶת בְּנֵי יִשְׂרָאֵל עַל יְדֵי חָרֶב.</p>"],[9514012256,"<p>וּכְדֵין אִתְפְּרַע מִנַּיְיהוּ, עַל יְדוֹי מִנְיָינָא דְּאִינוּן שְׁנִין, דְּחָסְרוּ מֵרָזָא דְּשֶׁבַע עַל חַטֹאתֵיכֶם. תָּא חֲזֵי, כַּד תִּמְנֵי עֶשְׂרִים וּתְרֵין שְׁנִין שֶׁבַע זִמְנִין, לְכָל חַד מֵאִינוּן עֲשָׂרָה דְּזַבִּינוּ לֵיהּ, הֲווֹ לְהוֹ אֶלֶף וַחֲמֵשׁ מְאָה וְאַרְבָּעִין.</p>"],[9514012257,"<p>לֹא עָלְתָה שַׁוְעָתָם לְפָנָיו. אָמַר רִבִּי יִצְחָק, כַּד עָבִיד קוּדְשָׁא בְּרִיךְ הוּא דִּינָא בְּפַמַּלְיָא שֶׁל מַעְלָה, הַהוּא דִינָא מַאי הֲוֵי. אֲמַר ר' אֶלְעָזָר, אַעֲבַר לְהוֹ בְּהַהוּא נְהַר דִּינוּר, וְאַעֲבַר לְהוֹן מִשּׁוּלְטָנְהוֹן, וּמַנֵּי שׁוּלְטָנִין אַחֲרָנִין דִּשְׁאָר עַמִּין. אָמַר לֵיהּ, וְהָא כְתִיב (תהלים קד) מְשָׁרְתָיו אֵשׁ לוֹהֵט. אֲמַר לֵיהּ אִית אֶשָׁא קַשְׁיָא מֵאֶשָׁא, וְאִית אֶשָׁא דְּכָבֵי אֶשָׁא.</p>"],[9514012258,"<p><Noneb> סִתְרֵי תוֹרָה </b></p>"],[9514012259,"<p>פְּתַח הַהוּא יוּדָאי וַאֲמַר, (תהילים ע״ג:כ״ח) וַאֲנִי קִרְבַת אֱלֹהִים לִי טוֹב וְגו'. תָּא חֲזֵי, כַּד בַּר נָשׁ אִתְקְרֵיב לְאוֹרַיְיתָא דְאִקְּרֵי טוֹב, דִּכְתִיב (שם קיט) טוֹב לִי תוֹרַת פִּיךָ, כְּדֵין אִתְקְרֵיב לְּקוּדְשָׁא בְּרִיךְ הוּא דְּאִקְרֵי טוֹב, דִּכְתִיב (שם קמה) טוֹב ה' לַכֹּל. וּכְדֵין אִתְקְרֵיב לְמֶהֱוֵי זַכָּאָה. כמדָּבָר אַחֵר, (ישעיהו ג׳:י׳) אִמְּרוּ צַדִּיק כִּי טוֹב, וְכַד אִיהוּ זַכָּאָה, שְׁכִינְתָּא שַׁרְיָא עֲלֵיהּ, וְאוֹלִיפַת לֵיהּ רָזִין עִילָּאִין בְּאוֹרַיְיתָא. בְּגִין דִּשְׁכִינְתָּא לָא אִזְדַּוְּוגָא אֶלָּא בְּטוֹב, דְּהָא צַדִּיק וְצֶדֶק כַּחֲדָא אָזְלִין.</p>"],[9514012260,"<p>תָּא חֲזֵי, כַּד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, קַיָּים לֵיהּ וְשָׁתֵיל עַל הַנְהוּ שִׁיתָּא יוֹמִין עִילָּאִין, וּשְׁבִיעָאָה דַּעֲלַיְיהוּ, דִּבְגִינֵיהּ דִּשְׁבִיעָאָה דְּאִקְּרֵי צַדּיק, מִתְּזָנִין עִילָּאִין וְתַתָּאִין, וַעֲלֵיהּ קָיְימִין, וּבֵיהּ מִסְתַּמְּכִין, וְהוּא יְסוֹדָא וְשָׁרְשָׁא דִילְהוֹן.</p>"],[9514012261,"<p>הֲדָא הוּא דִכְתִיב, (תהילים קמ״ה:ט״ו) עֵינֵי כֹל אֵלֶיךָ יְשַׂבֵּרוּ וְגו'. עֵינֵי כֹל אֵלֶיךָ יְשַׂבֵּרוּ, לְהַהוּא מְשַׁח רְבוּת עִלָּאָה, דִּנְגֵיד מִמּוֹחָא סְתִימָאָה דְּכָל סְתִימִין, לְהַאי כ\"ל. וּכְדֵין וְאַתָּה נוֹתֵן לָהֶם אֶת אָכְלָם בְּעִתּוֹ, דְּהַאי כָּל כַּד אִתְעַר לְכַלָּה, דְּאִיהִי כְּנֶסֶת יִשְׂרָאֵל. וּכְדֵין הוּא לְמִירְחַם עַל עָלְמָא, וְכוֹלְהוֹ עָלְמִין בְּחֵדוּ בְּשַׁעֲשׁוּעָא.</p>"],[9514012262,"<p>וּכְדֵין מַה כְּתִיב, פּוֹתֵחַ אֶת יָדֶךָ וְגו'. וְדָא רַעֲוָא דְּרַעֲוִין, דְּנָחֵית מִמּוֹחָא סְתִימָאָה, לְהַאי כָּל. וְכֵיוָן דְּהַאי כָּל אִתְבָּרֵךְ, כּוֹלְהוֹ עָלְמִין אִיתְבְּרִיכוּ, הֲדָא הוּא דִכְתִיב צַדִּיק ה' וְגו', קָרוֹב ה' וְגו', רְצוֹן יְרֵאָיו יַעֲשֶׂה וְגו'.</p>"],[9514012263,"<p>וּכְמָא דִּבְרָא הַאי בְּעָלְמָא עִילָּאָה, בְּרָזָא דִשְׁמֵיהּ קַדִּישָׁא, הָכֵי בְּרָא בְּעָלְמָא תַּתָּאָה, שִׁיתָּא זַכָּאי קְשׁוֹט, וְחַד שְׁבִיעָאָה. כְּדִכְתִיב (קהלת ז׳:י״ד) גַּם אֶת זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים.</p>"],[9514012264,"<p>וְכַד גָּרְמוּ חוֹבִין, וְדָחוֹ לְהַהוּא כָּל דְּאִיקְּרֵי צַדִּיק מֵאַתְרֵיהּ, כְּדִכְתִיב (עמוס ב׳:ו׳) עַל מִכְרָם בַּכֶּסֶף צַדִּיק. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, אֲנָא גָּזַרְנָא דִּיהֵא עָלְמָא תַּתָּאָה כְּגַוְּונָא דְּעָלְמָא עִילָּאָה, וִיהֵא הַהוּא צַדִּיק שַׁלִּיט עַל הָאָרֶץ, וְיֶהֱווֹן כָּל בְּנֵי עָלְמָא, מִתְבָּרְכִין עַל יְדוֹי.</p>"],[9514012265,"<p>הֲדָא הוּא דִכְתִיב, (בראשית מט) בֶּן פּוֹרָת יוֹסֵף, דְּהָא לֵית בְּכָל שַׁיְיפֵי גוּפָא דְּיַעֲבֵיד פֵּירִין, אֶלָּא הַאי צַדִּיק יְסוֹד עוֹלָם. וּבֶן פּוֹרָת עֲלֵי עָיִן, מַאי קָא מַיְירֵי.</p>"],[9514012266,"<p>אֶלָּא, כְּמָה דְּהַאי עַיִן קִיּוּמָא דְגַלְגַּלָּא, דְּלָא יָכְלָא גַּלְגַּלָּא לְאִתְקְיָימָא, אֶלָּא בְּבַת עַיִן דִּילֵיהּ. הָכֵי יוֹסֵף אִיהוּ כְּעַיִן לְכָל אִינוּן שִׁתָּא דְּסַחֲרִין לֵיהּ. מִיָּמִינֵיהּ תְּלָתָא, וּמִשְׂמָאלָא תְּלָתָא, וְאִיהוּ מְקַיֵּם לוֹן. וְהָכֵי אִיהוּ לְכָל עָלְמָא, דְּהָא עָלְמָא לָא קָיְימָא אֶלָּא עַל אִינוּן שִׁיתָּא, וּשְׁבִיעָאָה דַּעֲלַיְיהוּ.</p>"],[9514012267,"<p>וּקְרָא קוּדְשָׁא בְּרִיךְ הוּא לַצַּדִּיק בְּרָזָא דְשַׁבָּת. וְנָח בֵּיהּ, וַאֲנַח בֵּיהּ כָּל בִּרְכָאן, לְבָרְכָא כָּל שְׁאָר יוֹמִין. הֲדָא הוּא דִכְתִיב, (שמות כ׳:י״א) וַיָּנַח בַּיּוֹם הַשְּׁבִיעִי עַל כֵּן בֵּרַךְ ה' אֶת יוֹם הַשַּׁבָּת. מַאן יוֹם הַשַּׁבָּת, הֱוֵי אֵימָא דָּא צַדִּיק.</p>"],[9514012268,"<p>אֲמַר לוֹן קוּדְשָׁא בְּרִיךְ הוּא, אַתּוּן חִלַּלְתּוּן לְהַאי שַׁבָּת, דַּאֲנָא גָּזַרְנָא דִּיהֵא מֶלֶךְ עַל כָּל שְׁאָר יוֹמִין, וְאַתּוּן עֲבַדְתּוּן יָתֵיהּ עֶבֶד עֲבָדִין, אוּף אַתּוּן תִּסְבְּלוּן הַהוּא עֲבוֹדָה קַשְׁיָא.</p>"],[9514012269,"<p>תָּא חֲזֵי, כַּמָּה שְׁנִין יָתֵיב הַהוּא צַדִּיק, דְּלָא חָזָא לַאֲבוּהִי, כ\"ב שְׁנִין. הָא אִנוּן יָתְבוּ בְּמִצְרַיִם כ\"ב שְׁנִין, לְכָל שִׁבְטָא מֵאִינוּן עֶשֶׂר שְׁבָטִין דְּזַבִּינוּ לֵיהּ. לְפוּם חוּשְׁבְּנָא הֲווֹ מָאתָן וְעֶשְׂרִים שְׁנִין לְכוֹלְהוֹ, דַּל מִינַיְיהוּ עֶשֶׂר שְׁנִין דִּנְכִיתוּ לוֹן בֵּי דִינָא דִּלְעֵילָא, בְּגִין עֶשֶׂר שְׁבָטִין קַדִּישִׁין דְּמִיתוּ תַּמָּן בְּמִצְרַיִם, אִשְׁתָּאֲרוּ מָאתָן וְעֶשֶׂר, הֲדָא הוּא דִכְתִיב, (בראשית מב) רְד\"וּ שָׁמָּה.</p>"],[9514012270,"<p>אֲמַר לוֹן יַעֲקֹב, בְּבָעוּ מִינַּיְיכוּ, חוּתוּ לְגָלוּתָא, וּנְכִיתוּ אִינוּן חוֹבִין וְלָא יִתְחְרַב עַלְמָא בְּכַפְנָא, דְּהָא לֵית בְּכוֹ מַאן דְּיִזּוֹן לְכוֹ קוּדְשָׁא בְּרִיךְ הוּא, בַּר עַל יְדֵי דְּהַהוּא צַדִּיק דְּזַבִּינְתּוּן. הֲדָא הוּא דִכְתִיב, (תהילים קמ״ה:ט״ז) פּוֹתֵחַ אֶת יָדֶךָ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן. עַל יְדֵי דְּמַאן, עַל יְדֵי דְּכ\"ל. הָדַר פָּרֵישׁ מַאן הַאי כָּל, צַדִּיק, הֲדָא הוּא דִכְתִיב צַדִּיק ה' וְגו'.</p>"],[9514012271,"<p>וּכְגַוְּונָא דָא לְתַתָּא, עַל יְדָא דְהַאי צַדִּיק, הֲוָה לֵיהּ לְעָלְמָא שְׁזֵיבוּתָא, בְּאִינוּן שֶׁבַע שְׁנֵי כַּפְנָא. וְעַל דִּמְנָעוּ בִּרְכָאן מִשֶּׁבַע דַּרְגִּין עִילָּאִין, אִיתְעָרוּ דַּרְגִּין דְּסִטְרָא אָחֳרָא עֲלַיְיהוּ בְּחוֹבַיְיהוּ.</p>"],[9514012272,"<p>כֵיוָן דְּנָחַת יַעֲקֹב שְׁלֵימָא לְמִצְרַיִם, הוּא וְכָל אִינוּן שְׁבָטִין, וְחָמוֹ עָלְמָא תַּתָּאָה כְּגַוְונָא דְּעָלְמָא עִילָאָה, דְּעַל יְדֵי דְּהַהוּא צַדִּיק מִיתְּזַן עָלְמָא, הֲדָא הוּא דִכְתִיב, (בראשית מ״ב:ו׳) הוּא הַמַּשְׁבִּיר לְכָל עַם הָאָרֶץ.</p>"],[9514012273,"<p>הוּא הַמַּשְׁבִּיר, מַאי מַשְׁבִּיר. אֶלָּא שׁוֹבֵר הוּא בְּקַדְמִיתָא מֵעָלְמָא עִילָּאָה. כְּדִכְתִיב עֵינֵי כֹל אֵלֶיךָ יְשַׂבֵּרוּ. וּבָתַר מַשְׁבִּיר לְעָלְמָא תַּתָּאָה.</p>"],[9514012274,"<p>וּמְנָא לָן דְּיוֹסֵף אִקְּרֵי כָּל. דִּכְתִיב (מלכים א ה׳:י״א) וְכַלְכֹּל וְדַרְדַּע. וְתָאנָא, כַּלְכֹּל זֶה יוֹסֵף, דִּכְתִיב וַיְכַלְכֵּל, וּכְתִיב מִשָּׁם רוֹעֶה אֶבֶן יִשְׂרָאֵל.</p>"],[9514012275,"<p>וְכַד חָמָא יַעֲקֹב שְׁלֵימָא כָּל דָּא, וְחָמָא כָּל אִינוּן שֶׁבַע שְׁנִין עִילָּאִין, דְּאִסְתַּכְמוּ לְמֶהֱוֵי כַּפְנָא בְּעָלְמָא, עַל חוֹבָא דְּגָרְמוּ בְּנוֹי, דְּזַבִּינוּ לְהַאי זַכָּאָה קַדִּישָׁא, וְלַאֲפָקָא לֵיהּ מֵאַתְרֵיהּ. כְּדֵין צַלֵּי לְקוּדְשָׁא בְּרִיךְ הוּא, וְאַעֲדֵי מִנְּהוֹן חָמֵשׁ שְׁנִין.</p>"],[9514012276,"<p>מַאי טַעְמָא חָמֵשׁ שְׁנִין, אֶלָּא תָּא חֲזֵי, רָזָא דְמִלְּתָא הָכֵי הוּא, בְּאִינוּן יוֹמִין עִילָּאִין, אִיהוּ אָחִיד בַּחֲמִשָּׁאָה, דְּהָכֵי הוּא מִתַּתָּא לְעֵילָא. אֲבָל בְּאִינוּן תְּרֵין דַּעֲלֵיהּ, דַּאֲחָדִין בְּהוּ אַבָהָתוֹי, לָא הֲוָה לֵיהּ רְשׁוּתָא לְבַטָלָא מִידֵי, וְעַד חוּלָקֵיהּ בְּאִינוּן בָּטֵל גְּזֵירָה, וְלָא יַתִּיר.</p>"],[9514012277,"<p>וְיוֹסֵף הַצַּדִּיק נָמֵי עָבִיד הָכֵי, הֲדָא הוּא דִכְתִיב, (בראשית מ״ז:ב׳) וּמִקְצֵה אֶחָיו לָקַח חֲמִשָּׁה אֲנָשִׁים וַיַּצִּיגֵם לִפְנֵי פַרְעֹה. מַאן אִינוּן, חֲמִשָּׁה אִינוּן דְּלָא סָנֵי לֵיהּ, הֲדָא הוּא דִכְתִיב, (שם לז) וְהוּא נַעַר אֶת בְּנֵי בִּלְהָה וְגו'. אָמַר כְּדַאי אַתּוּן זַכָּאִין, לְמֵיקַם בְּהַאי פִּרְצָה דְּפָרְצוּ אֲחֵיכוֹן. לִפְנֵי פַרְעֹה, מַאן פַּרְעֹה, דָּא דִינָא עִילָּאָה, דְּקָיְימָא לְאִתְפְּרָעָא מֵחוֹבֵי עָלְמָא.</p>"],[9514012278,"<p>וְכַד אִשְׁתְּלִּימוּ אִינוּן יוֹמִין דְּאִתְגְּזַר עֲלַיְיהוּ לְמֵיתַב בְּגָלוּתָא, כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא אִיתְעַר בְּרַחֲמוֹהִי סַגִּיאִין עֲלַיְיהוּ, וּבְדִינָא עַל אִינוּן דְּאִשְׁתַּעְבְּדוּ בְּהוּ, וְאַפֵּיק לוֹן מִתַּמָּן.</p>"],[9514012279,"<p>כֵיוָן דְּמָטוֹי לְמָרָה, קָמַת מִדַּת דִּינָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וַאֲמַר, וְאֵיךְ יִפְקוּן יִשְׂרָאֵל מִגָּלוּתָא, וְהָא כְתִיב בְּאוֹרַיְיתָא דִּטְמִירָא תְּרֵי אַלְפֵי שְׁנִין מִקַּמֵּי דְּאִתְבְּרֵי עָלְמָא, דְּעַל חַד שִׁבְעָה עַל חוֹבֵיהוֹן אִית לְהוֹן לִיסְבַּל, בְּגִין הַהוּא פִּרְצָה רַבָּתָא דְּפָרְצוּ וְחָבוּ בְּהַהוּא זַכָּאָה קַדִּישָׁא.</p>"],[9514012280,"<p>אָמַר לֵיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא הָכֵי הוּא דִינָא, מִיהוּ בְּאוֹרַיְיתָא קַדִּישְׁתָּא, אִית לִי מַתָּנָה טוֹבָה, וְשַׁבָּת שְׁמָהּ, וְכַד אִינוּן נָטְרִין לָהּ, אִיהוּ קָיְימָא בְּהַהוּא אֲתַר, לְסָגְרָא הַהִיא פִּרְצָה דְּפָרְצוּ. דְּהַהוּא צַדִּיקָא שְׁבִיעָאָה בָּהּ אָחֵיד, וּכְדַאי הִיא לְכַפָּרָא עַל הַהוּא חוֹבָא.</p>"],[9514012281,"<p>הֲדָא הוּא דִכְתִיב, (שמות טו) וַיִּצְעַק אֶל ה'. מַאן וַיִּצְעַק, דָּא מִדַּת דִּינָא, דְּקָיְימָא וְצָוְוחָא קַמֵּיהּ. וַיּוֹרֵהוּ ה' עֵץ, דָּא אוֹרַיְיתָא, הֲדָא הוּא דִכְתִיב, (משלי ג׳:י״ח) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. וַיַּשְׁלֵךְ אֶל הַמָּיִם, מַאן אִינוּן מָיִם, מַיִם הַזֵּדוֹנִים דְּקָמוֹ לְאִתְפְּרָעָא מִינַיְיהוּ, וּכְדֵין וַיִּמְתְּקוּ הַמָּיִם, אַבְסִימוּ וַדַּאי, דְּהָא חָזוֹ אַסְוָותָא רַבָּתָא לְהַהוּא חוֹבָא.</p>"],[9514012282,"<p>וּמְנָא לָן דִּבְמָרָה אִתְפַּקָּדוֹ. דִּכְתִיב (דברים ה׳:י״ב) שָׁמוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְשׁוֹ כַּאֲשֶׁר צִוְּךָ ה' אֱלֹהֶיךָ, וְאָמַר מָר, כַּאֲשֶׁר צִוְּךָ, בְּמָרָה. אָמַר לוֹן קוּדְשָׁא בְּרִיךְ הוּא, אִי אַתּוּן נָטְרִין לְהַאי שְׁבִיעָאָה עִילָּאָה, לֵית רְשׁוּ לְמִדַּת דִּינָא לְקַטְרְגָא בְּכוֹ. הֲדָא הוּא דִכְתִיב, (שמות ט״ו:כ״ה) שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט.</p>"],[9514012283,"<p>וְעַל דָּא תָּנִינָן, יְכוֹלָה הִיא שַׁבָּת שֶׁתְּרַחֵם עָלֵינוּ, וִיקַבְּצֵנוּ קוּדְשָׁא בְּרִיךְ הוּא מִן גָּלוּתֵינוּ, וְאִלְמָלֵי שָׁמְרוּ יִשְׂרָאֵל שְׁתֵּי שַׁבָּתוֹת כְּהִלְּכָתָן, מִיָּד נִגְאָלִים.</p>"],[9514012284,"<p>תָּא חֲזֵי, כַּד גָּרְמוּ חוֹבִין, וְהַאי שַׁבָּת לָא אִתְנְטֵיר כִּדְקָא חָזֵי, כִּדְאַשְׁכְּחָן דְאַזְהַר לוֹן נְבִיאָה עִילָּאָה, הֲדָא הוּא דִכְתִיב, (ירמיהו י״ז:כ״א) כֹּה אָמַר ה' הִשָּׁמְרוּ בְּנַפְשׁוֹתֵיכֶם וְאַל תִּשְׂאוּ מַשָּׂא בְּיוֹם הַשַּׁבָּת וְהֵבֵאתֶם בְּשַׁעֲרֵי יְרוּשָׁלָיִם. מַאי וְאַל תִּשְׂאוּ מַשָּׂא. אֶלָּא אָמַר לוֹן, בְּבָעוּ מִינַּיְיכוּ, לֹא תִשְׂאוּ מַשָּׂא דְּהַהוּא חוֹבָא דְּשַׁבָּת עֲלַיְיכוּ.</p>"],[9514012285,"<p>וְאִי אַתּוּן נָטְרִין לֵיהּ, תִּגְרְמוּן קִיּוּמָא דְּעִילָּאִין וְתַתָּאִין. דְּהַהוּא שַׁבָּת עִילָּאָה דְּחַבְתּוּן לְקִבְלֵיהּ, מְדוֹרֵיהּ וְשַׁעֲשׁוּעֵיהּ לָאו אִיהוּ, אֶלָּא בְּשַׁעֲרֵי יְרוּשָׁלַיִם עִילָּאָה, דְּאִקְרוּן שַׁעֲרֵי צֶדֶק. וְאִיהִי כַּלָּה הַכְּלוּלָה מֵהַכֹּל.</p>"],[9514012286,"<p>וְאִי אַתּוּן נָטְרִין לֵיהּ, תִּגְרְמוּן דִּכְדֵין הִיא תִּתְחַזֵּק בִּידָא דְּמַלְכוּתָא דְאַרְעָא, מַלְכוּתָא דְּדָוִד, בְּגִין דְּהִיא מַלְכוּת אִתְקְרִיאַת, וּבְגִין דָּא אֲמַר דָּוִד, דְּאָחֵיד בָּהּ, (דברי הימים א כ״ט:י״א) לְךָ ה' הַמַּמְלָכָה, בִּתְרֵין ממי\"ן, לְאַכְלָלָא מַלְכוּתָא דִילֵיהּ, וּלְיַחֲדָא לָהּ בְּמַלְכוּתָא דִשְׁמַיָא. וְאִי אַתּוּן לָא תִשְׁמְעוּן לְקַדֵּשׁ לֵיהּ, וְתַעַבְדוּן לֵיהּ חוֹל, מַה כְּתִיב (ירמיהו י״ז:כ״ז) וְהִצַּתִּי אֵשׁ בִּשְׁעָרֶיהָ וְאָכְלָה אַרְמְנוֹת יְרוּשָׁלַיִם, דִּלְתַתָּא.</p>"],[9514012287,"<p>תָּא חֲזֵי, כְּדֵין אִתְעָרַת הַהִיא חֶרֶב נוֹקֶמֶת נְקַם בְּרִית, עַל דְּלָא נָטְרוּ הַהוּא בְּרִית קַדִּישָׁא, בִּתְלַת גְּוָונִין. חַד בְּרָזָא דְּצַדִּיק דְּזַבִּינוּ, דְּאָחֵיד בֵּיהּ, וּנְטַר לֵיהּ, וּבְגִינֵיהּ אִקְרֵי צַדִּיק. וְחַד, דִּכְתִיב (שם יז) וּבְשַׂר קֹדֶשׁ יַעַבְרוּ מֵעָלָיִךְ. וְחַד בָּרָזָא דְּשַׁבָּת דְּחִלְּלוּ, וְכֹלָּא בְּחַד אֲתַר אִיהוּ.</p>"],[9514012288,"<p>וּכְדֵין עַל שְׁלשָׁה פִּשְׁעֵי יִשְׂרָאֵל, אִתְגְּזַר עֲלַיְהוּ לְמֶהֱוֵי שִׁבְעִין שְׁנִין לְבַר מֵאַרְעָא קַדִּישָׁא, עֲשָׂרָה לְכָל יוֹמָא. וּלְסוֹף שִׁבְעִין שְׁנִין, אַפֵּיק לוֹ קוּדְשָׁא בְּרִיךְ הוּא מִתַּמָּן, וַאֲתוֹ לְאֶרֶץ יִשְׂרָאֵל. וְאִתְקַיַּים בֵּית שְׁנֵי ת\"כ שְׁנִין, עַל חֵילָא דְאוֹרַיְיתָא, דַּהֲווֹ מִתְעַסְּקִין בָּהּ, בְּאִינוּן פְּקוּדִין קַדִּישִׁין כִּדְקָא חָזֵי.</p>"],[9514012289,"<p>וְכַד אִשְׁתַּלִּימוּ, גָּרַם חוֹבָה דְּשִׂנְאַת חִנָּם, וְאִיתְעַר הַהִיא שִׂנְאַת חִנָּם דְּקַדְמֵיתָא, הֲדָא הוּא דִכְתִיב, (בראשית לז) וַיִּשְׂנְאוּ אֹתוֹ, לְהַהוּא צַדִּיק. וּכְדֵין יְהַב יַתְהוֹן קוּדְשָׁא בְּרִיךְ הוּא בִּידָא דְּמַאן דְּסָנֵי לוֹן שִׂנְאַת חִנָּם, הֲדָא הוּא דִכְתִיב בֶּאֱדוֹם (יחזקאל לה) יַעַן הֱיוֹת לָךְ אֵיבַת עוֹלָם וְתִגָּר אֶת בְּנֵי יִשְׂרָאֵל עַל יְדֵי חָרֶב.</p>"],[9514012290,"<p>וּכְדֵין אִתְפְּרַע מִנַיְיהוּ, עַל יְדֵי מִנְיָינָא דְּאִינוּן שְׁנִין, דְּחָסְרוּ מֵרָזָא דְּשֶׁבַע עַל חַטֹאתֵיכֶם. תָּא חֲזֵי, כַּד תִּמְנֶה כ\"ב שְׁנִין ז' זִמְנִין, לְכָל חַד מֵאִינוּן עֲשָׂרָה דְּזַבִּינוּ לֵיהּ, תִּשְׁכַּח אֶלֶף תק\"מ, וּכְדֵין יִתְעַר פּוּרְקָנָא דְיִשְׂרָאֵל, כְּצַפְרָא דְּשָׁארַת לְאַנְהָרָא זְעֵיר זְעֵיר, עַד י\"ז שְׁנִין, דְּאִסְתַּלַּק הַהוּא צַדִּיק דַּרְגָּא דְטוֹ\"ב, הֲדָא הוּא דִכְתִיב, (בראשית ל״ז:ב׳) יוֹסֵף בֶּן י\"ז שָׁנָה הָיָה רֹעֶה אֶת אֶחָיו. דְּהָא כְּדֵין יִתְחֲזֵי לְמֵיקַם בַּפֶּרֶץ, קַמֵּי מִדַּת דִּינָא, דְּהָא אִשְׁתְּלִימוּ חוֹבֵי עָלְמָא, וּכְדֵין (עובדיה א׳:י״ח) וְהָיָה בֵּית יַעֲקֹב אֵשׁ וּבֵית יוֹסֵף לֶהָבָה וּבֵית עֵשָׂו לָקַשׁ וְדָלְקוּ בָּהֶם וַאֲכָלוּם.</p>"],[9514012291,"<p>וּכְדֵין יִתְעַר קוּדְשָׁא בְּרִיךְ הוּא טַבְוָון סַגִּיאִין עַל יִשְׂרָאֵל, וְיִתְבַּע עֶלְבּוֹנְהוֹן, וְעֶלְבּוֹנָא דְאוֹרַיְיתָא, דְּאוֹקְדוּ בְנוּרָא. וְדָמָא דְּאִינוּן דְּאִתְקַטָלוּ עַל קְדוּשַּׁת שְׁמֵיהּ. וּכְדֵין יִתְרְעֵי יוֹסֵף לַאֲחוֹהִי, (ישעיהו י״א:י״ג) אֶפְרָיִם לֹא יְקַנֵּא אֶת יְהוּדָה וִיהוּדָה לֹא יָצוּר אֶת אֶפְרָיִם.</p>"],[9514012292,"<p>תָּא חֲזֵי דְּהָכֵי הוּא, דִּתְנַן בְּי\"ז בְּתַמּוּז בּוּטַל הַתָּמִיד, וּבְט' בְּאָב חָרַב בֵּית מַקְדְּשָׁא. כּדְּאָמַר רִבִּי יוֹסֵי, מְגַלְגְּלִין זְכוּת לְיוֹם זַכַּאי, וְחוֹבָה לְיוֹם חַיָּיב. דִּבְהַהִיא לֵילְיָא אַפִּיקוּ דִבָּה רָעָה עַל אַרְעָא קַדִּישָׁא, וַאֲרֵימוּ קָלְהוֹן בִּבְכִיָּה, וְאִתְקְּבָעַת לְדָרֵי דָרִין.</p>"],[9514012293,"<p>וְדוֹק וְתִשְׁכַּח, מִדְּבוּטַל הַתָּמִיד, דְּהֲוָה מְכַפֵּר עַל חוֹבֵיהוֹן, עַד דְּאִתְחְרַב בֵּי מַקְדְּשָׁא, בֵּין בְּזִמְנָא קַדְמָאָה בֵּין בְּזִמְנָא תִּנְיָנָא, כ\"ב יוֹמִין, לָקֳבֵל אִינוּן כ\"ב שְׁנִין דְּלָא חָמָא הַהוּא צַדִּיק אַפֵּי יְקָרָא דַּאֲבוּהָ, לְאַחֲזָאָה חָכְמְתָא עִילָּאָה, דְּהָא בְּהָא תַּלְיָא.</p>"],[9514012294,"<p>וְהָא אִיתְעָרוּ חַבְרַיָיא, דְּכַד חָרֵיב מַקְדְּשָׁא מוֹצָאֵי שַׁבָּת הָיְתָה, וּמוֹצָאֵי שְׁבִיעִית, וּמִשְׁמַרְתּוֹ שֶׁל יְהוֹיָרִיב הָיְתָה, וְהַלְּוִים עוֹמְדִים עַל דּוּכָנָם, וְאוֹמְרִים שִׁירָה: (תהילים צ״ד:כ״ב) יָגוֹדוּ עַל נֶפֶשׁ צַדִיק וְגו' וַיְהִי ה' לִי לְמִשְׂגָּב וְגו', וַיָּשֶׁב עֲלֵיהֶם אֶת אוֹנָם וְגו', וְלֹא הִסְפִּיקוּ לוֹמַר יַצְמִיתֵם ה' אֱלֹהֵינוּ, עַד שֶׁבָּאוּ גוֹיִם וּכְבָשׁוּם. דְּהָא אִי אֲמָרוּ לֵיהּ, לָא הֲוָה לוֹן תַּקָּנָה.</p>"],[9514012295,"<p>וּמוֹצָאֵי שַׁבָּת, חָכְמְתָא סַגִּיאָה קָא רָמַז, דִּנְפָקוּ מִשַּׁבָּת דְּהֲוָה רְפוּאָה לְמַכַּתְהוֹן. וּמוֹצָאֵי שְׁבִיעִית, דְּחָבוֹ לְגַבֵּי כְּנֶסֶת יִשְׂרָאֵל. וְלָא עוֹד, אֶלָּא דְּחָאבוּ בְּמִילָה, וְלָא קָיְימָא בְּשַׂר קֹדֶשׁ. וּמִשְׁמַרְתּוֹ שֶׁל יְהוֹיָרִיב, כְּמָה דְאַתְּ אָמֵר (ירמיה ב) עוֹד אָרִיב אִתְּכֶם נְאֻם ה' וְאֶת בְּנֵי בְנֵיכֶם אָרִיב.</p>"],[9514012296,"<p>וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לַאֲפָקָא לוֹן מִגָּלוּתָא, הֲדָא הוּא דִכְתִיב, (זכריה ט) גִּילִי מְאֹד בַּת צִיּוֹן הָרִיעִי בַּת יְרוּשָׁלַיִם הִנֵּה מַלְכֵּךְ יָבֹא לָךְ צַדִּי\"ק וְנוֹשָׁע הוּא.</p>"],[9514012297,"<p>וְאִי תֵימָא אַמַּאי אָתֵי מְשִׁיחָא מִיהוּדָה, מִיּוֹסֵף מִבָּעֵי לֵיהּ. אֶלָּא דְּתַרְוַיְהוּ יֵיתוֹן, וּבְגִין דּקוּדְשָׁא בְּרִיךְ הוּא לָא מְקַפֵּחַ שְׂכַר כָּל בְּרִיָה, יְהַב מַלְכוּתָא לְדָוִד, בְּגִין דְּהֲוָה עֲשִׂירָאָה לַצַּדִּיקִים, וּשְׁבִיעָאָה דְּאַחִים. וְהָכֵי הוּא מַלְכוּתָא דְאַרְעָא, כְּעֵין מַלְכוּתָא דִּרְקִיעָא.</p>"],[9514012298,"<p>(שמות י״ז:ט׳) וַיֹּאמֶר משֶׁה אֶל יְהוֹשֻׁעַ בְּחַר לָנוּ אֲנָשִׁים וְצֵא הִלָּחֵם וְגו', מַאי טַעְמָא יְהוֹשֻׁעַ אַגַּח קְרָבָא וְלָא מִן שְׁאָר עַמָּא. אֶלָּא בְּגִין דַּעֲמָלֵק אָתָא עֲלַיְיהוּ, עַל הַהוּא חוֹבָא דְּשַׁבַּתָּא דְּלָא נָטְרִין לֵיהּ, כְּמָה דְאִתְעָרוּ חֲכָמִים זִכְרוֹנָם לִבְרָכָה, אִלְמָלֵי נָטְרוּ יִשְׂרָאֵל שַׁבַּתָּא קַמָּא, לָא שָׁלְטָא בְּהוּ אוּמָּה וְלָשׁוֹן. מַה כְּתִיב (שם טז) וַיְהִי בַּיּוֹם הַשְּׁבִיעִי יָצְאוּ מִן הָעָם לִלְקֹט וְלֹא מָצָאוּ, וּכְתִיב וַיָּבֹא עֲמָלֵק.</p>"],[9514012299,"<p>וְתָּא חֲזֵי רָזָא דְמִלָּה, כַּד פַּקֵּיד לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל בְּמָרָה עַל שַׁבַּתָּא, בְּגִין דְּאַתְיָא מִדַּת דִּינָא לְקַטְרְגָא עַל הַהוּא חוֹבָא דְּצַדִּיק דְּזַבִּינוּ לֵיהּ, דְּאִיהוּ לָקֳבֵיל יוֹמָא דְשַׁבַּתָּא, וְאִינוּן אַפִּיקוּ לֵיהּ לְחוֹל, אֲמַר קוּדְשָׁא בְּרִיךְ הוּא, הָא אִית לוֹן רְפוּאָה לְהַהוּא חוֹבָה, אִי אִינוּן נָטְרִין לְיוֹמָא דְשַׁבַּתָּא, דְּאִיהוּ לָקֳבֵיל צַדִּיק חַי הָעוֹלָמִים. וְהַיְינוּ דִּכְתִיב (שם טו) וַיּוֹרֵהוּ ה' עֵץ. עֵץ חַיִּים, דְּיִנְטְרוּן יוֹמָא דְשַׁבַּתָּא. וְאִינוּן אֲחִילוּ לֵיהּ, כְּדֵין וַיָּבֹא עֲמָלֵק.</p>"],[9514012300,"<p>בְּהַהִיא שַׁעֲתָא, אָמַר לֵיהּ משֶׁה לִיהוֹשֻׁעַ, פּוֹק אַגַּח קְרָבָא בַּעֲמָלֵק, דְּהָא לָךְ חַזְיָא, בְּגִין דְּאַתְּ בַּר בְּרֵיהּ דְּהַהוּא צַדִּיק, וְאִיהוּ בְּהַהוּא חוֹבָא אָתֵי עֲלָן. וְאִי לָא אִשְׁתְּכַח מְקַטְרְגָא לֵיהּ לַעֲמָלֵק, מֵחוּלָקֵיהּ וּמִבְּנוֹי דְּהַהוּא צַדִּיק, לֵית מַאן דְּיָכֵיל לֵיהּ, כְּדֵין עֲבַד יְהוֹשֻׁעַ כְּמָא דַּאֲמַר משֶׁה.</p>"],[9514012301,"<p>וְתָּא חֲזֵי, דִּבְגִין הַהוּא חוֹבָא אָתָא עֲלַיְיהוּ, דְּאַרַע לוֹן לְאִינוּן דַּהֲווֹ מִבָּתַר עֲנָנָא, וּנְסֵיב מִינַיְיהוּ הַאי בְּרִית קַדִּישָׁא, וּזְרֵיק לֵיהּ כְּלַפֵּי עֵילָא. וְאִי לָאו דְּאִינוּן חָאבוּ בֵיהּ, לָא הֲוָה לֵיהּ סִיַּיעְתָּא מִלְּעֵילָא לְמֵיעְבַּד הָכֵי. אֶלָּא בְּגִין לְאַחֲזָאָה לוֹן, דְּיִשְׁתְּמוֹדְעוּן חוֹבֵיהוֹן דְּחָבוּ בְּהַהוּא צַדִּיק, דְּנָטַר הַאי בְּרִית, וְהַשְׁתָּא אֲחִילוּ שַׁבַּתָּא דְּאִיהוּ לְקִבְלֵיהּ, דְּאִיהִי קָאי לַאֲגָנָא עֲלַיְיהוּ מִקַּמֵּי מִדַּת דִּינָא.</p>"],[9514012302,"<p>תָּא חֲזֵי מַה כְּתִיב, (שם) וַיִּסְעוּ מִמָּרָה וַיָּבֹאוּ אֵילִמָה וְשָׁם שְׁתֵּים עֶשְׂרֵה עֵינֹת מַיִם וְגו'. מַהוּ אֵילִמָה, אֶלָּא דְּתָבוּ לְפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְקַבְּלָא מִלּוֹי בְּלִבָּא שְׁלִים, בְּגִין כָּךְ אֵלִ\"ימָ\"ה.</p>"],[9514012303,"<p>וְהָא אוֹקְמוּהָ, דְּהַהִיא אַתְרָא הֲוָה מְשׁוּבָּח בְּמַיָא, מִכָּל אַתְרִין דְּעָלְמָא, דְּהָא אוֹרַיְיתָא שֶׁבִּכְתָב תַּמָּן הוּא, וְתַמָּן תְּרֵין עֲשַׂר מַבּוּעִין, וְשִׁבְעִין דְּקָלִין. וְכוֹלָּא בְּרָזָא דִּמְהֵימְנוּתָא, דְּהָא כָּלְהוֹ ע' סַנְהֶדְּרִין מֵהַהוּא אַתְרָא מִתְזָנִין, וּמִתְבָּרְכִין מֵאִינוּן מַיִּין עִילָאִין בְּסִימָאן.</p>"],[9514012304,"<p>זַכָאָה מַאן דְּזָכֵי לְהַנְהוּ מַיָיא לְאִתְבָּרְכָא מִנַּיְיהוּ. וְיִשְׂרָאֵל קַדִּישִׁין שָׁרָאן תַּמָּן, וּמְחַבְּרִין אִינוּן מַיִין עִילָּאִין בְּאִינוּן תְּרֵין עֲשַׂר מַבּוּעִין תַּתָּאִין. וְאִי אִינוּן קִלְקְלוּ בְּקַדְמִיתָא, וְחָבוּ לְגַבֵּי הַהוּא צַדִּיק, הָא אַדְבְּקוּ לֵיהּ בְּאַתְרֵיהּ, וּמִתְּזָן עַל יָדֵיהּ עָלְמָא. וְשִׁבְעִים תְּמָרִים אִתְּזֵינָן מֵהַהוּא תָּמָר, (שיר השירים ז׳:ח׳) זֹאת קוֹמָתֵךְ דָּמְתָה לְתָמָר. וְאִינוּן תְּרֵין עֲשַׂר מַבּוּעִין, לָקֳבֵיל תְּרֵין עֲשַׂר שְׁבָטִין, סָחֲרִין לְהַהוּא אַתְרָא קַדִּישָׁא.</p>"],[9514012305,"<p>וַהֲווּ יִשְׂרָאֵל עָסְקִין בְּאוּלְפַן אוֹרַיְיתָא, דְּאוֹלִיפוּ מִמָּרָה. וְאִתְחַבַּר עִמַּיְיהוּ הַהוּא בְּרִית קַדִּישָׁא, וְאִתְפְּרַשׁ חִוְיָא עֲקִימָא מֵהַהוּא בְּאֵר מַיִם, דְּהֲוָה מְמָרֵר לְאִינוּן מַיִין. וּמַאן הֲוָה גָּרִים חוֹבַיְיהוּ עַד הַשְׁתָּא.</p>"],[9514012306,"<p>אֲבָל הַשְׁתָּא, כֵּיוָן דְּאַהֲדָרוּ בִּתְיוּבְתָּא לְמָארֵיהוֹן, וְקוּדְשָׁא בְּרִיךְ הוּא אוֹלִיף לוֹן אוֹרְחֵי דְּהַהוּא אִילָנָא דְחַיֵּי, הֲדָא הוּא דִכְתִיב, (שמות ט״ו:כ״ה) וַיּוֹרֵהוּ ה' עֵץ, דָּא תוֹרָה שֶׁבִּכְתָב. וַיַּשְׁלֵךְ אֶל הַמָּיִם, דָּא תוֹרָה שֶׁבְּעַל פֶּה. וּמַאי וַיַּשְׁלֵךְ, אֶלָּא יֵ\"שׁ לָ\"ךְ, יֵ\"שׁ, דָּא עָלְמָא דְּאָתֵי. הֲדָא הוּא דִכְתִיב, (משלי ח׳:כ״א) לְהַנְחִיל אוֹהֲבַי יֵשׁ. לָ\"ךְ, דָּא אִימָּא עִילָּאָה, חַמְשִׁין תַרְעִין דְּאִתְדְּבַק בֵּיהּ. כְּדֵין בְּסִימוּ מַיָא, וּנְחַת טַלָּא עִילָּאָה מֵעַתִּיקָא קַדִּישָׁא, וְאִתְמְלֵי חֲקַל תַּפּוּחִין.</p>"],[9514012307,"<p>מָאן גָּרַם כָּל דָּא, אֵלִ\"י מָ\"ה, תְּיוּבְתָּא דְּיִשְׂרָאֵל לְמָארֵיהוֹן. וּכְדֵין הֲוָה לְהוֹן רְשׁוּ, לְמִשְׁרֵי עַל הַנְהוּ מַיָּא. הֲדָא הוּא דִכְתִיב, (שמות ט״ו:כ״ז) וַיַּחֲנוּ שָׁם עַל הַמָּיִם. מַאי וַיַּחֲנוּ שָׁם, אֶלָּא סַמָּא דְחַיֵּי שַׁרְיָא בְּאִינוּן מַיִין, בְּגִין כָּךְ וַיַּחֲנוּ שָׁם עַל הַמָּיִם. מִהְרָשׁ הַנֶּעֱלָם</p>"],[9514012308,"<p>(שמות טז) וּמַטְךָ אֲשֶׁר הִכִּיתָ בּוֹ אֶת הַיְאֹר קַח בְּיָדְךָ וְהָלָכְתָּ. תַּנְיָא, אָמַר רִבִּי יוֹסֵי, גָּלֵיף הֲוָה חוּטְרָא מִתְּרֵין סִטְרִין, בִּשְׁמָא קַדִּישָׁא. חַד סִטְרָא דְרַחֲמֵי וְדִינָא בְּאַתְוָון גְּלִיפִין. וְחַד סְטַר דִּינָא בְּדִינָא, נָחָשׁ עֲלֵי צוּר.</p>"],[9514012309,"<p>תָּא חֲזֵי, כְּתִיב (שם יד) וְאַתָּה הָרֵם אֶת מַטְךָ וּנְטֵה אֶת יָדְךָ עַל הַיָּם. מַאי וּנְטֵה. כְּלוֹמַר, וּנְטֵה בְּחַד גִּיסָא, דִּגְלִיפָא בְּרַחֲמֵי וְדִינָא. וּכְתִיב וַיֵּט משֶׁה אֶת יָדוֹ, וְלָא כְתִיב וַיִּשְׁלַח אֶת יָדוֹ, כְּלוֹמַר, אַסְטֵי מֵחַד גִּיסָא.</p>"],[9514012310,"<p>וְאִי תֵימָא, דְּגָלֵיף הֲוָה מִקַּדְמַת דְּנָא נָחָשׁ עֲלֵי צוּר. אֶלָּא בְּאַסְנָא אִתְגְּלֵיף דִּכְתִיב (שם ד) וַיַּשְׁלִכֵהוּ אַרְצָה וַיְהִי לְנָחָשׁ. בְּהַהִיא שַׁעֲתָא אִתְגְּלֵיף נָחָשׁ עֲלֵי צוּר.</p>"],[9514012311,"<p>וְתָּא חֲזֵי אָמַר רִבִּי יְהוּדָה, בָּעָא קוּדְשָׁא בְּרִיךְ הוּא דִּשְׁמוֹי דַּהֲווֹ גְּלִיפִין בְּחוּטְרָא יַעֲבֵיד אָתָאן. וְתַנְיָא, תְּרֵין אָתִין אִתְעֲבִידוּ בְּיַמָּא, בְּהַהוּא סְטַר דְּסָטָא משֶׁה בְּרַחֲמֵי וְדִינָא. בָּזַע יַמָּא לְיִשְׂרָאֵל בְּי\"ב שְׁבִילִין, וְאָתֵיב בְּדִינָא עַל מִצְרָאֵי, וְאַטְבַּע לוֹן בִּתְהוֹמָא. הֲדָא הוּא דִכְתִיב, (שם טו) וַיָּשֶׁב ה' עֲלֵיהֶם אֶת מֵי הַיָּם.</p>"],[9514012312,"<p>בְּהַהִיא שַׁעֲתָא, בָּעֵי לַאֲפָקָא מַיָא, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, משֶׁה, אַסְטֵי חוּטְרָא מִגִּיסָא אָחֳרָא. דִּתְרֵין אָתָאן אִתְעֲבִידוּ בֵּיהּ. כְּמָא דְּאִתְעֲבֵיד מִסִּטְרָא אָחֳרָא. חַד אָת הָכָא, וְחַד אָת בִּמְרִיבָה. אֲבָל הַשְׁתָּא, (שם יז) וְהִכִּיתָ בַּצּוּר. מַאי צוּר. בְּהַאי צוּר דְּסָלֵיק נָחָשׁ.</p>"],[9514012313,"<p>לְזִמְנָא אָחֳרָא אָמַר רִבִּי אֶלְעָזָר, מַאי דִכְתִיב, (במדבר כ׳:ח׳) קַח אֶת הַמַּטֶה וְהַקְהֵל אֶת הָעֵדָה אַתָּה וְאַהֲרֹן אָחִיךָ וְדִבַּרְתֶּם. מַהוּ וְדִבַּרְתֶּם, אָמַר רִבִּי אֶלְעָזָר, מַנֵּי לֵיהּ עֲלֵי נָחָשׁ. דְּהָא אִתְעֲבֵיד בַּצּוּר, הַשְׁתָּא בָּעֵי דְּיִתְעַבֵּיד בַּנָּחָשׁ. לְאַשְׁלָמָא שְׁמוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּאִלֵּין אַתְוָון.</p>"],[9514012314,"<p>מַשְׁמַע דִּכְתִיב וְדִבַּרְתֶּם אֶל הַסֶּלַע. וּכְתִיב (שם כא) וַיְדַבֵּר הָעָם בֵּאלֹהִים וּבְמשֶׁה. מַה כְּתִיב בַּתְרֵיהּ, (שם) וַיְשַׁלַּח ה' בָּעָם אֵת הַנְּחָשִׁים הַשְּׂרָפִים. מַה נָּחָשׁ חֵילֵיהּ בְּפוּמֵיהּ, אוּף הָכָא בְּפוּמָא.</p>"],[9514012315,"<p>וּמשֶׁה לָא עָבִיד הָכֵי, אֶלָּא הִכָּה, וְלֹא אַשְׁלֵים שְׁמָא, אֶלָּא חָזַר כְּקַדְמֵיתָא בִּשְׁמָא דְּצוּר, וּשְׁבַק דְּנָחָשׁ, הֲדָא הוּא דִכְתִיב וַיַּךְ, וְלָא כְתִיב וַיְדַבֵּר, כְּמָה דְּאִתְפַּקַּד וְדִבַּרְתֶּם. דְּתָנִינָן, צוּר לְמֶעְבַּד, וְנָחָשׁ לְמַלָּלָא. וּכְתִיב (שם) וַיַּךְ אֶת הַסֶּלַע בְּמַטֵהוּ פַּעֲמָיִם, חַד דִּלְשֶׁעָבַר, וְחַד דְּהַשְׁתָּא.</p>"],[9514012316,"<p>תַּנְיָא, אָמַר רִבִּי אֶלְעָזָר בַּהּ שַׁעֲתָא אִשְׁתָּאַר שְׁמָא. כְּלוֹמַר, דְּלָא אִשְׁתְּלֵים בְּהַהוּא אָת, דִּשְׁבַק משֶׁה נָחָשׁ, וְלָא אִשְׁתְּלֵים כָּל שְׁמָא.</p>"],[9514012317,"<p>דְּהָא בְּחַד גִּיסָא אִשְׁתְּלֵים בְּיַמָּא. מִגִּיסָא אָחֳרָא שָׁרֵי בַּצּוּר, וְלָא אִשְׁתְּלֵים בַּנָּחָשׁ. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, עֲבָדַת דְּשָׁרֵי שְׁמִי, וְלָא אִשְׁתְּלֵים לְמֶעְבַּד אָתִין. אוּף אַתְּ שָׁרֵית, וְלָא תִשְׁתְּלֵים. לָכֵן לֹא תָבִיאוּ אֶת בְּנֵי יִשְׂרָאֵל. שָׁרֵית לַאֲפָקָא לוֹן, וְלָא תַשְׁלֵים לְאַעֲלָאָה לְהוֹן לְאַרְעָא, לָכֵן לֹא תָבִיאוּ.</p>"],[9514012318,"<p>אָמַר רִבִּי אֶלְעָזָר, יָדַע לִבָּא דְּמשֶׁה בְּקַדְמִיתָא דְּדָחֵיל, כַּד חָמָא נָחָשׁ. דִּכְתִיב (שמות ד׳:ג׳) וַיָּנָס משֶׁה מִפָּנָיו. לִבָּא חָמָא, וְלָא יָדַע.</p>"],[9514012319,"<p>אָמַר רִבִּי אֶלְעָזָר, כְּתִיב (במדבר כא) וַיַּעַשׂ משֶׁה נְחַשׁ נְחשֶׁת וַיְשִׂימֵהוּ עַל הַנֵּס. עַל נֵס לָא כְתִיב, אֶלָא עַל הַנֵּס, בָּעָא לְאִתְקַן וּלְהַשְּׁלֵים מַה דַּחֲסַר. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, משֶׁה, כְּתִיב (שם כז) לְהַקְדִּישֵׁנִי בַּמַּיִם, בַּמַּיִם וְלָא בְּדָבָר אַחֵר. כְּשֵׁם שֶׁהִתְחַלְתִּי בְּמַיִם, בָּעֵינָא דְּיִשְׁתְּלֵים בִּשְׁמֵי הַנֵּס בַּמַּיִם. אָמַר רִבִּי אֶלְעָזָר אַתְרָא דַּחֲסַר לָא שְׁלֵים, אֲבָל אִתְעֲבֵיד נִסָּא הָכָא.</p>"],[9514012320,"<p>אָמַר רִבִּי יְהוֹשֻׁעַ, כְּתִיב (שם כא) עֲשֵׂה לְךָ שָׂרָף. עֲשֵׂה לְךָ, לְתוֹעַלְתְּךָ. עֲשֵׂה לְךָ, תַּקֵן מִמַּה דְּחָסַרְתָּ. עִם כָּל זֶה לֹא תִּקֵּן אֶלָּא רְאִיָּה, שֶׁהָיוּ רוֹאִין בַּנָּחָשׁ וְחַיִּין, אֲבָל לֹא נִתְקַדֵּשׁ שְׁמָא בַּמַּיִם, וְנִשְׁאָר חָסֵר מֵהַשְּׁאָר.</p>"],[9514012321,"<p>וְתִקַנְתָּ בָּרְאִיָּה, (שם כז) עֲלֵה אֶל הַר הָעֲבָרִים הַזֶּה וּרְאֵה וְגו', וְרָאִיתָ אוֹתָהּ וְנֶאֱסַפְתָּ אֶל עַמֶּיךָ, (דברים לד) הֶרְאִיתִיךָ בְּעֵינֶיךָ וְשָׁמָּה לֹא תַעֲבֹר. תָּא חֲזֵי, דְּעוֹנְשׁוֹ הֲוָה דְּאֲפִילּוּ רְאִיָּה לָא תִקֵּן כִּדְחָזֵי, כֵּיוָן דַּעֲבַד לֵיהּ רְאִיָּה, בְּהַאי אַשְׁלֵים לֵיהּ רְאִיָּה, אֲבָל לָא אַשְׁלֵים שְׁמֵיהּ בְּמַיָא, כְּמוֹ כָּל שְׁאָר שְׁמָא.</p>"],[9514012322,"<p>אָמַר רִבִּי יִצְחָק, בְּשָׁעָה שֶׁאָמַר קוּדְשָׁא בְּרִיךְ הוּא לָכֵן לֹא תָבִיאוּ. אָמַר משֶׁה, הַאי חִוְויָא לְתַקָּלָא דְּעָלְמָא הֲוָה. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לָאו הָכֵי, דִּינָא הֲוָה לְחַיָּיבַיָא, וְחַיִּין לְמָארֵי קְשׁוֹט. דִּכְתִיב (במדבר כ״א:ח׳) וְרָאָה אוֹתוֹ וָחָי. בְּאוֹתָהּ שָׁעָה יָדַע משֶׁה דְרָכָיו, וְהִצְדִּיק עָלָיו אֶת הַדִּין.</p>"],[9514012323,"<p>פָּתַח וְאָמַר, (דברים ל״ב:ד׳) הַצּוּר תָּמִים פָּעֳלוֹ, דָּא הוּא צוּר דְּקָא אַמְרִינָן. אֵל אֱמוּנָה וְאֵין עָוֶל, דִּכְתִיב וְרָאָה אוֹתוֹ וָחָי. וּכְתִיב (תהילים י״ח:ל״א) הָאֵל תָּמִים דַּרְכּוֹ.</p>"],[9514012324,"<p>אָמַר רִבִּי חִיָּיא, וְהָא תָּנִינָן אֵל גְּזֵרַת רַחֲמֵי. כְּמָה דְאַתְּ אָמֵר (במדבר כג) אֵל מוֹצִיאָם מִמִּצְרַיִם. (שמות לד) אֵל רַחוּם וְחַנּוּן. אָמַר לֵיהּ לָאו הָכֵי, דְּתָנִינָן, דְּשַׁלֵּיט רַחֲמֵי עַל דִּינָא. אֵל בִּלְחוֹדוֹי יְכוֹלֶת הוּא, וּרְשׁוּתָא הוּא דִּילֵיהּ. מַאי יְכוֹלֶת, שׁוּלְטָנוּתָא. כְּלוֹמַר, שָׁלְטָנוּתָא דְּאֵל, אִתְגַּבַּר גְּזֵרָה דִּילֵיהּ. כְּמָה דְאַתְּ אָמֵר (בראשית לא) יֵשׁ לְאֵל יָדִי, רְשׁוּתָא דִילֵיהּ יְכוֹלֶת דְּעֵינָא בִישָׁא. אֲמַר לֵיהּ וְהָא כְתִיב (דברים י) הָאֵל הַגָּדוֹל הַגִּבּוֹר. אֵל גָּדוֹל נַצְחָא, אֵל בִּלְחוֹדוֹי נַצְחָא.</p>"],[9514012325,"<p>נֶהְדַּר לְמִילֵי קַדְמָאי, וּכְתִיב (שם לב) הַצּוּר תָּמִים פָּעֳלוֹ כִּי כָל דְּרָכָיו מִשְׁפָּט, הָא צוּר. אֵל אֱמוּנָה וְאֵין עָוֶל וְגו', הָא נָחָשׁ עֲלֵי צוּר. וּכְתִיב (איוב ח׳:ג׳) הַאֵל יְעַוֵּת מִשְׁפָּט. מִשּׁוּם דְּאוֹרְחֵיהּ דְּנָחָשׁ לְאַסְטָאָה אוֹרְחֵיהּ, לְכָךְ כְּתִיב וְאֵין עָוֶל. הַאֵל יְעַוֵּת מִשְׁפָּט חַס וְשָׁלוֹם. אָמַר רִבִּי אֶלְעָזָר, הַיְינוּ דִּכְתִיב (תהלים פה) אֶשְׁמְעָה מַה יְּדַבֵּר הָאֵל ה'.</p>"],[9514012326,"<p>(שמות ד׳:ד׳) וַיִּשְׁלַח יָדוֹ וַיַּחֲזֶק בּוֹ וַיְהִי לְמַטֶה בְּכַפּוֹ. כְּמָה דְאַתְּ אָמֵר מַטֶה כְּלַפֵּי חֶסֶד. אָמַר רִבִּי יוֹסֵי שְׁנֵי מַטוֹת הָיוּ, אֶחָד שֶׁל משֶׁה, וְאֶחָד שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. מַשְׁמַע דִּכְתִיב (שם יז) וּמַטֶה הָאֱלֹהִים.</p>"],[9514012327,"<p>דְּתָנִינָן, בְּשַׁעֲתָא שֶׁהָיָה נוֹטֵל משֶׁה הַמַּטֶה, הָיָה כְּאִלּוּ הָיָה בִּרְשׁוּתוֹ וּבִיכָלְתּוֹ. הֲדָא הוּא דִכְתִיב, (שמות ד) וַיִּקַּח משֶׁה אֶת מַטֶה הָאֱלֹהִים בְּיָדוֹ. וַדַּאי שֶׁבְּיָדוֹ לָקַח, אֶלָּא מַהוּ בְּיָדוֹ, בִּרְשׁוּתוֹ, כְּאִלּוּ הוּא שֶׁלּוֹ.</p>"],[9514012328,"<p>וְאָמַר רִבִּי יוֹסֵי, בִּרְשׁוּתוֹ שֶׁל משֶׁה הָיָה, עַד שֶׁהוּקַם הַמִּשְׁכָּן. כֵּיוָן שֶׁהוּקַם הַמִּשְׁכָּן, הֶחֱזִיר הַמַּטֶה לִפְנֵי הָעֵדוּת. וּמִשָּׁם הָיָה נוֹטְלוֹ לַעֲשׂוֹת בּוֹ נִסִּים. הֲדָא הוּא דִכְתִיב, (שמות ד) וַיִּקַּח משֶׁה אֶת הַמַּטֶה מִלִּפְנֵי ה', כֵּיוָן שֶׁלָּקְחוֹ הֲרֵי הוּא בִּרְשׁוּתוֹ, וּכְשֶׁלּוֹ הָיָה.</p>"],[9514012329,"<p>אָמַר רִבִּי יְהוֹשֻׁעַ, אוֹתוֹ הַמַּטֶה שֶׁל סְנַפִּירִינוֹן הָיָה, וּמִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית אִתְבְּרֵי. כְּמָה דְתָנִינָן, וְהַמִּכְתָּב וְהַמַּטֶה. רַבִּי יְהוּדָה אוֹמֵר, שֶׁל עֵץ הָיָה.</p>"],[9514012330,"<p>מַאן דַּאֲמַר שֶׁל סְנַפִּירִינוֹן הָיָה, דִּכְתִיב (יחזקאל א) כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא, וּכְתִיב מַטֵה הָאֱלֹהִים. וּמַאן דַּאֲמַר עֵץ הָיָה, דִּכְתִיב (שמות טו) וַיּוֹרֵהוּ ה' עֵץ וַיַּשְׁלֵךְ אֶל הַמָּיִם וְגו'.</p>"],[9514012331,"<p>שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ. אָמַר הַקָדוֹשׁ בָּרוּךְ הוּא, מִכָּאן וּלְהָלְאָה הֲרֵי חֹק וּמִשְׁפָּט לַעֲשׂוֹת נִסִּים. חֹק וּמִשְׁפָּט, דִּכְתִיב (משלי ל) נָחָשׁ עֲלֵי צוּר. וְשָׁם נִסָּהוּ, מִשּׁוּם דִּכְתִיב וַיִּמְתְּקוּ הַמָּיִם. דָּבָר אַחֵר, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מִכָּאן וּלְהָלְאָה חֹק וּמִשְׁפָּט, שֶׁלֹּא יְהֵא נִקְדָּשׁ אֶלָּא בַּמַּיִם שֶׁנִּמְתְּקוּ.</p>"],[9514012332,"<p>אָמַר רִבִּי יְהוּדָה, כְּתִיב כִּי מָרִים הֵם, מִכָּאן שָׁנִינוּ, יֵשׁ מַיִם עֲכוּרִים, וְיֵשׁ מַיִם צְלוּלִים, וְיֵשׁ מַיִם מְתוּקִים, וְיֵשׁ מַיִם מָרִים. וַיִּצְעַק אֶל ה', לָמָּה צָעַק, מִכָּאן שֶׁהָיָה בְּצַעַר בְּאוֹתָהּ שָׁעָה. אָמַר לֵיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, משֶׁה, הַנָּחָשׁ שֶׁנֶּהְפַּךְ בַּסְּנֶה, עַכְשָׁיו אִצְטְרִיךְ לְחָקְקָא לֵיהּ בַּצּוּר. וְתַרְוַיְיהוּ עָמְדוּ עַל הַמַּיִם הַמָּרִים. וּבְאוֹתָהּ שָׁעָה נִתְחַקֵּק צוּר בַּנָּחָשׁ שֶׁהָיָה בּוֹ קוֹדֶם, הֲדָא הוּא דִכְתִיב שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט.</p>"],[9514012333,"<p>כַד אָתָא רַבִּי אַבָּא, שְׁאִילוּ קַמֵּיהּ, אֲמַר לְהוֹ שַׁפִּיר קָאֲמַר ר' יְהוּדָה, וְהָכֵי הוּא. וַאֲנָא אִצְטְרִיךְ לְגַלָּאָה רָזָא דְמִלָּה, הָא חָזֵינָא דְּרַבִּי יְהוּדָה גָּלֵי לָה.</p>"],[9514012334,"<p>אֶלָּא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמשֶׁה, משֶׁה, הַשְׁתָּא בְּמִצְרַיִם הָיָה הַמַּטֶה שֶׁל אַהֲרֹן לִדְחוֹת הַקַּשׁ הַשּׁוֹלֵט עַל יִשְׂרָאֵל בְּמִצְרַיִם, אֲבָל כְּשֶׁיָּצְאוּ מִמִּצְרַיִם, כַּמָּה מְקַטְרְגִים מְזוּמָנִים עַל יִשְׂרָאֵל, לִדְחוֹתָם בַּיָּם, כַּמָּה מַיִם מָרִים נִזְדַּמְּנוּ אֶצְלָם. כַּמָּה מַיִם רָעִים יְקַטְרְגוּ בָהֶם.</p>"],[9514012335,"<p>בָּאוּ לַיָּם, בָּא רַהַב שָׂרוֹ שֶׁל מִצְרַיִם וְשֶׁל יַם. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, (שמות י״ד:ט״ז) משֶׁה הָרֵם אֶת מַטְךָ וּנְטֵה אֶת יָדְךָ. כֵּיוָן דְּאָמַר הָרֵם אֶת מַטְךָ, מַהוּ וּנְטֵה אֶת יָדְךָ. אֶלָּא הָרֵם אֶת מַטְךָ נֶגֶד שָׂרוֹ שֶׁל יָם. בָּאוּ לְמָרָה, כַּמָּה מַיִם מָרִים נִזְדַּמְּנוּ אֶצְלָם, וְנִצְטָעֵר משֶׁה וְצָעַק, הֲדָא הוּא דִכְתִיב וַיִּצְעַק אֶל ה'.</p>"],[9514012336,"<p>אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, משֶׁה, הֲרֵי לְךָ עֵצָה בָּזֶה, הַשְּׁלֵךְ הַמַּטֶה אֶצְלָם, וְיִתְחַקֵּק נָחָשׁ עֲלֵי צוּר שְׁנֵיהֶם בְּיַחַד, וְיִנָּצְלוּ. הֲדָא הוּא דִכְתִיב, וַיּוֹרֵהוּ ה' עֵץ. כמדָּבָר אַחֵר, (קהלת יא) מָקוֹם שֶׁיִּפּוֹל הָעֵץ, שֶׁהוּא עֵצָה. וַיַּשְׁלֵךְ אֶל הַמָּיִם. וּכְתִיב שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט, נָחָשׁ עֲלֵי צוּר. וְשָׁם נִסָּהוּ, עִטְרָהוּ בְּנִסִּים. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מִכָּאן וּלְהָלְאָה, הֲרֵי לְךָ שֶׁיַּעֲמוֹד אֵצֶל הַמַּיִם, הֲרֵי לְךָ שֶׁיִּתְקַדֵּשׁ שְׁמִי בַּמַּיִם.</p>"],[9514012337,"<p>כְשֶׁבָּאוּ לְאֵלִים, בָּאוּ הַמַּיִם לְקַטְרֵג עֲלֵיהֶם, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, משֶׁה, בַּמָּקוֹם הַזֶּה אֵין צָרִיךְ מַטֶה, הֲרֵי יַעֲקֹב שֶׁהוּא הָאִילָן בְּשִׁבְעִים נֶפֶשׁ, וְהוּא שִׁבְעִים תְּמָרִים. וּשְׁתֵּים עֶשְׂרֵה עֵינוֹת מָיִם, שְׁנֵים עָשָׂר שְׁבָטִים. כְּשִׁבְעִים עַמּוּדִים, וּשְׁנֵים עָשָׂר שְׁבָטִים, זְכוּתָם יָגֵן עֲלֵיכֶם, בַּמָּקוֹם הַזֶּה שֶׁנִּקְרָא אִילָן, וְהוּא אֵלִים. כְּמָה דְאַתְּ אָמֵר, (ישעיהו א׳:כ״ט) כִּי יֵבשׁוּ מֵאֵילִים אֲשֶׁר חֲמַדְתֶּם.</p>"],[9514012338,"<p>מִיָּד וַיַּחֲנוּ שָׁם עַל הַמָּיִם, מַשְׁמַע דִּכְתִיב עַל הַמָּיִם, וּמַשְׁמַע דִּכְתִיב, שָׁם שָׂם לוֹ, וְלֹא בְּמָקוֹם אַחֵר. וְשָׁם שָׁלְטוּ בְּנֵי יִשְׂרָאֵל עַל הַמָּיִם, וְלֹא הוּצְרַךְ הַמַּטֶה. מִכָּאן וּלְהָלְאָה אִצְטְרִיךְ הַמַּטֶה בַּנָּחָשׁ עֲלֵי צוּר, אֵצֶל הַמָּיִם.</p>"],[9514012339,"<p>בָּאוּ לְחוֹרֵב, בָּאוּ הַמַּיִם לְקַטְרֵג, אָמַר לֵיהּ הַקָדוֹשׁ בָּרוּךְ הוּא, וְהִכִּיתָ בַצוּר, הַמַּטֶה אִצְטְרִיךְ הָכָא, וְהִכִּיתָ לְאֵלּוּ בְּאוֹתוֹ צוּר, וְלֹא בַּנָּחָשׁ. אָמַר משֶׁה, יַתִּיר אִצְטְרִיךְ הָכָא, אֲנָא חָמֵי מַיִם דְּבָעוֹ לְשָׁטְפָא. אַמַּאי, הִנְנִי עוֹמֵד לְפָנֶיךָ שָׁם עַל הַצּוּר וְהִכִּיתָ בַצוּר.</p>"],[9514012340,"<p>אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמשֶׁה, עֲדַיִין בִּמְרִיבָה עֲתִידִים הַמַּיִם לְקַטְרֵג יוֹתֵר, שֶׁהֵם מַיִם עֲכוּרִים רָעִים וּזֵדוֹנִים, וְיִזְדַּוְּוגוּ בָּהֶם בְּיִשְׂרָאֵל בְּגָלוּי לְעֵינֵיהוֹן, וּבְאוֹתָהּ שָׁעָה אִצְטְרִיךְ הַמַּטֶה, וְהַתֵּיר עֲלֵיהֶם הַנָּחָשׁ בְּגָלוּי לְעֵינֵיהֶם, וְיִתְקַדֵּשׁ שְׁמִי. הֲדָא הוּא דִכְתִיב, (במדבר כ״ז:י״ד) לְהַקְדִּישֵׁנִי בַּמַּיִם לְעֵינֵיהֶם. מַהוּ לְעֵינֵיהֶם. בְּגָלוּי. כְּדָבָר שֶׁנִּזְדַּוְּוגוּ בָּהֶם בְּגָלוּי.</p>"],[9514012341,"<p>תָּא חֲזֵי, הָכֵי חָמָא דָוִד, דִּכְתִיב (תהילים קכ״ד:ב׳) לוּלֵי ה' שֶׁהָיָה לָנוּ בְּקוּם עָלֵינוּ אָדָם, זֶה פַּרְעֹה. אֲזַי עָבַר עַל נַפְשֵׁנוּ הַמַּיִם הַזֵּדוֹנִים, כִּדְאַמְרִינָן. וּכְתִיב (שם) נַפְשֵׁנוּ כְּצִפּוֹר נִמְלְטָה מִפַּח יוֹקְשִׁים וְגו'.</p>"],[9514012342,"<p>אָמַר רִבִּי אַבָּא, מַה רָאָה משֶׁה בְּאוֹתָהּ שָׁעָה, שֶׁלֹּא עָשָׂה בַּנָּחָשׁ. אֶלָּא יִשְׂרָאֵל הָיוּ דּוֹחֲקִין לְמשֶׁה תְּנָה לָנוּ מַיִם, נִתְיָעֵץ משֶׁה וְאָמַר, קוּדְשָׁא בְּרִיךְ הוּא אָמַר לִי לַעֲמוֹד בַּנָּחָשׁ, וַאֲנָא חָמֵי דְּאֵין גְּזֵירָה לַנָּחָשׁ בַּמַּיִם, דְּאֵין יְכוֹלְתּוֹ אֶלָּא בְּעָפָר, דִּכְתִיב (בראשית ג׳:י״ד) וְעָפָר תֹּאכַל כָּל יְמֵי חַיֶּיךָ, מַשְׁמַע דְּעַפְרָא יֵיכוֹל וִישֵׁיצֵי כָּל יוֹמוֹי, אֲבָל בְּמַיָּא לָא. וְיִשְׂרָאֵל דָּחֲקִין לִי, וְאַף עַל גַּב דְּיַעֲבֵיד נִיסָּא, לָא יַעֲבֵיד בַּאֲתַר דָּא, אֶלָּא כַּד אִתְחַקַּק, אִתְחַקַּק בְּעַפְרָא, וְלָא בְּמַיָא. דִּכְתִיב (שמות ד׳:ג׳) וַיַּשְׁלִיכֵהוּ אַרְצָה וַיְהִי לְנָחָשׁ. וְצוּר בְּדָא אִתְחַקַּק, בְּמַיָא, בְּמָרָה, וּכְבָר עֲבַד נִיסָּא. טַב דְּאִעֲבֵיד בְּהַאי, דְּאִתְעֲבֵיד נִסָּא אָחֳרָא. מִיָּד וַיַּךְ אֶת הַסֶּלַע בְּמַטֵהוּ פַּעֲמַיִם, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, משֶׁה יַעַן לֹא הֶאֱמַנְתֶּם בִּי לְהַקְדִּישֵׁנִי, דַּחֲשַׁבְתּוּן דְּלָא יָכֵיל נָחָשׁ בַּמַּיִם, לָכֵן לֹא תָבִיאוּ. וּמַטְךָ אֲשֶׁר הִכִּיתָ בוֹ אֶת הַיְאוֹר כו' מַאי טַעְמָא מִשּׁוּם דִּמְחַקַּק בְּנִיסִּין הֲוָה וּשְׁמָא קַדִּישָׁא עִלָּאָה רְשִׁימָא בֵּיהּ.</p>"],[9514012343,"<p>(שמות כ׳:ב׳) אָנֹכִי ה' אֱלֹהֶיךָ, בְּהַאי פְּסוּקָא שָׁאַל רַבִּי יֵיסָא זְעִירָא דְּמִן חַבְרַיָיא מֵרִבִּי שִׁמְעוֹן בֶּן יוֹחָאי, וְאָמַר לֵיהּ, אִית לִי לְמִשְׁאַל שְׁאִילְתָּא חָדָא מִינָךְ, וּמְכַשְׁכְּשָׁא לִי בְּלִבָּאי, וַאֲנָא דָּחֵיל מִלְּמִשְׁאַל מִינָךְ. וַאֲמִינָא, אִי נִשְׁאַל, דָּחֵילְנָא דִּילְמָא אִיתְעָנֵשׁ. אִי לָא נִשְׁאַל, מְשַׁבְּשָׁא לִי בְּלִבָּאי. אֲמַר לֵיהּ רַבִּי שִׁמְעוֹן, אֵימָא.</p>"],[9514012344,"<p>אָמַר לֵיהּ הַאי דּקוּדְשָׁא בְּרִיךְ הוּא מַדְכַּר לְהוֹן לְיִשְׂרָאֵל בְּכָל אֲתַר וַאֲתַר, אָנֹכִי ה' אֱלֹהֶיךָ אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם. (ויקרא י״ט:ל״ו) אֲנִי ה' אֱלֹהֵיכֶם אֲשֶׁר הוֹצֵאתִי אֶתְכֶם מֵאֶרֶץ מִצְרַיִם. מַאי רְבוּתָא אוֹלִיף הָכָא. תְּנָאָה שְׁלִים הוּא, הֲדָא הוּא דַּאֲמַר לְאַבְרָהָם, (בראשית ט״ו:י״ג) כִּי גֵר יִהְיֶה זַרְעֲךָ בְּאֶרֶץ לֹא לָהֶם וְגו' וְאַחֲרֵי כֵן יֵצְאוּ בִּרְכוּשׁ גָּדוֹל. אִם כֵּן, לָמָּה לְאַדְכְּרָא לְהוֹן מִילְּתָא דָא בְּכָל אֲתַר וַאֲתַר.</p>"],[9514012345,"<p>אָמַר לֵיהּ תָּא חֲזֵי בְּרִי, קוּדְשָׁא בְּרִיךְ הוּא לָא אַתְנֵי עִם אַבְרָהָם, אֶלָּא דְּיַפֵּיק יַת יִשְׂרָאֵל מִן גָּלוּתָא דְמִצְרַיִם, וְלָא מִתְּחוֹת שִׁעְבּוּדָא דְּדַחֲלָא אָחֳרָא. דְּוַדַּאי יִשְׂרָאֵל כַּד הֲווֹ בְּמִצְרַיִם, אִסְתְּאָבוֹ וְאִתְטְנָפוֹ גַּרְמֵיהוֹן בְּכָל זִינֵי מְסָאֲבוּ, עַד דַּהֲווֹ שָׁרָאן תְּחוֹת אַרְבָּעִים וְתֵשַׁע חֵילֵי דִּמְסָאֲבוּתָא. וְקוּדְשָׁא בְּרִיךְ הוּא אַפֵּיק יַתְהוֹן מִתְּחוֹת פּוּלְחַן כָּל שְׁאָר חֵילִין.</p>"],[9514012346,"<p>וְעוֹד, דְּאָעֵיל יַתְהוֹן בְּמ\"ט תַּרְעֵי דְּסוּכְלְתָנוֹ לְקִבְלֵיהוֹן. מַה דְּלָא אַתְנֵי עִם אַבְרָהָם, אֶלָּא לַאֲפָקוּתְהוֹן מִמִּצְרַיִם, וְהוּא עָבִיד טִיבוּתֵיהּ וְחַסְדֵּיהּ עִמְּהוֹן.</p>"],[9514012347,"<p>וּבְּגִין כָּךְ תִּשְׁכַּח בְּאוֹרַיְיתָא, חַמְשִׁין זִמְנִין יְצִיאַת מִצְרַיִם, לְאַחֲזָאָה לְכָל בְּנֵי עָלְמָא, חַסְדָּא דַּעֲבַד קוּדְשָׁא בְּרִיךְ הוּא עִם יִשְׂרָאֵל, דְּאַפֵּיק יַתְהוֹן מֵאִינוּן חֵילִין דִּמְסָאֲבוּ, וְאָעֵיל לוֹן לְגוֹ חֵילִין דְּדַכְיוּ, דְּהַיְינוּ חַמְשִׁין תַּרְעִין דְּסוּכְלְתָנוֹ.</p>"],[9514012348,"<p>וְהָא אִיהוּ דַּאֲנַן מַנָּן לְהוֹ, מִיּוֹמָא טָבָא דְפִסְחָא. וַאֲנַן מַנָּן יוֹמֵי וּשְׁבוּעֵי, וְהָא אִיתְעָרוֹ חַבְרַיָיא, מִצְוָה לְמִמְנֵי יוֹמֵי, וּמִצְוָה לְמִימְנֵי שְׁבוּעֵי. כִּי בְּכָל יוֹמָא אַפֵּיק לָן מֵחֵילָא דִּמְסָאֲבוּ, וְאָעֵיל לָן בְּחֵילָא דְּדַכְיוּ.</p>"],[9514012349,"<p>(שמות י״ח:כ״א) וְאַתָּה תֶּחֱזֶה מִכָּל הָעָם, בְּשִׁית סִטְרִין: בְּשַׂעֲרָא דְעַל רֵישָׁא, דְּאִיהִי מִתְתַּקְנָא עַל אוּדְנִין. בְּמִצְחָא, בְּשִׁרְטוּטִין דְּמִצְחָא. בְּעַיְינִין, וּבִקְרִיצִין דְּעַל עַיְינִין. בְּאַנְפִּין, וּבִדְיוֹקְנָא דְּאַנְפִּין. בְּחוֹטְמָא, דְּאִיהִי מִתְתַּקְּנָא בְּאוֹרַח מֵישָׁר עַל פּוּמָא. בְּגוּפָא, בְּקוֹמָה דִילֵיהּ, וּבְשִׁיעוּרָא דִילֵיהּ לְכָל סְטַר, לְד' סִטְרִין וּלְעֵילָא וְתַתָּא. הַאי אִיהוּ תִּיקּוּנָא דְּאָדָם. וּלְזִמְנִין אִיתְקְרֵי אַרְיֵהּ, וּלְזִמְנִין אִיהוּ דְיוֹקְנָא דְּשׁוֹר, וּלְזִמְנִין דִּיוּקְנָא דְנְשֶׁר.</p>"],[9514012350,"<p>וּכְעָן צָרִיךְ לְפָרְשָׁא, כֵּיוָן דְּאִיהוּ יִיחוּד דְּקוּדְשָׁא בְּרִיךְ הוּא בִּסְפִירָן, אַמַּאי אִתְקְרִיאוּ בִּדְיוֹקְנָא דְאָדָם, וּבִדְיוֹקְנָא דְאַרְיֵה, וּבִדְיוֹקְנָא דְשׁוֹר, וּבִדְיוֹקְנָא דְנְשֶׁר.</p>"],[9514012351,"<p>אֶלָּא וַדַּאי בְּזִמְנָא דְּבָעֵי לְמֵיעְבַּד עֲבִידְתֵּיהּ, וּלְאַנְהָגָא לְיִשְׂרָאֵל דְּאִתְקְרִיאוּ בְּמַזָּלָא דְאָדָם, אִתְלַבַּשׁ בִּדְיוֹקְנָא דְהַהִיא חַיָּה דְּאִתְקְרִיאַת אָדָם, וְאִתְקְרֵי הוּא אָדָם. וּבְזִמְנָא דְּבָעֵי לְאַנְהָגָא לְיִשְׂרָאֵל לְאִינוּן דְּאִתְקְרִיאוּ בְּמַזָּלָא דְאַרְיֵה, אִתְלַבַּשׁ בִּדְיוֹקְנָא דְהַהִיא חַיָּה דְּאִתְקְרִיאַת אַרְיֵה. וְהָכֵי בְּגַוְונָא דָא בְּחַיָּה דְּאִתְקְרִיאַת שׁוֹר. וְכֵן בְּגַוְונָא דָא בְּחַיָּה דְּאִתְקְרִיאַת נֶשֶׁר. וּבְגַוְונָא דָא שְׁכִינְתֵּיהּ.</p>"],[9514012352,"<p>וּבְּגִין כָּךְ אִתְקְרֵי קוּדְשָׁא בְּרִיךְ הוּא בְּאִלֵּין שְׁמָהָן, וְכָל חֵילִין דִּילְהוֹן. לֵית אֲתַר וְלֵית בְּרִיָה בְּעָלְמָא, דְּלָא שַׁלִּיט שְׁמֵיהּ עֲלֵיהּ, וְאִתְקְרִיאוּ בִּשְׁמֵיהּ. כְּגַוְונָא דָא דִּיוּקְנָא דְאָדָם, י' שַׁרְיָיא בְּרֵישָׁא. ה' ה' בְּעֶשֶׂר אֶצְבְּעָן, ו' בְּגוּפָא. וּכְגַוְונָא דָא בְּנֶשֶׁר, י' עַל רֵישֵׁיהּ ה' ה' עַל גַּדְפוֹי. ו' עַל גּוּפֵיהּ. וְהָכֵי בְּכָל חַיָּה וְחַיָּה. וְכֵן בְּכָל מַלְאָךְ וּמַלְאָךְ.</p>"],[9514012353,"<p>וְלֵית נִימָא בְּרֵישָׁא דְּלָא שַׁרְיָיא בָּהֶם שֵׁם יהו\"ה. וְלֵית עִשְׂבָּא, דְּלָא שַׁרְיָא בֵּיהּ שֵׁם יהו\"ה. וְשׁוֹשַׁנָּה, בְּתַפּוּחַ דִּילֵיהּ שַׁרְיָיא י'. וּבְשַׁרְבִיט דִּילָהּ ו'. בְּחָמֵשׁ עָלִין דִּלְבַר, וְחָמֵשׁ דִּלְגַּו, שַׁרְיָיא ה\"ה. לְאַחֲזָאָה, דְּלֵית אֲפִילּוּ עִשְׂבָּא דְּלָא אִתְבְּרֵי בִּשְׁמָא דְּיהו\"ה. דְּלָא יֵימְרוּן דֵּאלוֹהַּ אָחֳרָא בְּרָא לוֹן.</p>"],[9514012354,"<p>לֵית בְּרִיָה בְּעִילָּאִין וְתַתָּאִין, דְּלָאו אִינוּן רְשִׁימִין בִּשְׁמֵיהּ, וְכֵן בִּשְׁכִינְתָּא בְּכָל חַד. וּבְגִין כָּךְ אִתְקְרִיאַת שְׁכִינְתָּא שׁוֹשַׁנָּה. וְאִתְקְרִיאַת נִשְׁרָא. פָּרָה אֲדֻמָּה אַיֶּלֶת. יוֹנָה. צִפּוֹר. לֵית בְּרִיָה דְּלָא אִתְקְרִיאַת בִּשְׁמֵיהּ, כַּד אִתְלַבְּשָׁא בֵּיהּ, לְמֵיעְבַּד פְּעוּלָתֵיהּ.</p>"],[9514012355,"<p>וּבְגִין כָּךְ אִתְקְרִיאַת מַעֲשֵׂה מֶרְכָּבָה. כַּד רֹכֶבֶת בְּהַהִיא חַיָּה דְּאִיהִי נֶשֶׁר, אוֹ שׁוֹר, אוֹ אַרְיֵה, אוֹ אָדָם. וְשִׁבְחָא דְּכָלְהוֹ בְּרִיָּין דִּבְרָא, אִיהוּ אָדָם, דְּאִיהוּ דִּיוּקְנָא דְּכָל עָלְמָא, וּמִכָּל בְּרִיָּין דְּאִית בְּעָלְמָא, וּבְגִין כָּךְ אִיהוּ חָבִיב עֲלֵיהּ מִכָּל בְּרִיָּין.</p>"],[9514012356,"<p>וְכַמָּה בְּנֵי נָשָׁא אִינוּן בִּדְיוֹקְנָא דְּאָדָם מִלְּגָיו. וּמִלְּבַר לָא אִית בְּהוֹן אֶלָּא אוֹ עוֹפָא, אוֹ אַרְיֵה, אוֹ שׁוֹר, אוֹ חַיָּיא מֵאִלֵּין מַזָּלוֹת דְּאִתְקְרִיאוּ בִּבְנֵי נָשָׁא. וְאָחֳרָנִין בְּהִפּוּכָא, אִינוּן בִּדְיוֹקְנָא דְאָדָם מִלְּבַר, וְלָאו הָכֵי מִלְּגַו. וְעַל דָּא הֲווֹ אָמְרִין מִכָּל מָקוֹם, כָּל מִי שֶׁאֵין תּוֹכוֹ כְּבָרוֹ אַל יִכָּנֵס לְבֵית הַמִּדְרָשׁ. דְּאִתְחֲזֵי בְּאַנְפּוֹי דִּיוּקְנָא דְּאָדָם, וּמִלְּגָיו חִיוָא בִּישָׁא.</p>"],[9514012357,"<p>וּבְגִין דָּא אֲמַר קוּדְשָׁא בְּרִיךְ הוּא לְמשֶׁה, וְאַתָּה תֶּחֱזֶה מִכָּל הָעָם אַנְשֵׁי חַיִל, מִסִּטְרָא דְאַבְרָהָם. יִרְאֵי אֱלֹהִים, מִסִּטְרָא דְיִצְחָק. אַנְשֵׁי אֱמֶת, מִסִּטְרָא דְיַעֲקֹב. שׂוֹנְאֵי בֶצַע, מִסִּטְרָא דְדָוִד. דְּאִיהוּ רַגְלָא רְבִיעָאָה, וַעֲלַיְיהוּ שַׁרְיָיא יהו\"ה.</p>"],[9514012358,"<p>וְשַׂמְתָּ עֲלֵיהֶם שָׂרֵי אֲלָפִים, מִסִּטְרָא דְּא' מִן אַדְנ\"י. שָׂרֵי מֵאוֹת, מִסִּטְרָא דְאָת ד', דְּאִינוּן אַרְבַּע מְאָה שְׁנִין דְּמִצְרַיִם בַּקְּרָא. נ' שָׂרֵי חֲמִשִּׁים. י' שָׂרֵי עֲשָׂרוֹת.</p>"],[9514012359,"<p>וַאֲנָא בָּעֵינָא לְפָרְשָׁא, גּוּפָא בִּתְמַנְיָא תִּיקּוּנִין אִלֵּין, בְּגִין דְּאִית לוֹן יְסוֹדָא מֵהַאי קְרָא. אַף עַל גַּב דְּר\"שׁ לָא פָּרֵישׁ אֶלָּא בְּשִׁתָּא אַנְפִּין. וְרָזָא דִּתְמַנְיָיא אַנְפִּין אִלֵּין, בְּרָזָא דְּיאהדונה\"י.</p>"],[9514012360,"<p>וְאִלֵּין אִינוּן ח' תִּיקּוּנִין לְגַבַּיְיהוּ. וְאַתָּה תֶּחֱזֶה מִכָּל הָעָם אַנְשֵׁי חַיִל. בִּרְאִיָּיה, בְּעַיְינִין, וּבִקְרִיצִין דִּילְהוֹן, וּבִגְוָונִין דִּילְהוֹן, בַּעֲמִיקוּ דִּילְהוֹן, בַּאֲרִיכוּ דִּילְהוֹן, וּבִקְמִיטוּ דִּילְהוֹן. הָכָא רָזָא דְחַיָּה דְּאִיהוּ אַרְיֵה, חֶסֶד פָּעֵיל בֵּיהּ. וְאַרְיֵה דָּא מִיכָאֵל. בְּהִיפּוּךְ אַתְוָון אַרְיֵה, תִּשְׁכַּח לֵיהּ רְאִיָּה.</p>"],[9514012361,"<p>יִרְאֵי אֱלֹהִים בִּשְׁמִיעָה דְאוּדְנִין, וּבְשַׂעֲרָא דְּתַלְיָיא מֵרֵישָׁא עֲלַיְיהוּ וּשְׁמִיעָה אִיהִי חַיָּה דְּאִתְקְרִיאַת שׁוֹר. שַׂעֲרָא אִיהִי דִינָא. וְכַמָּה נִימִין תַּלְיָין מִינָהּ, דְּאִינוּן צְבָא הַשָּׁמַיִם, קָיְימִין עַל בֵּי דִינָא רַבְרְבָא, דְּאִיהִי גְבוּרָה לִשְׂמָאלָא, דִפְעוּלָתָהּ בְּחַיָּה דְּאִיהִי שׁוֹר, וְדָא גַבְרִיאֵל.</p>"],[9514012362,"<p>וּבִצְלוֹתָא, צָרִיךְ לְבַעֲרָא לוֹן מִן בָּתַר אוּדְנִין, דְּלָא יְהוֹן מְכַסִּין תַּרְעִין דִּשְׁמִיעָה, לְאָעֳלָא בְּהוֹן צְלוֹתָא. וְאִם לָאו, אִתְקַיִּים בֵּיהּ קְרָא, (משלי א׳:כ״ח) אָז יִקְרָאֻנְנִי וְלֹא אֶעֱנֶה. וּבְזִמְנָא דִּשְׁמִיעָה אִיהִי פְּנוּיָה מֵאִלֵּין דִּינִין, אִתְקַיֵּים בֵּיהּ (ישעיהו נ״ח:ט׳) אָז תִּקְרָא וַה' יַעֲנֶה.</p>"],[9514012363,"<p>אַנְשֵׁי אֱמֶת, בִּדְיוֹקְנָא דְּחוֹטְמָא, דְּאִיהוּ רוּחָא דְקוּדְשָׁא, וְדָא תִּפְאֶרֶת אִיהוּ חוֹטְמָא, חוֹתָם אֱמֶת. יַעֲקֹב שְׁלֵימָא. תְּרֵין אַנְפִּין אִית לֵיהּ לָקֳבֵל לֵאָ\"ה וְרָחֵ\"ל. וְאִלֵּין אִינוּן אַנְפּוֹי דְּרַחֲמֵי, כְּלִילָן חִיוַר וְסוּמָק, מִסִּטְרָא דְּחֶסֶד וּגְבוּרָה.</p>"],[9514012364,"<p>מִצְחָא מִתְתַּקְנָא עֲלַיְיהוּ, דְּאִיהוּ בִּינָה, בְּכַמָּה שִׁרְטוּטִין, דְּאִינוּן אוֹרְחִין דְּיַמָּא דְאוֹרַיְיתָא. עֲלַיְיהוּ אִיתְּמָר (תהילים כ״ה:י׳) כָּל אָרְחוֹת ה' חֶסֶד וֶאֱמֶת. מַאי נִיהוּ דְּעָבִיד אוֹרְחִין אִלֵּין, דְּאִינוּן שִׁרְטוּטִין דְּמִצְחָא. דָּא מוֹחָא, דְּאִיהוּ חָכְמָה. וְאִלֵּין שִׁרְטוּטִין, אִינוּן תְּלָתִין וּתְרֵין שְׁבִילִין דְּיַמָּא דְאוֹרַיְיתָא.</p>"],[9514012365,"<p>וְחַיָּה דְּרָכֵיב עֲלֵיהּ תִּפְאֶרֶת, דָּא נֶשֶׁר. הֲדָא הוּא דִכְתִיב (משלי ל׳:י״ט) דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמַיִם. וְדָא אוֹרִיאֵל. וּמוֹחָא וּמִצְחָא, וּתְרֵין אַנְפִּין אִלֵּין, דְּכָלְהוֹ עַל חוֹטְמָא. אִלֵּין אִינוּן אַרְבַּע בָּתֵּי דִּתְפִילִּין, דְּאִינוּן עַל רֵישָׁא דְּתִפְאֶרֶת.</p>"],[9514012366,"<p>וְחוֹטְמָא דְּאִיהוּ יַעֲקֹב, אִיתְּמָר בֵּיהּ (בראשית ב׳:ז׳) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים. וְדָא בִינָה, בֶּן י\"ה. משֶׁה רַבֵּנוּ אִיהוּ לֵיהּ כְּנִשְׁמָתָא דְחַיֵּי.</p>"],[9514012367,"<p>ל\"ב שִׁרְטוּטִין דְּמִצְחָא אִלֵּין, אַחְזְיָין רָזָא דְּל\"ב אַנְפִּין, וְגַדְפִין דְּד' חֵיוָן דְּאִינוּן ד' אַנְפִּין, וְד' גַּדְפִין לְכָל חַיָּה מֵאִלֵּין.</p>"],[9514012368,"<p>דִּיקְנָא דְאַנְפִּין, אִינוּן נִימִין דְּלֵית לוֹן סוֹף. וְאַחְזְיָין עַל סָבָא דְסָבִין דְּאִיהוּ עִילַּת הָעִילּוֹת, דְּלֵית סוֹף לְעָלְמִין דְּתַלְיָין מִנֵּיהּ.</p>"],[9514012369,"<p>שׂוֹנְאֵי בָצַע, דָּא פּוּמָא, וְאִיהִי מַלְכוּת. תְּרֵין שִׂפְוָון דִּילָהּ, מִתְתַּקְנָן עֲלָהּ, וְאִינוּן נֶצַח וָהוֹד. יְסוֹד, דָּא אִיהוּ לְשׁוֹן לְמוּדִים.</p>"],[9514012370,"<p>וְכָלְהוּ אָזְלִין בְּקַו הַמִּדָּה, דְּאִיהוּ קַו הַיּוֹשֶׁר, בֵּין עַיְינִין, בֵּין אַנְפִּין, בֵּין אוּדְנִין, וְחוֹטְמָא, וּמִצְחָא, וְשִׂפְוָון. וְאִלֵּין דְּלָאו אִינוּן בְּקַו הַמִּדָּה, דְּנָפְקִין מִקַּו הַיּוֹשֶׁר, וַדַּאי לָאו אִינוּן דְּיוֹקְנִין דִּלְעֵילָא, וְלָא שַׁרְיָיא שֵׁם יהו\"ה עֲלַיְיהוּ.</p>"],[9514012371,"<p>וּבְגִין דָּא אֲמַר לְמשֶׁה, וְאַתָּה תֶּחֱזֶה וְגו'. פּוּמָא וַדַּאי סִיּוּמָא דְאָדָם, וְדָא מַלְכוּת. וְחַיָּה דְּרָכֵיב בַּהּ, הוּא רְפָאֵל. אִיהוּ אֵפֶר, אִיהוּ עָפָר דְּבֵי מַקְדְּשָׁא, דְּאִתְנְטֵיל מִנֵּיהּ אָדָם. וּבְהִפּוּכָא אֵפֶר אִיהוּ פְּאֵר, וְדָא אִיהוּ (יחזקאל כ״ד:י״ז) פְּאֵרְךָ חֲבוֹשׁ עָלֶיךָ.</p>"],[9514012372,"<p>הֲרֵי לְךָ ד' תִּיקּוּנִין, דְּאִינוּן, רְאִיָה, שְׁמִיעָה, רֵיחַ, דִּבּוּר. וְהַאי דִּבּוּר, מִתַּמָּן נָטְלִין לֵיהּ נְבִיאִים, דְּאִינוּן תְּרֵין שִׂפְוָון. וְדָא אִיהוּ וְדִבַּרְתִּי עַל הַנְּבִיאִים.</p>"],[9514012373,"<p>וְעַל אִלֵּין אַרְבַּע תִּיקּוּנִין, שַׁרְיָיא יהו\"ה. וְסָלֵיק לַעֲשָׂרָה, דְּאִיהוּ יו\"ד ה\"א וא\"ו ה\"א, דְּאִינוּן עֶשֶׂר סְפִירִין, דְּנָהֲרִין בְּמוֹחָא וּבְמִצְחָא וּבְעַיְינִין וְאוּדְנִין וְאַנְפִּין וְחוֹטְמָא וּפוּמָא. מִצְחָא וּמוֹחָא תְּרֵין. עַיְינִין תְּרֵין. אוּדְנִין תְּרֵין. וְאַנְפּוֹי תְּרֵין. וְחוֹטְמָא וּפוּמָא תְּרֵין. הָא עֶשֶׂר.</p>"],[9514012374,"<p>ה' תִּיקּוּנִין דִּלְתַתָּא, אדנ\"י, וְאִינוּן עֲשִׂיָּה בְּיָדִין, נִעְנוּעַ בְּגוּפָא, שִׁימּוּשׁ בִּבְרִית מִילָה, הֲלִיכָה בָּרַגְלַיִם, וְהָכָא שִׁיעוּר קוֹמָה. וְצָרִיךְ לְאַחְזְרָא עַל כָּלְהוֹ.</p>"],[9514012375,"<p>וְאַתָּה תֶּחֱזֶה מִכָּל הָעָם, אַנְתְּ אִית לָךְ לְאִסְתַּכָּלָא, וְלָא אָחֳרָא. דְּאַנְתְּ אִיהוּ נְהוֹרָא דְּאוֹרַיְיתָא, לְקָיְימָא בָךְ (מלאכי ג) זִכְרוּ תּוֹרַת משֶׁה עַבְדִּי. וְאַתָּה תֶּחֱזֶה, וַדַּאי בִּרְאִיָה דִּילָךְ בְּעַיְינִין, בְּגִין דְּעֵינֵי כֹל אֵלֶיךָ יְשַׂבֵּרוּ, וְאַנְתְּ יְהֵיב לוֹן אֶת אָכְלָם בְּעִתּוֹ, דְּאִיהִי מֵיכְלָא דְּאוֹרַיְיתָא, בְּגִין דִּשְׁמָא דִילִי נְהֵיר בְּעֵינָךְ, וּבְכָל תִּיקּוּנִין דִּילָךְ.</p>"],[9514012376,"<p>פְּתַח וַאֲמַר, רִבּוֹן הָעוֹלָמִים, בִּרְשׁוּ דִּילָךְ אֲנָא אֵיעוֹל לְגַלָּאָה רָזִין טְמִירִין דִּילָךְ. (תהלים קיט) גַּל עֵינַי וְאַבִּיטָה נִפְלָאוֹת מִתּוֹרָתֶךָ, לְשַׁבָּחָא דְּכַלָּה דִּילָךְ, בְּאִלֵּין תִּיקּוּנִין, וּלְכָל אִינוּן דְּתַלְיָין מִינָהּ. וְאִינוּן רְשִׁימִין מִינָהּ, דְּאִיהִי תַּרְעָא דִּילָךְ לְאַעֳלָא בָּךְ, לְמֶחֱזֵי אַפָּךְ, דְּאִיהוּ תִּפְאֶרֶת. שׁוּפְרָא דִילָךְ, עֲלָה אִיתְּמָר (שיר השירים ד׳:א׳) כֻּלָּךְ יָפָה רַעֲיָתִי, (שם) הִנָּךְ יָפָה עֵינַיִךְ יוֹנִים. כְּיוֹנִים וַדַּאי, דְּאִינוּן מְרֻקָּמִין בְּגוּפַיְיהוּ בְּגַדְפַיְיהוּ, וּבִרְקִימוּ דִּילְּהוֹן אִשְׁתְּמוֹדְעִין בִּשְׁאָר עוֹפִין.</p>"],[9514012377,"<p>וְעוֹד כְּיוֹנִים, דְּלֵית בְּכָל עוֹפִין מְהֵימְנָא לְגַבֵּי בַּעֲלָהּ כְּיוֹנָה. עַיְינִין גַּבְהָנִין, מִסְתַּכְּלִין בְּאוֹרַח מִישׁוֹר לְגַבֵּי בַּעֲלָהּ. גַּדְפוֹי דְּיוֹנִים, אִלֵּין כַּנְפֵי עֵינָא, דִּי בְּהוֹן פָּרְחַת יוֹנָה לְגַבֵּי בַּעֲלָהּ. יוֹנִים אִתְקְרִיאוּ.</p>"],[9514012378,"<p>מִסִּטְרָא דְחֶסֶד חִוְּורִין. וְסוּמְקִין מִסִּטְרָא דִּגְבוּרָה. וִירוֹקִין מִסִּטְרָא דְּתִפְאֶרֶת. וְאוּכְמִין מִסִּטְרָא דְמַלְכוּת. דְּאִיתְּמָר בַּהּ (שיר השירים א׳:ה׳) שְׁחוֹרָה אֲנִי וְנָאוָה.</p>"],[9514012379,"<p>חִוָּורוֹ דִּילְהוֹן, כְּמַשְׂכִּיּוֹת כֶּסֶף. וְאִיהוּ כְּחִוָּורוֹ דְּשׁוֹשַׁנָּה. סוּמְקֵי דִּילְהוֹן, כְּתַפּוּחֵי זָהָב, וְאִיהוּ כְּסוּמְקֵי דְּשׁוֹשַׁנָּה. יְרוֹקָא דִּילְהוֹן, כָּלֵיל תְּרֵי גְּוָונִין. אוּכְמֵי דִּילְהוֹן שַׁפִּירוּ דְּאוֹרַיְיתָא, דְּאִיהִי אוּכְמָא שַׁפִּירְתָּא, כְּמָה דְּאִיתְּמָר שְׁחוֹרָה אֲנִי וְנָאוָה.</p>"],[9514012380,"<p>בְּגַוָּון חִיוָּר, אִיהוּ יָפָה כַלְּבָנָה. בְּגַוָּון סוּמָק, בָּרָה כַּחַמָּה. אֲיוּמָה כַּנִּדְגָּלוֹת, בִּתְרֵין גְּוָונִין אָחֳרָנִין. רִבּוֹן עָלְמָא, בְּאִלֵּין ד' גְוָונִין, אֱהֵא מִסְתַּכֵּל לְשִׁמְךָ יהו\"ה, דְּתִפְרוֹק לַהּ.</p>"],[9514012381,"<p>(איוב א) רְאֵה ה' כִּי הִגְדִּיל אוֹיֵב דְּאִיהוּ סמאָמַר לֵיהּ, דְּעַיְינִין דִּילֵיהּ עֲקִימִין, וּגְוָונוֹי חֲשִׁיכִין, וְלָא מִסְתַּכְּלִין בְּאוֹרַח מֵישַׁר, לְמֶעְבַּד טַב בְּגָלוּתָא עִם צַדִּיקַיָא, אֶלָּא עִם רַשִּׁיעַיָא, דְּאִינוּן עֲקִימִין בְּאוֹרְחַיְיהוּ בְּכֹלָּא. בְּנוֹי דְּנָחָשׁ הַקַּדְמוֹנִי, דְּקָטֵיל לְאָדָם וּלְכָל בִּרְיָין דְּאַתְיָין מִנֵּיהּ.</p>"],[9514012382,"<p>גַּוָּון חִוָּור דְּעַיְינִין דִּילֵיהּ, אִיהוּ נָחָשׁ. גַּוָון סוּמָק, שָׂרָף. גַּוָּון תְּלִיתָאי, יָרוֹק. כָּלֵיל מִתַּרְוַויְיהוּ, עַקְרָב. גַּוָּון רְבִיעָאָה אוֹדֶם, צִמָּאוֹן אֲשֶׁר אֵין מָיִם.</p>"],[9514012383,"<p>כָלְהוֹ גְּוָונִין דְּעֵינָא דְּרַשִּׁיעַיָּיא, קָטְלִין. עֲלַיְיהוּ אִיתְּמָר (משלי כ״ג:ו׳) אַל תִּלְחַם אֶת לֶחֶם רַע עָיִן וְאַל תִּתְאָו לְמַטְעַמֹּתָיו. וּבְגִין דָּא, אָסוּר לְעַמָּא קַדִּישָׁא לְאִסְתַּכֵּל בְּרַשִּׁיעַיָּיא. וְאוֹרַיְיתָא דִילְּהוֹן, צָרִיךְ לְאִתְכַּסָּאָה מִינַּיְיהוּ. הֲדָא הוּא דִכְתִיב, (תהילים קמ״ז:כ׳) לֹא עָשָׂה כֵן לְכָל גּוֹי וּמִשְׁפָּטִים בַּל יְדָעוּם.</p>"],[9514012384,"<p>כְמָה דְיוֹנָה צְרִיכַת נְטִירוּ מִנֵּץ, כְּגַוְּונָא דָּא צְרִיכִין נְטִירוּ, עֵינַיִךְ יוֹנִים דְּצַדִּיקִים, מֵעַיְינִין דְּרַשִּׁיעַיָּא, דְּאִינוּן עֵרֶב רַב, בְּנוֹי דְּלִילִית רַשִּׁיעָתָא, דְּאִינוּן קָשִׁין לְמֶעְבַּד טִיבוּ עִם עֲנִיֵּי בְּנֵי יִשְׂרָאֵל. וְאִינוּן עֲקִימִין בְּכָל אוֹרְחַיְיהוּ, בְּנוֹי דְּנָחָשׁ הַקַּדְמוֹנִי, דְּאִלֵּין אִינוּן זוּהֲמָא דְּהִטִיל חִוְּיָא בְּחַוָּה.</p>"],[9514012385,"<p>הֲרֵי אַרְבַּע גְּוָונִין בִּישִׁין לְקָטְלָא. וְאַרְבַּע גְּוָונִין אָחֳרָנִין טָבִין לְאַחָיָיא. תְּרֵין כְּרוּבֵי עֵינָא, אִינוּן נֶצַח וָהוֹד. אִלֵּין אִינוּן כַּנְפֵי יוֹנָה. עַיִן דָּא צַדִּיק, אִיהוּ יוֹנָה מַמָּשׁ. דְּכַר וְנוּקְבָא, אִינוּן צַדִּיק וְצֶדֶק. מִסִּטְרָא דְּצַדִּיק אִתְקְרִיאַת יוֹנָה, מִסִּטְרָא דְּתִפְאֶרֶת אִתְקְרִיאַת עַיִן.</p>"],[9514012386,"<p>נֶשֶׁר, הֲדָא הוּא דִכְתִיב, (משלי ל׳:י״ט) דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמָיִם. דְּלָא דָּחֵיל מֵעוֹפָא דְעָלְמָא, בְּגִין דְּנִשְׁרָא אִיהִי מַטְרוֹנִיתָא עִילָּאָה, וְשׁוּלְטָנוּתָהּ בְּיוֹמִין טָבִין וְשַׁבָּתוֹת. אֲבָל יוֹנָה שׁוּלְטָנוּתָהּ בְּשִׁית יוֹמֵי בְּרֵאשִׁית, וְאִיהִי בְּגָלוּתָא לֵית לָהּ מָנוֹחַ לְכַף רַגְלָהּ. בְּגִין דִּבְנוֹי דְּלִילִית, זוּהֲמָא דְּחִוְּיָא, עֲלַיְיהוּ אִיתְּמָר (בראשית ז׳:י״ח-י״ט) וְהַמַּיִם גָּבְרוּ מְאֹד מְאֹד עַל הָאָרֶץ, דְּאִינוּן יִשְׂרָאֵל דְּאִתְּמָר בְּהוֹן (בראשית כ״ח:י״ד) וְהָיָה זַרְעֲךָ כַּעֲפַר הָאָרֶ\"ץ. אִינוּן מִתְגַּבְּרִין עֲלַיְיהוּ בְּגָלוּתָא, בְּנָשִׁין שַׁפִּירִין, בִּבְנִין שַׁפִּירִין, בְּעוּתְרָא, בִּלְבוּשִׁין שַׁפִּירִין.</p>"],[9514012387,"<p>וְיִשְׂרָאֵל עֲנִיִּים בְּכֹלָּא, אוּכְמָא בְּכֹלָּא. בְּנוֹי דְּהַהוּא דְּאִיתְּמָר בַּהּ, (שיר השירים א׳:ו׳) אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחוֹרֶת, בְּגָלוּתָא. וְאִינוּן בְּנוֹי דְּהַהוּא דְּאִתְּמָר בֵּיהּ, (ישעיהו נ׳:ג׳) אַלְבִּישׁ שָׁמַיִם קַדְרוּת וְשַׂק אָשִׂים כְּסוּתָם. אִינוּן מִתְלַבְּשִׁין בְּאִינוּן לְבוּשִׁין, בְּגִין אִלֵּין רַשִּׁיעַיָּא דְּמִתְגַּבְּרִין עֲלַיְיהוּ בְּגָלוּתָא, דְּלָא מִסְתַּכְּלִין לוֹן אֶלָּא בְּעֵינָא בִּישָׁא. (משלי כ״ב:ג׳) וְעָרוּם רָאָה רָעָה וְנִסְתָּר, כְּגוֹן נֹחַ, וְהָכֵי צְרִיכִים יִשְׂרָאֵל לְאִתְכַּסָּאָה מִנַּיְיהוּ בְּגָלוּתָא, בִּלְּבוּשֵׁיהוֹן, בִּנְשֵׁיהוֹן, בִּבְנֵיהוֹן, בְּעוּתְרָא דִּלְהוֹן. וְלָאו לְמַגָּנָא אָמְרוּ מִכָּל מָקוֹם, דְּלֵית בְּרָכָה שׁוֹרָה אֶלָּא בְּדָבָר הַסָּמוּי מִן הָעַיִן.</p>"],[9514012388,"<p>וְנָחָשׁ וְעַקְרָב, אִלֵּין מוּמִין דְּעֵינָא. עַיְינִין עֲקִימִין דְּבַר נָשׁ, דְּלָא מִסְתַּכְּלִין בְּאוֹרַח מִישׁוֹר, חִוְּיָא, דְּאִיהוּ נָחָשׁ עֲקָלָתוֹן תַּמָּן. בְּהַאי לָא תָּפִיס כְּלָל, מֵאִינוּן דְּקַו הַמִּדָּה בְּהוּ. עֲלַיְיהוּ אִתְּמָר, (במדבר ט״ו:ל״ט) וְלֹא תָתוּרוּ אַחֲרֵי לְבַבְכֶם וְאַחֲרֵי עֵינֵיכֶם אֲשֶׁר אַתֶּם וְגו'. אַף עַל גַּב דְּיִשְׂרָאֵל אִינוּן בְּגָלוּתָא, וּפַרְנְסֵי דָרָא אִינוּן כְּגַוְונָא דְלִבָּא, וְעֵינֵי יִשְׂרָאֵל דַּהֲווֹ סַנְהֶדְּרֵי גְדוֹלָה, כֵּיוָן דְּאִינוּן זוֹנִים וּמְשׁוּטָפִין בְּזִמָּה, לֹא תָתוּרוּ אֲבַתְרַיְיהוּ, דְּהָא לֵית בְּהוּ מְהֵימָנוּתָא.</p>"],[9514012389,"<p>עַיְינִין עֲקִימִין, רַמַּאי אִיהוּ, וּמְפַתֵּי בְּנֵי נָשָׁא בְּלִישְׁנֵיהּ, כְּגוֹן דְּפַתֵּי נָחָשׁ לְחַוָּה. עֵץ הַדַּעַת טוֹב וָרָע אִיהוּ. אִתְחֲזֵי בְּפוּמֵיהּ וּבְמִלּוֹי טַב, וְלִבֵּיהּ רַמַּאי בִּישׁ, אִיסְתַּמַּר מִנֵּיהּ. עֲלֵיהּ אִתְּמָר, (בראשית ב׳:י״ז) וּמֵעֵץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ.</p>"],[9514012390,"<p>חִוָּורוֹ דְּעַיְינִין, מְכַסְיָיא כָּל גְּוָונִין אָחֳרָנִין. עַיְינִין דִּילֵיהּ אִינוּן רַבְרְבִין, גַּבְהָנִין, וְאִיהוּ גְּבַהּ לֵב, עֲלֵיהּ אִיתְּמָר (משלי ט״ז:ה׳) תּוֹעֲבַת ה' כָּל גְּבַהּ לֵב. כָּל טָבִין דַּעֲבֵיד, לְמֶעְבַּד לֵיהּ שֵׁם. וְאִיהִי מֵאִלֵּין דְּאִתְּמָר בְּהוֹן, (בראשית י״א:ד׳) הָבָה נִבְנֶה לָנוּ עִיר וּמִגְדָּל וְרֹאשׁוֹ בַּשָּׁמַיִם וְנַעֲשֶׂה לָנוּ שֵׁם. אִלֵּין אִינוּן דְּבוֹנִין בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת מִמָּמוֹנֵיהוֹן. וְכֹלָּא לְמֶעְבַּד לְהוֹן שֵׁם, וְלָא לִשְׁמָא דַה'. הַאי אִיהוּ גָּיְיפָא, דִּיוּקְנָא דַּחֲמוֹר נוֹאֵף אִיהוּ. אִסְתַּמַּר בְּרַתָּךְ וְאִתְּתָךְ מִנֵּיהּ, אִם יְהֵא אוּשְׁפִּיזָךְ.</p>"],[9514012391,"<p>וְעוֹד, הַאי בַּר נָשׁ מִשְׁתַּדֵּל כָּל יוֹמֵי בְּכִשּׁוּף, וְאַצְלַח בְּהוֹן עִם מַלְכִין וְשַׁלִּיטִין. אִיהוּ מְעוֹנֵן וּמְנַחֵשׁ וּמְכַשֵּׁף. וְאִיהוּ רְשִׁימוּ דִילֵיהּ רְשִׁימוּ דְחִוְּיָא, בְּמִדָּה חִוָּורָא. וְרוֹשֶׁם חִוָּור אִית לֵיהּ בְּכַתְּפוֹי, דְּמִתַּמָּן אִתְנְטֵיל נָחָשׁ, וְלֵית שַׂעֲרָא עַל הַהוּא רוֹשֶׁם. וּמַזָּלֵיהּ דְּהַאי בַּר נָשׁ בְּכָל מִלָּה, חִוָּורָא. שַׂעֲרָא דִּילֵיהּ חִוָּור, וְהוּא אָרִיךְ קוֹמָה, וְשַׂעֲרוֹי אֲרִיכִין.</p>"],[9514012392,"<p>וְעַיְינִין חִיוָּרִין, מִסְתַּכְּלִין בְּאוֹרַח מֵישָׁר. הַאי אִיהוּ מָארֵיהּ דְּחֶסֶד, דְּאִתְיְלֵיד הַאי בַּר נָשׁ בְּיוֹמָא קַדְמָאָה, בְּשַׁעֲתָא קַדְמָאָה, דְמַזָּלֵיהּ טָלֶה. וְחַיָּה דִילֵיהּ אַרְיֵהּ בְּיוֹמָא קַדְמָאָה, כָּל י\"ב מַזָּלוֹת, וְז' כּוֹכְבַיָיא, אִינוּן מְשׁוּעְבָּדִים לְכוֹכָבָא דִּילֵיהּ, וּלְמַזָּלָא דִּילֵיהּ. וְהָכֵי כָּל יוֹמָא וְיוֹמָא כְּגַוְונָא דָא.</p>"],[9514012393,"<p>הַאי בַּר נָשׁ אִיהוּ חִיוָּר, מֵחִוָּורוֹ דִּנְהוֹרָא דְּאִתְבְּרֵי בְּיוֹמָא קַדְמָאָה. הֲדָא הוּא דִכְתִיב, (בראשית א) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. אִתְיְלֵיד בְּרֵישׁ שַׁעֲתָא דְיוֹמָא, יְהֵא חַכִּימָא יַתִּיר בְּאוֹרַיְיתָא. וִיהֵא רֵישָׁא דְּמָארֵי מְתִיבָתָא. וְאִם אִתְיְלֵיד בְּאֶמְצָעִיתָא דְּשַׁעֲתָא, יְהֵא בֵּינוֹנִי בְּאוֹרַיְיתָא. וְאִם בְּסוֹפָא דְּשַׁעֲתָא, יְהֵא עָנִי בְּאוֹרַיְיתָא. זָנָב לָאֲרָיוֹת, דְּאִינוּן תַּלְמִידֵי חֲכָמִים.</p>"],[9514012394,"<p>וְהַאי אִיהוּ בְּמַזָּל רְאוּבֵ\"ן, דְּאִיהוּ אוֹ\"ר בֵּ\"ן, מִסִּטְרָא דְּחֶסֶד. וְסִיהֲרָא דְּאִיהִי מַלְכוּת, נָטְלָא חִוָּורוֹ דִּנְהוֹרָא. דְּמַלְכוּת אִיהִי סִיהֲרָא מִסִּטְרָא דְּחֶסֶד, יָפָה כַלְּבָנָה. וְאִיהִי חַמָּה מִסִּטְרָא דִגְבוּרָה. וְאִיהִי כּוֹכָב מִסִּטְרָא דְּת\"ת, הֲדָא הוּא דִכְתִיב, (במדבר כד) דָּרַךְ כּוֹכָב מִיַּעֲקֹב. וְאִיהִי נוֹגַהּ מִסִּטְרָא דְּנֶצַח. וְאִיהִי מַאְדִּים, מִסִּטְרָא דְּהוֹד, דְּאִתְאַדָּם בִּגְבוּרָה. וְאִיהִי שַׁבָּת, מִסִּטְרָא דִיסוֹד. שַׁבָּתָאי דְּמִסִּטְרָא טָבָא אִיתְּמָר בֵּיהּ שַׁבָּת.</p>"],[9514012395,"<p>אֲבָל מִסִּטְרָא אָחֳרָא שַׁבְּתָא\"י, וּבְזִמְנָא דְּהַאי שַׁלֵּיט עַל עָלְמָא אִסְתַּלַּק שַׁבָּת, וְאָמְרִין אוּשְׁפִּיזִין דְּאִינוּן נְשָׁמוֹת יְתֵירוֹת, אֵי שַׁבָּת.</p>"],[9514012396,"<p>וּבְגִין דָּא, עַיְינִין חִיוְּורִין, נָטְלִין בְּסִיהֲרָא מִסִּטְרָא דְּחֶסֶד. אִלֵּין אִינוּן מָארֵי דַּחֲסָדִים טוֹבִים, מִזַּרְעָא דְאַבְרָהָם. אִלֵּין עַיְינִין מִסְתַּכְּלִין בְּאוֹרַח מֵישָׁר כְּלַפֵּי יָמִינָא.</p>"],[9514012397,"<p>הַאי בַּר נָשׁ, וַותְּרָן אִיהוּ בְּמָמוֹנֵיהּ, דְּמָמוֹנָא דְנִשְׁמָתָא אִיהִי אוֹרַיְיתָא, וּשְׁאָר עוּתְרָא מָמוֹנָא דְגוּפָא. הַאי בַּר נָשׁ חִוָּור אִיהוּ כְּכַסְפָּא, אָרִיךְ קוֹמָה אִיהוּ. רְשִׁימוּ חִוָּור אִית בְּיָמִינָא דִּילֵיהּ. רָחֵים אִיהוּ מִבְּנֵי נָשָׁא, רָחֵים אִיהוּ מִקוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב, אַבְרָהָם אוֹהֲבִי. שַׂעֲרָא דִּילֵיהּ שְׁעִיעַ חִוָּור.</p>"],[9514012398,"<p>וְתָּא חֲזֵי, דְּלֵית עַיְינִין דְּלָאו אִינוּן כְּלִילִין מֵאַרְבַּע גְּוָונִין. וְאַמַּאי אִתְקְרִיאוּ עַיְינִין חִוָּורִין. אֶלָּא כָּל גַּוָּון דְּשָׁלֵיט עַל אָחֳרָנִין, אִתְקְרִיאוּ עַיְינִין עַל שְׁמֵיהּ. וּבְגִין דָּא כַּד שַׁלֵּיט גַּוָּון חִוָּור בְּעַיְינִין, אִתְקְרִיאוּ עַיְינִין חִוָּורִין. וּמַאן דְּבָעֵי לְאַצְלָחָא בְּאוֹרַיְיתָא, וְאִשְׁתַּדֵּל בָּהּ, עֲלֵיהּ אִיתְּמָר הָרוֹצֶה לְהַחְכִּים יַדְּרִים.</p>"],[9514012399,"<p>עַיְינִין סוּמְקִין מִסִּטְרָא אָחֳרָא, נָטְלִין סוּמְקוֹ מִשָּׂרָף, דְּאוֹקֵיד לוֹן בְּשַׁלְהוֹבוֹי דְּחַמָּה בִּישָׁא, וּמִתְאַדְּמִין בְּמַאְדִּים דְּסִטְרָא אַחֲרָא. דִּתְרֵין דַּרְגִּין אִלֵּין, אִינוּן מֵאוּמָה דְּעֵשָׂו, אִיהוּ אֱדוֹם מִסִּטְרָא דְּמַאְדִּים, וְאִתְּמָר בִּבְנוֹי דְּמוֹנִין לַחַמָּה, וּבְגִין דָּא כַּד לוֹקָה חַמָּה סִימָן רַע לְאֻמּוֹת הָעוֹלָם. לָקוּתָא דְחַמָּה דְּאוּמִין דְּעָלְמָא.</p>"],[9514012400,"<p>אוֹרַיְיתָא דְּאִיהִי אוּכְמָא, דְּאִתְּמָר בַּהּ (שיר השירים א׳:ה׳) שְׁחוֹרָה אֲנִי וְנָאוָה. לָקוּתָא דְשִׁמְשָׁא דִּסְטַר קַדִּישָׁא, שַׁבָּתָאי לִילִית פְּתַיָיא אוּכְמָא. וּבְנָהָא, אִינוּן לָקוּתָא דְּיִשְׂרָאֵל.</p>"],[9514012401,"<p>מַאְדִּים, לָקוּתָא דְסִיהֲרָא טָבָא דְּיַעֲקֹב. וּמַאְדִּים אִיהוּ עֵשָׂו. וּמַאְדִּים דְּסִטְרָא טָבָא, לָקוּתָא לְסִיהֲרָא בִּישָׁא, דְּמוֹנִין לָהּ אוּמָה דְּיִשְׂמָעֵאל.</p>"],[9514012402,"<p>לָקוּתָא דְּעַיְינִין בְּסוּמְקוֹ דִּילְהוֹן, וּבַאֲדִימוּ דִּילְּהוֹן בְּבִשְׂרָא, דִּגְבִינִין דִּלְהוֹן. הַאי אִיהוּ חַמָּה דְּאוֹקֵיד לוֹן, דְּאִיהוּ שָׂרָף, וְאוֹשְׁדִּין דִּמְעִין וְאַדִּימוּ. כּוּלְהוֹן לָקוּתָא דְמַאְדִּים אִלֵּין. אִינוּן עַיְינִין קְמִיטִין בְּיַבְשׁוּתָא, דְּשָׂרָף דְּאוֹקֵיד לוֹן וְאִתְקְמִיטוּ, וְעַיְינִין סוּמְקִין דְסִטְרָא אָחֳרָא הוּא.</p>"],[9514012403,"<p>מָארֵי דְעַיְינִין סוּמְקִין, אִסְטַמַּר מִינֵיהּ, אוֹשִׁיד דָּמִין אִיהוּ. וְאִי הוּא חָזַר בִּתְיוּבְתָּא, אוֹשִׁידוּ דְּדָמָא דִילֵיהּ, יְהֵא בְּפִקּוּדִין דְּאוֹרַיְיתָא. אוֹ יְהֵא טַבָּחָא. אוֹ מוֹהֲלָא.</p>"],[9514012404,"<p>וְהַאי בַּר נָשׁ, אִיהוּ קָמִיט בְּאַנְפּוֹי, בְּחוּטְמֵיהּ, בְּקָדְלֵיהּ, בְּגוּפֵיהּ, בִּדְרָעוֹי, בְּרַגְלוֹי. בְּהִפּוּכָא דְּעַיְינִין חִוָּורִין, דְּאִיהוּ אָרִיךְ בְּאַנְפּוֹי בְּחוּטְמֵיהּ בְּקַדְלֵיהּ בְּגוּפֵיהּ בִּדְרָעוֹי בְּרַגְלוֹי. דָּא רַחֲמֵי. וְדָא דִּינָא.</p>"],[9514012405,"<p>עַיְינִין סוּמְקִין דְּסִטְרָא דַּכְיָיא, אִלֵּין עַיְינִין דְּדָוִד דְּאִיתְּמָר בֵּיהּ, (שמואל א ט״ז:י״ב) וְהוּא אַדְמוֹנִי עִם יְפֵה עֵינַיִם וְטוֹב רֹאִי. שַׂעֲרֵי יְרוֹקִין בְּגַוָּון חַמָּה טוּבָא, אַנְפּוֹי סוּמְקֵי מִסִּטְרָא דְּמַאְדִּים טַב.</p>"],[9514012406,"<p>בְּשַׂעֲרוֹהִי הֲווֹ ז' מִינֵי גְּוָונֵי דַּהֲבָא, דְּאִיהוּ זָהָב סָגוּר, זְהַב אוֹפִיר, זְהַב פַּרְוָיִם, זָהָב שָׁחוּט, זָהָב טָהוֹר, זָהָב מוּפָּז, זְהַב תַּרְשִׁישׁ. ז' אִינוּן מִינֵי דַּהֲבָא, דִּשְׁבַע סְפִירִין אִתְכְּלִילָן בְּהוּ. וְשַׂעֲרָא דִילֵיהּ קָמִיט. וְכָל אֵיבָרִין דִּילֵיהּ קְמִיטִין. מִסִּטְרָא דִּשְׁבָרִים. וּבְגִין דָּא, דָּוִד הוּא הַקָּטָן, וְאִיהוּ דַרְגָּא דִּילֵיהּ הוֹד, דְּנָטֵיל בִּגְבוּרָה.</p>"],[9514012407,"<p>אֲבָל עַיְינָא חִוָּורִין, נָטְלִין בְּנֶצַח וְחֶסֶד, וְאִינוּן אֲרִיכִין. וְשִׁרְטוּטִין דְּמִצְחָא כָּלְהוֹן אֲרִיכִין, מִסִּטְרָא דִּתְקִיעָה. אֲבָל שִׁרְטוּטִין דְּמִצְחָא מִסִּטְרָא דְּבַּר נָשׁ קָמִיט, אִינוּן קְמִיטִין בְּרָזָא דִשְׁבָרִים. וְאִית לֵיהּ רוֹשֶׁם סוּמָק תְּחוֹת דְּרוֹעָא שְׂמָאלָא, אוֹ בִּדְרוֹעָא שְׂמָאלָא, אוֹ בְּשׁוֹקָא שְׂמָאלָא.</p>"],[9514012408,"<p>וּמַאן דְּאִתְיְילֵיד בְּשַׁעֲתָא קַדְמָאָה דְּיוֹמָא תִּנְיָינָא, דְּאִיהוּ דַרְגָּא דִגְבוּרָה. יְהֵא תַּקִּיף בְּיִצְרֵיהּ, אִם יִשְׁתַּדֵּל בְּאוֹרַיְיתָא דִּבְעַל פֶּה. וּמַלְכוּת אִיהוּ חַמָּה טָבָא, אוֹרַיְיתָא דִּבְעַל פֶּה מִסִּטְרָא דִגְבוּרָה, וְאִיהִי סִיהֲרָא קַדִּישָׁא, אוֹרַיְיתָא דְּבִכְתַב אִתְקְרִיאַת מִסִּטְרָא דְחֶסֶד.</p>"],[9514012409,"<p>חַמָּה בִּישָׁא אִיהִי גֵּיהִנֹּם, דְּאִתְבְּרֵי בְּיוֹמָא תִּנְיָינָא. וּבְסִטְרָא דְּדַרְגָּא דְּעֵשָׂו, נְפָקַת סוּמְקָא. אַף עַל גַּב דִּנְטִילַת לְבָתַר מִכָּל גְּוָונִין, חִוָּור וְיָרוֹק וְאוּכָם, מַאן דְּאָלִים גָּבַר, וְעַל שְׁמֵיהּ אִתְקְרִיאַת.</p>"],[9514012410,"<p>וְהַאי אִיהִי תִּיקּוּנָא דְּחָכְמְתָא עִילָּאָה. אֲבָל אִיסְטַגְנִינוֹן לָא נָטְלִין כּוֹכָבָא בְּסִידְּרָא דָא, אֶלָּא כְּפוּם מֶמְשֶׁלֶת דִּילְהוֹן בְּאוֹרַח חוּשְׁבְּנָא.</p>"],[9514012411,"<p>עַיְינִין סוּמְקִין, אִינוּן מֶרְכָּבָה דְּחַיָּה דְשׁוֹר, דְּאִיתְּמָר בַּהּ (יחזקאל א׳:י׳) וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל לְאַרְבַּעְתָּן, דְּאִינוּן ד' גְּוָונֵי עֵינָא. וְשׁוּלְטָנוֹ דְּאַרְבַּע גְּוָונִין אִלֵּין, אִיהוּ סוּמָק. אֲבָל עַיְינִין חִוָּורִין, מֶרְכָּבָה דִילְהוֹן אַרְיֵה.</p>"],[9514012412,"<p>וְאַרְיֵה אִיהוּ מִיכָאֵל. שׁוֹר, גַּבְרִיאֵל. וּמַאן דְּאִתְיְלֵיד בְּרֵישָׁא דְּשַׁעֲתָא דְּשׁוֹר, יְהֵא עֲתִיר בְּדַהֲבָא, וּבְכָל מִינֵי סוּמָק. בְּעַיְינִין חִוָּורִין נָהֵיר יהו\"ה רַחֲמֵי וַדַּאי, וְאִתְּמָר בֵּיהּ הָרוֹצֶה לְהַחְכִּים יַדְרִים. בְּעַיְינִין סוּמְקִין נָהֵיר אדנ\"י, וּבֵיהּ הָרוֹצֶה לְהַעֲשִׁיר יַצְפִּין.</p>"],[9514012413,"<p>מַאן דְּאִתְיְלֵיד בִּפְלוּגְתָּא דְּשַׁעֲתָא קַדְמָאָה דְּיוֹמָא תִּנְיָינָא, יְהֵא בֵּינוֹנִי בְּעוֹתְרָא. מַאן דְּאִתְיְלֵיד בְּסוֹפָא דְּשַׁעֲתָא, הַאי אִיהוּ בִּזְנָבָא דְשׁוֹר, יְהֵא עָנִי.</p>"],[9514012414,"<p>וְיוֹמִין דְּכָל חַד מִתְפַּלְּגִין לִתְלַת סִטְרִין, כְּגַוְונָא דְּנִשְׁמָתָא וְרוּחָא וְנַפְשָׁא. נִשְׁמָתָא אִיהוּ מִכָּרְסְיָיא יַקִּירָא, וְאִיהִי מֶרְכָּבָה בְּרֵישׁ כָּל כּוֹכָב וּמַזָּל. רוּחָא אִיהִי מִן מַלְאָכַיָּיא, וְאִיהִי מֶרְכָּבָה בִּמְצִיעוּת כָּל כּוֹכָב וּמַזָּל. וְנַפְשָׁא שׁוּתָּפֵי דִּבְעִירָאן וְעוֹפִין, וְכָל אִילֵּין דְּתַאֲוָה דְּעָלְמָא שְׁפֵלָה, וְאִיהִי מֶרְכָּבָה בְּסוֹפָא דְּכָל שַׁעֲתָא, וּבְסוֹפָּא דְּכָל כּוֹכָב וּמַזָּל.</p>"],[9514012415,"<p>וּמִסִּטְרָא דְּנַפְשָׁא דִּבְעִירָא, יוֹמוֹי דְּבַּר נָשׁ קְצִירִין, וְאִינוּן מְעַט וְרָעִים. דְּכָל יוֹמֵי דְּבַּר נָשׁ דְּאִינוּן בַּעֲנִיּוּתָא בְּצַעֲרָא וּבְדוֹחֲקָא, לָאו אִינוּן חַיִּים, וְכָל שֶׁכֵּן אִי אִינוּן יוֹמִין בְּלָא תוֹרָה וּמִצְוָה, דְּלָאו אִינוּן חַיִּים.</p>"],[9514012416,"<p>אִם חָזַר בִּתְיוּבְתָּא, אַף עַל גַּב דְּאִיהוּ בִּזְנַב טָלֶה אוֹ שׁוֹר, בְּכָל מַזָּל וּמַזָּל, קוּדְשָׁא בְּרִיךְ הוּא אוֹסֵיף בֵּיהּ רוּחָא יְתֵירָא דְּמַלְאָכִין, וְסָלֵיק מִזְּנָבָא לְמֶהֱוֵי בֵּינוֹנִי. זָכָה יַתִּיר לְמֵיהֱדַר בִּתְיוּבְתָּא בְּמַחֲשַׁבְתֵּיהּ, קוּדְשָׁא בְּרִיךְ הוּא יָהֵיב לֵיהּ נִשְׁמָתָא מִכּוּרְסַיָיא, וְסָלֵיק לְמֶהֱוֵי רֵישָׁא בְּרֵישׁ כָּל כּוֹכָב וּמַזָּל.</p>"],[9514012417,"<p>וּבְגִין דָּא אֵין מַזָּל לְיִשְׂרָאֵל. וְאַף עַל גַּב דְּאִתְיְלֵיד בְּרֵישׁ שַׁעֲתָא, וְקִלְקֵל עוֹבָדוֹי, קוּדְשָׁא בְּרִיךְ הוּא נָחֵית לֵיהּ מֵרֵישָׁא לְגוּפָא, לְמֶהֱוֵי בֵּינוֹנִי. וְאִי מְקַלְקֵל יַתִּיר בְּעוֹבָדוֹי, נָחֵית לֵיהּ לְסוֹפָא דְּכָל מַזָּל וּמַזָּל. וְהַאי אִיהוּ תָּלוּי בְּמַזָּל, וּמַזָּל רָכֵיב עֲלֵיהּ וְשַׁלֵּיט עֲלֵיהּ. אֲבָל בְּזִמְנָא דְּנִשְׁמָתֵיהּ שַׁלֵּיט וְרָכֵיב עַל מַזָּלָא, מַזָּלָא אִיהוּ טְפֵילָא לָרוֹכֵב עָלָיו.</p>"],[9514012418,"<p>וְאִם מַזָּלָא דְּאִיהוּ טְפֵלָה לָרוֹכֵב שַׁלֵּיט עֲלֵיהּ, אִיתְּמָר בֵּיהּ (דברים כ״ח:מ״ג-מ״ד) הַגֵּר אֲשֶׁר בְּקִרְבְּךָ יַעֲלֶה עָלֶיךָ מַעְלָה מָעְלָה וְאַתָּה תֵּרֵד מַטָה מָטָה הוּא יַלְוֶךָ וְאַתָּה לֹא תַלְוֶנּוּ הוּא יִהְיֶה לְרֹאשׁ וְאַתָּה תִּהְיֶה לְזָנָב. וְאִיתְּמָר עַל נִשְׁמָתֵיהּ וְרוּחֵיהּ, (שם) וְהָיוּ חַיֶּיךָ תְּלוּאִים לְךָ מִנְּגֶד.</p>"],[9514012419,"<p>וְאִם חָזַר בִּתְיוּבְתָּא, יַחְזְרוּן לֵיהּ רוּחֵיהּ וְנִשְׁמָתֵיהּ, וְאִתְקַיִּים בֵּיהּ קְרָא דִכְתִיב, (שם) וּנְתָנְךָ ה' לְרֹאשׁ וְלֹא לְזָנָב וְהָיִיתָ רַק לְמַעְלָה וְלֹא תִהְיֶה לְמָטָה כִּי תִשְׁמַע אֶל מִצְוֹת ה' אֱלֹהֶיךָ. בְּמִצְוֹת זָכֵי לְרוּחָא, בְּאוֹרַיְיתָא זָכֵי לְנִשְׁמָתָא.</p>"],[9514012420,"<p>עַיְינִין יְרוֹקִין דְּסִטְרָא אָחֳרָא, מִדִּידוּ דְּאִתְמְשַׁךְ מִנֵּיהּ רָזָא דְּתוֹהוּ, דְּאִיהִי קַו יָרוֹק, קְלִיפָּא דֶּאֱגוֹזָא.</p>"],[9514012421,"<p>וּתְלַת קְלִיפִּין אִינוּן, דְּאִתְחַזְיָין בְּעַיְינִין דְּסִטְרָא אָחֳרָא. תֹּהוּ גַּוָון יָרוֹק, קְלִיפָּא קַדְמָאָה דֶּאֱגוֹזָא. בְּהוּ גַּוָון חִוָּור, קְלִיפָּא תִּנְיָינָא דֶּאֱגוֹזָא, וְאִיהוּ חִוָּורָא דְּעַיְינִין. חשֶׁךְ קְלִיפָּא תְּלִיתָאָה דֶּאֱגוֹזָא, וְאִיהוּ סוּמְקָא, כְּעָשָׁן דְּאִצְטְבַּע בְּסוּמְקָא דֶּאֱשָׁא, וְאִיהוּ סוּמָק חָשׁוּךְ. מָרָה אוּכְמָא, תְּהוֹם, וְאִיהוּ חָלָל דֶּאֱגוֹזָא, וְדָא אִיהִי לְבוּשָׁא דְּיֵצֶר הָרָע.</p>"],[9514012422,"<p>נָטֵיל מָרָה יְרוֹקָה בְּסִטְרָא דְּתוֹהוּ, וְעָבִיד צִיּוּרִין וְשִׁרְטוּטִין כְּפוּם חוֹבִין דִּבְנֵי נָשָׁא. כָּלְהוֹ צִיּוּרִין וְשִׁרְטוּטִין עֲקִימִין, וְלָאו בְּאוֹרַח מֵישָׁר. וְכֵן חוֹטְמָא וְאַנְפִּין וְעַיְינִין, בְּכָל אֲתַר דְּיֵצֶר הָרָע חִוְּיָא בִּישָׁא שַׁרְיָיא, אִיהוּ עֲקִימָא, וְכָל צִיּוּרִין דִּילֵיהּ עֲקִימִין.</p>"],[9514012423,"<p>נָטֵיל מָרָה סוּמְקָא מִסִּטְרָא דְּחשֶׁךְ, וְעָבִיד צִיּוּרִין וְשִׁרְטוּטִין. נָטֵיל מָרָה אוּכְמָא מִסִּטְרָא דִּתְהוֹם, דְּאִיהוּ חָלָל דֶּאֱגוֹזָא, וְעָבִיד צִיּוּרִין וְשִׁרְטוּטִין.</p>"],[9514012424,"<p>וְתָּא חֲזֵי, תְּלַת קִטְרִין בְּבַּר נָשׁ מִסִּטְרָא דְּדַכְיוּ, וְאִינוּן נַפְשָׁא רוּחָא וְנִשְׁמָתָא. נֶפֶשׁ, נָטֵיל עַפְרָא וּמַיָא וְאֶשָׁא וְרוּחָא. הַאי נֶפֶשׁ סְטָא לְיָמִינָא, וְנָטֵיל מַיָא כָּלֵיל בְּפוּמָא דְּאַרְיֵה, וְעָבִיד צִיּוּרִין. וְהַהִיא מַיָא דְּנָטֵיל, אִיהוּ מִמּוֹחָא, וְאִתְפְּלַג לְאַרְבַּע מוֹחִין. וְרָזָא דְמִלָּה (בראשית ב׳:י׳) וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים. אִינוּן גִּיחוֹן פִּישׁוֹן פְּרָת חִדֶּקֶל.</p>"],[9514012425,"<p>וּבְזִמְנָא דְּיֵיתֵי מְשִׁיחָא, כָּל חַד וְחַד מֵאֲבָהָן, אַחֲזֵי פְּעוּלָתֵיהּ. הֲדָא הוּא דִכְתִיב, (שם א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ, דְּאִיהוּ חַיְתוֹ אָרֶץ, אַפֵּיק זַרְעָא דִילֵיהּ, כָּל חַד בְּיִחוּסֵיהּ. וְדָא זַרְעָא דְיִצְחָק, דְּאִיהוּ נֶפֶשׁ חַיָּה, דְּאִינוּן מִינָהּ, וְזַרְעָא דִילָהּ בְּאוּמָּה דָּא, זַרְעָא דְּאִינוּן עַמֵּי הָאָרֶץ, דְּחַיָּה דְּאִיהִי שׁוֹר, דַּרְגָּא דְיִצְחָק.</p>"],[9514012426,"<p>(שם) וַיֹּאמֶר אֱלֹהִים יִשְׁרְצוּ הַמַּיִם, אִלֵּין מָארֵיהוֹן דְּחָכְמָה, דְּאִיהִי נֶפֶשׁ חַיָּה, דְּאִינוּן כְּנוּנִין דְּמִתְרַבִּין בְּיַמָּא דְאוֹרַיְיתָא. וְאִינוּן מִסִּטְרָא דְּאַרְיֵה דְּיַמָּא, דְּאִיהוּ כְּשַׂר בַּיָּם. דְּאַרְיֵה דְּסִטְרָא אַחֲרָא אִיהוּ פָּסוּל בְּיַבֶּשְׁתָּא, וְאַרְיֵה דְיַמָּא אִיהוּ לְיָמִינָא, דְּאַבְרָהָם, וּבֵיהּ הָרוֹצֶה לְהַחְכִּים יַדְרִים.</p>"],[9514012427,"<p>וְעוֹף יְעוֹפֵף עַל הָאָרֶץ עַל פְּנֵי רְקִיעַ הַשָּׁמָיִם, וְדָא פְּנֵי נֶשֶׁר אִלֵּין זַרְעָא דְּיַעֲקֹב, דְּאִינוּן מָארֵי פִּקּוּדֵי דְאוֹרַיְיתָא.</p>"],[9514012428,"<p>(שם) וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד וְתֵרָאֶה הַיַּבָּשָׁה, הַיַּבָּשָׁה, דָּא אָדָם דְּאִתְנְטֵיל מֵד' סִטְרִין דְּעַפְרָא. כַּד אִתְקַיַּים בָּהּ, יָבְשָׁה הָאָרֶץ מִמֵּי טוֹפָנָא, יִפְקוּן מִן גָּלוּתָא. וְרָזָא דְמִלָּה וַיְהִי כֵ\"ן, דְּאִיהוּ שִׁבְעִין שְׁנִין.</p>"],[9514012429,"<p>בְּיוֹמָא קַדְמָאָה, עָבִיד עֲבִידְתֵּיהּ לְאַנְהָרָא לוֹן, הֲדָא הוּא דִכְתִיב, (שמות י׳:כ״ג) וּלְכָל בְּנֵי יִשְׂרָאֵל הָיָה אוֹר. וְעוֹד (שם יג) וַה' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם וְגו', כְּגַוְּונָא דְמִצְרַיִם. בְּיוֹמָא תִּנְיָנָא, וִיהִי מַבְדִּיל, אַפְרֵישׁ לְיִשְׂרָאֵל מִנַּיְיהוּ, הֲדָא הוּא דִכְתִיב וְלֹא קָרַב זֶה אֶל זֶה כָּל הַלָּיְלָה.</p>"],[9514012430,"<p>בְּיוֹמָא תְּלִיתָאָה, אַעֲבַר לוֹן בְּיַמָּא. הֲדָא הוּא דִכְתִיב, (בראשית א׳:ט׳) וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד וְתֵרָאֶה הַיַּבָּשָׁה. כְּתִיב הָכָא וְתֵרָאֶה הַיַּבָּשָׁה, וּכְתִיב הָתָם (שמות י״ד:כ״א) וַיָּשֶׂם אֶת הַיָּם לֶחָרָבָה.</p>"],[9514012431,"<p>אוֹר דְּיוֹמָא קַדְמָאָה, מִינֵיהּ נָהֲרִין שִׁמְשָׁא וְסִיהֲרָא, בְּיוֹמָא רְבִיעָאָה. וַעֲלַיְיהוּ אִתְּמָר, (שם יג) וַה' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם בְּעַמּוּד עָנָן לַנְחוֹתָם הַדֶּרֶךְ וְלַיְלָה בְּעַמּוּד אֵשׁ לְהָאִיר לָהֶם.</p>"],[9514012432,"<p>יוֹמָא תִּנְיָינָא, בֵּיהּ אִתְבְּרֵי יַמָּא. הֲדָא הוּא דִכְתִיב, (בראשית א׳:ו׳) יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם. וְיוֹם חֲמִישָׁאָה, מִינֵיהּ אַפֵּיק נוּנֵי יַמָּא. דִּכְמָה דִּמְאוֹרוֹת דְּיוֹמָא רְבִיעָאָה תַּלְיָין בְּיוֹמָא קַדְמָאָה, הָכֵי נוּנִין דְּיוֹמָא חֲמִישָׁאָה תַּלְיָין בְּיוֹמָא תִּנְיָינָא. יוֹמָא תְּלִיתָאָה, אִיהוּ כָּלֵיל מִכֹּלָּא, אִיהוּ דַרְגָּא דְּיַעֲקֹב, דְּאִיהוּ נִשְׁרָא, כְּלִילָא מִמַּיָא וְאֶשָׁא. וְיוֹמָא שְׁתִיתָאָה, בֵּיהּ תַּלְיָיא, וּבֵיהּ אִתְבְּרֵי אָדָם, מֵהַהוּא עַפְרָא דְּיוֹמָא תְּלִיתָאָה.</p>"],[9514012433,"<p>יוֹמָא קַדְמָאָה אַבְרָהָם, דְּדַרְגֵּיהּ חֶסֶד, לְקִבְלֵיהּ הוּא נֶצַח, וְאַהֲרֹן כַּהֲנָא נָהֵיר אַנְפּוֹי כְּשִׁמְשָׁא, אִיהוּ לְקִבְלֵיהּ, יוֹמָא רְבִיעָאָה, דָּא בְּדָא תַּלְיָא, הֲדָא הוּא דִכְתִיב, (תהילים ט״ז:י״א) נְעִימוֹת בִּימִינְךָ נֶצַח.</p>"],[9514012434,"<p>יוֹמָא תִּנְיָינָא יִצְחָק, דְּדַרְגֵּיהּ גְּבוּרָה, לְקִבְלֵיהּ יוֹמָא חֲמִישָׁאָה, דְּאִיהוּ הוֹד, דַּרְגָּא דְּדָוִד.</p>"],[9514012435,"<p>יוֹמָא תְּלִיתָאָה יַעֲקֹב, לְקִבְלֵיהּ יוֹמָא שְׁתִיתָאָה, שְׁלֹמֹה, דְּדַרְגֵּיהּ יְסוֹד, דְּאִיהוּ שָׁלוֹם ה', וַעֲלֵיהּ אִיתְּמָר (במדבר כ״ה:י״ב) הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם.</p>"],[9514012436,"<p>יוֹם שַׁבָּת, מַלְכוּת, דַּרְגָּא דְּבֶן י\"ה, דְּאִיהוּ ו'. דְּמַהֲלַךְ חֲמֵשׁ מְאָה שְׁנִין, דְּאִינוּן חָמֵשׁ סְפִירוֹת, מָטֵי לִיסוֹד, לְאִתְחַבְּרָא בְּה'. וְיוֹם שַׁבָּת אִיהוּ משֶׁה רַבֵּנוּ, דְּדַרְגֵּיהּ בִּינָה.</p>"],[9514012437,"<p>וְיוֹם שַׁבָּת כָּלֵיל כֹּלָּא, כְּגַוְונָא דָא, (בראשית ב׳:ב׳) וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי, דָּא יוֹמָא קַדְמָאָה. מְלַאכְתּוֹ, דָּא יוֹמָא רְבִיעָאָה. וַיִּשְׁבֹּת בַּיּוֹם הַשְּׁבִיעִי, דָּא יוֹמָא תִּנְיָינָא, מִכָּל מְלַאכְתּוֹ אֲשֶׁר עָשָׂה, דָּא יוֹמָא חֲמִישָׁאָה, דְּבֵיהּ אִתְחְרַב בֵּי מַקְדְּשָׁא, וְלָא הֲוָה בִּנְיָינָא בֵּיהּ בְּאֶלֶף חֲמִישָׁאָה. וַיְקַדֵּשׁ אוֹתוֹ, דָּא יוֹמָא תְּלִיתָאָה, כִּי בוֹ שָׁבַת מִכָּל מְלַאכְתּוֹ, דָּא יוֹמָא שְׁתִיתָאָה.</p>"],[9514012438,"<p>אֲשֶׁר בָּרָא אֱלֹהִים לַעֲשׂוֹת, דָּא גוּפִין לְנִשְׁמָתִין דְּרַשִּׁיעַיָּיא. דְּלָא בָּעָא לְמֶעְבַּד לוֹן גּוּפִין, דְּאָזְלִין כָּלְהוֹ נָע וָנָד. וְדָא רָזָא (משלי י״א:כ״א) יַד לְיַד לֹא יִנָּקֶה רָע.</p>"],[9514012439,"<p>וְשַׁבָּת דְּכָלְהוֹ, נַיְיחָא דְּכָלְהוֹ, יְהֵא משֶׁה. דְּאִיהוּ דּוּגְמַת בֶּן י\"ה, דְּבַת זוּגֵיהּ מַלְכוּת, שַׁבָּת. שַׁבָּת וַדַּאי, דַּעֲלָה אִתְּמָר (תהילים ק״ג:י״ט) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה, דְּאִיהוּ מְלָאכוֹת דְּאַדְכֵּיר בְּיוֹמָא דְשַׁבַּתָּא.</p>"],[9514012440,"<p>וְלָא כְמָא דְּחָשְׁבִין טִפְּשִׁין, דּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד עֲבִידְתָּא, אוֹ טָרַח לְמֶעְבַּד עֲבִידְתֵּיהּ, וְנָח בְּיוֹמָא שְׁבִיעָאָה, כְּבַר נָשׁ דְּטָרַח בַּעֲבִידְתֵּיהּ, וּלְבָתַר דְּסַיֵּים נָח. חַס וְשָׁלוֹם, אֶלָּא בְּכָל זִמְנָא דִּשְׁכִינְתָּא אִיהִי בְּגָלוּתָא, אִתְּמָר בַּהּ (בראשית ח׳:ט׳) וְלֹא מָצְאָה הַיּוֹנָה מָנוֹחַ, דְּלָא אִשְׁתְּכַח צַדִּיקָא, דִּיהֵא לָהּ נַיְיחָא בֵיהּ.</p>"],[9514012441,"<p>וְנַיְיחָא דִילָהּ, אִינוּן צַדִּיקַיָּיא, דְּנַחְתַת בְּהוֹן, כְּגוֹן אַבְרָהָם וְאַהֲרֹן וְזַרְעֵיהּ. יִצְחָק וְדָוִד וְזַרְעֵיהּ. יַעֲקֹב וּשְׁלֹמֹה וְזַרְעֵיהּ. וַעֲלַיְיהוּ אִתְּמָר, (בראשית ב׳:ב׳) וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי, וַיִּשְׁבֹּת בַּיּוֹם הַשְּׁבִיעִי, וַיְבָרֶךְ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי, וַיְקַדֵּשׁ אוֹתוֹ. יוֹמָא דְּכָלְהוֹ, נַיְיחָא דְּכָלְהוֹ.</p>"],[9514012442,"<p>יוֹם הַשְּׁבִיעִי, משֶׁה, כָּלֵיל כָּלְהוֹ, בֵּיהּ נָח שְׁכִינְתָּא מִכָּלְהוֹ, וְדָא אִיהוּ וַיִּשְׁבֹּת בַּיּוֹם הַשְּׁבִיעִי, שְׁבִיתָה דֵּאלֹהִים וַדַּאי, דְּאִיהִי שְׁכִינְתָּא, וְלָא אֲמַר וַיִּשְׁבֹּת ה', דְּאִימָּא אִיהוּ דְּטָרְחָא בְּבִנְיָן, הֲדָא הוּא דִכְתִיב, (ישעיהו נ׳:א׳) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם.</p>"],[9514012443,"<p>וּבְגִין דָּא ד' יְסוֹדִין, כָּל חַד עָבִיד עֲבִידְתֵּיהּ, חַד אַרְיֵה, וְהָא אִיתְּמָר. תִּנְיָנָא שׁוֹר, סוּמְקָא כְּוַורְדָא, סָטָא לִשְׂמָאלָא, נָטַל גַּוָּון אֶשָׁא וְעָבִיד צִיּוּרִין וְשִׁרְטוּטִין וְאַתְרֵיהּ בְּלִבָּא.</p>"],[9514012444,"<p>נֶשֶׁר, אַתְרֵיהּ בְּגוּפָא, נָטַל רוּחָא כְּלִילָא בְּפוּמָא, סָטָא לַאֲחוֹרָא, וְנָטֵיל גַּוָּון חַד מִסִּיהֲרָא, סָטָא לְקַמֵּיהּ, וְנָטַל גַּוָּון חַד מִשִּׁמְשָׁא, סָטָא לְיָמִינָא וּשְׂמָאלָא וְנָטֵיל תְּרֵין גְּוָונִין מִנַּיְיהוּ, אִשְׁתְּכַח כָּלֵיל מִכָּל גְּוָונִין. וְהַאי אִיהוּ נִשְׁרָא רַבְרְבָא, מָארֵי דְנוֹצָה, רַב גַּדְפִין, כָּל גְּוָונִין בֵּיהּ אִתְחַזְּיָין.</p>"],[9514012445,"<p>אָדָם סָטָא לְעֵילָא, וְשָׁרְיָיא בִּדְיוֹקְנָא דְּאַנְפִּין, וּרְשִׁים תַּמָּן דִּיוּקְנָא דְּכָלְהוֹ חֵיוָן, וְאִתְלַבַּשׁ בְּכָלְהוֹ, וְאִתְחֲזֵי דְּיוּקְנֵיהּ בְּהוּ. הֲדָא הוּא דִכְתִיב, (יחזקאל א׳:י׳) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם וּפְנֵי אַרְיֵהּ אֶל הַיָּמִין לְאַרְבַּעְתָּם וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל לְאַרְבַּעְתָּן וּפְנֵי נֶשֶׁר לְאַרְבַּעְתָּן. וּרְשִׁים בְּהוֹן צִיּוּרִין וּגְוָונִין דְּאַנְפִּין, וְשִׁרְטוּטִין דְּמִצְחָא.</p>"],[9514012446,"<p>בְּהוֹן רְשִׁים תְּלָתִין וּתְרֵין שְׁבִילִין, דְּאִינוּן נְתִיבוֹת פְּלִיאוֹת חָכְמָה. וְכּוּלְהוּ אִתְכַּסְיָין בִּתְלָתִין וּתְרֵין, בֵּין אַנְפִּין וְגַדְפִין דְּחֵיוָן, דְּשֵׁשׁ עָשָׂר אַנְפִּין אִינוּן לְאַרְבַּעְתָּן לְד' חֵיוָן, וְשֵׁשׁ עָשָׂר גַּדְפִין סָלְקִין ל\"ב. הָכֵי אִינוּן שִׁרְטוּטִין דְּמִצְחָא, וְשִׁרְטוּטִין דְּעַיְינִין.</p>"],[9514012447,"<p>תְּלַת עֲשַׂר גְּוָונִין אִינוּן בְּצִיּוּרִין דְאַנְפִּין דְּקַו הַמִּדָּה. וְכוּלְהוּ גְּוָונִין אָזְלִין בְּקַו הַמִּדָּה, בְּאוֹרַח קְשׁוֹט, וְכוּלְהוּ רְשִׁימִין בְּוא\"ו. תְּרֵין וּתְלָתִין שְׁבִילִין מְצוּיָירִין בְּיו\"ד ה\"א ה\"א.</p>"],[9514012448,"<p>תְּרֵין עֲשַׂר גְּוָונִין, דִּתְלַת חֵיוָן, דְאִינוּן ו\"ו, וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, א דְּמִתְלַבֵּשׁ בְּהוֹן וְאִיתְכַּסֵּי בְּהוֹן. ו' לְתַתָּא, ו' לְעֵילָא. ו' לְעֵילָא, שִׁית גְּוָונִין עִילָּאִין. ו' לְתַתָּא, שִׁית גְּוָונִין תַּתָּאִין. בְּשִׁית גְּוָונִין עִילָּאִין פָּרַח לְגַבֵּי עֵילָא. וּבְשִׁית גְּוָונִין תַּתָּאִין פָּרַח לְגַבֵּי תַּתָּא.</p>"],[9514012449,"<p>וְרָזָא דְמִלָּה, (ישעיהו ו׳:ב׳) בִּשְׁתַּיִם יְכַסֶּה פָנָיו וּבִשְׁתַּיִם יְכַסֶּה רַגְלָיו וּבִשְׁתַּיִם יְעוֹפֵף, אִלֵּין אִינוּן דְּיוֹקְנִין, דְּאִתְלַבַּשׁ בְּהוֹן א' עִלָּיאָה, דְּאִיהוּ תִּפְאֶרֶת. אָדָם, יו\"ד ה\"א וא\"ו ה\"א. אִלֵּין אִינוּן נְתִיבִין דְּחָכְמָה, נָתִיב לֹא יְדָעוֹ עָיִט, א', דְּאִיהוּ אָדָם, עֲלֵיהּ אִתְּמָר בְּמוּפְלָא מִמְּךָ אַל תִּדְרשׁ וּבִמְכוּסֶה מִמְּךָ אַל תַּחְקֹר. דְּאִיהוּ דְּאִתְעַטַר בִּגְוָונִין דְּאִינוּן ו\"ו, וְאִיהוּ לָא אִתְגַּלְּיָיא, עֲלֵיהּ אִיתְּמָר (דברים ד׳:ט״ו) כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה.</p>"],[9514012450,"<p>וְאִית לְתַתָּא דְּמוּת אָדָם, וְלֹא אָדָם. עֲלָה אִתְּמָר (במדבר י״ב:ח׳) וּתְמוּנַת ה' יַבִּיט וְדָא נֶפֶשׁ הַשִּׂכְלִית, מִסִּטְרָא דְּמַלְכוּת, דִּרְשִׁים כָּל גְּוָונִין אִלֵּין, וְאִיהִי אִתְקְרִיאַת יו\"ד ה\"א וא\"ו ה\"א, וְדָא אִיהוּ מַ\"ה לְּמַטָה.</p>"],[9514012451,"<p>רוּחַ רְשִׁים רְשִׁימִין בְּמַלְאָכַיָיא, דְּאִינוּן ד', מִיכָאֵ\"ל גַּבְרִיאֵ\"ל נוּרִיאֵ\"ל רְפָאֵ\"ל. וְסָלֵיק לְעֶשֶׂר, דְּאִינוּן: אֶרְאֶלִי\"ם. שְׂרָפִים. חַשְׁמַלִּים. שִׁנְאֲנִים. תַּרְשִׁישִׁים. אוֹפַנִּים. אֱלֹהִים. אִישִׁים. חַיּוֹת. בְּנֵי אֱלֹהִים.</p>"],[9514012452,"<p>וְכָלְהוֹ מִתְלַבְּשִׁין וְנָהֲרִין בִּגְוָונִין דְּאַנְפִּין. דִּגְוָונִין אִינוּן לְבוּשִׁין לְאִינוּן מַלְאָכִין, כְּגוּפָּא דְּמִתְלַבֵּשׁ בִּלְבוּשִׁין. וְאִינוּן אַחְזְיָין דְּיוֹקְנִין בִּלְבוּשִׁין, לִנְבִיאָה. וְרוּחָא דְאִיהוּ תִּפְאֶרֶת, רְכִיב בְּמַלְאָכַיָיא, בְּרוּחָא דְאִיהוּ רְכִיב בְּגוּפָא, וְרָזָא דְמִלָּה, (חבקוק ג׳:ח׳) כִּי תִרְכַּב עַל סוּסֶיךָ מַרְכְּבוֹתֶיךָ יְשׁוּעָה.</p>"],[9514012453,"<p>נִשְׁמָתָא אִיהִי מִסִּטְרָא דְבִינָה, וַעֲלָהּ שַׁרְיָיא מַחֲשָׁבָה דְּלֵית לָהּ סוֹף. וּבָהּ, לֵית דִּמְיוֹן, וְלֵית צוּרָה, וְלֵית דִּיוּקְנָא. בְּגִין דְּאִיהִי עָלְמָא דְּאָתֵי. וְלֵית בָּהּ לָא גוּפָא, וְלָא דִּיוּקְנָא, כְּמָה דְּאוֹקְמוּהָ מִכָּל מָקוֹם, הָעוֹלָם הַבָּא אֵין בּוֹ לֹא גּוּף וְלֹא גְּוִיָּה. וְנִשְׁמָתָא אִתְלְבַּשׁ בְּכוּרְסְיָא, דְּאִיהוּ אָדָם דִּבְרִיאָה, וּבְאַרְבַּע סִטְרִין דִּילְּהוֹן. תַּמָּן אִיתְּמָר, (דברים ד׳:ט״ו) כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה, דַּעֲלָה אִיתְּמָר (ישעיהו ס״ד:ג׳) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתֶךָ.</p>"],[9514012454,"<p>וּבְהַאי מַחֲשָׁבָה, הֲווֹ מְצַיְירִין כָּל נְבִיאַיָא, כָּל דִּמְיוֹנִין וְכָל צִיּוּרִין לְתַתָּא מִינָהּ. וּלְעֵילָא מִינָהּ לָא תָפְסִין צִיּוּר כְּלַל. בָּהּ לֹא הֲווֹ יָכְלִין לְמִתְפַּס צִיּוּר וְלָאו גַּוָּון כְּלָל. כָּל שֶׁכֵּן לְעֵילָא מִינָהּ.</p>"],[9514012455,"<p>וְצָרִיךָ לְאַחְזָרָא לְמִלָּה קַדְמָאָה. עַיְינִין יְרוֹקִין דְּסִטְרָא דְּדַכְיָיא, רַחֲמִים אִינוּן מִסִּטְרָא דְּת\"ת, וִירוֹקָא דִילְּהוֹן מִסִּטְרֵיהּ. אִיהוּ נְהֵיר בִּנְהוֹרָא דְּאֶבֶן מַרְגָּלִית.</p>"],[9514012456,"<p>דִּבְּגִין דָּא אִתְקְרִיאוּ סְפִירָן סְפִירוֹת, דְּנָהֲרִין גְּוָונִין דִּילְּהוֹן כְּסַפִּירִים יַקִּירִין, וְלָא כְּסַפִּירִים דְּאִינוּן פְּסוֹלוֹת דְּעָלְמָא שְׁפָלָה, אֶלָּא כְּאַבְנִין יַקִּירִין וּמַרְגְּלָאן דְּגִנְתָּא דְעֵדֶן, דִּנְהוֹרָא דִּלְהוֹן מִסּוֹף הָעוֹלָם וְעַד סוֹפוֹ. וְאִלֵּין אִינוּן סְפִירָן דְּנָהֲרִין לְבַר נָשׁ בְּאוֹרַיְיתָא כּוֹלָּא, עַד דְּלֵית שִׁיעוּרָא.</p>"]]});
